// 00-utils.js — Tiện ích chung: $, esc, rnd, pick, clamp, fmt, full
'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rnd=(a,b)=>a+Math.random()*(b-a);
const pick=a=>a[Math.floor(Math.random()*a.length)];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const r10=v=>Math.max(10000,Math.round(v/10000)*10000);
function fmt(v){ const neg=v<0; v=Math.abs(Math.round(v)); const s=v>=1e6?(Math.round(v/1e4)/100).toString().replace('.',',')+'tr':Math.round(v/1000)+'k'; return (neg?'−':'')+s; }
const full=v=>Math.round(v).toLocaleString('vi-VN')+'đ';
const OUT='#4A4458';

