// 01f-splash.js — 06/10 mach chinh: man tai + man mo dau (dac ta phong cach game muc E, ban gon)
(()=>{ const SP=document.getElementById('splash'); if(!SP) return;
  const IM={ngang:"img/feb708110897.webp",doc:"img/cfda1487889b.webp",logo:"img/d15a3418eb5d.webp"};
  SP.querySelector('.sp-bg').style.setProperty('--sp-ngang','url(../'+IM.ngang+')'); SP.querySelector('.sp-bg').style.setProperty('--sp-doc','url(../'+IM.doc+')');
  SP.querySelector('.sp-logo').style.backgroundImage='url('+IM.logo+')';
  const bar=SP.querySelector('.sp-bar i'), msg=SP.querySelector('.sp-msg'), t0=performance.now();
  const MSG=['Đang mở cửa tiệm…','Đang pha trà gừng…','Đang hâm nóng đá…','Đang gấp khăn…','Đang thắp đèn lồng…'];
  let p=0, mi=0; const tk=setInterval(()=>{ p=Math.min(p+(p<70?9:2),92); bar.style.width=p+'%'; const k=Math.min(MSG.length-1,Math.floor(p/20)); if(k!==mi){ mi=k; msg.textContent=MSG[k]; } },180);
  const slow=setTimeout(()=>{ msg.textContent='Mạng hơi chậm, tiệm vẫn đang chuẩn bị…'; },10000);
  window.addEventListener('DOMContentLoaded',()=>{ try{ window.__spSpeed=speed; speed=0; }catch(e){} });
  const ready=Promise.all([new Promise(r=>document.readyState==='complete'?r():window.addEventListener('load',r)),(document.fonts&&document.fonts.ready)||Promise.resolve(),new Promise(r=>setTimeout(r,800))]);
  ready.then(()=>{ clearInterval(tk); clearTimeout(slow); bar.style.width='100%'; msg.textContent='Sẵn sàng!';
    setTimeout(()=>{ SP.classList.add('ready'); const B=SP.querySelector('.sp-btns'); let has=false, sub='';
      try{ has=S.stage!=='story'; const pr=(typeof prem==='function')&&prem(); sub='Ngày '+S.day+(pr?' · '+pr.name:''); }catch(e){}
      B.innerHTML=has?`<button class="sp-main" data-sp="go"><b>Chơi tiếp</b><small>${sub}</small></button><button class="sp-sub2" data-sp="new">Ván mới</button>`:`<button class="sp-main" data-sp="go"><b>Chơi</b></button>`;
      B.hidden=false; },220); });
  SP.addEventListener('click',e=>{ const b=e.target.closest('[data-sp]'); if(!b) return;
    if(b.dataset.sp==='new'){ if(b.dataset.arm!=='1'){ b.dataset.arm='1'; b.textContent='Bấm lần nữa để xoá ván cũ'; b.classList.add('danger'); return; }
      try{ localStorage.removeItem(KEY); }catch(_){} location.reload(); return; }
    SP.classList.add('out'); try{ if(typeof sfx==='function') sfx('good'); }catch(_){}
    setTimeout(()=>{ SP.remove(); try{ speed=window.__spSpeed||1; if(typeof renderAll==='function') renderAll(); }catch(_){} document.body.classList.add('sp-done'); },650); });
})();

// 17e-1: icon dot E (E1-E4, art/out/*.webp) -> UI_ICON; logo ghi chu SPA MIU bang code; hieu ung toa sang/lap lanh qua bien CSS
// Sinh boi tools/pack_e_icons.py. KHONG sua tay phan du lieu.
(()=>{ window.UI_ICON=window.UI_ICON||{}; const D={"ic-cam": "img/0d7e3d67bd6b.webp", "ic-sai": "img/210aab1a878f.webp", "ic-an": "img/86ff75d3df86.webp", "ic-len": "img/cc7f54b7233d.webp", "ic-xuong": "img/5aeacf0169a5.webp", "ic-tim": "img/56bcee779003.webp", "ic-trochoi": "img/0c60250d9b5e.webp", "ic-xucxac": "img/f03760dd670f.webp", "ic-thaoduoc": "img/f9a8319c32b6.webp", "yc-nhac": "img/bf9d4343a1e1.webp", "yc-manhtay": "img/168391857356.webp", "yc-douong": "img/99b7cf8abb46.webp", "ic-hoinong": "img/a0e2866c5181.webp", "ic-lanh": "img/efad97d8e857.webp", "ic-nhietke": "img/66e0696013bf.webp", "ic-sao-day": "img/50ba8fefa832.webp", "ic-sao-rong": "img/a64dfadb050a.webp", "ic-sao-nho": "img/52575fa0b47b.webp", "logo-e": "img/b8aed52cd89c.webp", "fx-toa-sang": "img/11a58efba2f8.webp", "fx-lap-lanh": "img/0e7f8e65a341.webp"};
  Object.assign(UI_ICON,D);
  document.documentElement.style.setProperty('--fx-toa','url('+D['fx-toa-sang']+')');
  document.documentElement.style.setProperty('--fx-lap','url('+D['fx-lap-lanh']+')');
  // logo: ve hinh + chu SPA MIU len ruy-bang trong
  const im=new Image(); im.onload=()=>{
    const c=document.createElement('canvas'); c.width=256; c.height=Math.round(256*im.height/im.width); const g=c.getContext('2d'); g.drawImage(im,0,0,c.width,c.height);
    g.font='900 '+Math.round(c.width*0.105)+'px "Baloo 2","Nunito",system-ui,sans-serif'; g.textAlign='center'; g.textBaseline='middle'; g.lineJoin='round';
    const x=c.width*0.5,y=c.height*0.80; g.lineWidth=3; g.strokeStyle='#fff8ec'; g.strokeText('SPA MIU',x,y); g.fillStyle='#7a4f3a'; g.fillText('SPA MIU',x,y);
    const u=c.toDataURL('image/webp',.9); UI_ICON.logo=u;
    const sp=document.querySelector('.sp-logo'); if(sp) sp.style.backgroundImage='url('+u+')';
  }; im.src=D['logo-e'];
})();

// 02-economy.js — Kinh tế: khoản vay, mặt bằng, dịch vụ, vật tư, loại khách, thợ bay, chỉ số, sự cố
'use strict';
// ---------- economy (giá tham khảo thị trường, xem ghi chú nguồn trong Sổ sách) ----------
// ---------- hoàn cảnh khởi nghiệp (độ khó) ----------
// Luật chơi giống nhau ở cả 3 mức; chỉ khác vốn tự có và khoản vay, như ngoài đời.
// Nguồn: NHCSXH cho vay giải quyết việc làm tối đa 200tr/lao động, 6,24%/năm (vbsp.org.vn, 01/2026);
// vay thế chấp ngân hàng thương mại ~5,5–10,5%/năm, tín chấp ~11–24%/năm (bảng lãi suất 09/2026).
// v3.1: ai cũng mở ở chợ đêm. Độ khó = vốn tự có + lãi suất (áp cho mọi khoản vay trong game, kể cả vay mở chi nhánh).
// 20e (14/10): vay đầu 60tr cả 3 mức, lãi Dễ 10% / Vừa 15% / Khó 24%, góp mỗi 10 ngày, trễ thì bị nhắc 3 lần rồi siết nợ.
// Lãi tham khảo: thế chấp ~5,5–10,5%/năm, tín chấp ~11–24%/năm (bảng lãi suất các ngân hàng 09/2026).
const DIFFS={
 de:{name:'Dễ', title:'Gia đình hỗ trợ', own:100e6, loan:60e6, months:60, yearRate:.10, kind:'Vay thế chấp (sổ đỏ nhà bố mẹ)',
   desc:'Có 100tr tiết kiệm, gia đình cho mượn sổ đỏ nên vay được lãi thấp nhất 10%/năm, trả dài hạn, góp mỗi kỳ 10 ngày.'},
 vua:{name:'Vừa', title:'Vay thế chấp thông thường', own:50e6, loan:60e6, months:48, yearRate:.15, kind:'Vay thế chấp (xe và tài sản cá nhân)',
   desc:'Có 50tr tự để dành, thế chấp tài sản nhỏ nên lãi trung bình 15%/năm, góp mỗi kỳ 10 ngày.'},
 kho:{name:'Khó', title:'Tự thân lập nghiệp', own:30e6, loan:60e6, months:36, yearRate:.24, wage:.4, kind:'Vay tín chấp cá nhân',
   desc:'Chỉ có 30tr và một khoản tín chấp lãi 24%/năm, phải trả hết trong 4 kỳ (40 ngày), mỗi kỳ 25% tổng nợ. Sai một bước là thiếu tiền góp.'},
 legacy:{name:'Bản cũ', title:'Khoản vay bản cũ', own:0, loan:500e6, months:60, yearRate:.10, kind:'Vay tín chấp'}
};
const LOAN={amount:150e6, months:60, yearRate:.0624};
function applyDiff(k){ const d=DIFFS[k]||DIFFS.vua; LOAN.amount=d.loan; LOAN.months=d.months; LOAN.yearRate=d.yearRate; }
// 20e: kỳ góp 10 ngày game. mRate = lãi MỖI KỲ; periodPay = tiền góp mỗi kỳ (gốc + lãi chia đều); monthlyPay = 3 kỳ (chỉ để hiện/tính chi phí tháng)
const PERIOD=10;
const mRate=()=>LOAN.yearRate*PERIOD/360;
// 20g: mức Khó mỗi kỳ trả 25% tổng (gốc + lãi 40 ngày) → vay hết sau 4 kỳ
const periodPay=()=>{ if(S.diff==='kho') return LOAN.amount*(1+LOAN.yearRate*4*PERIOD/360)*.25; const r=mRate(), n=LOAN.months*30/PERIOD; return LOAN.amount*r/(1-Math.pow(1+r,-n)); };
const monthlyPay=()=>periodPay()*30/PERIOD;
// 21c: số kỳ góp của khoản vay hiện tại (Khó = 4 kỳ, còn lại = tháng × 3) và tiền góp mỗi kỳ cho dư nợ P bất kỳ (dùng để hiện chữ, khớp periodPay)
const numPeriods=()=>S.diff==='kho'?4:LOAN.months*30/PERIOD;
const periodPayFor=(P,yr,months,diff)=>{ if(diff==='kho') return P*(1+yr*4*PERIOD/360)*.25; const r=yr*PERIOD/360, n=months*30/PERIOD; return P*r/(1-Math.pow(1+r,-n)); };
const pctRate=()=>String(Math.round(LOAN.yearRate*10000)/100).replace('.',',')+'%/năm';
// Điện kinh doanh dưới 6kV (QĐ 1279/QĐ-BCT, 10/5/2025): bình thường 3.152đ, cao điểm 5.422đ, thấp điểm 1.918đ.
// Tiệm mở 10:00–02:00 → bình quân theo giờ ≈ 3.270đ, cộng VAT ≈ 3.550đ/kWh.
// Giá nước kinh doanh ở Phú Quốc chưa tra được văn bản mới nhất: giữ mức ước tính.
const ELEC=3550, WATER=11340;
// KTV: lương cứng thấp + tua 30% giá dịch vụ + giữ 100% tip (cách trả phổ biến ở tiệm massage)
const TUA=.30;
// Thuế hộ kinh doanh 2026: doanh thu dưới 500tr/năm miễn thuế; phần vượt nộp GTGT 5% + TNCN 2% (dịch vụ)
const TAX={free:500e6, rate:.07, yearDays:360};
// Giặt khăn, ga, đồ dùng một lần mỗi lượt khách; chi phí khác hằng tháng (internet, rác, phí quẹt thẻ, sửa vặt) theo mặt bằng
