const PREMISES=[
 {id:'chodem', name:'Chợ đêm Dương Đông', lvl:0, rent:15e6, fit:15e6, misc:3e6, demand:18, traffic:.8, chairs:4, rooms:2, market:200000, kwh:40, mix:[.55,.4,.05], groups:0, desc:'Chợ đêm vừa chuyển về chỗ mới nên còn vắng. Chủ yếu dân địa phương và khách du lịch trong nước, ít khách nhất trong 3 khu nhưng giá thuê rẻ nhất.'},
 {id:'thd', name:'Đường Trần Hưng Đạo', lvl:1, rent:30e6, fit:25e6, misc:5e6, demand:30, traffic:1, chairs:6, rooms:3, market:250000, kwh:60, mix:[.2,.35,.45], groups:.05, desc:'Trục đường chính nối các khách sạn. Nhiều khách Tây đi bộ ghé vào, tip cao hơn khách trong nước.'},
 {id:'sunset', name:'Khu Sunset', lvl:2, rent:50e6, fit:35e6, misc:8e6, demand:42, traffic:1.3, chairs:8, rooms:4, market:320000, kwh:85, mix:[0,.01,.99], groups:.7, desc:'Khu ngắm hoàng hôn, xe du lịch đổ khách theo đoàn. Gần như toàn khách nước ngoài, đoàn đi qua hướng dẫn viên (hoa hồng 20%).'}
];
