const slot=id=>SLOTS.find(s=>s.id===id);

// ---------- giá mở khoá theo thị trường ----------
const REALP={cashier:12e6,sofa:6e6,tea:1.5e6,trolley:3.5e6,changing:15e6,towel:4.5e6,art:1e6,fish:5e6,buddha:2e6,fountain:6e6,plant1:5e5,plant2:5e5,lamps:3e6,lights:8e5};
SLOTS.forEach(s=>{
  if(REALP[s.id]) s.price=REALP[s.id];
  if(s.zone==='chan'){ s.price=4.9e6; s.desc='Ghế foot có tăng đơ gỗ và chậu ngâm.'; }
  if(s.id.startsWith('room')){ s.price=9e6; s.name='Phòng body '+(s.need+1)+' (giường + vách)'; s.desc='Giường massage gỗ có lỗ mặt, vách rèm và đèn.'; }
  if(s.id==='trolley') s.desc='Máy hâm đá nóng và bộ đá bazan, cần cho massage đá nóng.';
  if(s.id==='towel') s.desc='Tủ hấp khăn nóng. Có tủ thì khăn hỏng ít hơn.';
});

// 24k: NGUON TEN CHUAN. Mot hinh = mot ten: moi noi (menu, mua sam, so tay, thong bao, nhiem vu, bill, dien thoai, huong dan) doc ten tu day.
// Vat pham / dich vu / vat tu lay thang tu bang du lieu (SLOTS, SERVICES, SUP); phan con lai (khu, tab, vai tro) ghi o day. Doi chieu: docs/bao-cao/bang-ten-24k.md
'use strict';
const TEN={
  slot:id=>{ const s=typeof slot==='function'?slot(id):SLOTS.find(x=>x.id===id); return s?s.name:id; },
  svc:k=>SERVICES[k]?SERVICES[k].name:k,
  sup:k=>SUP[k]?SUP[k].name:k,
  // khu / tab / vai tro (ten hien tren giao dien)
  tab:{shop:'Tiệm',buy:'Mua sắm',staff:'Nhân sự',skill:'Dịch vụ',phone:'Điện thoại',book:'Sổ sách'},
  role:{owner:'Chủ tiệm',cashier:'Thu ngân',manager:'Quản lý ca',ktvc:'KTV chính',hv:'Học việc'},
  khu:{don:'Khu đón khách',chan:'Khu massage chân',body:'Phòng body riêng'},
  thu:{ghost:'Cần mua:'},
  get batbuoc(){ return ['cashier','sofa','chair1','towel'].map(id=>TEN.slot(id)).join(', '); }   // 4 mon bat buoc truoc khi khai truong (ghe: mon dau tien)
};

// 04-state.js — Trạng thái game S, lưu/tải localStorage, giá dịch vụ
'use strict';
// ---------- state ----------
const KEY='spa-lynh-nguyen-v8';
function fresh(){ return {stage:'story', owner:'', name:'Spa Miu', cash:0, debt:0, prem:null, owned:{}, log:[],
  day:1, time:0, prices:{}, skills:{foot:{lv:1,exp:0}}, xp:0, cashier:null, manager:false, selfHaggle:false,
  staff:[], cands:[], nextId:1, returning:0, referrals:0, group:[], inbox:[],
  mission:0, won:false, sats:[], best:0, flyUsed:0, taught:0, retServed:0, solved:0,
  stock:{soak:50,oil:2000,candle:20,towel:40}, auto:{restock:false, fly:false},
  staffDoneSinceIssue:0, svcLog:[],
  stats:null, totals:{served:0,rev:0,tips:0,lost:0}, look:{skin:'#F6D2B4',hair:'#3B2A26'}}; }
const freshStats=()=>({rev:0,tips:0,served:0,lost:0,missed:0,deals:0,costs:0,fly:0,comm:0,sup:0,by:{},byRev:{}});
let S=fresh();
try{ const r=localStorage.getItem(KEY); if(r){ const d=JSON.parse(r); if(d&&d.stage) S=Object.assign(fresh(),d); } }catch(e){}
S.stock=Object.assign(fresh().stock,S.stock||{}); S.auto=Object.assign(fresh().auto,S.auto||{});
if(!S.stats) S.stats=freshStats();
// Save cũ (chưa chọn hoàn cảnh) đã ký khoản vay 500tr → giữ đúng điều khoản cũ
if(!S.diff && S.stage!=='story') S.diff='legacy';
applyDiff(S.diff||'vua');
const save=()=>{ if(window.__khongLuu) return; try{ localStorage.setItem(KEY,JSON.stringify(S)); }catch(e){} };
const prem=()=>PREMISES.find(p=>p.id===S.prem);
const market=k=>Math.round((prem()?prem().market:250000)*SERVICES[k].mul/10000)*10000;
let promoMul=()=>1;   // v3.4 (15w): giảm giá khai trương
const priceOf=k=>{ const b=S.prices[k]||market(k), m=promoMul(); return m===1?b:Math.round(b*m/10000)*10000; };
const addLog=(t,a)=>{ S.log.unshift({t,a,d:S.day}); S.log=S.log.slice(0,80); if(window.onAddLog) window.onAddLog(t,a); };
let tab='shop', armed=null, speed=1, phoneTab='group';

function available(s){
  const p=prem(); if(!p) return {ok:false,why:'Chưa thuê mặt bằng'};
  if(s.zone==='chan' && s.seat>=p.chairs) return {ok:false,why:'Mặt bằng không đủ chỗ',space:true};
  if(s.id.startsWith('room') && s.need>=p.rooms) return {ok:false,why:'Mặt bằng không đủ phòng',space:true};
  if(s.needSlot && !S.owned[s.needSlot]) return {ok:false,why:'Cần '+slot(s.needSlot).name+' trước',dep:true};
  return {ok:true};
}

// 05-characters.js — Nhân vật SVG (tóc, da, avatarMini)
'use strict';
// ---------- characters ----------
const HAIRS={
 short:(c)=>`<path d="M-15 -56a15 15 0 0 1 30 0q-4-6-15-6t-15 6z" fill="${c}"/>`,
 bob:(c)=>`<path d="M-17 -44v-12a17 16 0 0 1 34 0v12q-4 2-5-4v-6q-12-6-24 0v6q-1 6-5 4z" fill="${c}"/>`,
 bun:(c)=>`<circle cx="0" cy="-72" r="7" fill="${c}"/><path d="M-15 -55a15 15 0 0 1 30 0q-6-5-15-5t-15 5z" fill="${c}"/>`,
 long:(c)=>`<path d="M-17 -30v-26a17 16 0 0 1 34 0v26h-7v-22q-10-8-20 0v22z" fill="${c}"/>`
};
function charSVG(o){
  const hair=HAIRS[o.hs||'short'](o.hair);
  const hat = o.hat ? `<ellipse cx="0" cy="-66" rx="21" ry="5" fill="${o.hat}"/><path d="M-11 -66a11 9 0 0 1 22 0z" fill="${o.hat}"/>` : '';
  const shades = o.shades ? `<rect x="-11" y="-58" width="9" height="6" rx="2" fill="${OUT}"/><rect x="2" y="-58" width="9" height="6" rx="2" fill="${OUT}"/><path d="M-2 -56h4" stroke="${OUT}" stroke-width="1.5"/>` : `<circle cx="-5" cy="-54" r="2" fill="${OUT}"/><circle cx="5" cy="-54" r="2" fill="${OUT}"/>`;
  const apron = o.apron ? `<path d="M-8 -36h16v20h-16z" fill="${o.apron}" stroke="${OUT}" stroke-width="2"/>` : '';
  return `<g class="body">${G(`<rect x="-8" y="-18" width="7" height="18" rx="3" fill="${o.pants}"/><rect x="1" y="-18" width="7" height="18" rx="3" fill="${o.pants}"/>
    <rect x="-13" y="-40" width="26" height="25" rx="9" fill="${o.shirt}"/>`)}${apron}
    <g class="arms">${G(`<rect x="-18" y="-36" width="7" height="16" rx="3.5" fill="${o.shirt}"/><rect x="11" y="-36" width="7" height="16" rx="3.5" fill="${o.shirt}"/>`)}</g>
    ${G(`<circle cx="0" cy="-54" r="15" fill="${o.skin}"/>`)}
    <g stroke="${OUT}" stroke-width="2.4" stroke-linejoin="round">${hair}</g>${hat?`<g stroke="${OUT}" stroke-width="2.4">${hat}</g>`:''}
    ${shades}<ellipse cx="-9" cy="-48" rx="3" ry="2" fill="#F7A8B8"/><ellipse cx="9" cy="-48" rx="3" ry="2" fill="#F7A8B8"/>
    <path d="M-3 -47q3 3 6 0" stroke="${OUT}" stroke-width="1.8" fill="none" stroke-linecap="round"/></g>`;
}
const SKINS=['#F6D2B4','#EDBE98','#D9A27A','#F9DCC4'];
function lookFor(type){
  const shirts=['#BFE3F7','#F7A8B8','#FBD796','#C9E8B8','#C9B8F0','#FBF6EA'];
  const o={skin:pick(SKINS), hair:pick(['#3B2A26','#5A3B2E','#2A2226']), hs:pick(['short','bob','bun','long']), shirt:pick(shirts), pants:pick(['#6E80B8','#4A4458','#B9B6C2','#E9A94E'])};
  if(type==='tay'){ o.skin=pick(['#FBE3D2','#F6D2B4']); o.hair=pick(['#F3D27A','#C98A4E','#E8B866']); if(Math.random()<.5) o.shades=true; if(Math.random()<.4) o.hat='#FBD796'; }
  if(type==='dl' && Math.random()<.5) o.hat=pick(['#FBF6EA','#F7A8B8']);
  return o;
}
function avatarMini(o){ return `<svg class="av" viewBox="-24 -84 48 88">${charSVG(o)}</svg>`; }

// 06-scene.js — Cảnh ẩn (SVG 1400x500) chạy mô phỏng người đi lại, mua ô
'use strict';
// ---------- scene ----------
const sceneEl=$('#scene');
function drawScene(popId){
  const O=S.owned, p=prem();
  let h=`<defs>
    <radialGradient id="gGlow"><stop offset="0" stop-color="#FFF1B8" stop-opacity=".85"/><stop offset="1" stop-color="#FFF1B8" stop-opacity="0"/></radialGradient>
    <pattern id="dots" width="22" height="22" patternUnits="userSpaceOnUse"><circle cx="4" cy="4" r="2" fill="#FBF6EA" opacity=".6"/></pattern>
  </defs>`;
  // outside: day sky
  h+=`<rect x="0" y="0" width="130" height="500" fill="#CDEBFA"/>
    ${G(`<path d="M18 110a12 12 0 0 1 20-8 14 14 0 0 1 26 4 10 10 0 0 1 0 18H22a10 10 0 0 1-4-14z" fill="#FBF6EA"/><circle cx="100" cy="80" r="14" fill="#FBD796"/>`)}
    ${G(`<rect x="-4" y="430" width="140" height="74" fill="#D8D6DE"/><path d="M40 430v70M90 430v70" fill="none"/>`)}
    ${G(`<rect x="16" y="260" width="6" height="170" fill="#B9B6C2"/><circle cx="19" cy="254" r="9" fill="#FFF1B8"/>`)}`;
  // awning + sign
  let sc=''; for(let x=130;x<1400;x+=36) sc+=`<path d="M${x} 36v10a18 12 0 0 0 36 0v-10z" fill="${(x/36)%2<1?'#F7A8B8':'#FBF6EA'}"/>`;
  h+=G(`<rect x="130" y="-4" width="1274" height="42" fill="#FBF6EA"/>${sc}`);
  h+=`<rect x="${765-Math.max(120,S.name.length*8+40)}" y="4" width="${Math.max(240,S.name.length*16+80)}" height="28" rx="14" fill="#F9C87A" stroke="${OUT}" stroke-width="2.6"/>
    <text x="765" y="25" text-anchor="middle" font-family="Baloo 2, Nunito, sans-serif" font-weight="800" font-size="19" fill="${OUT}">${esc(S.name)}</text>`;
  // walls
  h+=G(`<rect x="130" y="58" width="300" height="342" fill="#FDE3E4"/><rect x="430" y="58" width="480" height="342" fill="#E4F4EA"/><rect x="910" y="58" width="360" height="342" fill="#ECE4F8"/><rect x="1270" y="58" width="134" height="342" fill="#FDEBDD"/>`);
  h+=`<rect x="130" y="58" width="300" height="342" fill="url(#dots)"/>`;
  // entrance door
  h+=G(`<rect x="122" y="58" width="14" height="372" fill="#C9B8F0"/><rect x="94" y="170" width="42" height="260" rx="4" fill="#D8EEFA"/><path d="M102 190l20-16M102 214l28-22" stroke="#FBF6EA" fill="none" stroke-width="4"/><rect x="126" y="292" width="5" height="30" rx="2" fill="#F9C87A"/>
    <rect x="68" y="136" width="64" height="24" rx="8" fill="${S.stage==='open'?'#8FD3AE':'#F7A8B8'}"/>`);
  h+=`<text x="100" y="153" text-anchor="middle" font-family="Nunito, sans-serif" font-weight="800" font-size="12" fill="${OUT}">${S.stage==='open'?'ĐANG MỞ':'SẮP MỞ'}</text>`;
  // reception shelves (like reference: pink open shelves)
  h+=G(`<rect x="182" y="120" width="116" height="110" rx="4" fill="#F7A8B8"/><rect x="188" y="126" width="104" height="30" rx="2" fill="#FAD0D8"/><rect x="188" y="160" width="104" height="30" rx="2" fill="#FAD0D8"/><rect x="188" y="194" width="104" height="30" rx="2" fill="#FAD0D8"/>
    <rect x="196" y="134" width="12" height="20" rx="4" fill="#FBF6EA"/><rect x="212" y="138" width="12" height="16" rx="4" fill="#BFE3F7"/><rect x="262" y="134" width="12" height="20" rx="4" fill="#F9C87A"/><rect x="266" y="170" width="18" height="18" rx="4" fill="#FBF6EA"/><rect x="196" y="170" width="14" height="18" rx="4" fill="#C9E8B8"/><rect x="264" y="202" width="14" height="20" rx="4" fill="#C9B8F0"/>`);
  h+=`<text x="360" y="108" text-anchor="middle" font-family="Baloo 2, Nunito, sans-serif" font-weight="800" font-size="16" fill="${OUT}">Thu ngân</text>`;
  // hall mirror strip
  h+=G(`<rect x="444" y="196" width="456" height="96" rx="6" fill="#BFE3F7"/>`)+`<path d="M470 280l40-70M500 284l50-84M720 282l42-72M820 284l40-70" stroke="#FBF6EA" stroke-width="5" opacity=".8"/>`;
  if(!O.art) h+=`<text x="670" y="188" text-anchor="middle" font-family="Baloo 2, Nunito, sans-serif" font-weight="800" font-size="16" fill="${OUT}">Massage chân</text>`;
  // arch
  h+=G(`<rect x="424" y="58" width="12" height="372" fill="#FBF6EA"/>`);
  // rooms
  for(let i=0;i<4;i++){
    const x=910+i*90, ok=p? i<p.rooms : i<1;
    h+=G(`<rect x="${x}" y="58" width="7" height="372" fill="#C9B8F0"/><path d="M${x+11} 110q10 150 0 290h13q-6-160 0-290z" fill="#FAD0D8"/><rect x="${x+40}" y="146" width="16" height="22" rx="7" fill="#FBF6EA"/>`)
      +`<circle cx="${x+48}" cy="158" r="22" fill="url(#gGlow)"/><text x="${x+50}" y="100" text-anchor="middle" font-family="Baloo 2, Nunito, sans-serif" font-weight="800" font-size="14" fill="${OUT}">Phòng ${i+1}</text>`;
    if(!ok) h+=`<rect x="${x+7}" y="58" width="83" height="372" fill="#B9B6C2" opacity=".55"/>`+G(`<rect x="${x+14}" y="220" width="68" height="40" rx="8" fill="#FBF6EA"/>`)+`<text x="${x+48}" y="238" text-anchor="middle" font-family="Nunito, sans-serif" font-weight="800" font-size="10" fill="${OUT}">Không đủ</text><text x="${x+48}" y="251" text-anchor="middle" font-family="Nunito, sans-serif" font-weight="800" font-size="10" fill="${OUT}">diện tích</text>`;
  }
  h+=G(`<rect x="1270" y="58" width="7" height="372" fill="#F9C87A"/><rect x="1290" y="150" width="96" height="10" rx="3" fill="#F9C87A"/><rect x="1298" y="126" width="22" height="24" rx="5" fill="#FBF6EA"/><rect x="1326" y="130" width="22" height="20" rx="5" fill="#BFE3F7"/><rect x="1354" y="126" width="22" height="24" rx="5" fill="#F7A8B8"/>`)+`<text x="1337" y="100" text-anchor="middle" font-family="Baloo 2, Nunito, sans-serif" font-weight="800" font-size="14" fill="${OUT}">Góc khăn</text>`;
  // baseboard + planks floor (reference style)
  h+=G(`<rect x="130" y="400" width="1274" height="30" fill="#D8D6DE"/><rect x="130" y="430" width="1274" height="74" fill="#FBF1D8"/>`);
  let pl=''; for(let x=170;x<1400;x+=46) pl+=`M${x} 430v74`; h+=`<path d="${pl}" stroke="${OUT}" stroke-width="2"/>`;
  if(O.lamps) for(const lx of [540,670,800]) h+=`<ellipse cx="${lx}" cy="260" rx="70" ry="150" fill="url(#gGlow)" opacity=".5"/>`;
  h+=`<g id="lBack"></g>`;
  for(const s of SLOTS){
    const own=!!O[s.id], av=available(s), pop=popId===s.id?'pop':'';
    if(s.listOnly) continue;
    if(own) h+=`<g class="owned" data-slot="${s.id}"><g class="${pop}">${slotArt(s)}</g></g>`;
    else if(av.dep) continue;
    else if(av.space){ if(s.zone==='chan') h+=`<g class="nospace" transform="translate(${s.x},${s.y})"><rect class="hit" x="0" y="0" width="${s.w}" height="${s.h}" rx="10" style="fill:rgba(185,182,194,.35)"/><text x="${s.w/2}" y="${s.h/2}" text-anchor="middle">Hết chỗ</text></g>`; }
    else if(S.stage!=='story'){
      const small=s.w<50;
      h+=`<g class="slot" data-slot="${s.id}" tabindex="0" role="button" aria-label="Mở khoá ${esc(s.name)} giá ${fmt(s.price)}">
        <rect class="hit" x="${s.x}" y="${s.y}" width="${s.w}" height="${s.h}" rx="10"/>
        <g transform="translate(${s.x+s.w/2},${s.y+s.h/2-(small?0:8)})">${G(`<circle r="${small?9:12}" fill="#FBF6EA"/><rect x="-5" y="-1" width="10" height="8" rx="2" fill="#F9C87A"/><path d="M-3.5 -1v-3a3.5 3.5 0 0 1 7 0v3" fill="none" stroke-width="2"/>`)}</g>
        ${small?'':`<text class="price-tag" x="${s.x+s.w/2}" y="${s.y+s.h/2+20}" text-anchor="middle">${fmt(s.price)}</text>`}</g>`;
    }
  }
  h+=`<g id="lFront"></g><g id="lFx"></g>`;
  sceneEl.innerHTML=h;
  reattach();
}
function slotArt(s){
  if(s.id==='lamps') return [540,670,800].map((x,i)=>{ const y=84+i%2*12; return `<path d="M${x} 46V${y-10}" stroke="${OUT}" stroke-width="2.4"/><circle cx="${x}" cy="${y}" r="30" fill="url(#gGlow)"/>`+G(`<path d="M${x-22} ${y+6}a10 10 0 0 1 4-16 12 12 0 0 1 22-4 10 10 0 0 1 16 8 8 8 0 0 1-2 12z" fill="#FBF6EA"/>`)+`<circle cx="${x}" cy="${y+10}" r="4" fill="#FFF1B8" stroke="${OUT}" stroke-width="2"/>`; }).join('');
  if(s.id==='lights'){
    let d='M136 52', b=''; const cols=['#FFF1B8','#F7A8B8','#C9E8B8','#BFE3F7','#C9B8F0'];
    for(let x=136;x<1390;x+=48) d+=` Q${x+24} 72 ${x+48} 52`;
    for(let x=148,k=0;x<1390;x+=24,k++){ const t=((x-136)%48)/48, y=52+20*4*t*(1-t)*0.95+5; b+=`<circle cx="${x}" cy="${y.toFixed(1)}" r="4" fill="${cols[k%5]}" stroke="${OUT}" stroke-width="1.8" class="twinkle" style="animation-delay:${(-(k%7)*.25).toFixed(2)}s"/>`; }
    return `<path d="${d}" stroke="${OUT}" stroke-width="2" fill="none"/>${b}`;
  }
  return `<g transform="translate(${s.x},${s.y})">${A[s.art]}</g>`;
}
function burst(id){
  if(slot(id).listOnly) return;
  const s=slot(id), cx=s.x+s.w/2, cy=s.y+s.h/2, fx=$('#lFx'); if(!fx) return;
  let inner=`<circle cx="${cx}" cy="${cy}" r="${Math.max(s.w,s.h)*.7}" fill="url(#gGlow)" class="flash"/>`;
  const cols=['#F9C87A','#F7A8B8','#8FD3AE','#C9B8F0','#BFE3F7'];
  for(let i=0;i<14;i++){ const a=i/14*Math.PI*2, d=40+Math.random()*40;
    inner+=`<path d="M0-7L2-2 7 0 2 2 0 7-2 2-7 0-2-2z" transform="translate(${cx},${cy})" fill="${cols[i%5]}" stroke="${OUT}" stroke-width="1.5" class="spark" style="--dx:${(Math.cos(a)*d).toFixed(0)}px;--dy:${(Math.sin(a)*d).toFixed(0)}px"/>`; }
  const g=document.createElementNS('http://www.w3.org/2000/svg','g'); g.innerHTML=inner; fx.appendChild(g); setTimeout(()=>g.remove(),1300);
}
sceneEl.addEventListener('click',e=>{ const g=e.target.closest('[data-slot]'); if(g) openSlot(g.dataset.slot); });
sceneEl.addEventListener('keydown',e=>{ if((e.key==='Enter'||e.key===' ')&&e.target.closest('.slot')){ e.preventDefault(); openSlot(e.target.closest('.slot').dataset.slot); } });

function heroSVG(s){ if(!s.art) return ''; const pad=14; return `<svg viewBox="${s.x-pad-10} ${s.y-pad-14} ${Math.max(s.w,40)+pad*2+20} ${s.h+pad*2+14}">${slotArt(s)}</svg>`; }
function openSlot(id){
  const s=slot(id), own=!!S.owned[id], av=available(s);
  sheet(`<div class="item-hero">${heroSVG(s)}<div><div style="font-family:var(--font-display);font-weight:800;font-size:1.3rem;line-height:1.1">${esc(s.name)}</div><div class="note">${ZONES.find(z=>z[0]===s.zone)[1]}</div></div></div>
    <p class="note">${esc(s.desc)}</p>
    ${own?'<p><span class="tag">Đã sở hữu</span></p>':!av.ok?`<p><span class="tag grey">${av.why}</span></p>`:`<p class="note">Giá <b>${full(s.price)}</b>. Tiền mặt ${fmt(S.cash)}.</p>`}
    <div class="row"><button class="btn alt" data-x>Đóng</button>${!own&&av.ok?`<button class="btn big butter" data-buy ${S.cash<s.price?'disabled':''}>${S.cash<s.price?'Không đủ tiền':'Mua & mở khoá · '+fmt(s.price)}</button>`:''}</div>`, sh=>{
      sh.querySelector('[data-x]').onclick=closeSheet;
      const b=sh.querySelector('[data-buy]'); if(b) b.onclick=()=>{ closeSheet(); buy(id); };
    });
}
function buy(id){
  const s=slot(id); if(S.owned[id]||S.cash<s.price||!available(s).ok) return;
  S.cash-=s.price; S.owned[id]=1; addLog('Mua '+s.name,-s.price); save();
  drawScene(id); burst(id); renderTop(); renderPane(); toast(`Đã mở khoá ${s.name}!`,'good');
}

const NS='http://www.w3.org/2000/svg';
function setPos(w,x,y,dur){
  w.x=x; w.y=y; const d=dur?dur/Math.max(speed,1):0;
  w.el.style.transition=d?`transform ${d}s linear`:'none';
  w.el.style.transform=`translate(${x}px,${y}px)`;
  w.walkT=dur||0; w.el.classList.toggle('walking',!!dur);
}
function walkTo(w,[x,y]){ const dist=Math.hypot(x-w.x,y-w.y); setPos(w,x,y,Math.max(.25,dist/150)); }
function layerOf(w){ return document.getElementById(w.layer==='back'?'lBack':'lFront'); }
function fxText(x,y,txt,cls){ const fx=$('#lFx'); if(!fx) return; const t=document.createElementNS(NS,'text'); t.setAttribute('x',x); t.setAttribute('y',y); t.setAttribute('text-anchor','middle'); t.setAttribute('class','floaty '+(cls||'')); t.textContent=txt; fx.appendChild(t); setTimeout(()=>t.remove(),1600); }
const EMO={heart:G('<path d="M0 8S-9 2-9-4a4.5 4.5 0 0 1 9-2 4.5 4.5 0 0 1 9 2c0 6-9 12-9 12z" fill="#F7A8B8"/>'),
  smile:G('<circle r="8" fill="#FBD796"/>')+`<path d="M-4 1q4 4 8 0" stroke="${OUT}" stroke-width="1.8" fill="none"/><circle cx="-3" cy="-2" r="1.3" fill="${OUT}"/><circle cx="3" cy="-2" r="1.3" fill="${OUT}"/>`,
  angry:G('<path d="M-9 4a5 5 0 0 1 1-9 7 7 0 0 1 13-1 5 5 0 0 1 3 10z" fill="#D8D6DE"/>')};
function emote(w,k,ms){ ms=ms||1500; w.emoK=k; w.emoU=performance.now()+ms; const fx=$('#lFx'); if(!fx) return;   // 19a: nho cam xuc de phong ve vong lap vui/gian
  const g=document.createElementNS(NS,'g'); g.setAttribute('transform',`translate(${w.x},${w.y-88})`); g.innerHTML=`<g class="emo">${EMO[k]}</g>`; fx.appendChild(g); setTimeout(()=>g.remove(),ms); }
// 19i: khach dung lai ms mili-giay (vong vui/gian) roi moi di ra cua; khong giu quay (state da 'leave'), khach sau van vao duoc
function leaveHold(g,ms){ g.holdU=performance.now()+ms; setTimeout(()=>{ g.holdU=0; if(guests.includes(g)&&g.state==='leave') walkTo(g,P.street); },ms); }
function bubble(w,txt){
  if(w.bub) w.bub.remove();
  const fx=$('#lFx'); if(!fx) return;
  const t=txt.length>34?txt.slice(0,33)+'…':txt, wpx=Math.max(60,t.length*6.2+18);
  const g=document.createElementNS(NS,'g'); g.setAttribute('transform',`translate(${w.x},${w.y-96})`);
  g.innerHTML=`<path d="M${-wpx/2} -26h${wpx}a8 8 0 0 1 8 8v10a8 8 0 0 1-8 8H6l-6 7-6-7H${-wpx/2}a8 8 0 0 1-8-8v-10a8 8 0 0 1 8-8z" fill="#FBF6EA" stroke="${OUT}" stroke-width="2.4" stroke-linejoin="round" transform="translate(0,0)"/><text class="bubble-t" x="0" y="-9" text-anchor="middle">${esc(t)}</text>`;
  fx.appendChild(g); w.bub=g; clearTimeout(w.bubT); w.bubT=setTimeout(()=>{ g.remove(); if(w.bub===g) w.bub=null; },2600);
}

// 07-people.js — Chủ, lễ tân, quản lý, nhân viên, vị trí; kiểm tra năng lực
'use strict';
// ---------- people & positions ----------
// 10/10 Viec 16 #8 (P6): gan anh TOAN THAN nv-* cho the nhan su/tuyen/chu tiem (avatarMini uu tien __nv).
// Chu tiem = le tan ao dai, thu ngân = le tan, quan ly = KTV nam, KTV = nv-ktv-{nam|nu}-N1 dung N1.
const OWNER_LOOK=()=>({skin:S.look.skin,hair:S.look.hair,hs:'short',shirt:'#8FD3AE',pants:'#4A4458',apron:'#FBF6EA',__img:'owner',__nv:'chutiem-dung01-H1'});
const CASHIER_LOOK={skin:'#F9DCC4',hair:'#2A2226',hs:'bun',shirt:'#F7A8B8',pants:'#4A4458',apron:'#FBF6EA',__img:'recep',__nv:'nv-letan-L1'};
const MANAGER_LOOK={skin:'#EDBE98',hair:'#2A2226',hs:'short',shirt:'#BFE3F7',pants:'#4A4458',__img:'c_m',__nv:'nv-ktv-nam-N1'};
const staffLook=st=>Object.assign({},st.look,{shirt:'#C9B8F0',pants:'#4A4458',apron:'#FBF6EA',__img:['ktv','facialist','nailtech'][(st.id||0)%3],
  __nv:typeof staffMale==='function'&&staffMale(st)?'nv-ktv-nam-N1':'nv-ktv-nu-N1'});
const flyLook=()=>({skin:pick(SKINS),hair:pick(['#2A2226','#5A3B2E']),hs:pick(['bun','long','bob']),shirt:'#6E80B8',pants:'#4A4458',apron:'#F9C87A'});
const P={ street:[40,492], counter:[240,494], pay:[300,496], queue:[[178,496],[150,498],[112,498],[80,498],[52,498]],
  sofa:[[352,448],[374,448],[396,448]], stand:[[440,498],[460,498],[480,498]],
  chairG:i=>[466+i*58,440], chairW:i=>[498+i*58,494], bedG:i=>[924+i*90,392], bedW:i=>[990+i*90,494],
  ownerDesk:[240,404], ownerIdle:[418,494], cashier:[240,404], staffIdle:i=>[1292+(i%4)*26, i<4?494:474], flyWait:i=>[1240-i*22,494] };
function mkWalker(look){ const el=document.createElementNS(NS,'g'); el.setAttribute('class','walker'); el.innerHTML=`<g class="pose">${charSVG(look)}</g>`; return {el,x:0,y:0,walkT:0,layer:'front'}; }
walkTo=function(w,[x,y]){ const dist=Math.hypot(x-w.x,y-w.y); setPos(w,x,y,Math.max(.25,dist/260)); };
let guests=[], W=[], cashierEl=null, gid=1, flyCalls=[];
const ownerW=()=>W.find(w=>w.kind==='owner');
function reattach(){ [...W.map(w=>w.walker), ...(cashierEl?[cashierEl]:[]), ...guests].forEach(w=>{ const L=layerOf(w); if(L) L.appendChild(w.el); }); }
function sortFront(){ const L=$('#lFront'); if(!L) return; [...guests.filter(g=>g.layer==='front'), ...W.map(w=>w.walker).filter(w=>w.layer==='front')].sort((a,b)=>a.y-b.y).forEach(w=>L.appendChild(w.el)); }
function idlePos(w){
  if(w.kind==='owner') return S.cashier? P.ownerIdle : P.ownerDesk;
  if(w.kind==='staff'){ const i=S.staff.findIndex(s=>s.id===w.id); return P.staffIdle(Math.max(0,i)); }
  return P.flyWait(W.filter(x=>x.kind==='fly').indexOf(w));
}
function goIdle(w){ w.state='idle'; w.walker.el.classList.remove('working'); const p=idlePos(w);
  w.walker.layer=(w.kind==='owner'&&!S.cashier)?'back':'front'; const L=layerOf(w.walker); if(L) L.appendChild(w.walker.el); walkTo(w.walker,p); }
function ensureWorkers(){
  if(!S.prem) return;
  if(!ownerW()){ const wk=mkWalker(OWNER_LOOK()); W.push({kind:'owner',id:'owner',walker:wk,state:'idle'}); setPos(wk,...(S.cashier?P.ownerIdle:P.ownerDesk)); wk.layer=S.cashier?'front':'back'; }
  S.staff.forEach((st,i)=>{ if(!W.find(w=>w.kind==='staff'&&w.id===st.id)){ const wk=mkWalker(staffLook(st)); W.push({kind:'staff',id:st.id,walker:wk,state:'idle'}); setPos(wk,...P.staffIdle(i)); } });
  W=W.filter(w=>{ if(w.kind==='staff' && !S.staff.find(s=>s.id===w.id)){ w.walker.el.remove(); return false; } return true; });
  if(S.cashier && !cashierEl){ cashierEl=mkWalker(CASHIER_LOOK); cashierEl.layer='back'; setPos(cashierEl,...P.cashier); }
  if(!S.cashier && cashierEl){ cashierEl.el.remove(); cashierEl=null; }
  const o=ownerW(); if(o.state==='idle') { o.walker.layer=S.cashier?'front':'back'; setPos(o.walker,...idlePos(o)); }
  reattach();
}

// ---------- capability ----------
const ownedChairs=()=>{ const p=prem(); return SLOTS.filter(s=>s.zone==='chan'&&S.owned[s.id]&&s.seat<(p?p.chairs:0)).map(s=>s.seat); };
const ownedBeds=()=>{ const p=prem(); return SLOTS.filter(s=>s.id.startsWith('room')&&S.owned[s.id]&&s.need<(p?p.rooms:0)).map(s=>s.need); };
const decorBonus=()=>SLOTS.filter(s=>s.zone==='dc'&&S.owned[s.id]).length*2;
function hasStation(k){ const sv=SERVICES[k]; if(sv.item && !S.owned[sv.item]) return false; return sv.st==='chair'? ownedChairs().length>0 : ownedBeds().length>0; }
function someoneKnows(k){ return !!S.skills[k] || S.staff.some(s=>s.skills[k]); }
const canOffer=k=>hasStation(k) && (someoneKnows(k) || S.auto.fly);
const supNeed=(k,key)=>{ let u=SUP[key].use(k); if(key==='towel'&&S.owned.towel) u*=.5; return u; };
const hasSupplies=k=>SUPK.every(key=>S.stock[key]>=supNeed(k,key)-1e-9);
const staffOf=w=>w&&w.kind==='staff'?S.staff.find(s=>s.id===w.id):null;
const lvOf=(w,k)=> w.kind==='owner'? (S.skills[k]?S.skills[k].lv:0) : w.kind==='fly'? (w.spec===k?5:3) : ((staffOf(w)||{skills:{}}).skills[k]||0);
let busyChair={}, busyBed={};
const stName=st=>st.t==='chair'?'Ghế '+(st.i+1):'Giường '+(st.i+1);
function freeStation(k){ const sv=SERVICES[k];
  if(sv.st==='chair'){ const c=ownedChairs().find(i=>!busyChair[i]); return c===undefined?null:{t:'chair',i:c}; }
  const b=ownedBeds().find(i=>!busyBed[i]); return b===undefined?null:{t:'bed',i:b}; }
const stationFree=st=>st.t==='chair'? (ownedChairs().includes(st.i)&&!busyChair[st.i]) : (ownedBeds().includes(st.i)&&!busyBed[st.i]);
function holdStation(st,v){ if(st.t==='chair') busyChair[st.i]=v; else busyBed[st.i]=v; }
function freeStationOf(st){ if(!st) return; if(st.t==='chair') delete busyChair[st.i]; else delete busyBed[st.i]; }
const WK=DAY/200; // hệ số quy đổi thời gian chờ
// Khách tăng dần đều: tiệm mới ít người biết, càng mở lâu, phục vụ càng nhiều, càng được đánh giá tốt thì càng đông
// Độ biết tới của tiệm: tăng theo ngày mở cửa và lượt khách, tối đa 1 (cả khu đều biết tiệm)
const fame=()=>clamp(0.35+(S.day-1)*0.05+S.totals.served/600,0.35,1);
// Trong ngày: trưa vắng, chiều tối đông nhất (17h–23h), khuya thưa dần
function hourCurve(){ const h=(10+S.time*GMIN/60)%24; return h<12?.6:h<17?.85:h<23?1.35:.8; }

// 08-dayflow-haggle.js — Luồng ngày (mở cửa, sinh khách theo độ nổi tiếng) + trả giá ở quầy
'use strict';
// ---------- day flow ----------
let spawnT=3, haggling=null, returnQueue=[], uiT=0, timers=[];
const seats=[null,null,null], stands=[null,null,null];
function later(t,fn){ timers.push({t,fn}); }
function startDay(){
  S.stage='open'; S.time=0; S.stats=freshStats(); spawnT=3;
  returnQueue=[]; for(let i=0;i<S.returning;i++) returnQueue.push({t:6+i*14,kind:'ret'}); for(let i=0;i<S.referrals;i++) returnQueue.push({t:12+i*16,kind:'ref'});
  returnQueue.sort((a,b)=>a.t-b.t); S.returning=0; S.referrals=0;
  busyChair={}; busyBed={}; flyCalls=[];
  S.staff.forEach(s=>s.done=0);
  save(); drawScene(); ensureWorkers(); renderAll();
}
function pickType(){ const m=prem().mix, r=Math.random(); return r<m[0]?'dp':r<m[0]+m[1]?'dl':'tay'; }
function pickWant(){ let r=Math.random()*SK.reduce((a,k)=>a+SERVICES[k].w,0); for(const k of SK){ r-=SERVICES[k].w; if(r<=0) return k; } return 'foot'; }
function spawn(kind){
  const type=pickType();
  const q=guests.filter(g=>['queue','toQueue'].includes(g.state)).length;
  if(q>=P.queue.length){ S.stats.lost++; return; }
  const look=lookFor(type), w=mkWalker(look); w.id=gid++; w.type=type; w.look=look; w.kind=kind||'new';
  w.want=pickWant(); if(kind==='ret'){ const opts=SK.filter(canOffer); if(opts.length) w.want=pick(opts); }
  w.M=market(w.want)*rnd(...CTYPES[type].f)*(kind==='ref'?1.15:1);
  w.wait=0; w.qwait=0; w.layer='front'; guests.push(w);
  setPos(w,...P.street); const L=layerOf(w); if(L) L.appendChild(w.el);
  w.state='toQueue'; relineQueue();
}
function relineQueue(){ let idx=0; for(const g of guests){ if(g.state==='queue'||g.state==='toQueue'){ g.qi=idx; walkTo(g,P.queue[idx]); g.state='toQueue'; idx++; } } }
const counterBusy=()=>guests.some(g=>['atCounter','toCounter'].includes(g.state));
function freeSeat(){ let i=seats.findIndex(x=>x===null); if(i>=0) return {kind:'sofa',i}; i=stands.findIndex(x=>x===null); if(i>=0) return {kind:'stand',i}; return null; }
function arriveCounter(g){
  g.state='atCounter'; const T=CTYPES[g.type], sname=SERVICES[g.want].name;
  if(!canOffer(g.want)){ bubble(g, g.type==='tay'?`Do you have ${sname}?`:`Có ${sname} không em?`); later(1.6,()=>{ if(!guests.includes(g)) return; bubble(g,T.none); S.stats.missed++; reject(g); }); return; }
  if(!hasSupplies(g.want)){ bubble(g,`Có ${sname} không em?`); later(1.4,()=>{ if(!guests.includes(g)) return; bubble(g,'Hết đồ rồi hả? Thôi chị về.'); toast('Thiếu vật tư, khách bỏ về! Vào Mua sắm để nhập hàng.','warn'); S.stats.missed++; reject(g); }); return; }
  if(!freeSeat()){ bubble(g, g.type==='tay'?'Too busy… bye!':'Đông quá, thôi để bữa khác.'); S.stats.lost++; reject(g); return; }
  if(g.kind==='ret'){ bubble(g,'Như hôm qua nha em!'); later(1.1,()=>deal(g,priceOf(g.want),false)); return; }
  if(S.cashier && !S.selfHaggle){ autoHaggle(g); return; }
  openHaggle(g);
}
function autoHaggle(g){
  const T=CTYPES[g.type], P0=priceOf(g.want), lv=S.cashier.lv;
  bubble(g,pick(T.ask).replace('{S}',SERVICES[g.want].name));
  later(1.4,()=>{ if(!guests.includes(g)) return; const f=0.8+0.04*lv;
    if(P0<=g.M){ bubble(g,pick(T.ok)); deal(g, r10(Math.min(P0, Math.max(P0*f, g.M*f))), false); }
    else if(Math.random()<0.4+0.12*lv){ const price=r10(Math.min(P0,g.M*f)); bubble(g,pick(T.ok)); deal(g,price,price>0.92*g.M); }
    else { bubble(g,pick(T.no)); S.stats.lost++; reject(g); } });
}
function deal(g,price,squeezed){
  if(!guests.includes(g) || g.state!=='atCounter') return;   // chặn hẹn giờ cũ chốt lại khách đã ngồi
  g.price=price; g.squeezed=squeezed; S.stats.deals++;
  const s=freeSeat(); if(!s){ S.stats.lost++; reject(g); return; }
  if(s.kind==='sofa') seats[s.i]=g.id; else stands[s.i]=g.id;
  g.seat=s; g.state='toSeat'; walkTo(g, s.kind==='sofa'?P.sofa[s.i]:P.stand[s.i]);
  relineQueue();
}
function reject(g){ const atC=g.state==='atCounter'||g.state==='toCounter'; freeSeatOf(g); if(g.resSt){ freeStationOf(g.resSt); g.resSt=null; } g.state='leave'; if(atC){ emote(g,'angry',1900); leaveHold(g,1900); } else { emote(g,'angry'); walkTo(g,P.street); } relineQueue(); }
function freeSeatOf(g){ if(!g.seat) return; if(g.seat.kind==='sofa') seats[g.seat.i]=null; else stands[g.seat.i]=null; g.seat=null; }
function promoteStand(){ stands.forEach((id,i)=>{ if(id===null) return; const si=seats.findIndex(x=>x===null); if(si<0) return; const g=guests.find(x=>x.id===id); if(!g){ stands[i]=null; return; } stands[i]=null; seats[si]=g.id; g.seat={kind:'sofa',i:si}; walkTo(g,P.sofa[si]); g.state='toSeat'; }); }

// ---------- haggle ----------
// Thông số trả giá theo từng khách (15v ghi đè theo tính cách): số lượt, mức ra giá đầu, bước nâng giá, ngưỡng đồng ý ngay, ngưỡng bỏ đi
let hgP=g=>({maxR:3, open:[.72,.88], step:[.4,.6], instant:.85, walk:9});
function openHaggle(g){
  const T=CTYPES[g.type], P0=priceOf(g.want), sname=SERVICES[g.want].name;
  haggling={g, ask:P0, round:1, chat:[]};
  haggling.chat.push(['c',pick(T.ask).replace('{S}',sname)]); haggling.chat.push(['o',`${sname} ${SERVICES[g.want].min} phút giá ${fmt(P0)} ạ.`]);
  if(g.kind==='ref') haggling.chat.push(['c','Bạn chị giới thiệu qua đó em.']);
  if(P0<=g.M*hgP(g).instant){ haggling.chat.push(['c',pick(T.ok)]); renderHaggle(true); setTimeout(()=>{ if(haggling&&haggling.g===g) closeHaggle(); deal(g,P0,false); },900); return; }
  haggling.offer=r10(Math.min(P0,g.M)*rnd(...hgP(g).open)); if(haggling.offer>=P0) haggling.offer=r10(P0*0.9);
  const t=pick(T.counter).replace('{O}',fmt(haggling.offer)); haggling.chat.push(['c',t]); bubble(g,t);
  renderHaggle();
}
function moodOf(h){ const r=h.ask/h.g.M; return r<=1?['g','Có vẻ sẵn lòng']:r<=1.15?['m','Đang lưỡng lự']:['b','Nhăn mặt, sắp bỏ đi']; }
function renderHaggle(done){
  const box=$('#haggle'); if(!haggling){ box.hidden=true; return; }
  const h=haggling, g=h.g, T=CTYPES[g.type], mid=r10((h.offer+h.ask)/2), md=moodOf(h);
  box.hidden=false;
  box.innerHTML=`<div class="hg-head">${portrait(g)}<div style="flex:1;min-width:0"><div class="n">Khách trả giá · ${SERVICES[g.want].name}</div><span class="chip ${T.chip}">${T.name}</span> <span class="note">niêm yết ${fmt(priceOf(g.want))}</span></div>
    <div style="text-align:right"><div class="note">Lượt ${h.round}/${hgP(g).maxR}</div><div class="mood ${md[0]}">${md[1]}</div></div></div>
    <div class="chat">${h.chat.slice(-4).map(([w,t])=>`<div class="msg ${w}">${esc(t)}</div>`).join('')}</div>
    ${done?'':`<div class="hg-actions"><button class="btn mint" data-h="offer">Đồng ý ${fmt(h.offer)}</button>${mid>h.offer&&mid<h.ask?`<button class="btn butter" data-h="mid">Chốt ${fmt(mid)}</button>`:''}<button class="btn" data-h="hold">Giữ ${fmt(h.ask)}</button></div>`}`;
}
$('#haggle').addEventListener('click',e=>{
  const b=e.target.closest('[data-h]'); if(!b||!haggling) return;
  const h=haggling, g=h.g, T=CTYPES[g.type];
  const X = b.dataset.h==='offer'? h.offer : b.dataset.h==='mid'? r10((h.offer+h.ask)/2) : h.ask;
  h.chat.push(['o', b.dataset.h==='offer'?`Dạ được, ${fmt(X)} nha.`: b.dataset.h==='mid'?`Em bớt còn ${fmt(X)}, chốt nha?`:`Giá này tốt nhất rồi ạ, ${fmt(X)}.`]);
  if(X<=h.offer || X<=g.M){ h.chat.push(['c',pick(T.ok)]); renderHaggle(true); setTimeout(()=>{ if(haggling&&haggling.g===g) closeHaggle(); deal(g,X,X>h.offer&&X>0.92*g.M); },800); return; }
  h.ask=X; h.round++;
  if(h.round>hgP(g).maxR || X>g.M*hgP(g).walk){ const t=pick(T.no); h.chat.push(['c',t]); renderHaggle(true); setTimeout(()=>{ if(haggling&&haggling.g===g) closeHaggle(); if(g.state!=='atCounter') return; bubble(g,t); S.stats.lost++; reject(g); },900); return; }
  h.offer=r10(Math.min(g.M, h.offer+(g.M-h.offer)*rnd(...hgP(g).step))); if(h.offer>=h.ask) h.offer=r10(h.ask-10000);
  const t=pick(T.raise).replace('{O}',fmt(h.offer)); h.chat.push(['c',t]); bubble(g,t); renderHaggle();
});
function closeHaggle(){ haggling=null; renderHaggle(); }

// 09-service.js — Phân khách, làm dịch vụ, hao vật tư, kết thúc dịch vụ, tip, sự cố khách
'use strict';
// ---------- service ----------
function useSupplies(k){ SUPK.forEach(key=>{ S.stock[key]=Math.max(0,S.stock[key]-supNeed(k,key)); }); }
function dispatch(w,g,st){
  holdStation(st,g.id); freeSeatOf(g); g.station=st; g.worker=w; g.state='toStation'; g.arr=false; w.arr=false; g.resSt=null;
  w.state='toStation'; w.guest=g; w.walker.layer='front'; const L=layerOf(w.walker); if(L) L.appendChild(w.walker.el);
  walkTo(g, st.t==='chair'?P.chairG(st.i):P.bedG(st.i)); walkTo(w.walker, st.t==='chair'?P.chairW(st.i):P.bedW(st.i));
  const lv=lvOf(w,g.want), stf=staffOf(w);
  let f=(1-0.07*(lv-1));
  if(stf){ f*=(1-(stf.st.s-5)*0.04); if(stf.lazy) f*=1.15; if((stf.done||0)>stf.st.e*2+4) f*=1.15; }
  g.dur=(SERVICES[g.want].min/SVC_SPEED)/GMIN*f; g.svc=0;
  useSupplies(g.want);
  promoteStand();
}
function assign(){
  for(const g of guests.filter(g=>g.state==='seated'&&g.flyW&&g.flyW.state==='idle')){ const st=g.resSt; if(st){ dispatch(g.flyW,g,st); } }
  const waiting=guests.filter(g=>g.state==='seated'&&!g.flyRes).sort((a,b)=>b.wait-a.wait);
  for(const g of waiting){
    if(!hasSupplies(g.want)) continue;
    const st=freeStation(g.want); if(!st) continue;
    const cands=W.filter(w=>w.state==='idle'&&w.kind!=='fly'&&lvOf(w,g.want)>0 && !(g.want==='stone'&&lvOf(w,'body')<1));
    if(!cands.length){ if(S.auto.fly && g.wait>8*WK && !g.flyRes) postFly(g,st,true); continue; }
    cands.sort((a,b)=>lvOf(b,g.want)-lvOf(a,g.want) || (a.kind==='owner'?1:-1));
    dispatch(cands[0],g,st);
  }
}
function arriveService(g){ if(g.arr && g.worker && g.worker.arr){ g.state='service'; g.worker.state='busy'; g.worker.walker.el.classList.add('working'); if(g.station.t==='bed') g.el.classList.add('lying'); } }
function finishService(g){
  const w=g.worker, lv=lvOf(w,g.want), stf=staffOf(w), bed=g.station.t==='bed';
  let sat=53+lv*7+decorBonus()+(S.owned.tea?4:0)+(S.owned.towel?3:0)+(bed?(S.owned.changing?6:-6):0)-Math.min(20,g.wait/WK*0.45)-(g.squeezed?6:0)-(window.CDEM&&CDEM.satPen?CDEM.satPen():0)+rnd(-5,5);
  if(stf){ sat+=(stf.morale-60)/6+(stf.st.q-5)*2.5; if(stf.lazy) sat-=12; if((stf.done||0)>stf.st.e*2+4) sat-=8; if(stf.taught&&stf.taught[g.want]) sat+=4; }
  if(w.kind==='fly') sat+= w.spec===g.want?14:5;
  sat=clamp(sat,0,100); g.sat=sat;
  const tr=CTYPES[g.type].tip; let q=w.kind==='fly'?1.4:1; if(stf) q*=1+(stf.st.c-5)*0.06;
  let tip=0; if(sat>=80) tip=r10(g.price*tr[0]*q); else if(sat>=65 && tr[1]) tip=r10(g.price*tr[1]*q);
  if(g.type==='dp' && Math.random()<.5) tip=0;
  g.tip=tip; g.flyFee = w.kind==='fly'? r10(g.price*FLY_FEE):0;
  g.comm = (w.kind==='fly' && g.want==='foot' && w.spec==='foot')? r10(g.price*FLY_COMMISSION):0;
  if(w.kind==='owner'){ S.xp+=5; const sk=S.skills[g.want]; sk.exp=(sk.exp||0)+10; if(sk.lv<5 && sk.exp>=sk.lv*60){ sk.exp-=sk.lv*60; sk.lv++; toast(`Chủ tiệm lên cấp ${sk.lv} ${SERVICES[g.want].name}!`,'good'); } }
  if(stf){ stf.done=(stf.done||0)+1; stf.xp=(stf.xp||0)+10;
    if(stf.xp>=stf.lvl*60 && stf.lvl<10){ stf.xp-=stf.lvl*60; stf.lvl++; const low=STK.reduce((a,k)=>stf.st[k]<stf.st[a]?k:a,STK[0]); if(stf.st[low]<10) stf.st[low]++; toast(`${stf.name} lên cấp ${stf.lvl}: ${STATS[low]} +1 (bù điểm yếu).`,'good'); }
    const L=stf.skills[g.want]; stf.sexp=stf.sexp||{}; stf.sexp[g.want]=(stf.sexp[g.want]||0)+10; if(L<5 && stf.sexp[g.want]>=L*80){ stf.sexp[g.want]-=L*80; stf.skills[g.want]=L+1; }
    S.staffDoneSinceIssue=(S.staffDoneSinceIssue||0)+1; if(S.staffDoneSinceIssue>=10){ S.staffDoneSinceIssue=0; g.problem=pick(PROBLEMS); } }
  freeStationOf(g.station); g.el.classList.remove('lying'); w.walker.el.classList.remove('working');
  if(w.kind==='fly'){ w.state='leaving'; walkTo(w.walker,P.street);
    groupMsg(w.name, `Xong ${stName(g.station)} rồi nha chị! Công ${fmt(g.flyFee)} + tip ${fmt(g.tip)}${g.comm?`, gửi quán hoa hồng ${fmt(g.comm)}`:''}.`); }
  else goIdle(w);
  g.worker=null; g.state='toPay'; walkTo(g,P.pay);
}
function problemSheet(g,done){
  const pb=g.problem;
  if(S.manager){ const good=Math.random()<.7; if(good){ toast('Quản lý ca đã xử lý êm: '+pb.t,'good'); } else { g.price=r10(g.price*.9); toast('Quản lý ca xử lý tạm được, giảm giá cho khách.'); } g.problem=null; done(); return; }
  const opts=[...pb.o].sort(()=>Math.random()-.5);
  sheet(`<h2>Khách gặp vấn đề!</h2><div class="scene-s">${portrait(g)}<p><b>${esc(pb.t)}</b><br><span class="note">Xử lý êm xuôi, khách không phản hồi xấu thì chủ tiệm được +10 điểm nghề.</span></p></div>
    <div class="list">${opts.map((o,i)=>`<button class="btn alt" style="text-align:left;white-space:normal" data-o="${o[1]}">${esc(o[0])}</button>`).join('')}</div>`, sh=>{
    sh.querySelectorAll('[data-o]').forEach(b=>b.onclick=()=>{ const sc=+b.dataset.o; closeSheet();
      if(sc===2){ S.xp+=10; S.solved=(S.solved||0)+1; toast('Xử lý êm xuôi! +10 điểm nghề.','good'); }
      else if(sc===1){ g.price=r10(g.price*(pb.t.includes('mạnh')?0.8:0.9)); toast('Khách tạm hài lòng, không được điểm nghề.'); }
      else { g.sat=25; g.tip=0; toast('Khách bực mình, để lại đánh giá xấu.','warn'); }
      g.problem=null; done(); });
  });
}
function pay(g){
  if(g.problem){ problemSheet(g,()=>pay(g)); return; }
  const toShop=g.price-g.flyFee+g.comm+(g.flyFee?0:g.tip);
  S.cash+=toShop; S.stats.rev+=g.price; if(!g.flyFee) S.stats.tips+=g.tip; S.stats.served++; S.stats.fly+=g.flyFee; S.stats.comm+=g.comm;
  S.stats.by[g.want]=(S.stats.by[g.want]||0)+1; S.stats.byRev[g.want]=(S.stats.byRev[g.want]||0)+g.price;
  S.totals.served++; S.totals.rev+=g.price; S.totals.tips+=g.flyFee?0:g.tip; if(g.kind==='ret') S.retServed++;
  fxText(g.x,g.y-100,'+'+fmt(g.price)); if(g.tip) setTimeout(()=>fxText(g.x,g.y-84,(g.flyFee?'tip thợ bay ':'tip +')+fmt(g.tip),'tip'),250);
  emote(g, g.sat>=78?'heart':g.sat>=50?'smile':'angry',1900);
  S.sats=(S.sats||[]).concat(Math.round(g.sat)).slice(-30);
  const fb=g.flyFee?0.2:0, nm=g.type==='tay'?pick(['Anna','Tom','Lucas','Mia','Noah']):pick(['chị '+pick(NAMES_NU),'anh '+pick(NAMES_NAM),'cô '+pick(NAMES_NU)]);
  if(g.sat>=85 && Math.random()<.25+fb){ S.returning++; inboxMsg(nm, g.type==='tay'?'Great massage! I will come back tomorrow.':'Mai ghé lại nha em, làm '+SERVICES[g.want].name.toLowerCase()+' đã lắm.'); bubble(g, g.type==='tay'?'See you tomorrow!':'Mai quay lại nha!'); }
  if(g.sat>=90 && Math.random()<.2+fb){ S.referrals++; inboxMsg(nm, g.type==='tay'?'I told my friend about your spa!':'Mai dẫn bạn qua làm luôn nha em.'); }
  g.state='leave'; leaveHold(g,1900); renderTop(); if(tab==='shop') renderScreen();
}

// 10-fly-group.js — Nhóm Bay Spa: đăng tin, thợ bay trả lời, like để chọn, phí/hoa hồng
'use strict';
// ---------- nhóm bay ----------
const unread={group:false,inbox:false};
let msgId=1;
function groupMsg(who,t,me,extra){ const m=Object.assign({id:msgId++,who,t,me:!!me},extra||{}); S.group.push(m); S.group=S.group.slice(-50); if(tab!=='phone'||phoneTab!=='group') unread.group=true; renderNav(); if(tab==='phone') renderScreen(); return m; }
function inboxMsg(who,t,ic){ S.inbox.push(ic?{who,t,ic}:{who,t}); S.inbox=S.inbox.slice(-40); if(tab!=='phone'||phoneTab!=='inbox') unread.inbox=true; renderNav(); if(tab==='phone') renderScreen(); }
const specLabel=k=>({foot:'giỏi chân',neck:'giỏi cổ vai gáy',body:'giỏi body',thai:'giỏi Thái',stone:'giỏi đá nóng'})[k];
function postFly(g,st,auto){
  if(!g||!st||!stationFree(st)){ toast('Ghế hoặc giường đó không trống.','warn'); return false; }
  if(SERVICES[g.want].st!==st.t){ toast('Dịch vụ này không làm ở chỗ đó.','warn'); return false; }
  holdStation(st,'res'+g.id); g.resSt=st; g.flyRes=true;
  const req=groupMsg(S.owner||'Chủ tiệm', `Cần 1 thợ ${SERVICES[g.want].name.toLowerCase()} ở ${S.name}, khách ngồi ${stName(st)} nha. Ai rảnh thả 1.`, true, {req:true});
  const peak=S.time>DAY*.35&&S.time<DAY*.8, n=Math.random()<(peak?.25:.08)?0:1+Math.floor(Math.random()*(peak?2:3));
  const pool=[...FLY_POOL].sort(()=>Math.random()-.5).slice(0,n);
  pool.forEach((f,i)=>flyCalls.push({t:rnd(1.2,4)+i*1.3, g, req:req.id, name:f[0], spec:f[1]}));
  if(!n) flyCalls.push({t:5, g, req:req.id, none:true});
  flyCalls.push({t:14, g, req:req.id, timeout:true});
  if(!auto) toast('Đã đăng tin, chờ thợ bay trả lời rồi thả tim để chọn.');
  return true;
}
function likeFly(mid){
  const m=S.group.find(x=>x.id===mid); if(!m||!m.reply||m.liked) return;
  const g=guests.find(x=>x.id===m.gid); if(!g||g.state!=='seated'||g.flyW){ toast('Khách này đã có người làm hoặc đã về.','warn'); return; }
  m.liked=true; S.group.filter(x=>x.req===m.req&&x.reply&&x!==m).forEach(x=>x.passed=true);
  const name=m.who; groupMsg(name, `Em tới liền nha chị, ${stName(g.resSt)}!`);
  const wk=mkWalker(flyLook()); const w={kind:'fly',id:'f'+gid++,walker:wk,state:'toWait',name,spec:m.spec}; W.push(w); g.flyW=w;
  setPos(wk,...P.street); const L=layerOf(wk); if(L) L.appendChild(wk.el); walkTo(wk,idlePos(w)); S.flyUsed++;
  if(tab==='phone') renderScreen();
}
function resolveFlyCall(c){
  const g=c.g;
  if(c.timeout){ if(guests.includes(g)&&g.flyRes&&!g.flyW){ g.flyRes=false; if(g.resSt){ freeStationOf(g.resSt); g.resSt=null; } } return; }
  if(!guests.includes(g)||g.state!=='seated'||g.flyW) return;
  if(c.none){ groupMsg(pick(FLY_POOL)[0]+' ('+specLabel(pick(SK))+')','Giờ này tụi em kín khách hết rồi chị ơi.'); return; }
  const m=groupMsg(`${c.name} (${specLabel(c.spec)})`, Math.random()<.6?'1':'.', false, {reply:true, req:c.req, gid:g.id, spec:c.spec});
  if(S.auto.fly){ later(1.5,()=>{ const reps=S.group.filter(x=>x.req===c.req&&x.reply&&!x.liked&&!x.passed); if(!reps.length||g.flyW) return; const best=reps.find(x=>x.spec===g.want)||reps[0]; likeFly(best.id); }); }
}

// 11-tick.js — Vòng lặp thời gian, tự nhập vật tư, kết thúc ngày, lương
'use strict';
// ---------- tick ----------
let hintRestock=0;   // 19r: gợi ý 1 lần/phiên khi vật tư <20% mà chưa bật tự nhập (không tự bật)
function autoRestock(){
  if(!S.auto.restock){ if(!hintRestock&&S.stage==='open'&&SUPK.some(k=>S.stock[k]<SUP[k].cap*.2)){ hintRestock=1; toast('Vật tư sắp hết. Có thể bật "Tự nhập vật tư" ở Sổ sách › Cài đặt.','warn'); } return; }
  SUPK.forEach(k=>{ const s=SUP[k]; if(S.stock[k]<s.cap*.25){ const cr=typeof SUP_CREDIT!=='undefined'?SUP_CREDIT:0, retail=cr&&S.cash-Math.round(s.price*1.05)<-cr, c=Math.round(s.price*(retail?1.35:1.05)); if(S.cash-c>=-cr||retail){ S.cash-=c; S.stock[k]=Math.min(s.cap,S.stock[k]+s.batch); S.stats.sup+=c; addLog(`${retail?'Mua lẻ ngoài chợ (giá cao)':'Tự nhập'} ${s.name} (${s.batch} ${s.unit})`,-c); } } });
}
function tick(dt){
  if(S.stage!=='open' || haggling || !$('#sheetBg').hidden) return;
  S.time=Math.min(DAY,S.time+dt);
  for(const t of timers.slice()){ t.t-=dt; if(t.t<=0){ timers.splice(timers.indexOf(t),1); t.fn(); } }
  if(S.time<OPEN_END){
    spawnT-=dt; if(spawnT<=0){ spawn('new'); const stations=ownedChairs().length+ownedBeds().length, target=(prem().demand||30*prem().traffic)*Math.min(1.15,.85+stations*.03)*(0.6+rating()*0.1)*fame()*hourCurve(); spawnT=OPEN_END/target*rnd(.6,1.4); }
    while(returnQueue.length && S.time>=returnQueue[0].t){ spawn(returnQueue.shift().kind); }
  }
  for(const c of flyCalls.slice()){ c.t-=dt; if(c.t<=0){ flyCalls.splice(flyCalls.indexOf(c),1); resolveFlyCall(c); } }
  for(const wk of [...guests, ...W.map(w=>w.walker)]){ if(wk.walkT>0){ wk.walkT-=dt; if(wk.walkT<=0){ wk.el.classList.remove('walking'); arrive(wk); } } }
  if(!counterBusy()){ const front=guests.find(g=>g.state==='queue'&&g.qi===0); if(front){ front.state='toCounter'; walkTo(front,P.counter); relineQueue(); } }
  for(const g of guests){ if(g.state==='seated'){ g.wait+=dt; if(g.wait/WK>55 && !g.flyW){ bubble(g, g.type==='tay'?'Waited too long…':'Chờ lâu quá, thôi về.'); S.stats.lost++; g.flyRes=false; reject(g); promoteStand(); } } }
  for(const w of W.filter(w=>w.kind==='fly'&&w.state==='idle')){ const g=guests.find(x=>x.flyW===w); if(!g){ w.state='leaving'; walkTo(w.walker,P.street); groupMsg(w.name,'Khách về rồi hả chị, thôi em về nha.'); } }
  assign();
  for(const g of guests){ if(g.state==='service'){ g.svc+=dt; if(g.svc>=g.dur) finishService(g); } }
  uiT+=dt; if(uiT>.5){ uiT=0; sortFront(); renderTop(); autoRestock(); checkMissions(); }
  if(S.time>=DAY && !guests.length && !W.some(w=>w.kind==='fly')) endDay();
}
function arrive(wk){
  const w=W.find(x=>x.walker===wk);
  if(w){
    if(w.state==='toStation'){ w.arr=true; arriveService(w.guest); }
    else if(w.state==='toWait'){ w.state='idle'; }
    else if(w.state==='leaving'){ wk.el.remove(); W=W.filter(x=>x!==w); }
    return;
  }
  const g=wk;
  if(g.state==='toQueue') g.state='queue';
  else if(g.state==='toCounter') arriveCounter(g);
  else if(g.state==='toSeat') g.state='seated';
  else if(g.state==='toStation'){ g.arr=true; arriveService(g); }
  else if(g.state==='toPay') pay(g);
  else if(g.state==='leave'){ g.el.remove(); if(g.bub) g.bub.remove(); guests=guests.filter(x=>x!==g); }
}
const daily=m=>Math.round(m*((DIFFS[S.diff]||{}).wage||1)/30);   // 20a: hệ số lương theo độ khó (chỉ Khó < 1)
function endDay(){
  S.stage='closed';
  const st=S.stats, cw=S.cashier?daily(CASHIER.monthly+CASHIER.step*(S.cashier.lv-1)):0, mw=S.manager?daily(MANAGER.monthly):0;
  const sw=S.staff.reduce((a,s)=>a+daily(s.monthly)-(s.fine||0),0);
  const kwh=Math.round(prem().kwh+3*(ownedChairs().length+ownedBeds().length)+0.8*st.served), m3=Math.round((0.6+0.05*st.served)*100)/100, elec=kwh*ELEC, water=Math.round(m3*WATER);
  S.cash-=elec+water+cw+sw+mw; st.costs+=elec+water+cw+sw+mw;
  // nến thơm cháy theo giờ mở cửa ở phòng body
  S.stock.candle=Math.max(0,S.stock.candle-ownedBeds().length*1);
  let notes='';
  if(S.cashier && S.cashier.lv>=5){ S.returning++; notes+='<div class="note">Thu ngân cấp tối đa: thêm <b>1 khách hứa sáng mai quay lại</b>.</div>'; }
  const quits=[];
  S.staff.forEach(s=>{ s.fine=0; s.morale=clamp(s.morale-2-(s.done>s.st.e*2+4?4:0),0,100); s.lazy = Math.random()<(10-s.st.d)*0.05*(s.morale<60?1.5:.5); if(s.morale<25 && Math.random()<.5) quits.push(s); });
  quits.forEach(s=>{ S.staff=S.staff.filter(x=>x!==s); notes+=`<div class="note" style="color:var(--danger)">${esc(s.name)} tinh thần quá thấp nên đã <b>xin nghỉ việc</b>.</div>`; });
  const lazy=S.staff.filter(s=>s.lazy); if(lazy.length) notes+=`<div class="note">${lazy.map(s=>esc(s.name)).join(', ')} đang <b>lơ là</b>.</div>`;
  /* v3.1: tiền thuê mặt bằng thu theo ngày sau mỗi ngày bán */ const rentDay=Math.round(prem().rent/30/1000)*1000; S.cash-=rentDay; st.costs+=rentDay; st.rent=rentDay;
  S.svcLog=(S.svcLog||[]).concat({d:S.day,by:st.by,rev:st.byRev,served:st.served,gross:st.rev+st.tips}).slice(-60);
  const gross=st.rev+st.tips+st.comm, net=gross-st.costs-st.sup; S.best=Math.max(S.best,gross);
  addLog(`Ngày ${S.day}: thu ${fmt(gross)}, chi ${fmt(st.costs+st.sup)}`, net);
  makeCands(); save(); ensureWorkers(); renderAll(); checkMissions();
  const top=Object.entries(st.by).sort((a,b)=>b[1]-a[1]).slice(0,3);
  sheet(`<h2>Đóng cửa ngày ${S.day}</h2>
    <div><div class="note">Lãi trong ngày</div><div class="big-num" style="color:${net>=0?'var(--mint-d)':'var(--danger)'}">${net>=0?'+':''}${fmt(net)}</div></div>
    <dl class="ledger"><dt>Tiền dịch vụ</dt><dd>${fmt(st.rev)}</dd><dt>Tiền tip</dt><dd>${fmt(st.tips)}</dd>${st.comm?`<dt>Hoa hồng thợ bay gửi quán</dt><dd>${fmt(st.comm)}</dd>`:''}
    <dt>Tiền điện</dt><dd>−${fmt(elec)}</dd><dt>Tiền nước</dt><dd>−${fmt(water)}</dd><dt>Tiền thuê tiệm</dt><dd>−${fmt(st.rent)}</dd>
    ${st.sup?`<dt>Tự nhập vật tư</dt><dd>−${fmt(st.sup)}</dd>`:''}${st.fly?`<dt>Công thợ bay (đã trừ vào tiền khách)</dt><dd>${fmt(st.fly)}</dd>`:''}${cw+sw+mw?`<dt>Lương (lương tháng ÷ 30)</dt><dd>−${fmt(cw+sw+mw)}</dd>`:''}
    <dt class="sum">Khách phục vụ</dt><dd class="sum">${st.served}</dd><dt>Khách chê đắt / bỏ về</dt><dd>${st.lost}</dd><dt>Hỏi dịch vụ chưa có / thiếu vật tư</dt><dd>${st.missed}</dd>
    <dt>Hẹn quay lại / giới thiệu</dt><dd>${S.returning} / ${S.referrals}</dd></dl>
    ${top.length?`<div class="note">Dịch vụ bán chạy: ${top.map(([k,n])=>`<b>${SERVICES[k].name}</b> (${n})`).join(', ')}</div>`:''}
    ${notes}
    <div class="row"><button class="btn big butter" data-go>Mở cửa ngày ${S.day+1}</button></div>`, sh=>{
      sh.querySelector('[data-go]').onclick=()=>{ S.day++; closeSheet(); startDay(); };
    });
}
let last=performance.now();
function frame(now){ const dt=Math.min(.1,(now-last)/1000); last=now; if(speed>0) tick(dt*speed); requestAnimationFrame(frame); }

// 12-staff-missions.js — Tuyển nhân viên, dạy nghề, nhiệm vụ
'use strict';
// ---------- staff ----------
// Lương cứng; phần lớn thu nhập KTV đến từ tua (TUA) và tip
const baseSalary=(sum,tc)=>Math.round((2.5e6+sum*0.1e6+(tc?1.5e6:0))/5e5)*5e5;
function makeCands(){
  S.cands=[];
  for(let i=0;i<3;i++){
    const tc=Math.random()<.35, skills={};
    if(tc){ const pool=['foot','neck','body','thai']; const a=pick(pool); let b=pick(pool); if(b===a) b='foot'; skills[a]=2+(Math.random()<.4?1:0); skills[b]=skills[b]||2; if(skills.body && Math.random()<.4) skills.stone=2; }
    else { skills.foot=1; if(Math.random()<.35) skills.neck=1; }
    const st={}; STK.forEach(k=>st[k]=Math.floor(rnd(tc?4:2,tc?9.99:7.99)));
    const sum=STK.reduce((a,k)=>a+st[k],0), monthly=baseSalary(sum,tc);
    const lk=lookFor('dp'), male=Math.random()<1/3;
    S.cands.push({id:S.nextId++, name:pick(['Nguyễn','Trần','Lê','Phạm','Võ','Đặng','Huỳnh'])+' '+pick(male?NAMES_NAM:NAMES_NU), male, rank:tc?'tc':'hv', skills, st, monthly, look:{skin:lk.skin,hair:lk.hair,hs:lk.hs}});
  }
}
if(!S.cands.length||!S.cands[0].st) makeCands();
const staffCap=()=>{ const p=prem(); return p? p.chairs+p.rooms : 0; };
const skillChips=s=>Object.entries(s.skills).map(([k,l])=>`<span class="sk">${SERVICES[k].name} ${l}</span>`).join('');
const statBars=st=>`<div class="statg">${STK.map(k=>`<span class="sl">${STATS[k]}</span><span class="sb"><i style="width:${st[k]*10}%" class="${st[k]<=3?'lo':st[k]>=8?'hi':''}"></i></span><b>${st[k]}</b>`).join('')}</div>`;
function teachSheet(id){
  const st=S.staff.find(s=>s.id===id); if(!st) return;
  const rows=SK.filter(k=>S.skills[k]).map(k=>{ const L=st.skills[k]||0, olv=S.skills[k].lv, xp=20*(L+1), cash=1e6*(L+1);
    const block = L>=5? 'Đã tối đa' : olv<=L ? `Chủ tiệm cần cấp ${L+1}+` : (k==='stone'&&!st.skills.body)?'Cần biết Massage body':null;
    return `<div class="item"><div class="grow"><div class="n">${SERVICES[k].name}</div><div class="m">${esc(st.name)}: ${L?'cấp '+L:'chưa biết'} · chủ tiệm cấp ${olv}</div></div>${block?`<span class="tag grey">${block}</span>`:`<button class="btn butter sm" data-teach="${k}" ${S.xp<xp||S.cash<cash?'disabled':''}>Dạy lên ${L+1} · ${xp} điểm nghề + ${fmt(cash)}</button>`}</div>`; }).join('');
  sheet(`<h2>Dạy nghề cho ${esc(st.name)}</h2><p class="note">Chủ tiệm chỉ dạy được kỹ năng mình đã học, tới cấp thấp hơn cấp của mình. Bạn đang có <b>${S.xp} điểm nghề</b>.</p><div class="list">${rows||'<p class="note">Chủ tiệm chưa có kỹ năng nào để dạy.</p>'}</div><div class="row"><button class="btn alt" data-x>Đóng</button></div>`, sh=>{
    sh.querySelector('[data-x]').onclick=closeSheet;
    sh.querySelectorAll('[data-teach]').forEach(b=>b.onclick=()=>{ const k=b.dataset.teach, L=st.skills[k]||0, xp=20*(L+1), cash=1e6*(L+1); if(S.xp<xp||S.cash<cash) return; S.xp-=xp; S.cash-=cash; st.skills[k]=L+1; st.taught=st.taught||{}; st.taught[k]=true; st.morale=clamp(st.morale+5,0,100); S.taught++; addLog(`Dạy ${SERVICES[k].name} cho ${st.name}`,-cash); save(); toast(`${st.name} đã học ${SERVICES[k].name} cấp ${L+1}.`,'good'); teachSheet(id); renderScreen(); });
  });
}

// ---------- missions ----------
const MISSIONS=[
 ['Khai trương tiệm', ()=>S.stage==='open'||S.day>1, 5e6], ['Phục vụ 10 lượt khách', ()=>S.totals.served>=10, 5e6], ['Thuê thu ngân', ()=>!!S.cashier, 5e6],
 ['Chủ tiệm học Cổ vai gáy', ()=>!!S.skills.neck, 5e6], ['Có 2 KTV', ()=>S.staff.length>=2, 8e6], ['Học Massage body và mở phòng body', ()=>!!S.skills.body&&ownedBeds().length>0, 10e6],
 ['Dạy nghề cho KTV', ()=>S.taught>=1, 8e6], ['Gọi thợ bay lần đầu', ()=>S.flyUsed>=1, 5e6], ['Xử lý êm 5 sự cố khách', ()=>(S.solved||0)>=5, 8e6],
 ['Doanh thu một ngày đạt 5 triệu', ()=>S.best>=5e6, 10e6], ['Đánh giá đạt 4,5 sao', ()=>S.sats.length>=10&&rating()>=4.5, 10e6], ['Phục vụ 5 lượt khách quen quay lại', ()=>S.retServed>=5, 10e6],
 ['Mở khoá phòng thay đồ', ()=>!!S.owned.changing, 10e6], ['Chủ tiệm học Massage đá nóng', ()=>!!S.skills.stone, 15e6], ['Có 5 KTV', ()=>S.staff.length>=5, 15e6],
 ['Doanh thu một ngày đạt 10 triệu', ()=>S.best>=10e6, 20e6], ['Phục vụ tổng 300 lượt khách', ()=>S.totals.served>=300, 30e6]
];
// Không ai trả tiền cho việc hoàn thành mục tiêu: thưởng bằng điểm nghề (kinh nghiệm) và hoa sen (dùng ở mini game)
const mReward=m=>({xp:Math.round(m[2]/1e5), sen:Math.max(1,Math.round(m[2]/5e6))});
const mRewardTxt=m=>{ const r=mReward(m); return `+${r.xp} điểm nghề, +${r.sen} sen`; };
function checkMissions(){
  let ch=false;
  while(S.mission<MISSIONS.length && MISSIONS[S.mission][1]()){ const m=MISSIONS[S.mission]; const rw=mReward(m); S.xp+=rw.xp; if(S.mg) S.mg.lotus=(S.mg.lotus||0)+rw.sen; S.mission++; ch=true; toast(`Hoàn thành: ${m[0]} (${mRewardTxt(m)})`,'good'); }
  if(ch){ save(); renderTop(); if(tab==='shop'||tab==='book') renderScreen(); if(S.mission>=MISSIONS.length && !S.won){ S.won=true; save(); setTimeout(()=>sheet(`<h2>Tiệm đủ điều kiện lên Resort!</h2><p>${esc(S.name)} đã hoàn thành mọi nhiệm vụ. Khu <b>Bãi Trường</b> đã mở khoá.</p><p class="note">Bản đồ Resort sẽ là phần mở rộng tiếp theo.</p><div class="row"><button class="btn big butter" data-x>Tiếp tục</button></div>`, sh=>sh.querySelector('[data-x]').onclick=closeSheet),500); } }
}

// 13-screens.js — HUD, thanh tab, các màn hình tab (Mua sắm, Nhân sự, Dịch vụ, Điện thoại, Sổ sách)
'use strict';
// 06/10 Viec 11 G.2: man ngang thap — Mua sam / Nhan su / Dich vu mo thanh sheet trai, canh tiem van chay ben phai
const LAND_Q=matchMedia('(orientation:landscape) and (max-height:600px)');
const SHEET_TABS={buy:'Mua sắm',staff:'Nhân sự',skill:'Dịch vụ'};
// 06/10 Viec 11 buoc 2: tab con. Xep the sau cung theo tieu de the (the do file khac chen vao cung duoc xep dung cho).
// [ma, nhan, regex tieu de]; regex null = nhom mac dinh (the khong khop nhom nao)
const SUBT={
  buy:[['do','Đồ đạc',null],['vt','Vật tư',/Kho vật tư/],['bt','Bảo trì',/Bảo trì/],['meo','Mèo',/Mèo trang trí/]],
  staff:[['nv','Nhân viên',null],['tuyen','Tuyển',/Ứng viên|Tuyển/],['td','Tự động',/Tự động/]],
  skill:[['gia','Bảng giá',/Bảng giá/],['hoc','Học nghề',/Kỹ năng|Học/],['chu','Chủ tiệm',null]],
};
const subSel={};
function subTabs(){ const D=$('#dyn'); if(!D) return; const def=SUBT[tab]; D.classList.toggle('has-subt',!!def); if(!def){ delete D.dataset.sub; return; }
  const cur=subSel[tab]||def[0][0], dflt=def.find(d=>!d[2])[0];
  [...D.children].forEach(el=>{ if(el.matches('.tsh-head,.subt')) return; const t=(el.querySelector('.sec-t')||el).textContent, m=def.find(d=>d[2]&&d[2].test(t)), k=m?m[0]:dflt; el.dataset.sub=k; el.hidden=k!==cur; });
  D.dataset.sub=tab+'-'+cur;
  const row=`<div class="subt" role="tablist">${def.map(([k,l])=>`<button role="tab" data-subt="${k}" aria-selected="${k===cur}">${l}</button>`).join('')}</div>`;
  const h=D.querySelector('.tsh-head'); if(h) h.insertAdjacentHTML('afterend',row); else D.insertAdjacentHTML('afterbegin',row);
  D.querySelectorAll('.card').forEach(c=>{ const n=c.querySelector(':scope > p.note'), st=c.querySelector(':scope > .sec-t'); if(n&&st&&!st.querySelector('.ib')) st.insertAdjacentHTML('beforeend','<button class="ib" data-ib aria-label="Giải thích">i</button>'); });
}
// 06/10 Viec 11 buoc 3 (G.3): man ngang thap — So sach / Dien thoai thanh 2 cot (trai 300 danh muc, phai chi tiet), an canh
const COL_TABS={book:'Sổ sách',phone:'Điện thoại'};
const colTab=()=>LAND_Q.matches&&!!S.prem&&!!COL_TABS[tab]&&(window.RM?RM.view==='room':S.roomView!=='list');
const colSel={};
const cardTitle=c=>{ const t=c.querySelector('.sec-t')||c.querySelector('summary'); return t?t.textContent.trim():''; };
const cardKey=c=>cardTitle(c).split(/[0-9·:]/)[0].trim().slice(0,32);
function twoCol(){ const D=$('#dyn'); if(!D) return; const on=colTab(); D.classList.toggle('tcol2',on); if(!on) return;
  const L=document.createElement('div'), R=document.createElement('div'); L.className='col-l'; R.className='col-r';
  const kids=[...D.children];
  if(tab==='book'){
    const stat=kids.find(c=>/^Tình hình tiệm/.test(cardTitle(c))); if(stat) L.appendChild(stat);
    const list=document.createElement('div'); list.className='col-list'; L.appendChild(list);
    const rest=kids.filter(c=>c!==stat), keys=rest.map(cardKey);
    let cur=colSel.book; if(!keys.includes(cur)) cur=keys.find(k=>/^Hôm nay/.test(k))||keys[0]; colSel.book=cur;
    rest.forEach((c,i)=>{ const k=keys[i], sel=k===cur, st=(c.querySelector('.sec-t')||c.querySelector('summary'));
      const lab=st?st.cloneNode(true):document.createElement('span'); lab.querySelectorAll('button,input,select,.ib').forEach(x=>x.remove());
      const b=document.createElement('button'); b.className='col-row'; b.dataset.col=k; b.setAttribute('aria-selected',sel); b.innerHTML=lab.innerHTML||k; list.appendChild(b);
      c.hidden=!sel; if(sel){ if(c.tagName==='DETAILS') c.open=true; c.querySelectorAll('details').forEach(d=>d.open=true); }
      R.appendChild(c); });
  } else { kids.forEach(c=>{ (c.classList.contains('seg')?L:R).appendChild(c); }); }
  D.append(L,R);
}
// 07/10 G.3 man doc: So sach = danh sach muc; bam muc -> man chi tiet truot tu phai, nut ‹ quay lai
function bookPortrait(){ const D=$('#dyn'); if(!D) return; const on=!LAND_Q.matches&&tab==='book'&&!!S.prem; D.classList.toggle('bkp',on); delete D.dataset.bkt; if(!on) return;
  const kids=[...D.children], stat=kids.find(c=>/^Tình hình tiệm/.test(cardTitle(c))), rest=kids.filter(c=>c!==stat), keys=rest.map(cardKey), cur=keys.includes(colSel.bookP)?colSel.bookP:null;
  if(!cur){ const list=document.createElement('div'); list.className='col-list card';
    rest.forEach((c,i)=>{ c.hidden=true; const st=c.querySelector('.sec-t')||c.querySelector('summary'), lab=st?st.cloneNode(true):document.createElement('span'); lab.querySelectorAll('button,input,select,.ib').forEach(x=>x.remove());
      list.insertAdjacentHTML('beforeend',`<button class="col-row" data-colp="${esc(keys[i])}">${lab.innerHTML||esc(keys[i])}<span class="chev" aria-hidden="true">›</span></button>`); });
    (stat||D.firstChild)?(stat?stat.after(list):D.prepend(list)):D.append(list);
    const bt=colSel.bookTab||'tq'; D.dataset.bkt=bt;   // 21m: 2 tab, không cuộn
    D.insertAdjacentHTML('afterbegin',`<div class="seg bk-tabs" role="tablist"><button data-bkt="tq" aria-pressed="${bt==='tq'}">Tình hình</button><button data-bkt="st" aria-pressed="${bt==='st'}">Sổ tay</button></div>`); return; }
  if(stat) stat.hidden=true;
  rest.forEach((c,i)=>{ const sel=keys[i]===cur; c.hidden=!sel; if(sel){ if(c.tagName==='DETAILS') c.open=true; c.querySelectorAll('details').forEach(d=>d.open=true); c.classList.add('bk-in'); } });
  D.insertAdjacentHTML('afterbegin',`<div class="bk-head"><button class="bk-back" data-colback aria-label="Quay lại Sổ sách">‹</button><b>${esc(cur)}</b></div>`); }
const sheetTab=()=>LAND_Q.matches&&!!S.prem&&!!SHEET_TABS[tab]&&(window.RM?RM.view==='room':S.roomView!=='list');
// ---------- header, nav, screens ----------
function rating(){ const a=S.sats||[]; if(!a.length) return 4; return clamp(a.reduce((x,y)=>x+y,0)/a.length/20,1,5); }
function clockStr(){ const m=Math.min(960,Math.floor(S.time*GMIN)), t=(600+m)%1440; return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`; }
function renderTop(){
  $('#spaName').textContent=S.name; const c=$('#cash'); c.textContent=fmt(S.cash); c.classList.toggle('neg',S.cash<0);
  $('#rating').textContent=rating().toFixed(1).replace('.',',');
  const p=prem();
  if(S.stage==='open') $('#sub').textContent=`Ngày ${S.day} · ${clockStr()}${S.time>=OPEN_END?' · ngưng nhận khách':' · mở cửa 10h–2h'}`;
  else $('#sub').textContent=p?`Ngày ${S.day} · ${S.stage==='build'?'chuẩn bị khai trương':'đóng cửa'} · ${p.name}`:'Chưa thuê mặt bằng';
}
const ICON={
 shop:'<path class="fillme" d="M4 12h20v12H4z" fill="#FBF6EA"/><path d="M2 12l3-7h18l3 7z" fill="#F9C87A"/><rect x="11" y="16" width="6" height="8" fill="#BCD7DC"/>',
 buy:'<path class="fillme" d="M5 9h18l-2 15H7z" fill="#FBF6EA"/><path d="M10 9a4 4 0 0 1 8 0" fill="none"/>',
 staff:'<circle class="fillme" cx="10" cy="10" r="4" fill="#FBF6EA"/><circle cx="19" cy="11" r="3.5" fill="#E9B8A6"/><path d="M3 24a7 7 0 0 1 14 0z" fill="#FBF6EA" class="fillme"/><path d="M14 24a5.5 5.5 0 0 1 11 0z" fill="#E9B8A6"/>',
 skill:'<path class="fillme" d="M14 3l3 7 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1z" fill="#FBF6EA"/>',
 phone:'<rect class="fillme" x="8" y="3" width="12" height="22" rx="3" fill="#FBF6EA"/><path d="M12 21h4" fill="none"/>',
 book:'<path class="fillme" d="M5 5h14a3 3 0 0 1 3 3v16H8a3 3 0 0 1-3-3z" fill="#FBF6EA"/><path d="M9 11h9M9 15h7" fill="none"/>'
};
const NAV_UI={shop:'tiem',buy:'muasam',staff:'nhansu',skill:'dichvu',phone:'dienthoai',book:'sosach'}; // 06/10 icon ve tay
const TABS=[['shop','Tiệm'],['buy','Mua sắm'],['staff','Nhân sự'],['skill','Dịch vụ'],['phone','Điện thoại'],['book','Sổ sách']];
function renderNav(){
  const low=SUPK.some(k=>S.stock[k]<SUP[k].cap*.15);
  $('#nav').innerHTML=TABS.map(([k,l])=>`<button role="tab" data-tab="${k}" aria-selected="${tab===k}">${(window.uiIco&&uiIco(NAV_UI[k],'nav-ico'))||`<svg viewBox="0 0 28 28">${G(ICON[k])}</svg>`}<span class="lb">${l}</span>${(k==='phone'&&(unread.group||unread.inbox))||(k==='buy'&&low)?'<span class="dot"></span>':''}</button>`).join('');
}
$('#nav').addEventListener('click',e=>{ const b=e.target.closest('[data-tab]'); if(!b) return; tab=b.dataset.tab; colSel.bookP=null; armed=null; if(tab==='phone') unread[phoneTab]=false; renderNav(); renderScreen(); $('#screen').scrollTop=0; $('#dyn').scrollTop=0; });
$('#dyn').addEventListener('click',e=>{ if(e.target.closest('[data-tshx]')){ tab='shop'; renderNav(); renderScreen(); return; }
  const st=e.target.closest('[data-subt]'); if(st){ subSel[tab]=st.dataset.subt; renderScreen(); $('#dyn').scrollTop=0; $('#screen').scrollTop=0; return; }
  const bk=e.target.closest('button[data-bkt]'); if(bk){ colSel.bookTab=bk.dataset.bkt; renderScreen(); $('#screen').scrollTop=0; return; }
  const cp=e.target.closest('[data-colp]'); if(cp){ colSel.bookP=cp.dataset.colp; renderScreen(); $('#screen').scrollTop=0; return; }
  if(e.target.closest('[data-colback]')){ colSel.bookP=null; renderScreen(); $('#screen').scrollTop=0; return; }
  const cr=e.target.closest('[data-col]'); if(cr){ colSel[tab]=cr.dataset.col; renderScreen(); const r=$('#dyn .col-r'); if(r){ r.scrollTop=0; r.classList.add('swap'); } return; }
  const ib=e.target.closest('[data-ib]'); if(ib){ const c=ib.closest('.card'); if(c) c.classList.toggle('show-note'); } });
LAND_Q.addEventListener('change',()=>{ if(typeof renderAll==='function') renderAll(); });
function readiness(){ const o=S.owned, ch=SLOTS.find(s=>s.zone==='chan'&&!s.noSell)||{id:'chair1'};   // 24k: ten + id lay tu bang vat pham (ten-chuan.js), de khung Khai truong chi dung mon + mo thang Mua sam
  return [{id:'cashier',ok:!!o.cashier},{id:'sofa',ok:!!o.sofa},{id:ch.id,ok:ownedChairs().length>0},{id:'towel',ok:!!o.towel}].map(r=>({id:r.id,t:TEN.slot(r.id),ok:r.ok})); }
function missionCard(full){
  if(!full){ const m=MISSIONS[S.mission]; return `<div class="card"><div class="sec-t">Nhiệm vụ <span class="note">${S.mission}/${MISSIONS.length}</span></div>${m?`<div class="mission now" style="margin-top:6px"><i></i><span>${m[0]} <span class="tag">${mRewardTxt(m)}</span></span></div>`:'<p class="note">Đã hoàn thành tất cả.</p>'}</div>`; }
  return `<div class="card"><div class="sec-t">Nhiệm vụ lên Resort <span class="note">${S.mission}/${MISSIONS.length}</span></div><div class="list" style="margin-top:6px">${MISSIONS.map((m,i)=>`<div class="mission ${i<S.mission?'done':i===S.mission?'now':''}"><i></i><span>${m[0]} · ${mRewardTxt(m)}</span></div>`).join('')}</div></div>`;
}
function autoCard(){
  const rows=[
    ['Thu ngân tự trả giá', S.cashier?'Đang chạy':'Thuê ở tab Nhân sự', !!S.cashier, null],
    ['Tự nhập vật tư khi sắp hết (có phí giao)', S.auto.restock?'Bật':'Tắt', S.auto.restock, 'restock'],
    ['Tự đăng tin và chọn thợ bay hợp sở trường', S.auto.fly?'Bật':'Tắt', S.auto.fly, 'fly'],
    ['Quản lý ca xử lý sự cố khách (chủ không được điểm nghề)', S.manager?'Đang chạy':'Thuê ở tab Nhân sự', S.manager, null]
  ];
  return `<div class="card"><div class="sec-t">Tự động hoá</div><p class="note">Bật dần từng phần để khỏi phải làm tay mọi việc.</p><div class="list" style="margin-top:6px">${rows.map(r=>`<div class="item${r[2]?'':' own'}"><div class="grow"><div class="n" style="font-size:var(--fz-than)">${r[0]}</div><div class="m">${r[1]}</div></div>${r[3]?`<label class="switch"><input type="checkbox" data-auto="${r[3]}" ${r[2]?'checked':''}></label>`:(r[2]?'<span class="tag">Có</span>':'')}</div>`).join('')}</div></div>`;
}
function renderPane(){ renderScreen(); }
function renderAll(){ renderTop(); renderNav(); renderScreen(); }
function statsTable(days){
  const logs=(S.svcLog||[]).slice(-days); const by={}, rev={}; let served=0, gross=0;
  logs.forEach(l=>{ Object.entries(l.by||{}).forEach(([k,n])=>by[k]=(by[k]||0)+n); Object.entries(l.rev||{}).forEach(([k,n])=>rev[k]=(rev[k]||0)+n); served+=l.served||0; gross+=l.gross||0; });
  const rows=Object.entries(by).sort((a,b)=>b[1]-a[1]); const max=rows.length?rows[0][1]:1;
  if(!rows.length) return '<p class="note">Chưa có dữ liệu. Chạy hết ít nhất một ngày để xem thống kê.</p>';
  return `<p class="note">${logs.length} ngày gần nhất: <b>${served}</b> lượt khách, doanh thu <b>${fmt(gross)}</b>.</p><div class="list" style="margin-top:6px">${rows.map(([k,n],i)=>`<div class="srow"><span class="sn">${i===0?'<span class="tag">Nhiều nhất</span> ':''}${SERVICES[k].name}</span><span class="sbar"><i style="width:${n/max*100}%"></i></span><span class="sv">${n} lượt · ${fmt(rev[k]||0)}</span></div>`).join('')}</div>`;
}
let statRange=1;
function shopIco(s){ // 10/10 Viec 16 #1: mot mon mot hinh - Mua sắm uu tien anh ve tay (handKeyOf), nhu Kho/canh; het anh thi ve icon danh muc
  if(!s) return '';
  if(window.CDEM&&CDEM.url(s.id)) return `<img class="ico" src="${CDEM.url(s.id)}" alt="">`;   // 19g
  if(typeof window.handKeyOf==='function'){ const k=handKeyOf(typeOfSlot(s.id)); if(k&&window.HAND_ART&&HAND_ART[k]) return `<img class="ico" src="${HAND_ART[k].file}" alt="">`; }
  return ico(SLOT_IMG[s.id]||(s.zone==='chan'?'footchair':s.id.startsWith('room')?'bed':''));
}
function renderScreen(){
  $('#sceneCard').hidden = tab!=='shop'&&!sheetTab()&&!colTab();
  const D=$('#dyn'); let h='';
  if(tab==='shop'){ /* toàn bộ tiệm nằm trong bảng #board, xem renderBoard */ }
  if(tab==='buy'){
    h+=`<div class="card"><div class="sec-t">Kho vật tư</div><p class="note">Mỗi lượt khách hao hụt vật tư theo tỷ lệ: chân dùng 1 gói thuốc ngâm + 10ml dầu, cổ vai gáy 15ml dầu, body/Thái/đá nóng 30ml dầu + ¼ cây nến, mỗi khách hỏng 0,2 khăn (có tủ hấp còn 0,1). Nến còn cháy mỗi đêm theo số phòng.</p><div class="list" style="margin-top:8px">`;
    SUPK.forEach(k=>{ const s=SUP[k], n=S.stock[k];
      h+=`<div class="item${n<s.cap*.15?' own':''}">${ico(SUP_ICON[k])}<div class="grow"><div class="n">${s.name} ${n<=0?'<span class="tag warn">Hết</span>':n<s.cap*.25?'<span class="tag warn">Sắp hết</span>':''}</div><div class="bar" style="margin-top:3px"><i style="width:${Math.min(100,n/s.cap*100)}%"></i></div><div class="m">${Math.floor(n)}/${s.cap} ${s.unit}</div></div><button class="btn butter sm" data-sup="${k}" ${S.cash<s.price||n>=s.cap?'disabled':''}>Nhập ${s.batch} ${s.unit}<br>${fmt(s.price)}</button></div>`; });
    h+=`</div><label class="switch" style="margin-top:8px"><input type="checkbox" data-auto="restock" ${S.auto.restock?'checked':''}> Tự nhập vật tư khi sắp hết (có phí giao)</label></div>`;
    ZONES.forEach(([z,label])=>{
      h+=`<div class="card"><div class="sec-t">${label}</div><div class="list" style="margin-top:8px">`;
      SLOTS.filter(s=>s.zone===z).forEach(s=>{ if(s.noSell) return; const own=S.owned[s.id], av=available(s); if(av.space) return;
        h+=`<div class="item${own?' own':''}">${shopIco(s)}<div class="grow"><div class="n">${esc(s.name)}</div></div>${own?'<span class="tag">Đã có</span>':!av.ok?`<span class="tag grey">${av.why}</span>`:`<button class="btn butter sm" data-buy="${s.id}" ${S.cash<s.price?'disabled':''}>Mua · ${fmt(s.price)}</button>`}</div>`; });
      h+='</div></div>';
    });
  }
  if(tab==='staff'){
    const c=S.cashier;
    h+=autoCard();
    h+=`<div class="card"><div class="sec-t">Thu ngân</div>`;
    if(!c) h+=`<div class="item" style="margin-top:8px">${avatarMini(CASHIER_LOOK)}<div class="grow"><div class="n">Ngọc Hân</div><div class="m">Cấp 1 · ${fmt(CASHIER.monthly)}/tháng</div></div><button class="btn butter sm" id="hireC">Thuê</button></div><p class="note" style="margin-top:6px">Đứng quầy, tự trả giá và chốt với khách.</p>`;
    else { const m=CASHIER.monthly+CASHIER.step*(c.lv-1), next=CASHIER.up[c.lv];
      h+=`<div class="item" style="margin-top:8px">${avatarMini(CASHIER_LOOK)}<div class="grow"><div class="n">Ngọc Hân · cấp ${c.lv}/5</div><div class="m">${fmt(m)}/tháng · chốt ${Math.round((0.8+0.04*c.lv)*100)}% giá · giữ khách ${Math.round((0.4+0.12*c.lv)*100)}%</div></div>${c.lv<5?`<button class="btn butter sm" id="upC" ${S.cash<next?'disabled':''}>Nâng · ${fmt(next)}</button>`:'<span class="tag">Tối đa</span>'}</div>
        <label class="switch" style="margin-top:6px"><input type="checkbox" id="selfH" ${S.selfHaggle?'checked':''}> Chủ tiệm tự trả giá</label>
        <button class="btn sm ${armed==='fireC'?'arm':'danger'}" id="fireC" style="margin-top:6px">${armed==='fireC'?'Bấm lần nữa để cho nghỉ':'Cho thu ngân nghỉ'}</button>`; }
    h+=`</div><div class="card"><div class="sec-t">Quản lý ca</div><div class="item" style="margin-top:8px">${avatarMini(MANAGER_LOOK)}<div class="grow"><div class="n">Anh Bảo</div><div class="m">${fmt(MANAGER.monthly)}/tháng · tự xử lý sự cố khách</div></div>${S.manager?`<button class="btn sm ${armed==='fireM'?'arm':'danger'}" id="fireM">${armed==='fireM'?'Xác nhận':'Cho nghỉ'}</button>`:'<button class="btn butter sm" id="hireM">Thuê</button>'}</div></div>`;
    h+=`<div class="card"><div class="sec-t">KTV <span class="note">${S.staff.length}/${staffCap()}</span></div><div class="list" style="margin-top:8px">`;
    if(!S.staff.length) h+='<p class="note">Chưa có KTV. Tuyển ở mục bên dưới.</p>';
    S.staff.forEach(s=>{ const w=W.find(x=>x.kind==='staff'&&x.id===s.id), busy=w&&w.state!=='idle';
      h+=`<div class="item" style="align-items:flex-start">${avatarMini(staffLook(s))}<div class="grow"><div class="n">${esc(s.name)} <span class="tag lav">${s.rank==='tc'?'KTV chính':'Học việc'} · cấp ${s.lvl}</span> ${s.lazy?'<span class="tag warn">Lơ là</span>':''}${busy?' <span class="tag">Đang làm</span>':''}</div>
        <div class="skills">${skillChips(s)}</div>${statBars(s.st)}
        <div class="m" style="margin-top:3px">Lương cứng ${fmt(s.monthly)}/tháng + tua ${Math.round(TUA*100)}%${s.tuaM?` (tháng này ${fmt(s.tuaM)} tua, ${fmt(s.tipM||0)} tip)`:''} · tinh thần ${Math.round(s.morale)} · ${s.xp||0}/${s.lvl*60} kinh nghiệm tới cấp sau${s.fine?` · bị trừ ${fmt(s.fine)}`:''}</div><div class="bar mor${s.morale<40?' low':''}"><i style="width:${s.morale}%"></i></div>
        <div class="row" style="margin-top:6px"><button class="btn mint sm" data-rew="${s.id}" ${S.cash<300000?'disabled':''}>Thưởng 300k</button><button class="btn sm" data-pun="${s.id}">Phạt 100k</button><button class="btn butter sm" data-tea="${s.id}">Dạy nghề</button><button class="btn sm ${armed==='fire'+s.id?'arm':'danger'}" data-fire="${s.id}" ${busy?'disabled':''}>${armed==='fire'+s.id?'Xác nhận':'Cho nghỉ'}</button></div></div></div>`; });
    h+=`</div></div><div class="card"><div class="sec-t">Ứng viên hôm nay</div><p class="note">Mỗi người mạnh yếu khác nhau. Lương tháng theo năng lực. Mỗi lần lên cấp, chỉ số thấp nhất tự tăng 1 để bù điểm yếu.</p><div class="list" style="margin-top:8px">`;
    S.cands.forEach(c=>{ h+=`<div class="item" style="align-items:flex-start">${avatarMini(staffLook(c))}<div class="grow"><div class="n">${esc(c.name)} <span class="tag lav">${c.rank==='tc'?'KTV chính':'Học việc'}</span>${c.moi?' <span class="tag mint">Mới</span>':''}</div><div class="skills">${skillChips(c)}</div>${statBars(c.st)}<div class="m">Lương cứng ${fmt(c.monthly)}/tháng + tua ${Math.round(TUA*100)}% + tip</div></div><button class="btn butter sm" data-hire="${c.id}" ${S.staff.length>=staffCap()?'disabled':''}>Thuê</button></div>`; });
    if(!S.cands.length) h+='<p class="note">Hết ứng viên, sáng mai có người mới.</p>';
    h+=`</div><button class="btn alt" id="reroll" style="margin-top:8px;width:100%" ${S.cash<500000?'disabled':''}>Đăng tin tuyển dụng · 500k</button><p class="note" style="margin-top:6px">Tay nghề: khách hài lòng hơn. Tốc độ: làm nhanh hơn. Duyên khách: tip nhiều hơn. Sức bền: làm nhiều khách/ngày không mệt. Kỷ luật: ít lơ là.</p></div>`;
  }
  if(tab==='skill'){
    h+=`<div class="card"><div class="row">${avatarMini(OWNER_LOOK())}<div><div class="sec-t">${esc(S.owner||'Chủ tiệm')}</div><div class="note">Điểm nghề: <b>${S.xp}</b> · đã xử lý êm <b>${S.solved||0}</b> sự cố</div></div></div><p class="note" style="margin-top:6px">Xử lý êm chuyện của khách: +10 điểm nghề. Tự tay làm khách: +5.</p></div>`;
    h+=`<div class="card"><div class="sec-t">Kỹ năng</div><div class="list" style="margin-top:8px">`;
    SK.forEach(k=>{ const sv=SERVICES[k], sk=S.skills[k];
      if(sk){ const up={cash:2e6*sk.lv,xp:30*sk.lv};
        h+=`<div class="item">${ico(SVC_ICON[k])}<div class="grow"><div class="n">${sv.name} · cấp ${sk.lv}/5</div><div class="bar" style="margin-top:3px"><i style="width:${sk.lv>=5?100:(sk.exp||0)/(sk.lv*60)*100}%"></i></div><div class="m">${sk.lv>=5?'Tối đa':`${sk.exp||0}/${sk.lv*60} kinh nghiệm thực hành`}</div></div>${sk.lv<5?`<button class="btn butter sm" data-up="${k}" ${S.cash<up.cash||S.xp<up.xp?'disabled':''}>Khoá nâng cao<br>${fmt(up.cash)} + ${up.xp} điểm</button>`:'<span class="tag">Tối đa</span>'}</div>`;
      } else { const L=sv.learn, need=sv.needSkill&&!S.skills[sv.needSkill];
        h+=`<div class="item own">${ico(SVC_ICON[k])}<div class="grow"><div class="n">${sv.name}</div><div class="m">${sv.min} phút · ${sv.st==='chair'?'ghế massage':'phòng body'}${sv.item?' + xe đá nóng':''}</div></div>${need?`<span class="tag grey">Cần ${SERVICES[sv.needSkill].name}</span>`:`<button class="btn butter sm" data-learn="${k}" ${S.cash<L.cash||S.xp<L.xp?'disabled':''}>Học · ${fmt(L.cash)}<br>+ ${L.xp} điểm nghề</button>`}</div>`; }
    });
    h+=`</div></div><div class="card"><div class="sec-t">Bảng giá theo lượt</div><p class="note">Giá thị trường tham khảo các spa ở Phú Quốc, theo khu ${prem()?esc(prem().name):''}. Đặt cao thì khách trả giá gắt và dễ bỏ đi.</p><div class="list" style="margin-top:8px">`;
    SK.forEach(k=>{ const off=canOffer(k); h+=`<div class="item${off?'':' own'}">${ico(SVC_ICON[k])}<div class="grow"><div class="n">${SERVICES[k].name} · ${SERVICES[k].min}'</div><div class="m">Thị trường ~${fmt(market(k))}${off?'':' · chưa phục vụ được'}</div></div><div class="pricebox"><button class="btn alt sm" data-p="${k}" data-d="-10000" aria-label="Giảm giá">−</button><b>${fmt(priceOf(k))}</b><button class="btn alt sm" data-p="${k}" data-d="10000" aria-label="Tăng giá">+</button></div></div>`; });
    h+='</div></div>';
  }
  if(tab==='phone'){
    const feed = phoneTab==='group'? S.group.slice(-40).map(m=>`<div class="pm${m.me?' me':''}${m.reply?' rep':''}"><b>${esc(m.who)}</b>${esc(m.t)}${m.reply?(m.liked?'<span class="liked">Đã chọn</span>':m.passed?'':`<button class="likeb" data-like="${m.id}" aria-label="Thả tim chọn thợ này">♥</button>`):''}</div>`).join('') : S.inbox.slice(-30).map(m=>`<div class="pm"><b>${m.ic&&window.UI_ICON&&UI_ICON[m.ic]?`<img src="${UI_ICON[m.ic]}" alt="" style="width:28px;height:28px;object-fit:contain;vertical-align:middle;margin-right:4px">`:''}${esc(m.who)}</b>${esc(m.t)}</div>`).join('');
    const waitG=guests.filter(g=>g.state==='seated'&&!g.flyRes);
    let form='';
    if(phoneTab==='group'){
      if(S.stage!=='open') form='<p class="note">Tiệm chưa mở cửa. Khi có khách đang chờ, đăng tin tại đây.</p>';
      else if(!waitG.length) form='<p class="note">Chưa có khách nào đang chờ để gọi thợ bay.</p>';
      else { const g0=waitG.sort((a,b)=>b.wait-a.wait)[0], st0=freeStation(g0.want);
        form=`<label class="note" for="flyG">Khách đang chờ</label><select id="flyG" class="sel">${waitG.map(g=>`<option value="${g.id}">${CTYPES[g.type].name} · ${SERVICES[g.want].name} · chờ ${Math.round(g.wait*GMIN)}'</option>`).join('')}</select>
          <div class="row"><label class="note" for="flyN">Số ${SERVICES[g0.want].st==='chair'?'ghế':'giường'} khách ngồi</label><input id="flyN" type="number" min="1" max="8" value="${st0?st0.i+1:''}" class="numin"><button class="btn lav" id="flyPost">Đăng tin</button></div>`; }
    }
    h+=`<div class="seg"><button data-pt="group" aria-pressed="${phoneTab==='group'}">Nhóm Bay${unread.group?' •':''}</button><button data-pt="inbox" aria-pressed="${phoneTab==='inbox'}">Tin khách${unread.inbox?' •':''}</button></div>
      <div class="phone-app"><div class="pa-top"><div class="gav">${phoneTab==='group'?'NB':'KH'}</div><div><div class="n">${phoneTab==='group'?'Nhóm Bay':'Khách quen'}</div><div class="note">${phoneTab==='group'?'Thợ rảnh thả "1" hoặc ".". Thả tim tin nhắn để chọn thợ đó đi làm.':'Khách hẹn quay lại và giới thiệu bạn bè'}</div></div></div>
      <div class="pa-feed" id="feed">${feed||`<div class="pm sys">${phoneTab==='group'?'Chưa có tin nhắn.':'Khách hài lòng cao sẽ nhắn hẹn quay lại hoặc giới thiệu bạn.'}</div>`}</div>
      ${phoneTab==='group'?`<div class="pa-actions">${form}<label class="switch"><input type="checkbox" data-auto="fly" ${S.auto.fly?'checked':''}> Tự đăng tin và tự thả tim thợ hợp sở trường</label><p class="note">Thợ bay lấy ${Math.round(FLY_FEE*100)}% tiền dịch vụ và giữ tip. Thợ đúng sở trường thì khách hài lòng hơn.</p></div>`:`<div class="pa-actions"><dl class="ledger"><dt>Hẹn quay lại ngày mai</dt><dd>${S.returning}</dd><dt>Bạn bè được giới thiệu</dt><dd>${S.referrals}</dd><dt>Khách quen đã phục vụ</dt><dd>${S.retServed}</dd></dl></div>`}</div>`;
  }
  if(tab==='book'){
    const p=prem();
    { const st=S.stats; h+=`<div class="card"><div class="sec-t">Hôm nay</div><div class="tiles" style="margin-top:8px"><div class="tile"><b>${fmt(st.rev+st.tips)}</b><small>thu hôm nay</small></div><div class="tile"><b>${st.served}</b><small>khách đã làm</small></div><div class="tile"><b>${st.lost+st.missed}</b><small>khách mất</small></div></div><p class="note" style="margin-top:8px">Độ nổi tiếng: <b>${Math.round(fame()*100)}%</b>. Mở lâu và được khen thì khách đông hơn.</p></div>`; }
    h+=`<div class="card"><div class="sec-t">Thống kê dịch vụ</div><div class="seg" style="margin:8px 0">${[[1,'Hôm qua'],[7,'7 ngày'],[30,'30 ngày']].map(([v,l])=>`<button data-range="${v}" aria-pressed="${statRange===v}">${l}</button>`).join('')}</div>${statsTable(statRange)}</div>`;
    h+=`<div class="card"><div class="sec-t">Chi phí</div><dl class="ledger" style="margin-top:6px"><dt>Thuê mặt bằng/tháng</dt><dd>${p?fmt(p.rent):'—'}</dd><dt>Lương/tháng</dt><dd>${fmt(S.staff.reduce((a,s)=>a+s.monthly,0)+(S.cashier?CASHIER.monthly+CASHIER.step*(S.cashier.lv-1):0)+(S.manager?MANAGER.monthly:0))}</dd><dt>Điện</dt><dd>${full(ELEC)}/kWh</dd><dt>Nước</dt><dd>${full(WATER)}/m³</dd><dt class="sum">Ngày tới kỳ trả tiền thuê</dt><dd class="sum">${30-(S.day%30||30)}</dd></dl></div>
      ${missionCard(true)}
      <div class="card"><div class="sec-t">Toàn thời gian</div><dl class="ledger" style="margin-top:6px"><dt>Lượt khách</dt><dd>${S.totals.served}</dd><dt>Doanh thu</dt><dd>${fmt(S.totals.rev)}</dd><dt>Tip</dt><dd>${fmt(S.totals.tips)}</dd><dt>Ngày thu cao nhất</dt><dd>${fmt(S.best)}</dd></dl></div>
      <div class="card"><div class="sec-t">Nhật ký</div><div class="list" style="margin-top:6px">${S.log.slice(0,25).map(l=>`<div class="row" style="justify-content:space-between;font-size:var(--fz-ghichu)"><span style="flex:1;min-width:0">${esc(l.t)}</span><b style="color:${l.a>=0?'var(--mint-d)':'var(--danger)'};font-variant-numeric:tabular-nums">${l.a>=0?'+':''}${fmt(l.a)}</b></div>`).join('')}</div></div>
      <div class="card"><div class="sec-t">Nguồn giá tham khảo</div><p class="note">Giá dịch vụ và lương theo mức thật ở Phú Quốc.</p></div>
      <button class="btn ${armed==='reset'?'arm':'danger'}" id="reset">${armed==='reset'?'Bấm lần nữa để xoá hết và chơi lại':'Chơi lại từ đầu'}</button>`;
  }
  D.innerHTML=h;
  const f=$('#feed'); if(f) f.scrollTop=f.scrollHeight;
}
$('#dyn').addEventListener('change',e=>{
  if(e.target.id==='selfH'){ S.selfHaggle=e.target.checked; save(); renderScreen(); }
  if(e.target.dataset.auto){ S.auto[e.target.dataset.auto]=e.target.checked; save(); renderScreen(); }
  if(e.target.id==='flyG'){ const g=guests.find(x=>x.id==e.target.value); const st=g&&freeStation(g.want); const n=$('#flyN'); if(n) n.value=st?st.i+1:''; }
});
$('#dyn').addEventListener('click',e=>{
  const b=e.target.closest('button'); if(!b||b.disabled) return; const d=b.dataset;
  if(d.speed!==undefined){ speed=+d.speed; renderScreen(); return; }
  if(d.buy){ buy(d.buy); return; }
  if(d.sup){ const s=SUP[d.sup]; if(S.cash<s.price) return; S.cash-=s.price; S.stock[d.sup]=Math.min(s.cap,S.stock[d.sup]+s.batch); addLog(`Nhập ${s.name} (${s.batch} ${s.unit})`,-s.price); save(); renderAll(); return; }
  if(b.id==='open'){ startDay(); toast('Khai trương hồng phát! Khách đang tới.','good'); return; }
  if(d.range){ statRange=+d.range; renderScreen(); return; }
  if(d.like){ likeFly(+d.like); return; }
  if(b.id==='flyPost'){ const g=guests.find(x=>x.id==$('#flyG').value); const n=+$('#flyN').value; if(!g){ toast('Khách không còn chờ.','warn'); return; } const st={t:SERVICES[g.want].st==='chair'?'chair':'bed', i:n-1}; if(!n||!stationFree(st)){ toast(`${stName(st)} không trống hoặc chưa mở khoá.`,'warn'); return; } postFly(g,st,false); renderScreen(); return; }
  if(d.pt){ phoneTab=d.pt; unread[phoneTab]=false; renderNav(); renderScreen(); return; }
  if(b.id==='hireC'){ S.cashier={lv:1}; addLog('Thuê thu ngân Ngọc Hân',0); save(); ensureWorkers(); renderAll(); toast('Ngọc Hân đã đứng quầy.','good'); return; }
  if(b.id==='upC'){ const c=CASHIER.up[S.cashier.lv]; if(S.cash<c) return; S.cash-=c; S.cashier.lv++; addLog(`Đào tạo thu ngân lên cấp ${S.cashier.lv}`,-c); save(); renderAll(); toast(`Thu ngân lên cấp ${S.cashier.lv}!`,'good'); return; }
  if(b.id==='fireC'){ if(armed!=='fireC'){ armed='fireC'; renderScreen(); return; } S.cashier=null; armed=null; save(); ensureWorkers(); const o=ownerW(); if(o.state==='idle') goIdle(o); renderAll(); return; }
  if(b.id==='hireM'){ S.manager=true; addLog('Thuê quản lý ca',0); save(); renderAll(); toast('Quản lý ca đã nhận việc.','good'); return; }
  if(b.id==='fireM'){ if(armed!=='fireM'){ armed='fireM'; renderScreen(); return; } S.manager=false; armed=null; save(); renderAll(); return; }
  if(d.hire){ const c=S.cands.find(x=>x.id==d.hire); if(!c||S.staff.length>=staffCap()) return; S.cands=S.cands.filter(x=>x!==c); S.staff.push({id:c.id,name:c.name,male:staffMale(c),rank:c.rank,skills:c.skills,st:c.st,monthly:c.monthly,lvl:1,xp:0,morale:70,look:c.look,taught:{},lazy:false,fine:0,done:0}); addLog('Tuyển '+c.name,0); save(); ensureWorkers(); renderScreen(); toast(`${c.name} đã nhận việc.`,'good'); return; }
  if(b.id==='reroll'){ S.cash-=500000; addLog('Đăng tin tuyển dụng',-500000); makeCands(); save(); renderAll(); return; }
  if(d.rew){ const s=S.staff.find(x=>x.id==d.rew); S.cash-=300000; s.morale=clamp(s.morale+15,0,100); addLog('Thưởng '+s.name,-300000); save(); renderAll(); toast(`${s.name} vui hẳn lên!`,'good'); return; }
  if(d.pun){ const s=S.staff.find(x=>x.id==d.pun); s.fine=(s.fine||0)+100000; s.morale=clamp(s.morale-10,0,100); s.lazy=false; save(); renderScreen(); toast(`Đã nhắc nhở ${s.name}, trừ 100k lương hôm nay.`); return; }
  if(d.tea){ teachSheet(+d.tea); return; }
  if(d.fire){ const id=+d.fire; if(armed!=='fire'+id){ armed='fire'+id; renderScreen(); return; } const s=S.staff.find(x=>x.id===id); S.staff=S.staff.filter(x=>x.id!==id); armed=null; addLog('Cho '+s.name+' nghỉ',0); save(); ensureWorkers(); renderScreen(); return; }
  if(d.learn){ learnSkill(d.learn); return; }   // 15q-progress.js: có thời gian học
  if(d.up){ upSkill(d.up); return; }
  if(d.p){ S.prices[d.p]=clamp(priceOf(d.p)+ +d.d,50000,3000000); save(); renderScreen(); return; }
  if(b.id==='reset'){ const go=()=>{ S.maDaNhan=[]; window.__khongLuu=true; try{localStorage.removeItem(KEY);}catch(_){} location.reload(); }; if(armed==='reset'){ go(); return; } if(window.uiConfirm){ uiConfirm('Xoá hết tiến trình và chơi lại từ đầu?','Xoá hết','Giữ lại',go); return; } if(armed!=='reset'){ armed='reset'; renderScreen(); return; } go(); }   // 24e: hộp xác nhận thẻ gỗ
});

// 14-story.js — Mở đầu, ngân hàng, chọn mặt bằng, sheet, toast
'use strict';
// ---------- story ----------
function sheet(html,bind){ const was=$('#sheetBg').hidden; $('#sheetBg').classList.toggle('intro',S.stage==='story'||S.stage==='prem'); $('#sheet').innerHTML=html; $('#sheetBg').hidden=false; if(was&&window.CC) CC.sheetIn(); if(bind) bind($('#sheet')); const f=$('#sheet').querySelector('input,button.big,button'); if(f) f.focus(); }
const closeSheet=()=>{ if(window.CC) CC.sheetOut(); $('#sheetBg').hidden=true; };
$('#sheetBg').addEventListener('click',e=>{ if(e.target.id==='sheetBg' && (S.stage==='build'||S.stage==='open') ) closeSheet(); });
const steps=n=>`<div class="steps">${[1,2,3,4].map(i=>`<i class="${i<=n?'on':''}"></i>`).join('')}</div>`;
var SC_BANK=`<svg viewBox="0 0 84 84">${G('<circle cx="42" cy="42" r="38" fill="#DCEBFF"/><path d="M16 34l26-14 26 14z" fill="#BCD7DC"/><rect x="20" y="36" width="44" height="5" fill="#FBF6EA"/><rect x="24" y="42" width="7" height="20" fill="#FBF6EA"/><rect x="38.5" y="42" width="7" height="20" fill="#FBF6EA"/><rect x="53" y="42" width="7" height="20" fill="#FBF6EA"/><rect x="18" y="62" width="48" height="7" rx="2" fill="#F9C87A"/>')}</svg>`;
function story(){
  const me=`<svg viewBox="-42 -90 84 96">${G('<circle cx="0" cy="-40" r="38" fill="#FDE3E4"/>')}${charSVG({skin:S.look.skin,hair:S.look.hair,hs:'short',shirt:'#8FD3AE',pants:'#4A4458',apron:'#FBF6EA'})}</svg>`;
  sheet(`${steps(1)}<div class="scene-s">${me}<p>Bạn có đôi tay khéo và biết <b>massage chân</b>. Giấc mơ là một tiệm spa nhỏ ở <b>Phú Quốc</b>, nơi khách du lịch đổ về quanh năm. Chỉ có điều, vốn liếng trong tay chẳng được bao nhiêu.</p></div>
    <label for="ownerIn">Tên chủ tiệm</label><input id="ownerIn" maxlength="24" placeholder="Ví dụ: Huy" value="${esc(S.owner)}">
    <label for="spaIn">Tên tiệm spa</label><input id="spaIn" maxlength="22" value="${esc(S.name)}">
    <div class="row"><button class="btn big butter" data-go>Đến ngân hàng</button></div>`, sh=>{
      sh.querySelector('[data-go]').onclick=()=>{ S.owner=sh.querySelector('#ownerIn').value.trim()||'Bạn'; S.name=sh.querySelector('#spaIn').value.trim()||'Spa Miu'; renderTop(); drawScene(); window.introRun?introRun(pickDiff):pickDiff(); };
    });
}
function pickDiff(){
  if(window.cicHas&&cicHas()){ S.diff='kho'; applyDiff('kho'); S.cicRun=true; setTimeout(()=>toast('Hồ sơ CIC xấu: chỉ mở mức Khó, không có ngân hàng.','warn'),500); return miuQua(); }   // 20j
  let k=S.diff&&DIFFS[S.diff]&&S.diff!=='legacy'?S.diff:'vua';
  const card=([id,d])=>{ const pay=periodPayFor(d.loan,d.yearRate,d.months,id), kyN=id==='kho'?4:d.months*3;
    return `<button class="prem diff" data-d="${id}" aria-pressed="${k===id}"><span class="n">${d.name} · ${d.title}</span><span class="note">${d.desc}</span>
    <dl class="ledger" style="font-size:var(--fz-ghichu)"><dt>Vốn tự có</dt><dd>${fmt(d.own)}</dd><dt>${d.kind}</dt><dd>${fmt(d.loan)}</dd><dt>Lãi suất</dt><dd>${String(Math.round(d.yearRate*10000)/100).replace('.',',')}%/năm</dd><dt>Số kỳ góp</dt><dd>${kyN} kỳ (${kyN*10} ngày)</dd><dt>Góp mỗi kỳ 10 ngày</dt><dd>${fmt(pay)}</dd>${d.start?`<dt>Khai trương</dt><dd>tháng ${d.start} (${typeof MONTHS!=='undefined'?MONTHS[d.start].name:''})</dd>`:''}<dt class="sum">Tổng vốn</dt><dd class="sum">${fmt(d.own+d.loan)}</dd></dl></button>`; };
  const draw=()=>sheet(`${steps(2)}<h2>Hoàn cảnh khởi nghiệp</h2><p class="note">Ai cũng khởi nghiệp ở Chợ đêm Dương Đông rồi mở dần Trần Hưng Đạo, Sunset và cuối cùng là Resort Bãi Trường. Luật chơi như nhau ở cả ba mức; chỉ khác vốn tự có và lãi suất (áp cho mọi khoản vay về sau).</p>
    <div class="premises">${Object.entries(DIFFS).filter(([id])=>id!=='legacy').map(card).join('')}</div>
    <div class="row"><button class="btn alt" data-back>Quay lại</button><button class="btn big butter" data-go>Chọn ${DIFFS[k].name}</button></div>`, sh=>{
      sh.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>{ k=b.dataset.d; draw(); });
      sh.querySelector('[data-back]').onclick=story;
      sh.querySelector('[data-go]').onclick=()=>{ S.diff=k; applyDiff(k); bank(); };
    });
  draw();
}
// 20l: ván mới khi có CIC xấu: không ngân hàng; Miu để lại 50tr (không lãi, không trả) rồi biến mất cả ván
function miuQua(){
  S.miuGone=true;
  sheet(`${steps(3)}<div class="scene-s miu"><img src="img/a0d433484f1d.webp" alt="Miu" onerror="this.remove()"><div class="mt"><p>Hồ sơ CIC xấu nên ngân hàng đóng cửa với bạn. Đêm trước ngày khai trương, một bóng mèo quen thuộc ghé qua…</p><p><b>"Meo… (Miu để lại một túi tiền rồi biến mất)"</b></p></div></div>
    <div class="contract"><dl class="ledger"><dt>Vốn tự có</dt><dd>${full(0)} (đã bị ngân hàng siết hết)</dd><dt>Tiền Miu để lại</dt><dd>${full(50e6)}</dd><dt>Vay ngân hàng</dt><dd>Không</dd></dl></div>
    <p class="note">Tiền Miu cho: không lãi, không phải trả. Miu sẽ không ở trong tiệm suốt ván này. Qua map mới mà hết nợ vay nóng thì CIC được xóa.</p>
    <div class="row"><button class="btn alt" data-back>Quay lại</button><button class="btn big butter" data-go>Nhận tiền, vào tiệm</button></div>`, sh=>{
      sh.querySelector('[data-back]').onclick=story;
      sh.querySelector('[data-go]').onclick=()=>{ S.cash=50e6; S.debt=0; S.log=[]; addLog('Miu để lại túi tiền',50e6); S.stage='prem'; save(); renderTop(); premises(); };
    });
}
function bank(){
  const d=DIFFS[S.diff]||DIFFS.vua;
  sheet(`${steps(3)}<div class="scene-s">${SC_BANK}<p>Cán bộ tín dụng xem kế hoạch kinh doanh của ${esc(S.owner)} và duyệt khoản <b>${d.kind.toLowerCase()}</b>.</p></div>
    <div class="contract"><dl class="ledger"><dt>Vốn tự có</dt><dd>${full(d.own)}</dd><dt>Số tiền vay</dt><dd>${full(LOAN.amount)}</dd><dt>Lãi suất</dt><dd>${pctRate()}</dd><dt>Số kỳ góp</dt><dd>${numPeriods()} kỳ (${numPeriods()*10} ngày)</dd><dt>Tổng lãi cả khoản vay</dt><dd>${full(periodPay()*numPeriods()-LOAN.amount)}</dd><dt class="sum">Góp mỗi kỳ 10 ngày (gốc + lãi)</dt><dd class="sum">${full(periodPay())}</dd></dl></div>
    <p class="note">Góp gốc + lãi mỗi kỳ 10 ngày.${S.diff==='kho'?' Mức Khó: mỗi kỳ trả một phần lớn nợ.':''} Thiếu tiền thì ngân hàng nhắc 3 lần rồi siết nợ. Tiền thuê mặt bằng trừ theo ngày sau mỗi ngày bán; tiền nhà ở và điện nước của chủ tiệm cũng trừ theo ngày. Trễ góp thì bị phạt lãi quá hạn 150% và có thể bị ghi nợ xấu CIC.</p>
    <p class="note" style="color:var(--danger)"><b>Cảnh báo CIC:</b> ${window.CIC_TXT||''}</p>
    <div class="row"><button class="btn alt" data-back>Quay lại</button><button class="btn big butter" data-go>Ký hợp đồng vay</button></div>`, sh=>{
      sh.querySelector('[data-back]').onclick=S.cicRun?story:pickDiff;
      sh.querySelector('[data-go]').onclick=()=>{ S.cash=d.own+LOAN.amount; S.debt=LOAN.amount; S.log=[]; if(d.own) addLog('Vốn tự có',d.own); addLog('Giải ngân khoản vay',LOAN.amount); S.stage='prem'; save(); renderTop(); premises(); if(window.cicWarn) setTimeout(cicWarn,800); };
    });
}
function premises(){
  let choice=S.prem||(S.cash-upfront(PREMISES[1])>=27e6?'thd':'chodem');
  const card=p=>`<button class="prem" data-p="${p.id}" aria-pressed="${choice===p.id}"><span class="n">${p.name}</span><span class="note">${p.desc}</span>
    <dl class="ledger" style="font-size:var(--fz-ghichu)"><dt>Ghế massage chân</dt><dd>tối đa ${p.chairs}</dd><dt>Phòng body</dt><dd>tối đa ${p.rooms}</dd><dt>Thuê/tháng</dt><dd>${fmt(p.rent)}</dd><dt>Lượng khách</dt><dd class="stars">${'★'.repeat(p.lvl+1)}${'☆'.repeat(2-p.lvl)}</dd><dt>Khách nước ngoài</dt><dd>${Math.round(p.mix[2]*100)}%</dd><dt>Khách đi đoàn</dt><dd>${Math.round((p.groups||0)*4.5/((p.groups||0)*4.5+1-(p.groups||0))*100)}%</dd><dt>Giá massage chân</dt><dd>~${fmt(p.market)}</dd><dt>Cọc + tháng đầu</dt><dd>${fmt(p.rent*3)}</dd><dt>Sửa sang</dt><dd>${fmt(p.fit||0)}</dd><dt>Còn lại</dt><dd style="color:${S.cash-upfront(p)<27e6?'var(--danger)':'inherit'}">${fmt(S.cash-upfront(p))}</dd></dl>${S.cash-upfront(p)<27e6?'<span class="note" style="color:var(--danger)">Không đủ tiền sắm đồ tối thiểu để khai trương</span>':''}</button>`;
  const draw=()=>sheet(`${steps(4)}<h2>Chọn mặt bằng</h2><p class="note">Trả trước gồm 2 tháng cọc, tiền thuê tháng đầu và tiền sửa sang (sơn, máy lạnh, điện nước, bảng hiệu). Sau đó còn phải sắm ${TEN.batbuoc} (khoảng 27tr) mới khai trương được.</p><div class="premises">${PREMISES.map(card).join('')}<div class="prem" style="opacity:.6;border-style:dashed"><span class="n">${RESORT.name} · đã khoá</span><span class="note">${RESORT.desc}</span></div></div>
    <div class="row"><button class="btn big butter" data-go>Ký hợp đồng thuê</button></div>`, sh=>{
      sh.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>{ choice=b.dataset.p; draw(); });
      sh.querySelector('[data-go]').onclick=()=>{ const p=PREMISES.find(x=>x.id===choice); if(S.cash-upfront(p)<27e6){ toast('Không đủ vốn cho mặt bằng này, chọn chỗ rẻ hơn.','warn'); return; } S.prem=p.id; S.cash-=upfront(p); addLog('Cọc, thuê tháng đầu, sửa sang: '+p.name,-upfront(p)); S.stage='build'; save(); closeSheet(); drawScene(); ensureWorkers(); renderAll(); toast('Nhận chìa khoá! Vào tab Mua sắm để sắm ' + TEN.batbuoc + '.','good'); if(S.cicRun&&window.cicOffer) setTimeout(cicOffer,1200); };
    });
  draw();
}
// 06/10 mach chinh (dac ta V9 muc 3): toast moi - tu an theo loai, xep chong (ngang 2/doc 3), trung noi dung thi x2, toi da 1 cai/600ms, cham/vuot len de tat, giu tay thi dung dem gio
const TOAST_K={info:['ℹ️',2500],good:['🪙',2500],warn:['⚠️',3500],urgent:['⛔',0],tip:['💡',3500]};   // 22c: toast tự tắt ~2,5 s (cảnh báo 3,5 s, khẩn giữ tới khi chạm)
const TOASTQ={q:[],last:0,h:null};
function toast(msg,kind,opt){ kind=TOAST_K[kind]?kind:'info'; opt=opt||{}; const b=$('#toasts'); if(!b) return;
  for(const t of b.children){ if(!t._dead&&t._msg===msg){ t._n=(t._n||1)+1; t.querySelector('.tt').textContent=t.querySelector('.tt').textContent.replace(/ ×\d+$/,'')+' ×'+t._n; if(t._arm) t._arm(); return; } }
  if(TOASTQ.q.some(x=>x[0]===msg)) return; if(kind==='warn'||kind==='urgent') TOASTQ.q.unshift([msg,kind,opt]); else TOASTQ.q.push([msg,kind,opt]); while(TOASTQ.q.length>4){ const i=TOASTQ.q.findIndex(x=>x[1]==='info'||x[1]==='tip'||x[1]==='good'); TOASTQ.q.splice(i<0?TOASTQ.q.length-1:i,1); } toastPump(); }
function toastPump(){ if(TOASTQ.h||!TOASTQ.q.length) return; const w=600-(Date.now()-TOASTQ.last);
  // 17w: toi da 1 toast tren man; cung loai -> thay the, khac loai -> cho toast cu xong; canh bao/khan len dau hang
  const go=()=>{ TOASTQ.h=null; const b=$('#toasts'); const it=TOASTQ.q[0]; if(!it) return; const live=b?[...b.children].filter(x=>!x._dead):[];
    if(live.length&&it[1]!=='urgent'){ const o=live[0]; if(o._kind===it[1]&&!o.classList.contains('urgent')) toastKill(o); else if(it[1]==='warn'&&!o.classList.contains('warn')&&!o.classList.contains('urgent')) toastKill(o); else { TOASTQ.h=setTimeout(go,250); return; } }
    TOASTQ.q.shift(); TOASTQ.last=Date.now(); toastShow(it[0],it[1],it[2]); toastPump(); };
  if(w<=0) go(); else TOASTQ.h=setTimeout(go,w); }
function toastKill(t){ if(!t||t._dead) return; t._dead=1; clearTimeout(t._h); t.classList.add('out'); setTimeout(()=>t.remove(),210); }
function toastShow(msg,kind,opt){ const b=$('#toasts'), K=TOAST_K[kind];
  if(kind==='urgent') for(const o of [...b.children]) if(o.classList.contains('urgent')) toastKill(o);
  const t=document.createElement('div'); t.className='toast '+kind; t._msg=msg; t._kind=kind; t.setAttribute('role',kind==='warn'||kind==='urgent'?'alert':'status');
  t.innerHTML='<span class="ti" aria-hidden="true"></span><span class="tt"></span>'+(opt.more?'<button class="tm" aria-label="Xem thêm trong Sổ tay">›</button>':'')+'<i class="tbar"></i>';
  t.querySelector('.ti').textContent=K[0]; const tt=t.querySelector('.tt'); if(opt.html) tt.innerHTML=msg; else tt.innerHTML=String(msg).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/&lt;(\/?)(b|i)&gt;/g,'<$1$2>'); // 06/10: cho phep <b>/<i>, con lai van ma hoa
  b.prepend(t); b.classList.toggle('low',typeof haggling!=='undefined'&&!!haggling); const max=1;
  const live=[...b.children].filter(x=>!x._dead); for(let i=max;i<live.length;i++) toastKill(live[i]);
  let dur=K[1]; if(kind==='tip') dur=Math.min(5000,3500+Math.max(0,tt.textContent.length-40)*40);
  const bar=t.querySelector('.tbar'); if(!dur) bar.remove(); let left=dur, t0=0;
  const run=()=>{ if(!dur||t._dead) return; clearTimeout(t._h); t0=Date.now(); bar.style.transition='none'; bar.style.transform='scaleX('+(left/dur)+')'; void bar.offsetWidth; bar.style.transition='transform '+left+'ms linear'; bar.style.transform='scaleX(0)'; t._h=setTimeout(()=>toastKill(t),left); };
  const pause=()=>{ if(!dur||!t._h) return; clearTimeout(t._h); t._h=null; left=Math.max(400,left-(Date.now()-t0)); bar.style.transition='none'; bar.style.transform='scaleX('+(left/dur)+')'; };
  t._arm=()=>{ left=dur; run(); };
  t.addEventListener('pointerdown',e=>{ t._y=e.clientY; pause(); });
  t.addEventListener('pointerup',e=>{ if(e.target.closest('.tm')){ toastKill(t); opt.more(); return; } const dy=(t._y||e.clientY)-e.clientY; if(dy>12||Math.abs(dy)<6) toastKill(t); else run(); });
  t.addEventListener('pointerleave',()=>{ if(!t._h) run(); });
  run(); }

// 06/10 toi: doi tab -> tat toast thuong cua man truoc (giu canh bao/khan) de khong treo de len noi dung tab moi
function toastClearSoft(){ const b=$('#toasts'); if(!b) return; for(const t of [...b.children]) if(!t.classList.contains('warn')&&!t.classList.contains('urgent')) toastKill(t); TOASTQ.q=TOASTQ.q.filter(x=>x[1]==='warn'||x[1]==='urgent'); }
{ const nv=$('#nav'); if(nv) nv.addEventListener('click',e=>{ if(e.target.closest('[data-tab]')) toastClearSoft(); },true); }

// 15-board.js — Tab Tiệm gói gọn 1 màn hình (renderBoard) + các lớp bọc hình thiết kế
'use strict';
// ---------- tab Tiệm: 1 màn hình, dùng bộ hình thiết kế ----------
bubble=(orig=>function(w,t){ w.lastSay=t; orig(w,t); })(bubble);
avatarMini=(orig=>function(o){   // 10/10 Viec 16 #8: uu tien anh toan than nv-*, ha ve lai anh cu neu chua co nv
  if(o&&o.__nv&&window.HAND_ART&&HAND_ART[o.__nv]) return `<img class="av avimg" src="${HAND_ART[o.__nv].file}" alt="">`;
  return o&&o.__img&&IMG[o.__img]?`<img class="av avimg" src="${IMG[o.__img]}" alt="">`:orig(o); })(avatarMini);
let boardPop=null;
drawScene=(orig=>function(p){ orig(p); if(p) boardPop=p; renderBoard(); })(drawScene);
const imgOf=s=>SLOT_IMG[s.id]||(s.zone==='chan'?'footchair':s.id.startsWith('room')?'bed':null);
function artHTML(s){ const k=imgOf(s); if(k&&IMG[k]) return `<img class="art" src="${IMG[k]}" alt="">`; return `<svg class="art" viewBox="${s.x-6} ${s.y-12} ${s.w+14} ${s.h+16}">${slotArt(s)}</svg>`; }
const SHORT={};   // 24k: bo ten rut gon (Quầy, Máy khăn...): 1 vat = 1 ten, lay tu TEN.slot
function stationGuest(s){
  let st=null; if(s.zone==='chan') st={t:'chair',i:s.seat}; else if(s.id.startsWith('room')) st={t:'bed',i:s.need}; else return null;
  return guests.find(g=>g.station&&g.station.t===st.t&&g.station.i===st.i&&(g.state==='service'||g.state==='toStation'))||null;
}
function workerName(w){ if(!w) return ''; if(w.kind==='owner') return 'Chủ tiệm'; if(w.kind==='fly') return (w.name||'Thợ bay').split(' (')[0]; const s=staffOf(w); return s?s.name.split(' ').pop():''; }
function trayHTML(s,label){
  const own=!!S.owned[s.id], av=available(s);
  if(!own && av.space) return '';
  const pop=boardPop===s.id?' pop':'';
  if(!own) return `<button class="tray locked${pop}" data-slot="${s.id}" aria-label="Mở khoá ${esc(s.name)}">${artHTML(s)}<span class="lab">${label}</span><span class="lockt">Khoá<small>${av.dep?'—':fmt(s.price)}</small></span></button>`;
  const g=stationGuest(s);
  if(g){ const inSvc=g.state==='service'&&g.dur, left=inSvc?Math.max(1,Math.ceil(SERVICES[g.want].min*(1-g.svc/g.dur))):SERVICES[g.want].min, pct=inSvc?Math.min(100,g.svc/g.dur*100):0;
    const pose=s.zone==='chan'?'d_soak':'d_massage';
    return `<button class="tray busy${pop}" data-slot="${s.id}" aria-label="${esc(s.name)}: ${SERVICES[g.want].name}, còn ${left} phút"><img class="art pose" src="${IMG[pose]}" alt=""><span class="cd">${inSvc?left+"'":'…'}</span><span class="pg"><i style="width:${pct}%"></i></span><span class="lab">${esc(workerName(g.worker))} · x2</span></button>`; }
  let bd='';
  if(s.id==='sofa'){ const n=seats.filter(x=>x!==null).length+stands.filter(x=>x!==null).length; bd=`<span class="bd">${n}</span>`; }
  if(s.id==='towel') bd=`<span class="bd">${Math.floor(S.stock.towel)}</span>`;
  const art = s.id==='sofa' && seats.some(x=>x!==null) ? `<img class="art" src="${IMG.p_wait}" alt="">` : artHTML(s);
  return `<button class="tray${pop}" data-slot="${s.id}" aria-label="${esc(s.name)}">${art}${bd}<span class="lab">${label}</span></button>`;
}
function renderBoard(){
  const B=$('#board'); if(!B||tab!=='shop') return;
  const p=prem(), open=S.stage==='open';
  let h=`<div class="front"><div class="awn"></div><div class="signrow"><span class="open${open?' on':''}">${open?'ĐANG MỞ CỬA':S.stage==='build'?'CHUẨN BỊ KHAI TRƯƠNG':'ĐÓNG CỬA'}</span><span class="spd" role="group" aria-label="Tốc độ">${[['0','Dừng'],['1','×1'],['2','×2'],['3','×3']].map(([v,l])=>`<button data-speed="${v}" aria-pressed="${speed==+v}">${l}</button>`).join('')}</span></div></div>`;
  const atC=(haggling&&haggling.g)||guests.find(g=>g.state==='atCounter'||g.state==='toCounter');
  const qn=guests.filter(g=>['queue','toQueue'].includes(g.state)).length, wn=guests.filter(g=>g.state==='seated'||g.state==='toSeat').length, idle=W.filter(w=>w.state==='idle'&&w.kind!=='fly').length;
  const cnt=`<div class="cnt"><span>Hàng chờ ${qn}</span><span>Ghế chờ ${wn}</span><span>Người rảnh ${idle}</span></div>`;
  const staffImg=k=>`<img class="pimg" src="${IMG[k]}" alt="">`;
  if(S.stage==='build'){ const r=readiness(), miss=r.filter(x=>!x.ok), ready=!miss.length;   // 24k: "Can mua:" + icon tung mon (cham -> Mua sam dung muc)
    const chips=miss.map(x=>`<button type="button" class="need" data-need="${x.id}" aria-label="Mua ${esc(x.t)}">${shopIco(slot(x.id))}<span>${esc(x.t)}</span></button>`).join('');
    h+=`<div class="counterv"><div class="pt">${staffImg('owner')}</div><div class="bub idle">${ready?'<span class="q">Đủ đồ rồi, khai trương thôi!</span>':`<span class="q">${TEN.thu.ghost}</span><span class="needs">${chips}</span>`}<button class="btn butter sm openb" id="open" ${ready?'':'disabled'}>Khai trương</button></div></div>`; }
  else if(atC){ const T=CTYPES[atC.type], sn=SERVICES[atC.want].name, say=haggling&&haggling.g===atC? haggling.chat[haggling.chat.length-1][1] : (atC.lastSay||`${sn}…`);
    const f=haggling&&haggling.g===atC? Math.max(.1,1-(haggling.round-1)/3) : 1;
    h+=`<div class="counterv"><div class="pt">${portrait(atC)}</div><div class="bub"><div class="q"><span class="kh">Khách hỏi</span>${esc(say).replace(sn,`<em>${sn}</em>`)}</div><div class="pl">KIÊN NHẪN<span class="b"><i class="${f<.4?'crit':f<.7?'low':''}" style="width:${f*100}%"></i></span></div>${cnt}</div></div>`; }
  else h+=`<div class="counterv"><div class="pt">${staffImg(S.cashier?'recep':'owner')}</div><div class="bub idle"><b>${open?'Đang chờ khách…':'Tiệm đang đóng cửa'}</b>${open?cnt:''}</div></div>`;
  const zone=(title,sub,ids,cls)=>{ const items=ids.map(id=>{ const s=slot(id); return trayHTML(s, TEN.slot(id)||(s.zone==='chan'?'Ghế '+(s.seat+1):'Giường '+(s.need+1))); }).join(''); return items?`<div class="plaque">${title}${sub?`<small>${sub}</small>`:''}</div><div class="trays ${cls||''}">${items}</div>`:''; };
  h+=zone(TEN.khu.don,'',['cashier','sofa','tea','towel','changing'],'c5');
  h+=zone('Massage chân',p?`${ownedChairs().length}/${p.chairs} ghế · mỗi ghế 1 khách`:'',SLOTS.filter(s=>s.zone==='chan').map(s=>s.id));
  h+=zone('Phòng body',p?`${ownedBeds().length}/${p.rooms} giường · mỗi giường 1 khách`:'',[...SLOTS.filter(s=>s.id.startsWith('room')).map(s=>s.id),'trolley'],'c5');
  B.innerHTML=h; boardPop=null;
}
$('#board').addEventListener('click',e=>{
  const sp=e.target.closest('[data-speed]'); if(sp){ speed=+sp.dataset.speed; renderBoard(); return; }
  if(e.target.closest('#open')){ if(!e.target.closest('#open').disabled){ startDay(); toast('Khai trương hồng phát! Khách đang tới.','good'); } return; }
  const t=e.target.closest('[data-slot]'); if(t) openSlot(t.dataset.slot);
});
heroSVG=(orig=>function(s){ const k=imgOf(s); return k&&IMG[k]?`<img src="${IMG[k]}" alt="" style="width:110px;height:90px;object-fit:contain;flex:none">`:orig(s); })(heroSVG);
setInterval(()=>{ if(tab==='shop' && $('#sheetBg').hidden) renderBoard(); },400);
renderScreen=(orig=>function(){ orig(); renderBoard(); })(renderScreen);
let phoneSig=''; setInterval(()=>{ if(tab!=='phone'||!$('#sheetBg').hidden) return; const ae=document.activeElement; if(ae&&(ae.id==='flyG'||ae.id==='flyN')) return; const sig=guests.filter(g=>g.state==='seated'&&!g.flyRes).map(g=>g.id).join(',')+'|'+S.group.length; if(sig!==phoneSig){ phoneSig=sig; renderScreen(); } },800);

// 15b-reviews.js — v1.9: Đánh giá của khách + trả lời của chủ quán
// Nạp sau 15-board.js, trước 16-boot.js. Bọc lại (monkey-patch): rating, finishService, pay, deal, pickType, hourCurve, renderScreen, renderNav, endDay.
'use strict';
if(!Array.isArray(S.reviews)) S.reviews=[];
S.rv=Object.assign({devotion:0, vouchers:0, badPress:0, nextId:1}, S.rv||{});
unread.reviews=false;

// ---------- số liệu ----------
const RV={
  prior:{stars:4, n:5},              // 5 đánh giá mồi 4★ để tiệm mới không rớt sao vì 1 khách
  decay:0.98, window:50, keep:200,
  write:s=>s>=85?.30:s>=60?.10:s>=40?.25:.60,   // khách bực viết nhiều hơn
  tayMul:1.3, bloggerRate:1/200, bloggerW:5,
  timing:days=>days<=0?1:days<=2?.6:.2          // trả lời trong ngày hiệu lực cao nhất
};
const starsOf=s=>s>=90?5:s>=75?4:s>=55?3:s>=35?2:1;

// Điểm sao hiển thị: trung bình có trọng số 50 đánh giá gần nhất + đánh giá mồi
rating=function(){
  let num=RV.prior.stars*RV.prior.n, den=RV.prior.n;
  S.reviews.slice(0,RV.window).forEach((r,i)=>{ const w=Math.pow(RV.decay,i)*(r.w||1); num+=w*r.stars; den+=w; });
  return clamp(num/den,1,5);
};

// ---------- ghi lại lý do khách hài lòng / không (khớp công thức trong finishService) ----------
finishService=(orig=>function(g){
  const w=g.worker, stf=staffOf(w), lv=lvOf(w,g.want), bed=g.station&&g.station.t==='bed', R=[];
  const waitPen=Math.min(20,g.wait/WK*0.45);
  if(waitPen>=8) R.push(['wait',-waitPen]);
  if(g.squeezed) R.push(['squeezed',-6]);
  if(bed && !S.owned.changing) R.push(['nochange',-6]);
  if(bed && S.owned.changing) R.push(['change',6]);
  if(S.owned.tea) R.push(['tea',4]);
  if(S.owned.towel) R.push(['towel',3]);
  if(decorBonus()>=8) R.push(['decor',decorBonus()]);
  if(stf){ if(stf.lazy) R.push(['lazy',-12]); if((stf.done||0)>stf.st.e*2+4) R.push(['tired',-8]);
    if(stf.st.q>=8) R.push(['skill',(stf.st.q-5)*2.5]); else if(stf.st.q<=3) R.push(['noskill',(stf.st.q-5)*2.5]);
    if(stf.st.c>=8) R.push(['charm',3]); }
  if(w && w.kind==='fly' && w.spec===g.want) R.push(['flyspec',14]);
  if(w && w.kind==='owner' && lv>=4) R.push(['owner',lv*3]);
  g.rv={reasons:R, staffId:stf?stf.id:null, staffName:stf?stf.name.split(' ').pop():(w&&w.kind==='fly'?String(w.name||'').split(' (')[0]:w&&w.kind==='owner'?'chủ tiệm':'')};
  orig(g);
  if(g.problem) g.rv.problem=true;
})(finishService);

// ---------- mẫu câu ----------
const RV_VI={
  wait:['chờ gần tiếng mới tới lượt','đợi lâu quá','ngồi chờ mỏi cả lưng'],
  squeezed:['trả giá mệt quá','giá hơi chát so với chỗ khác'],
  nochange:['làm body mà không có chỗ thay đồ','phải thay đồ ngay trong phòng, bất tiện'],
  change:['có phòng thay đồ sạch sẽ','chỗ thay đồ gọn gàng'],
  tea:['được mời trà gừng ấm','trà gừng ngon'],
  towel:['khăn nóng thơm','khăn ấm sạch sẽ'],
  decor:['tiệm trang trí xinh','không gian đẹp, thư giãn'],
  lazy:['{K} làm qua loa','{K} vừa làm vừa bấm điện thoại'],
  tired:['{K} có vẻ đuối sức','{K} làm yếu tay dần'],
  skill:['{K} tay nghề rất tốt','{K} bấm huyệt chuẩn'],
  noskill:['{K} tay nghề còn non','{K} bấm chưa đúng chỗ'],
  charm:['{K} dễ thương, nói chuyện vui'],
  flyspec:['thợ {K} làm đúng nghề, đã lắm'],
  owner:['chính {K} làm, rất tận tâm'],
  problemGood:['có sự cố nhỏ nhưng tiệm xử lý nhanh'],
  problemBad:['gặp sự cố mà tiệm xử lý không ra gì']
};
const RV_EN={
  wait:['waited almost an hour','the wait was too long'],
  squeezed:['had to haggle too much','a bit pricey'],
  nochange:['no changing room for the body massage'],
  change:['clean changing room'],
  tea:['lovely ginger tea'], towel:['nice hot towels'], decor:['beautiful, relaxing place'],
  lazy:['{K} was on the phone during the massage'], tired:['{K} seemed exhausted'],
  skill:['{K} has amazing hands','{K} really knows the pressure points'], noskill:['{K} is still learning'],
  charm:['{K} was so friendly'], flyspec:['{K} was an expert'], owner:['the owner {K} did it personally'],
  problemGood:['a small issue, handled quickly'], problemBad:['had a problem and nobody fixed it properly']
};
const RV_OPEN_VI={5:['Tuyệt vời!','Rất hài lòng.','Sẽ quay lại!'],4:['Khá ổn.','Hài lòng.'],3:['Tạm được.','Bình thường.'],2:['Hơi thất vọng.','Chưa ổn lắm.'],1:['Tệ.','Không quay lại nữa.']};
const RV_OPEN_EN={5:['Amazing!','Loved it!'],4:['Pretty good.','Nice.'],3:['It was okay.'],2:['Disappointing.'],1:['Terrible.','Never again.']};

const RV_SVC_EN={foot:'foot massage',neck:'neck & shoulder massage',body:'body massage',thai:'Thai massage',stone:'hot stone massage'};
const RV_MALE=['Tuấn','Minh','Phúc','Khoa'];
const vnName=()=>{ const n=pick(NAMES); return (RV_MALE.includes(n)?pick(['anh ','chú ']):pick(['chị ','cô ','bạn ']))+n; };
function reviewText(g,stars){
  const en=g.type==='tay', L=en?RV_EN:RV_VI, reasons=[...(g.rv?g.rv.reasons:[])];
  if(g.rv&&g.rv.problem) reasons.push(g.sat<=30?['problemBad',-15]:['problemGood',3]);
  const pos=stars>=4, pool=reasons.filter(r=>pos? r[1]>0 : r[1]<0).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1]));
  const picks=pool.slice(0,2).map(r=>pick(L[r[0]]).replace('{K}',g.rv.staffName||(en?'the therapist':'KTV')));
  const svc=en? RV_SVC_EN[g.want] : SERVICES[g.want].name.toLowerCase();
  const fb=en? (stars>=4?`good ${svc}`:stars===3?'nothing special':`${svc} not worth the price`) : (stars>=4?`${svc} ổn`:stars===3?'không có gì đặc biệt':`${svc} chưa đáng tiền`);
  let body=picks.length? picks.join(en?', ':', ') : fb;
  body=body.charAt(0).toUpperCase()+body.slice(1)+'.';
  return `${pick((en?RV_OPEN_EN:RV_OPEN_VI)[stars])} ${body}`;
}

function makeReview(g){
  const blogger=Math.random()<RV.bloggerRate;
  let p=RV.write(g.sat)*(g.type==='tay'?RV.tayMul:1);
  if(!blogger && Math.random()>=p) return;
  const stars=starsOf(g.sat);
  const name=blogger? 'Travel blogger @'+pick(['wanderpq','islandhopper','spa.diaries']) : g.type==='tay'? pick(['Anna','Tom','Lucas','Mia','Noah','Emma','Oliver','Sofia','Min-ji','Arjun']) : vnName();
  const r={id:S.rv.nextId++, d:S.day, t:S.time, name, type:g.type, pid:g.pid, stars, orig:stars, text:reviewText(g,stars), svc:g.want,
    reasons:(g.rv?g.rv.reasons:[]).map(x=>x[0]), staffId:g.rv?g.rv.staffId:null, w:blogger?RV.bloggerW:1, blogger, reply:null};
  S.reviews.unshift(r); S.reviews=S.reviews.slice(0,RV.keep);
  if(r.staffId){ const st=S.staff.find(s=>s.id===r.staffId); const mention=r.reasons.some(k=>['lazy','tired','skill','noskill','charm'].includes(k));
    if(st && mention) st.morale=clamp(st.morale+(stars>=4?5:stars<=2?-5:0),0,100); }
  if(tab!=='phone'||phoneTab!=='reviews') unread.reviews=true;
  if(stars<=2) toast(`${blogger?'Blogger':'Khách'} vừa để lại ${stars}★. Vào Điện thoại › Đánh giá để trả lời.`,'warn');
  else if(blogger) toast(`Một blogger du lịch vừa viết ${stars}★ về tiệm!`,'good');
  renderNav();
}

pay=(orig=>function(g){
  if(g.problem) return orig(g);       // orig mở bảng sự cố rồi tự gọi lại pay
  orig(g); makeReview(g); save();
})(pay);

// Phiếu giảm 20% cho khách quay lại nhờ lời xin lỗi
deal=(orig=>function(g,price,squeezed){
  if(g.kind==='ret' && S.rv.vouchers>0 && !g.voucher){ g.voucher=true; S.rv.vouchers--; price=r10(price*0.8); bubble(g,'Chị có phiếu giảm giá nè em!'); }
  return orig(g,price,squeezed);
})(deal);

// Dưới 3,5★ khách Tây giảm 30%
pickType=(orig=>function(){ const t=orig(); if(t==='tay' && rating()<3.5 && Math.random()<.3) return 'dl'; return t; })(pickType);
// Cãi lại khách bị lan truyền: lượng khách −10% trong 3 ngày
hourCurve=(orig=>function(){ return orig()*(S.rv.badPress>=S.day?0.9:1); })(hourCurve);

// Nhiệm vụ 4,5 sao: tính theo đánh giá thật
{ const m=MISSIONS.find(x=>x[0]==='Đánh giá đạt 4,5 sao'); if(m) m[1]=()=>S.reviews.length>=10&&rating()>=4.5; }

// ---------- trả lời ----------
const REPLY={
  thank:{label:'Cảm ơn', vi:'Cảm ơn anh/chị đã ghé {S}! Hẹn gặp lại ạ.', en:'Thank you for visiting {S}! See you again.'},
  fix:{label:'Xin lỗi & sửa', vi:'Tiệm thành thật xin lỗi. Tiệm đã ghi nhận và đang sửa ngay ạ.', en:'We are truly sorry. We have noted this and are fixing it right away.'},
  voucher:{label:'Xin lỗi + phiếu giảm giá', vi:'Tiệm xin lỗi và gửi anh/chị phiếu giảm giá cho lần sau ạ.', en:'We apologise — here is a 20% voucher for your next visit.'},
  explain:{label:'Giải thích', vi:'Cảm ơn góp ý. Tiệm xin giải thích thêm để anh/chị hiểu hơn ạ.', en:'Thanks for the feedback, let us explain a little more.'},
  argue:{label:'Cãi lại', vi:'Tiệm làm đúng quy trình, anh/chị khó tính quá.', en:'We did everything right, you are just too picky.'}
};
const replyOpts=r=>r.stars>=4?['thank']:r.stars===3?['thank','explain']:['fix','voucher','explain','argue'];
const FIXABLE={nochange:()=>!!S.owned.changing, lazy:()=>!S.staff.some(s=>s.lazy), noskill:()=>true, tired:()=>true};
function doReply(id,kind){
  const r=S.reviews.find(x=>x.id===id); if(!r||r.reply) return;
  const k=RV.timing(S.day-r.d), up=()=>{ if(r.stars<5){ r.stars++; r.edited=true; } };
  let out='';
  if(kind==='thank'){ S.rv.devotion++; if(r.stars>=4 && Math.random()<.15*k){ S.returning++; out='Khách hẹn sẽ quay lại'; inboxMsg(r.name, r.type==='tay'?'Thanks for the reply! See you soon.':'Cảm ơn tiệm, bữa nào ghé lại nha.'); } }
  if(kind==='fix'){ const fixed=r.reasons.some(x=>FIXABLE[x]&&FIXABLE[x]()); if(Math.random()<(fixed?.7:.35)*k){ up(); out=`Khách sửa lên ${r.stars}★`; } }
  if(kind==='voucher'){ if(Math.random()<.6*k){ S.returning++; S.rv.vouchers++; out='Khách sẽ quay lại dùng phiếu'; } if(Math.random()<.3*k){ up(); out=(out?out+', ':'')+`sửa lên ${r.stars}★`; } }
  if(kind==='argue'){ if(Math.random()<.2){ S.rv.badPress=S.day+3; out='Bị chê khắp nơi! Khách ít đi vài ngày'; toast('Câu trả lời bị chia sẻ khắp nhóm du lịch, khách ít đi vài ngày.','warn'); } }
  r.reply={kind, d:S.day, text:(r.type==='tay'?REPLY[kind].en:REPLY[kind].vi).replace('{S}',S.name), out, late:S.day-r.d};
  if(out && kind!=='argue') toast(out,'good');
  save(); renderTop(); renderScreen();
}

// ---------- giao diện: Điện thoại › Đánh giá ----------
const starStr=n=>'★'.repeat(n)+'☆'.repeat(5-n);
function reviewsHTML(){
  const all=S.reviews, n=all.length, un=all.filter(r=>!r.reply&&r.stars<=3).length, rep=all.filter(r=>r.reply).length;
  const dist=[5,4,3,2,1].map(s=>[s,all.slice(0,RV.window).filter(r=>r.stars===s).length]), mx=Math.max(1,...dist.map(d=>d[1]));
  const card=r=>{ const T=CTYPES[r.type];
    const ago=S.day-r.d===0?'hôm nay':`${S.day-r.d} ngày trước`;
    const btns=!r.reply? `<div class="row" style="margin-top:6px">${replyOpts(r).map(k=>`<button class="btn sm ${k==='argue'?'danger':k==='thank'?'mint':'butter'}" data-rep="${r.id}" data-k="${k}">${REPLY[k].label}</button>`).join('')}</div>${S.day-r.d>0?`<div class="note" style="margin-top:3px">Trả lời muộn ${S.day-r.d} ngày: hiệu lực còn ${Math.round(RV.timing(S.day-r.d)*100)}%</div>`:''}` : '';
    const rp=r.reply? `<div class="pm me" style="margin-top:6px;max-width:100%"><b>Chủ tiệm trả lời${r.reply.late?` (muộn ${r.reply.late} ngày)`:''}</b>${esc(r.reply.text)}</div>${r.reply.out?`<span class="tag${r.reply.kind==='argue'?' warn':''}" style="margin-top:4px">${esc(r.reply.out)}</span>`:''}` : '';
    return `<div class="item" style="align-items:flex-start">${r.pid&&IMG[r.pid]?`<img class="av avimg" src="${IMG[r.pid]}" alt="">`:''}<div class="grow">
      <div class="n">${esc(r.name)} <span class="chip ${T.chip}">${T.name}</span>${r.blogger?' <span class="tag lav">Blogger ×5</span>':''}</div>
      <div class="m"><span class="stars" style="font-size:var(--fz-than)">${starStr(r.stars)}</span>${r.edited?` <span class="tag">đã sửa từ ${r.orig}★</span>`:''} · ${SERVICES[r.svc].name} · ${ago}</div>
      <div style="font-weight:700;font-size:var(--fz-than);margin-top:3px">${esc(r.text)}</div>${rp}${btns}</div></div>`; };
  return `<div class="seg"><button data-pt="group" aria-pressed="false">Nhóm Bay${unread.group?' •':''}</button><button data-pt="inbox" aria-pressed="false">Tin khách${unread.inbox?' •':''}</button><button data-pt="reviews" aria-pressed="true">Đánh giá</button></div>
  <div class="card"><div class="row" style="justify-content:space-between;align-items:flex-end"><div><div class="big-num">${rating().toFixed(1).replace('.',',')} <span class="stars" style="font-size:var(--fz-tieude)">★</span></div><div class="note">${n} đánh giá · đã trả lời ${n?Math.round(rep/n*100):0}% · chờ trả lời ${un}</div></div>
    <div style="min-width:150px">${dist.map(([s,c])=>`<div class="srow" style="grid-template-columns:18px 1fr 22px;font-size:var(--fz-ghichu)"><span>${s}★</span><span class="sbar"><i style="width:${c/mx*100}%"></i></span><span class="sv">${c}</span></div>`).join('')}</div></div>
    <p class="note" style="margin-top:6px">Sao tính từ 50 đánh giá gần nhất (mới nặng hơn cũ). Khách bực viết nhiều hơn khách vui. Trả lời trong ngày hiệu lực cao nhất. ${S.rv.badPress>=S.day?'<b style="color:var(--danger)">Đang bị chê khắp nơi, khách ít đi.</b>':''}${S.rv.vouchers?` Phiếu giảm giá đang chờ khách dùng: <b>${S.rv.vouchers}</b>.`:''}</p></div>
  <div class="list">${n?all.slice(0,40).map(card).join(''):'<p class="note">Chưa có đánh giá nào. Khách rất hài lòng hoặc rất bực mới hay viết.</p>'}</div>`;
}
renderScreen=(orig=>function(){
  orig();
  if(tab!=='phone') return;
  const D=$('#dyn');
  if(phoneTab==='reviews'){ unread.reviews=false; D.innerHTML=reviewsHTML(); renderNav(); return; }
  const seg=D.querySelector('.seg'); if(seg && !seg.querySelector('[data-pt="reviews"]')){
    seg.querySelectorAll('button').forEach(b=>{ b.textContent=b.textContent.replace('Nhóm Bay Spa','Nhóm Bay').replace('Tin nhắn khách','Tin khách'); });
    seg.insertAdjacentHTML('beforeend',`<button data-pt="reviews" aria-pressed="false">Đánh giá${unread.reviews?' •':''}</button>`); }
})(renderScreen);
$('#dyn').addEventListener('click',e=>{ const b=e.target.closest('[data-rep]'); if(b) doReply(+b.dataset.rep,b.dataset.k); });
renderNav=(orig=>function(){ orig(); if(unread.reviews){ const b=$('#nav [data-tab="phone"]'); if(b&&!b.querySelector('.dot')) b.insertAdjacentHTML('beforeend','<span class="dot"></span>'); } })(renderNav);

// ---------- tóm tắt cuối ngày ----------
endDay=(orig=>function(){
  const today=S.reviews.filter(r=>r.d===S.day);
  orig();
  const row=$('#sheet .row:last-child'); if(!row) return;
  const avg=today.length? today.reduce((a,r)=>a+r.stars,0)/today.length : 0, un=S.reviews.filter(r=>!r.reply&&r.stars<=3).length;
  row.insertAdjacentHTML('beforebegin',`<div class="note">Đánh giá mới hôm nay: <b>${today.length}</b>${today.length?` (trung bình ${avg.toFixed(1).replace('.',',')}★)`:''} · sao hiện tại <b>${rating().toFixed(1).replace('.',',')}★</b>${un?` · <b style="color:var(--danger)">${un} đánh giá chưa trả lời</b> — trả lời càng sớm càng hiệu quả`:''}.</div>`);
})(endDay);

// 15c-minigames.js — v2.0: Kho đồ, Hoa sen, trần phần thưởng, Bấm huyệt (khi chủ tự làm khách), Pha nước ngâm (khi gặp sự cố nước nguội). Bàn pha chế + 2048 ở 15d.
// Nạp sau 15b-reviews.js. Bọc lại: dispatch, finishService, problemSheet, renderBoard.
'use strict';
// ---------- dữ liệu ----------
const ING={
  sa:{name:'Sả', r:0}, gung:{name:'Gừng', r:0}, tram:{name:'Lá tràm', r:0}, dua:{name:'Dầu dừa', r:0},
  tieu:{name:'Tiêu Phú Quốc', r:1}, sim:{name:'Sim rừng', r:1},
  bazan:{name:'Đá bazan', r:2}, ngoctrai:{name:'Ngọc trai', r:3}
};
const RARITY=[{name:'Thường',p:.70,ref:20000,cls:''},{name:'Hiếm',p:.25,ref:60000,cls:'lav'},{name:'Quý',p:.045,ref:150000,cls:'warn'},{name:'Huyền thoại',p:.005,ref:500000,cls:'warn'}];
const ING_CAP=50;
const MG_GAMES={
  rub:{name:'Bấm huyệt bàn chân', bias:['gung','sa']},
  soak:{name:'Pha nước ngâm', bias:['sa','tram']},
  fold:{name:'Gấp khăn', bias:['dua','tram']}
};
const MG_REF={soak:5000, towel:25000};          // giá tham chiếu vật tư (theo giá lô)
const MG_SAT={S:12, A:7, B:0, C:-3};             // cộng vào hài lòng khi chủ tự bấm huyệt
const MG_ICON={soak:'m_soak1',oil:'i_oil',candle:'m_cnd1',towel:'i_towel',lotus:'i_happy',xp:'i_star',sa:'plant',gung:'plant2',tram:'plant',dua:'m_oil1',tieu:'i_stamina',sim:'plant2',bazan:'i_stone',ngoctrai:'i_money'};   // 20u: icon vật phẩm trên màn kết quả (dùng IMG sẵn có)
const gradeOf=sc=>sc>=90?'S':sc>=75?'A':sc>=50?'B':'C';
const playMul=n=>n<=3?1:n<=6?.5:.1;               // giảm dần theo lượt trong ngày

S.mg=Object.assign({day:0, used:0, plays:{}, pity:{rare:0, prec:0}, lotus:0, inv:{}, towels:0, askOwner:true, skipToday:0, best:{}}, S.mg||{});
function mgDay(){ if(S.mg.day!==S.day){ S.mg.day=S.day; S.mg.used=0; S.mg.plays={}; S.mg.towels=0; } }
function mgCap(){ const l=(S.svcLog||[]).slice(-3); const avg=l.length? l.reduce((a,x)=>a+(x.gross||0),0)/l.length : 0; return Math.min(300000+0.06*avg, 2e6); }
const invCount=()=>Object.values(S.mg.inv).reduce((a,b)=>a+b,0);

function rollRarity(){
  S.mg.pity.rare++; S.mg.pity.prec++;
  let r; if(S.mg.pity.prec>=60) r=2; else if(S.mg.pity.rare>=20) r=1;
  else { let x=Math.random(), acc=0; r=0; for(let i=0;i<RARITY.length;i++){ acc+=RARITY[i].p; if(x<acc){ r=i; break; } } }
  if(r>=1) S.mg.pity.rare=0; if(r>=2) S.mg.pity.prec=0;
  return r;
}
function rollIng(game){
  const r=rollRarity(); const pool=Object.keys(ING).filter(k=>ING[k].r===r);
  const bias=MG_GAMES[game].bias.filter(k=>ING[k].r===r);
  return (bias.length&&Math.random()<.5)? pick(bias) : pick(pool);
}

// Phát thưởng: chặn theo trần giá trị/ngày và giảm dần theo lượt
function mgGrant(game, score, supplies){
  mgDay();
  const n=(S.mg.plays[game]||0)+1; S.mg.plays[game]=n;
  const grade=gradeOf(score), mul=playMul(n), cap=mgCap(), out=[];
  S.mg.best[game]=Math.max(S.mg.best[game]||0, score);
  let budget=Math.max(0,cap-S.mg.used), items=[];
  // vật tư
  (supplies||[]).forEach(([key,qty])=>{
    let q=Math.floor(qty*mul); if(key==='towel') q=Math.min(q, 12-S.mg.towels);
    const ref=key==='towel'?MG_REF.towel:MG_REF.soak; q=Math.max(0,Math.min(q, Math.floor(budget/ref)));
    q=Math.min(q, SUP[key].cap-Math.floor(S.stock[key]));
    if(q>0){ S.stock[key]+=q; if(key==='towel') S.mg.towels+=q; S.mg.used+=q*ref; budget-=q*ref; out.push(`+${q} ${SUP[key].unit} ${SUP[key].name.toLowerCase()}`); items.push({k:key,n:q,lb:SUP[key].name}); }
  });
  // nguyên liệu (A: 60%, S: chắc chắn)
  const dropP=(grade==='S'?1:grade==='A'?.6:0)*mul;
  if(Math.random()<dropP && budget>=RARITY[0].ref){ const pity0={...S.mg.pity}; let k=rollIng(game);
    if(ING[k].r===1 && budget<RARITY[1].ref){ S.mg.pity={rare:pity0.rare+1, prec:pity0.prec+1}; k=pick(Object.keys(ING).filter(x=>ING[x].r===0)); }  // hết ngân sách: hạ xuống Thường, giữ bảo hiểm
    const ref=RARITY[ING[k].r].ref;
    { if((S.mg.inv[k]||0)<ING_CAP){ S.mg.inv[k]=(S.mg.inv[k]||0)+1; S.mg.used+=Math.min(ref,budget); out.push(`+1 ${ING[k].name} (${RARITY[ING[k].r].name})`); items.push({k,n:1,lb:`${ING[k].name} · ${RARITY[ING[k].r].name}`}); } else out.push(`${ING[k].name} đã đầy kho`); } }
  // Hoa sen
  const lotus=Math.round((grade==='S'?2:grade==='A'?1:0)*(mul>=1?1:mul>=.5?.5:0)); if(lotus){ S.mg.lotus+=lotus; out.push(`+${lotus} hoa sen`); items.push({k:'lotus',n:lotus,lb:'Hoa sen'}); }
  if(grade==='S' && game==='rub'){ S.xp+=5; out.push('+5 điểm nghề'); items.push({k:'xp',n:5,lb:'Điểm nghề'}); }
  const notes=[]; if(mul<1) notes.push(`Lượt thứ ${n} hôm nay: thưởng còn ${Math.round(mul*100)}%.`);
  if(S.mg.used>=cap-1) notes.push('Đã chạm trần phần thưởng hôm nay, mai chơi tiếp sẽ có đồ.');
  save();
  return {grade, score, out, notes, items};
}

// ---------- khung mini game ----------
let mgLive=null;   // {raf, done}
function mgStop(){ if(mgLive&&mgLive.raf) cancelAnimationFrame(mgLive.raf); mgLive=null; }
function mgIntro(game, desc, start, onSkip, skipLabel){
  mgStop();
  sheet(`${mgHead(game==='soak'?'i_foot':game==='rub'?'i_foot':'i_towel',MG_GAMES[game].name,desc)}
    <p class="note">Hôm nay đã chơi ${(mgDay(),S.mg.plays[game]||0)} lượt · điểm cao nhất ${S.mg.best[game]||0}.</p>
    <div class="row"><button class="btn alt" data-skip>${skipLabel||'Để sau'}</button><button class="btn big butter" data-start>Bắt đầu</button></div>`, sh=>{
      sh.querySelector('[data-skip]').onclick=()=>{ closeSheet(); if(onSkip) onSkip(); };
      sh.querySelector('[data-start]').onclick=start;
    });
}
function mgResult(game, score, supplies, extra, after){
  mgStop();
  const res=mgGrant(game, score, supplies);
  sheet(`<div class="mg-grade g${res.grade}">${res.grade}</div><h2 style="text-align:center">${MG_GAMES[game].name}: ${Math.round(score)} điểm</h2>
    ${extra?`<p class="note" style="text-align:center">${extra}</p>`:''}
    ${res.items.length?`<div class="mg-res">${res.items.map(it=>`<div class="rt">${mgImg(MG_ICON[it.k]||'i_star')}<b>+${it.n}</b><small>${esc(it.lb)}</small></div>`).join('')}</div>`:'<p class="note" style="text-align:center">Lượt này không có vật phẩm.</p>'}
    ${res.out.filter(t=>/đầy kho/.test(t)).map(t=>`<p class="note" style="text-align:center">${esc(t)}</p>`).join('')}
    ${res.notes.length?`<p class="note mg-resn">${res.notes.join(' ')}</p>`:''}
    <div class="row"><button class="btn big butter" data-ok>Xong</button></div>`, sh=>{
      sh.querySelector('[data-ok]').onclick=()=>{ closeSheet(); renderAll(); if(after) after(res); };
    });
  return res;
}
// Người chơi bấm ra ngoài làm đóng bảng giữa chừng → coi như bỏ qua
function mgGuard(onAbort){ if($('#sheetBg').hidden){ mgStop(); onAbort(); return true; } return false; }
function floatTxt(stage,x,y,t,cls){ const e=document.createElement('div'); e.className='mg-fb '+(cls||''); e.style.left=x+'%'; e.style.top=y+'%'; e.textContent=t; stage.appendChild(e); setTimeout(()=>e.remove(),700); }

// ---------- 1. Bấm huyệt bàn chân (nhịp) ----------
const RUB_PTS=[[42,18],[58,26],[46,40],[60,52],[44,64],[56,78],[48,30],[52,60]];
function playRub(lv, onEnd, onAbort){
  const D=0.8+0.1*clamp(lv||1,1,5), GAP=D+0.3, BEATS=8;
  $('#sheet').innerHTML=`${mgHead('i_foot','Bấm huyệt bàn chân','Chạm huyệt khi vòng khép khớp chấm hồng.')}
    <div class="mg-stage" id="mgStage" style="background-image:url('${IMG.i_foot}')"></div><div class="mg-hud" id="mgHud">0 / ${BEATS}</div>`;
  const stage=$('#mgStage'), hud=$('#mgHud'), t0=performance.now()/1000+0.6, beats=[];
  for(let i=0;i<BEATS;i++){ const [x,y]=RUB_PTS[i]; beats.push({x,y,tp:t0+i*GAP+D, show:t0+i*GAP, el:null, score:null}); }
  let judged=0, sum=0;
  const judge=(b,sc,label,cls)=>{ b.score=sc; sum+=sc; judged++; floatTxt(stage,b.x,b.y-8,label,cls); if(b.el){ b.el.classList.add('done'); setTimeout(()=>b.el&&b.el.remove(),250); } hud.textContent=`${judged} / ${BEATS}`; };
  const loop=()=>{
    if(mgGuard(onAbort)) return;
    const now=performance.now()/1000;
    beats.forEach(b=>{
      if(b.score!==null) return;
      if(now>=b.show && !b.el){ b.el=document.createElement('button'); b.el.className='mg-pt'; b.el.style.left=b.x+'%'; b.el.style.top=b.y+'%'; b.el.innerHTML='<i class="ring"></i><i class="dotp"></i>'; b.el.setAttribute('aria-label','Huyệt');
        b.el.onpointerdown=e=>{ e.preventDefault(); if(b.score!==null) return; const err=Math.abs(performance.now()/1000-b.tp);
          if(err<=0.08) judge(b,100,'Chuẩn!','good'); else if(err<=0.18) judge(b,70,'Tốt'); else if(err<=0.3) judge(b,40,'Được'); else judge(b,0,'Trượt','bad'); };
        stage.appendChild(b.el); }
      if(b.el){ const k=clamp((b.tp-now)/D,0,1); b.el.querySelector('.ring').style.transform=`scale(${1+1.6*k})`; }
      if(now>b.tp+0.35) judge(b,0,'Trượt','bad');
    });
    if(judged>=BEATS){ setTimeout(()=>onEnd(sum/BEATS),500); mgLive.raf=0; return; }
    mgLive.raf=requestAnimationFrame(loop);
  };
  mgLive={raf:requestAnimationFrame(loop)};
}

// ---------- 2. Pha nước ngâm (nhiệt độ + thứ tự thảo dược) ----------
const HERBS=['Gừng','Sả','Muối hột','Lá tràm','Quế'];
function playSoak(onEnd, onAbort){
  $('#sheet').innerHTML=`${mgHead('i_tub','Pha nước ngâm','Bước 1: bấm Dừng khi kim nằm trong vùng 40–42°C.')}
    <div class="mg-gauge"><div class="zone" style="left:50%;width:10%"></div><div class="needle" id="mgNeedle"></div></div>
    <div class="row" style="justify-content:space-between"><span class="note">30°C</span><b id="mgTemp" class="big-num" style="font-size:var(--fz-tieude)">—</b><span class="note">50°C</span></div>
    <div class="row"><button class="btn big butter" id="mgStop">Dừng</button></div>`;
  let ph=Math.random()*6, sp=2.2, temp=40, stopped=false; const t0=performance.now();
  const loop=()=>{
    if(mgGuard(onAbort)) return;
    if(stopped) return;
    const el=(performance.now()-t0)/1000; ph+=0.016*(sp+el*0.5);
    temp=40+10*Math.sin(ph); const nd=$('#mgNeedle'); if(nd) nd.style.left=((temp-30)/20*100)+'%';
    const tt=$('#mgTemp'); if(tt) tt.textContent=temp.toFixed(1).replace('.',',')+'°C';
    mgLive.raf=requestAnimationFrame(loop);
  };
  mgLive={raf:requestAnimationFrame(loop)};
  $('#mgStop').onclick=()=>{ stopped=true; const d=Math.abs(temp-41); const tScore=d<=1?60:d<=2?40:d<=4?20:0;
    const recipe=[...HERBS].sort(()=>Math.random()-.5).slice(0,3);
    $('#sheet').innerHTML=`${mgHead('i_tub','Pha nước ngâm','')}<p class="note">Nhiệt độ ${temp.toFixed(1).replace('.',',')}°C (+${tScore}). Bước 2: nhớ thứ tự thảo dược rồi thả lại đúng thứ tự.</p>
      <div class="mg-recipe" id="mgRecipe">${recipe.map((h,i)=>`<span class="sk">${i+1}. ${h}</span>`).join(' ')}</div><div class="hg-actions" id="mgHerbs"></div><p class="note" id="mgPick"></p>`;
    setTimeout(()=>{ if(mgGuard(onAbort)) return; const rc=$('#mgRecipe'); if(!rc) return; rc.innerHTML='<span class="note">Thả thảo dược theo thứ tự vừa thấy</span>';
      let idx=0, hScore=0, over=false; const box=$('#mgHerbs');
      box.innerHTML=[...HERBS].sort(()=>Math.random()-.5).map(h=>`<button class="btn alt" data-h="${h}">${h}</button>`).join('');
      box.querySelectorAll('[data-h]').forEach(b=>b.onclick=()=>{ if(over) return; const ok=b.dataset.h===recipe[idx];
        b.disabled=true; b.classList.add(ok?'mint':'danger'); $('#mgPick').textContent=ok?`Đúng ${idx+1}/3`:`Sai, phải là ${recipe[idx]}`;
        if(ok){ hScore+=40/3; idx++; } if(!ok||idx>=3){ over=true; setTimeout(()=>onEnd(tScore+hScore, `Nhiệt độ +${tScore}, thảo dược +${Math.round(hScore)}`),600); } });
    },1800);
  };
}

// ---------- 3. Gấp khăn (nhớ chuỗi) ----------
const FOLDS=[['up','Gấp đôi','↑'],['right','Gấp ba','→'],['down','Cuộn tròn','↓'],['left','Xoắn thiên nga','←']];
function playFold(onEnd, onAbort){
  const LENS=[3,4,5,6], TOTAL=LENS.reduce((a,b)=>a+b,0); let round=0, got=0, seq=[];
  $('#sheet').innerHTML=`<h2>Gấp khăn</h2><p class="note" id="mgMsg">Nhìn thứ tự nếp gấp rồi làm lại y hệt.</p>
    <div class="mg-fold">${FOLDS.map(f=>`<button class="btn alt" data-f="${f[0]}" disabled><span style="font-size:var(--fz-tieude)">${f[2]}</span><br>${f[1]}</button>`).join('')}</div><div class="mg-hud" id="mgHud"></div>`;
  const btns=[...$('#sheet').querySelectorAll('[data-f]')], msg=$('#mgMsg'), hud=$('#mgHud');
  const setDis=v=>btns.forEach(b=>b.disabled=v);
  const show=()=>{ if(mgGuard(onAbort)) return; seq=[]; for(let i=0;i<LENS[round];i++) seq.push(pick(FOLDS)[0]);
    setDis(true); msg.textContent=`Vòng ${round+1}/4: nhìn kỹ ${LENS[round]} nếp gấp…`; hud.textContent=`${got} / ${TOTAL}`;
    seq.forEach((f,i)=>{ setTimeout(()=>{ const b=btns.find(x=>x.dataset.f===f); if(!b) return; b.classList.add('lit'); setTimeout(()=>b.classList.remove('lit'),380); }, 600+i*560); });
    setTimeout(()=>{ if(mgGuard(onAbort)) return; setDis(false); msg.textContent='Tới lượt bạn gấp.'; input(0); }, 600+seq.length*560);
  };
  const input=pos=>{ btns.forEach(b=>b.onclick=()=>{ if(mgGuard(onAbort)) return; b.classList.add('lit'); setTimeout(()=>b.classList.remove('lit'),150);
      if(b.dataset.f===seq[pos]){ got++; pos++; hud.textContent=`${got} / ${TOTAL}`; if(pos>=seq.length){ round++; setDis(true); if(round>=LENS.length) return onEnd(got/TOTAL*100, 'Gấp đủ 4 vòng!'); msg.textContent='Chuẩn! Vòng tiếp theo…'; setTimeout(show,700); } else input(pos); }
      else { setDis(true); msg.textContent='Sai nếp rồi!'; setTimeout(()=>onEnd(got/TOTAL*100, `Gấp đúng ${got}/${TOTAL} nếp`),700); } }); };
  mgLive={raf:0}; show();
}

// ---------- mở từ bảng tiệm ----------
function openSoak(after){ mgIntro('soak','Giữ nhiệt đúng, thả thảo dược theo thứ tự.',
  ()=>playSoak((sc,ex)=>mgResult('soak',sc,[['soak',Math.round(5+15*sc/100)]],ex,after), ()=>{}), null); }
function openFold(){ mgIntro('fold','Gấp khăn cho góc khăn. Mỗi lượt ra 2–6 khăn, tối đa 12 khăn/ngày.',
  ()=>playFold((sc,ex)=>mgResult('fold',sc,[['towel',Math.round(2+4*sc/100)]],ex), ()=>{})); }
// 20u: luyện tay Bấm huyệt (không cần khách thật): thưởng theo luật lượt/ngày của mgGrant, không đổi hài lòng khách
function openRubPractice(){ mgIntro('rub','Luyện tay, không cần khách.',
  ()=>playRub(S.skills&&S.skills.foot?S.skills.foot.lv:1,(sc,sl)=>mgResult('rub',sc,[],'Luyện tay: không ảnh hưởng khách'),()=>{}),null); }
function openInv(){
  mgDay(); const cap=mgCap();
  const rows=Object.keys(ING).map(k=>{ const n=S.mg.inv[k]||0, R=RARITY[ING[k].r]; return `<div class="item${n?'':' own'}"><div class="grow"><div class="n">${ING[k].name} <span class="tag ${R.cls}">${R.name}</span></div><div class="m">${n}/${ING_CAP}</div></div><b>${n}</b></div>`; }).join('');
  sheet(`${mgHead('shelf','Kho đồ','Nguyên liệu đưa lên Bàn pha chế để gộp thành đồ cấp cao.')}<div class="tiles"><div class="tile"><b>${S.mg.lotus}</b><small>hoa sen</small></div><div class="tile"><b>${fmt(S.mg.used)}</b><small>thưởng hôm nay</small></div><div class="tile"><b>${fmt(cap)}</b><small>trần hôm nay</small></div></div>
    <p class="note">Thưởng mỗi ngày có hạn. Chơi nhiều thì thưởng ít dần. Hoa sen đổi thêm lượt ở Bàn pha chế.</p>
    <div class="list">${rows}</div>
    <p class="note">Chơi đều tay thì chắc chắn ra đồ hiếm và đồ quý.</p>
    <label class="switch"><input type="checkbox" id="mgAsk" ${S.mg.askOwner?'checked':''}> Khi chủ tiệm tự làm khách foot / cổ vai gáy, mời chơi Bấm huyệt</label>
    <div class="row"><button class="btn big butter" data-x>Đóng</button></div>`, sh=>{
      sh.querySelector('[data-x]').onclick=closeSheet;
      sh.querySelector('#mgAsk').onchange=e=>{ S.mg.askOwner=e.target.checked; save(); };
    });
}

// ---------- chủ tiệm tự bấm huyệt khi phục vụ ----------
dispatch=(orig=>function(w,g,st){
  orig(w,g,st);
  if(w.kind!=='owner' || !['foot','neck'].includes(g.want) || !S.mg.askOwner || S.mg.skipToday===S.day) return;
  if(!$('#sheetBg').hidden || haggling) return;      // đang có bảng khác thì chủ làm như thường
  const lv=S.skills[g.want]?S.skills[g.want].lv:1;
  sheet(`${mgHead('i_foot','Chủ tiệm tự làm '+SERVICES[g.want].name.toLowerCase(),'')}<div class="scene-s">${portrait(g)}<p>Tự tay bấm huyệt cho khách? Điểm cao thì khách hài lòng hơn (S +12, A +7), điểm thấp thì kém hơn làm bình thường một chút (C −3).</p></div>
    <label class="switch"><input type="checkbox" id="mgNoMore"> Hôm nay không hỏi nữa</label>
    <div class="row"><button class="btn alt" data-skip>Làm bình thường</button><button class="btn big butter" data-start>Bấm huyệt</button></div>`, sh=>{
      const noMore=()=>{ if(sh.querySelector('#mgNoMore').checked) S.mg.skipToday=S.day; };
      sh.querySelector('[data-skip]').onclick=()=>{ noMore(); closeSheet(); };
      sh.querySelector('[data-start]').onclick=()=>{ noMore(); playRub(lv, (sc,sl)=>{ g.mgGrade=gradeOf(sc); g.mgSleep=sl?sl.bonus:0; mgResult('rub',sc,[],`Khách sẽ ${MG_SAT[g.mgGrade]>=0?'+':''}${MG_SAT[g.mgGrade]} hài lòng${sl?` · khách ngủ quên, tip +${Math.round(sl.bonus*100)}%`:''}`); }, ()=>{}); };
    });
})(dispatch);
RV_VI.mgGood=['chủ tiệm bấm huyệt quá đã','chủ tiệm tay nghề đỉnh']; RV_VI.mgBad=['chủ tiệm bấm hơi vụng'];
RV_EN.mgGood=['the owner has magic hands']; RV_EN.mgBad=['the owner was a bit clumsy'];
finishService=(orig=>function(g){
  const grade=g.mgGrade; orig(g);
  if(grade){ const m=MG_SAT[grade]; g.sat=clamp(g.sat+m,0,100); if(g.rv&&m) g.rv.reasons.push([m>0?'mgGood':'mgBad',m]); g.mgGrade=null; }
})(finishService);

// ---------- sự cố "nước ngâm nguội": tự tay pha lại ----------
problemSheet=(orig=>function(g,done){
  orig(g,done);
  if(S.manager || !g.problem || !/nước ngâm/.test(g.problem.t)) return;
  const list=$('#sheet .list'); if(!list) return;
  list.insertAdjacentHTML('afterbegin','<button class="btn mint" style="text-align:left;white-space:normal" data-mgfix>Tự tay pha lại nước ngâm (mini game)</button>');
  list.querySelector('[data-mgfix]').onclick=()=>{
    const pb=g.problem;
    playSoak((sc,ex)=>{ const q=sc>=75?2:sc>=50?1:0;
      mgResult('soak',sc,[['soak',Math.round(5+15*sc/100)]],ex+(q===2?' · Khách rất hài lòng với thau nước mới':q===1?' · Khách tạm chịu':' · Khách vẫn chê'),()=>{
        if(q===2){ S.xp+=10; S.solved=(S.solved||0)+1; toast('Xử lý êm xuôi! +10 điểm nghề.','good'); }
        else if(q===1){ g.price=r10(g.price*0.9); toast('Khách tạm hài lòng, được giảm giá.'); }
        else { g.sat=25; g.tip=0; toast('Khách bực mình, để lại đánh giá xấu.','warn'); }
        g.problem=null; done(); });
    }, ()=>{ problemSheet(g,done); });
    void pb;
  };
})(problemSheet);

// ---------- thanh việc tay dưới bảng tiệm ----------
renderBoard=(orig=>function(){
  orig(); const B=$('#board'); if(!B||tab!=='shop'||!S.prem) return;
  mgDay();
  const m=S.mg.board?S.mg.board.filter(mbTop).length:0, g2=S.mg.g2048;
  B.insertAdjacentHTML('beforeend',`<div class="plaque">Việc tay<small>Hôm nay ${fmt(S.mg.used)}/${fmt(mgCap())}</small></div><div class="trays mgbar">
    <button class="tray" data-mg="rub">${mgImg('i_foot','art')}<span class="lab">Bấm huyệt</span></button>
    <button class="tray" data-mg="soak">${mgImg('m_soak1','art')}<span class="lab">Pha nước ngâm</span></button>
    <button class="tray" data-mg="merge">${mgImg('i_oil','art')}<span class="lab">Bàn pha chế</span>${m?`<span class="bd">${m}</span>`:''}</button>
    <button class="tray" data-mg="g2048">${mgImg('i_towel','art')}<span class="lab">Tủ spa 2048</span>${g2?'<span class="bd">…</span>':''}</button>
  </div>`);
})(renderBoard);
$('#board').addEventListener('click',e=>{ const b=e.target.closest('[data-mg]'); if(!b) return; const k=b.dataset.mg; if(k==='rub') openRubPractice(); if(k==='soak') openSoak(); if(k==='merge') openMerge(); if(k==='g2048') openG2048(); if(k==='inv') openInv(); if(k==='daily') openDaily(); });

// 15d-merge2048.js — v2.0c: 2 mini game theo lối chơi quen thuộc
//  • Bàn pha chế (gộp đồ kiểu merge): 4 dòng nguyên liệu, mỗi dòng 7 cấp; cấp cuối là vật tư thật của quán (thu về kho, khỏi phải mua)
//  • Tủ spa 2048: luật 2048 gốc, ô chỉ hiện số, kiểu nút tròn viền đậm của game
'use strict';
MG_GAMES.merge={name:'Bàn pha chế', bias:['tieu','sim']};
MG_GAMES.g2048={name:'Tủ spa 2048', bias:['dua','tram']};
const mgImg=(k,cls)=>IMG[k]?`<img class="${cls||''}" src="${IMG[k]}" alt="" draggable="false">`:'';
const mgHead=(icon,title,sub)=>`<div class="mg-head"><span class="mg-ico">${mgImg(icon)}</span><div><h2>${title}</h2>${sub?`<div class="note">${sub}</div>`:''}</div></div>`;

// Hình cấp 1..6 là hình clay (assets/img/m_<tên>N.webp, khoá IMG m_<tên>N); cấp 7 lấy hình vật tư thật (fb)

// ---------- 4 dòng đồ, 7 cấp; cấp cuối = vật tư thật (≈ 1 lô nhập, giá tham chiếu ~250k) ----------
const CHAINS={
  oil:{name:'Dầu massage', sup:'oil', qty:1000, tiers:[['oil1','Hạt sả'],['oil2','Mầm sả'],['oil3','Sả non'],['oil4','Sả già'],['oil5','Sả phơi khô'],['oil6','Lọ tinh dầu sả'],['oil7','Can dầu massage 1 lít','i_oil']]},
  soak:{name:'Thuốc ngâm chân', sup:'soak', qty:50, tiers:[['soak1','Lát gừng'],['soak2','Củ gừng'],['soak3','Bó gừng sả'],['soak4','Thảo mộc phơi'],['soak5','Túi thảo mộc'],['soak6','Hộp thuốc ngâm'],['soak7','Thùng 50 gói thuốc ngâm','i_foot']]},
  candle:{name:'Nến thơm', sup:'candle', qty:10, tiers:[['cnd1','Giọt sáp ong'],['cnd2','Viên sáp'],['cnd3','Khối sáp'],['cnd4','Nồi sáp chảy'],['cnd5','Sáp pha tinh dầu'],['cnd6','Nến rót hũ'],['cnd7','Hộp 10 nến thơm','diffuser']]},
  towel:{name:'Khăn', sup:'towel', qty:10, tiers:[['twl1','Nụ bông'],['twl2','Bông gòn'],['twl3','Cuộn sợi'],['twl4','Tấm vải'],['twl5','Khăn thô'],['twl6','Khăn trắng'],['twl7','Chồng 10 khăn','i_towel']]}
};
const CH_KEYS=Object.keys(CHAINS), TOP_T=6, MB={cols:6, rows:6, energyDay:30, t2Chance:.15, buyCost:2, buyQty:6};
// Hình clay cho món trung gian (nạp bằng tools/import_merge.py → js/01b-merge-assets.js, khoá m_<tên>) được ưu tiên; chưa có thì dùng hình vẽ tay
const tierArt=(c,t)=>{ const [k,,fb]=CHAINS[c].tiers[t]; if(IMG['m_'+k]) return mgImg('m_'+k,'art'); if(fb) return mgImg(fb,'art'); return ''; };
// Nguyên liệu trong kho đưa lên bàn ở cấp tương đương giá trị (Thường ≈ cấp 3, Hiếm ≈ cấp 4, Quý ≈ cấp 5, Huyền thoại ≈ cấp 6)
const ING_TO_BOARD={sa:['oil',2], gung:['soak',2], tram:['soak',2], dua:['candle',2], tieu:['soak',3], sim:['candle',3], bazan:['*',4], ngoctrai:['*',5]};

// Chuyển save cũ: bàn cũ (dòng herb/stone, 4 cấp) bỏ đi
if(!S.mg.board || S.mg.board.length!==MB.cols*MB.rows || S.mg.board.some(x=>x&&!CHAINS[x.c])) S.mg.board=Array(MB.cols*MB.rows).fill(null);
if(S.mg.energy===undefined) S.mg.energy=MB.energyDay;
S.mg.eDay=S.mg.eDay||0; S.mg.made=S.mg.made||{};
function mbEnergy(){ if(S.mg.eDay!==S.day){ S.mg.eDay=S.day; S.mg.energy=Math.max(S.mg.energy,MB.energyDay); } }
const mbFree=()=>S.mg.board.findIndex(x=>!x);
const mbTop=it=>!!it && it.t===TOP_T;

// Thu sản phẩm cấp cuối thẳng vào kho vật tư của quán. Lượt lấy nguyên liệu/ngày là giới hạn, nên không tính vào trần phần thưởng.
function mbHarvest(i){
  const it=S.mg.board[i]; if(!mbTop(it)) return;
  const ch=CHAINS[it.c], s=SUP[ch.sup], room=s.cap-Math.floor(S.stock[ch.sup]);
  if(room<ch.qty*0.5){ toast(`Kho ${s.name.toLowerCase()} gần đầy (${Math.floor(S.stock[ch.sup])}/${s.cap}). Dùng bớt rồi hãy thu.`,'warn'); return; }
  const n=Math.min(ch.qty,room); S.stock[ch.sup]+=n; S.mg.board[i]=null; S.mg.lotus+=1;
  S.mg.made[ch.sup]=(S.mg.made[ch.sup]||0)+1; S.mg.plays.merge=(S.mg.plays.merge||0)+1;
  addLog(`Tự làm ${ch.tiers[TOP_T][1]} (khỏi mua ~${fmt(s.price*n/s.batch)})`,0);
  save(); mbRender(); renderTop(); renderNav();
  toast(`+${n} ${s.unit} ${s.name.toLowerCase()} vào kho · +1 hoa sen`,'good');
}
let mbSel=null, mbFx=null, mbNew=null;
function mbSpawn(){
  mbEnergy(); if(S.mg.energy<=0){ toast('Hết lượt lấy nguyên liệu hôm nay. Đổi hoa sen lấy thêm, hoặc chờ ngày mai.','warn'); return; }
  const f=mbFree(); if(f<0){ toast('Bàn đầy rồi, gộp bớt đồ đi.','warn'); return; }
  S.mg.energy--; S.mg.board[f]={c:pick(CH_KEYS), t:Math.random()<MB.t2Chance?1:0}; mbNew=f; save(); mbRender();
}
function mbAct(from,to){
  const B=S.mg.board, a=B[from], b=B[to]; if(from===to||!a) return false;
  if(!b){ B[to]=a; B[from]=null; }
  else if(b.c===a.c && b.t===a.t && !mbTop(a)){ B[to]={c:a.c,t:a.t+1}; B[from]=null; mbFx=to; }
  else { B[to]=a; B[from]=b; }                 // khác loại thì đổi chỗ
  mbSel=null; save(); mbRender(); return true;
}
function mbCell(it,i){
  if(!it) return `<div class="mg-cell empty" data-i="${i}"></div>`;
  const ch=CHAINS[it.c], name=ch.tiers[it.t][1], top=mbTop(it);
  return `<div class="mg-cell c-${it.c}${mbSel===i?' sel':''}${mbFx===i?' pop':''}${mbNew===i?' new':''}${top?' top':''}" data-i="${i}" title="${esc(name)}">${tierArt(it.c,it.t)}<span class="lv">${it.t+1}</span>${top?'<span class="bd harvest">Thu</span>':''}</div>`;
}
function mbInfo(){
  const el=$('#mbInfo'); if(!el) return;
  const it=mbSel!==null?S.mg.board[mbSel]:null;
  if(!it){ el.innerHTML='<span class="note">Chạm một món để xem tên và món tiếp theo.</span>'; return; }
  const ch=CHAINS[it.c], cur=ch.tiers[it.t][1];
  el.innerHTML= mbTop(it)? `<b>${cur}</b> <span class="note">· chạm lần nữa để thu vào kho (+${ch.qty} ${SUP[ch.sup].unit})</span>` : `<b>${cur}</b> <span class="note">cấp ${it.t+1}/7 · 2 món này gộp thành</span> <b>${ch.tiers[it.t+1][1]}</b>`;
}
function mbRender(){
  const g=$('#mbGrid'); if(!g) return; mbEnergy();
  g.innerHTML=S.mg.board.map(mbCell).join(''); mbFx=null; mbNew=null;
  const e=$('#mbEnergy'); if(e) e.textContent=S.mg.energy;
  const l=$('#mbLotus'); if(l) l.textContent=S.mg.lotus;
  const bb=$('#mbBuy'); if(bb) bb.disabled=S.mg.lotus<MB.buyCost;
  mbInfo();
}
function openMerge(){
  mgStop(); mbEnergy(); mbSel=null;
  const legend=CH_KEYS.map(k=>{ const c=CHAINS[k]; return `<div class="mg-chain"><b>${c.name}</b><span class="mg-steps">${c.tiers.map((t,i)=>`<span title="${esc(t[1])}">${tierArt(k,i)}</span>`).join('<i>›</i>')}</span><small>${c.tiers.map(t=>t[1]).join(' → ')}. Thu: +${c.qty} ${SUP[c.sup].unit} vào kho (khỏi mua ~${fmt(SUP[c.sup].price*c.qty/SUP[c.sup].batch)}).</small></div>`; }).join('');
  const invBtns=Object.keys(ING_TO_BOARD).filter(k=>(S.mg.inv[k]||0)>0).map(k=>{ const [c,t]=ING_TO_BOARD[k]; return `<button class="btn sm alt" data-ing="${k}">${ING[k].name} ×${S.mg.inv[k]} → ${c==='*'?`món cấp ${t+1} ngẫu nhiên`:CHAINS[c].tiers[t][1]}</button>`; }).join('');
  sheet(`<div class="mg-main"><div class="mg-grid mb" id="mbGrid" style="grid-template-columns:repeat(${MB.cols},1fr)"></div></div><div class="mg-side">${mgHead('i_oil','Bàn pha chế','Gộp 2 món giống nhau lên cấp mới.')}
    <div class="mg-top"><button class="mg-gen" id="mbGen">${mgImg('basket')}<span><b>Lấy nguyên liệu</b><small>còn <b id="mbEnergy">${S.mg.energy}</b> lượt hôm nay</small></span></button>
      <div class="mg-stat"><span>${mgImg('i_happy')}<b id="mbLotus">${S.mg.lotus}</b> sen</span><button class="btn sm lav" id="mbBuy">+${MB.buyQty} lượt · ${MB.buyCost} sen</button></div></div>
    <div class="mg-info" id="mbInfo"></div>
    <p class="note mg-hint">Kéo món vào món giống hệt.</p>
    ${invBtns?`<div class="card"><div class="sec-t">Đưa nguyên liệu trong kho lên bàn</div><div class="row" style="margin-top:6px">${invBtns}</div></div>`:''}
    <details class="card"><summary class="sec-t">4 dòng đồ ▾</summary><div class="list" style="margin-top:6px">${legend}</div></details>
    <div class="row"><button class="btn big butter" data-x>Đóng</button></div></div>`, sh=>{
      sh.querySelector('[data-x]').onclick=()=>{ closeSheet(); renderAll(); };
      sh.querySelector('#mbGen').onclick=mbSpawn;
      sh.querySelector('#mbBuy').onclick=()=>{ if(S.mg.lotus<MB.buyCost) return; S.mg.lotus-=MB.buyCost; S.mg.energy+=MB.buyQty; save(); mbRender(); };
      sh.querySelectorAll('[data-ing]').forEach(b=>b.onclick=()=>{ const k=b.dataset.ing, f=mbFree(); if(f<0){ toast('Bàn đầy rồi.','warn'); return; } if(!(S.mg.inv[k]>0)) return;
        let [c,t]=ING_TO_BOARD[k]; if(c==='*') c=pick(CH_KEYS); S.mg.inv[k]--; S.mg.board[f]={c,t}; mbNew=f; save(); openMerge(); });
      const g=sh.querySelector('#mbGrid'); let drag=null;
      g.addEventListener('pointerdown',e=>{ const c=e.target.closest('.mg-cell'); if(!c) return; drag={i:+c.dataset.i, x:e.clientX, y:e.clientY, moved:false, el:c}; });
      g.addEventListener('pointermove',e=>{ if(!drag||!S.mg.board[drag.i]) return; const dx=e.clientX-drag.x, dy=e.clientY-drag.y; if(!drag.moved && Math.hypot(dx,dy)>8){ drag.moved=true; drag.el.classList.add('drag'); try{ g.setPointerCapture(e.pointerId); }catch(_){} }
        if(drag.moved) drag.el.style.transform=`translate(${dx}px,${dy}px) scale(1.1)`; });
      g.addEventListener('pointerup',e=>{ if(!drag) return; const d=drag; drag=null; d.el.style.transform=''; d.el.classList.remove('drag');
        if(d.moved){ const t=document.elementFromPoint(e.clientX,e.clientY), c=t&&t.closest&&t.closest('.mg-cell'); if(c) mbAct(d.i,+c.dataset.i); else mbRender(); return; }
        const it=S.mg.board[d.i];
        if(mbSel!==null && mbSel!==d.i){ mbAct(mbSel,d.i); return; }
        if(mbSel===d.i && mbTop(it)){ mbHarvest(d.i); mbSel=null; mbRender(); return; }
        mbSel= it&&mbSel!==d.i ? d.i : null; mbRender(); });
      g.addEventListener('pointercancel',()=>{ if(drag){ drag.el.style.transform=''; drag.el.classList.remove('drag'); drag=null; } });
      mbRender();
    });
}

// =================== TỦ SPA 2048 (chỉ số) ===================
const g2048Score=m=>m>=11?100:m>=10?98:m>=9?92:m>=8?80:m>=7?60:m>=6?45:30;   // 2048/1024/512/256/128/64
function g2New(){ mgDay(); S.mg.g2Day=S.mg.g2Day===S.day? S.day : (S.mg.g2N=0, S.day); S.mg.g2N=(S.mg.g2N||0)+1;
  const g={grid:Array(16).fill(0), score:0, over:false, max:1, ms:[], dayN:S.mg.g2N}; g2Add(g); g2Add(g); return g; }
function g2Add(g){ const e=g.grid.map((v,i)=>v?-1:i).filter(i=>i>=0); if(!e.length) return -1; const i=pick(e); g.grid[i]=Math.random()<.9?1:2; return i; }
const G2L={left:[0,1,2,3].map(r=>[r*4,r*4+1,r*4+2,r*4+3]), right:[0,1,2,3].map(r=>[r*4+3,r*4+2,r*4+1,r*4]), up:[0,1,2,3].map(c=>[c,c+4,c+8,c+12]), down:[0,1,2,3].map(c=>[c+12,c+8,c+4,c])};
function g2Move(g,dir){
  let moved=false; const merged=[];
  G2L[dir].forEach(line=>{
    const vals=line.map(i=>g.grid[i]).filter(v=>v), out=[];
    for(let k=0;k<vals.length;k++){ if(vals[k]===vals[k+1]){ out.push(vals[k]+1); g.score+=Math.pow(2,vals[k]+1); k++; merged.push(line[out.length-1]); } else out.push(vals[k]); }
    while(out.length<4) out.push(0);
    line.forEach((idx,k)=>{ if(g.grid[idx]!==out[k]){ moved=true; g.grid[idx]=out[k]; } });
  });
  let added=-1; if(moved){ added=g2Add(g); g.max=Math.max(...g.grid); }
  g.over=!g2CanMove(g); return {moved, merged, added};
}
function g2CanMove(g){ if(g.grid.includes(0)) return true; for(let i=0;i<16;i++){ const r=i>>2, c=i&3; if(c<3&&g.grid[i]===g.grid[i+1]) return true; if(r<3&&g.grid[i]===g.grid[i+4]) return true; } return false; }
let g2Key=null;
// Thưởng theo mốc trong ván: đạt ô 128/256/512/1024/2048 lần đầu trong ván thì nhận ngay.
// Ván thứ 1–3 trong ngày nhận đủ, ván 4–6 nhận 50%, từ ván 7 nhận 10% (nguyên liệu chỉ ở 3 ván đầu).
const G2_MS={7:{sen:1, txt:'Mốc 128'}, 8:{sen:0, ing:0, txt:'Mốc 256'}, 9:{sen:2, energy:6, txt:'Mốc 512'}, 10:{sen:3, ing:1, energy:10, txt:'Mốc 1024'}, 11:{sen:5, pearl:true, txt:'Mốc 2048 — Bậc thầy 2048!'}};
function g2Milestone(g){
  g.ms=g.ms||[]; const out=[];
  for(let v=7; v<=Math.min(g.max,11); v++){
    if(g.ms.includes(v)) continue; g.ms.push(v);
    const m=G2_MS[v], mul=playMul(g.dayN||1), got=[];
    const sen=Math.floor(m.sen*mul+(mul>=1?0:0.5)); if(sen>0){ S.mg.lotus+=sen; got.push(`+${sen} hoa sen`); }
    if(m.energy){ const e=Math.floor(m.energy*mul); if(e>0){ S.mg.energy=(S.mg.energy||0)+e; got.push(`+${e} lượt Bàn pha chế`); } }
    if(m.ing!==undefined && mul>=1){ const pool=Object.keys(ING).filter(k=>ING[k].r===m.ing), k=m.ing===0? rollIng('g2048') : pick(pool);
      if((S.mg.inv[k]||0)<ING_CAP){ S.mg.inv[k]=(S.mg.inv[k]||0)+1; got.push(`+1 ${ING[k].name}`); } }
    if(m.pearl && mul>=1){ S.mg.inv.ngoctrai=(S.mg.inv.ngoctrai||0)+1; S.mg.title2048=true; got.push('+1 Ngọc trai'); }
    out.push({v, txt:m.txt, got});
  }
  if(out.length) save();
  return out;
}
function g2Celebrate(list){
  const wrap=$('.g2-wrap'); if(!wrap||!list.length) return;
  const m=list[list.length-1], img=IMG['g2048_'+m.v];
  const d=document.createElement('div'); d.className='g2-ms';
  d.innerHTML=`${img?`<img src="${img}" alt="">`:`<b class="big-num">${Math.pow(2,m.v)}</b>`}<b>${m.txt}</b><small>${list.map(x=>x.got.join(' · ')||'Đã nhận đủ thưởng mốc này hôm nay').join('<br>')}</small>`;
  wrap.appendChild(d); setTimeout(()=>d.classList.add('bye'),1900); setTimeout(()=>d.remove(),2300);
}
// Hướng dẫn vuốt: bàn tay vẽ tay lướt phải → trái → lên → xuống, hiện ở đầu mỗi ván cho tới lần vuốt đầu tiên
const G2_HAND=`<svg viewBox="0 0 48 60" aria-hidden="true">${G('<path d="M40 34c4-1 7 2 5 6l-4 7" fill="#F6D2B4"/><rect x="9" y="3" width="11" height="32" rx="5.5" fill="#F6D2B4"/><path d="M9 30v12c0 9 7 15 15 15h2c8 0 14-6 14-14V32c0-4-6-5-7-1 0-4-6-5-7-1 0-4-7-4-7 0v2" fill="#F6D2B4"/><path d="M26 31v4M33 31v4" fill="none" stroke-width="2"/>')}<ellipse cx="13" cy="9" rx="2" ry="3" fill="#FBF6EA" opacity=".7"/></svg>`;
const G2_TUT=`<div class="g2-tut" id="g2Tut" role="img" aria-label="Vuốt lên, xuống, trái, phải để gộp số">
  <div class="g2-trail"></div><div class="g2-hand"><i class="ripple"></i>${G2_HAND}</div>
  <div class="g2-tut-lbl"><b class="l1">Vuốt sang phải →</b><b class="l2">← Vuốt sang trái</b><b class="l3">↑ Vuốt lên</b><b class="l4">↓ Vuốt xuống</b><b class="l0">Vuốt lên · xuống · trái · phải</b></div>
  <small>Chạm để bắt đầu</small></div>`;
function g2Render(fx){
  const g=S.mg.g2048, el=$('#g2Grid'); if(!el||!g) return;
  el.innerHTML=g.grid.map((v,i)=>{ if(!v) return '<div class="g2-cell empty"></div>'; const n=Math.pow(2,v), d=String(n).length, anim=(fx&&fx.merged.includes(i)?' pop':'')+(fx&&fx.added===i?' new':'');
    if(IMG['g2048_'+v]) return `<div class="g2-cell pic${anim}" aria-label="${n}"><img src="${IMG['g2048_'+v]}" alt="${n}" draggable="false"></div>`;
    return `<div class="g2-cell v${Math.min(v,12)} d${d}${anim}"><span>${n}</span>${v>=11?'<i class="g2-star">★</i>':''}</div>`; }).join('');
  $('#g2Score').textContent=g.score; $('#g2Max').textContent=Math.pow(2,g.max);
  $('#g2Best').textContent=Math.max(S.mg.best2048||0,g.score);
  if(g.over) $('#g2Msg').innerHTML='<b>Hết đường đi!</b> Bấm nhận thưởng.';
}
function g2Finish(){
  const g=S.mg.g2048; if(!g) return; document.removeEventListener('keydown',g2Key);
  const sc=g2048Score(g.max);
  const rec=g.score>(S.mg.best2048||0) && g.score>=500; if(rec) S.mg.lotus+=2;
  S.mg.best2048=Math.max(S.mg.best2048||0,g.score); S.mg.g2048=null; save();
  const q=sc>=90?6:sc>=75?5:sc>=50?3:2;
  mgResult('g2048',sc,[['towel',q]],`Ô cao nhất ${Math.pow(2,g.max)} · ${g.score} điểm${rec?' · <b>Kỷ lục mới! +2 hoa sen</b>':''}`);
}
function openG2048(){
  mgStop(); if(!S.mg.g2048) S.mg.g2048=g2New();
  sheet(`<div class="mg-main"><div class="g2-wrap"><div class="g2-grid" id="g2Grid"></div>${S.mg.g2048.score===0?G2_TUT:''}</div></div><div class="mg-side">${mgHead('i_towel','Tủ spa 2048','Vuốt để gộp 2 ô cùng số.')}
    <div class="tiles"><div class="tile"><b id="g2Score">0</b><small>điểm</small></div><div class="tile"><b id="g2Max">2</b><small>ô cao nhất</small></div><div class="tile"><b id="g2Best">0</b><small>kỷ lục</small></div></div>
    <p class="note" id="g2Msg">Từ ô 128 có thưởng.</p>
    <div class="row"><button class="btn alt" data-x>Để sau</button><button class="btn big butter" data-end>Nhận thưởng & kết thúc</button></div></div>`, sh=>{
      const tut=()=>{ const t=sh.querySelector('#g2Tut'); if(t){ t.classList.add('bye'); setTimeout(()=>t.remove(),250); } };
      const go=dir=>{ tut(); const g=S.mg.g2048; if(!g||g.over) return; const r=g2Move(g,dir); if(r.moved){ save(); g2Render(r); const ms=g2Milestone(g); if(ms.length) g2Celebrate(ms); } };
      const tt=sh.querySelector('#g2Tut'); if(tt) tt.addEventListener('pointerdown',e=>{ e.stopPropagation(); tut(); });
      sh.querySelector('[data-x]').onclick=()=>{ document.removeEventListener('keydown',g2Key); closeSheet(); renderAll(); };
      sh.querySelector('[data-end]').onclick=g2Finish;
      const grid=sh.querySelector('#g2Grid'); let st=null;
      grid.addEventListener('pointerdown',e=>{ st={x:e.clientX,y:e.clientY}; try{ grid.setPointerCapture(e.pointerId); }catch(_){} });
      grid.addEventListener('pointerup',e=>{ if(!st) return; const dx=e.clientX-st.x, dy=e.clientY-st.y; st=null; if(Math.max(Math.abs(dx),Math.abs(dy))<24) return; go(Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up')); });
      document.removeEventListener('keydown',g2Key);
      g2Key=e=>{ if($('#sheetBg').hidden||!$('#g2Grid')){ document.removeEventListener('keydown',g2Key); return; } const m={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'}[e.key]; if(m){ e.preventDefault(); go(m); } };
      document.addEventListener('keydown',g2Key);
      g2Render();
    });
}

// 15e-daily.js — v2.1: Pha chế vật phẩm hỗ trợ, nhiệm vụ ngày, điểm danh chuỗi ngày thật, vườn thảo mộc
// Nạp sau 15d. Bọc lại: finishService, dispatch, hourCurve, spawn, doReply, mbAct, g2Milestone, openInv, startDay.
'use strict';
S.mg.items=S.mg.items||{};     // vật phẩm đã pha: {key:[ngày pha,...]}
S.mg.active=S.mg.active||{};   // đang dùng: {key:{until:ngày}} hoặc {key:{left:n}}

// =================== VẬT PHẨM HỖ TRỢ ===================
const BUFFS={
  tea:{name:'Trà gừng mật ong', img:'teatable', rec:{gung:2,sa:1}, sen:0, kind:'count', n:8, desc:'8 khách kế tiếp hài lòng hơn'},
  sim:{name:'Bánh sim', img:'i_happy', rec:{sim:2}, sen:1, kind:'instant', desc:'KTV buồn nhất vui lên'},
  lemon:{name:'Tinh dầu sả chanh', img:'m_oil6', rec:{sa:3,dua:1}, sen:2, kind:'day', desc:'KTV làm nhanh hơn, hết ngày'},
  pepper:{name:'Cao tiêu nóng', img:'i_stamina', rec:{tieu:2,dua:1}, sen:2, kind:'day', desc:'KTV không bị mệt vì làm nhiều khách, hết ngày'},
  stone:{name:'Bộ đá bazan chuẩn', img:'i_stone', rec:{bazan:1}, sen:3, kind:'day', desc:'Khách massage đá nóng hài lòng hơn, hết ngày'},
  incense:{name:'Nhang trầm khai vận', img:'diffuser', rec:{tram:2,sim:1}, sen:4, kind:'day', desc:'Khách đông hơn, hết ngày'},
  menu:{name:'Menu tiếng Anh in màu', img:'art', rec:{tram:1}, sen:6, kind:'day', desc:'Khách Tây chịu giá cao hơn, hết ngày'},
  flyvip:{name:'Vé thợ bay thân thiết', img:'i_money', rec:{}, sen:8, kind:'count', n:1, desc:'Lần gọi thợ bay tới trả công rẻ hơn'}
};
const BUFF_MAX=3, ITEM_LIFE=7, SAT_CAP=10;
const buffOn=k=>{ const a=S.mg.active[k]; if(!a) return false; return a.until!==undefined? a.until>=S.day : a.left>0; };
const activeCount=()=>Object.keys(BUFFS).filter(buffOn).length;
function itemsTidy(){ Object.keys(S.mg.items).forEach(k=>{ S.mg.items[k]=(S.mg.items[k]||[]).filter(d=>S.day-d<ITEM_LIFE); });
  Object.keys(S.mg.active).forEach(k=>{ if(!buffOn(k)) delete S.mg.active[k]; }); }
const canCraft=k=>{ const b=BUFFS[k]; return S.mg.lotus>=b.sen && Object.entries(b.rec).every(([i,n])=>(S.mg.inv[i]||0)>=n); };
function craft(k){ if(!canCraft(k)) return; const b=BUFFS[k]; S.mg.lotus-=b.sen; Object.entries(b.rec).forEach(([i,n])=>S.mg.inv[i]-=n);
  (S.mg.items[k]=S.mg.items[k]||[]).push(S.day); save(); toast(`Đã pha ${b.name}!`,'good'); openInv(); }
function useItem(k){
  itemsTidy(); const b=BUFFS[k], list=S.mg.items[k]||[]; if(!list.length) return;
  if(b.kind==='instant'){ const st=[...S.staff].sort((a,c)=>a.morale-c.morale)[0]; if(!st){ toast('Chưa có KTV nào để tặng bánh.','warn'); return; }
    st.morale=clamp(st.morale+15,0,100); list.shift(); save(); toast(`${st.name} ăn bánh sim, vui hẳn lên.`,'good'); openInv(); return; }
  if(buffOn(k)){ toast('Vật phẩm này đang có hiệu lực, cùng loại không cộng dồn.','warn'); return; }
  if(activeCount()>=BUFF_MAX){ toast(`Tối đa ${BUFF_MAX} vật phẩm chạy cùng lúc.`,'warn'); return; }
  list.shift(); S.mg.active[k]= b.kind==='day'? {until:S.stage==='open'?S.day:S.day+1} : {left:b.n};
  save(); toast(`Đang dùng: ${b.name}`,'good'); openInv(); renderAll();
}
// --- hiệu ứng ---
const withRested=(stf,fn)=>{ if(!stf||!buffOn('pepper')) return fn(); const d=stf.done||0; stf.done=0; try{ return fn(); } finally{ stf.done=d+((stf.done||0)); } };
dispatch=(orig=>function(w,g,st){
  withRested(staffOf(w),()=>orig(w,g,st));
  if(buffOn('lemon') && w.kind==='staff' && g.dur) g.dur*=0.9;
})(dispatch);
finishService=(orig=>function(g){
  const w=g.worker, want=g.want;
  withRested(staffOf(w),()=>orig(g));
  let bonus=0;
  if(buffOn('tea')){ bonus+=5; S.mg.active.tea.left--; }
  if(want==='stone' && buffOn('stone')) bonus+=8;
  bonus=Math.min(bonus,SAT_CAP); if(bonus){ g.sat=clamp(g.sat+bonus,0,100); }
  if(w && w.kind==='fly' && g.flyFee && buffOn('flyvip')){ g.flyFee=r10(g.price*0.4); S.mg.active.flyvip.left--; toast('Vé thợ bay thân thiết: trả công rẻ hơn.','good'); }
})(finishService);
hourCurve=(orig=>function(){ return orig()*(buffOn('incense')?1.1:1); })(hourCurve);
spawn=(orig=>function(kind){ const n=guests.length; orig(kind); const g=guests[guests.length-1]; if(guests.length>n && g && g.type==='tay' && buffOn('menu')) g.M*=1.05; })(spawn);

// Kho đồ: thêm phần pha chế + vật phẩm đang có
openInv=(orig=>function(){
  orig(); itemsTidy();
  const box=document.createElement('div'); box.className='list';
  const act=Object.keys(BUFFS).filter(buffOn).map(k=>{ const a=S.mg.active[k]; return `<span class="tag">${BUFFS[k].name}${a.left!==undefined?` · còn ${a.left}`:' · hết ngày'}</span>`; }).join(' ');
  box.innerHTML=`<div class="plaque">Pha chế vật phẩm<small>tối đa ${BUFF_MAX} vật phẩm chạy cùng lúc · để quá ${ITEM_LIFE} ngày sẽ hỏng</small></div>
    ${act?`<div class="row">${act}</div>`:''}
    ${Object.keys(BUFFS).map(k=>{ const b=BUFFS[k], have=(S.mg.items[k]||[]).length;
      const need=[...Object.entries(b.rec).map(([i,n])=>`${ING[i].name} ${S.mg.inv[i]||0}/${n}`), ...(b.sen?[`Sen ${S.mg.lotus}/${b.sen}`]:[])].join(' · ');
      return `<div class="item${have?'':' own'}">${mgImg(b.img,'ico')}<div class="grow"><div class="n">${b.name}${have?` <span class="tag">có ${have}</span>`:''}${buffOn(k)?' <span class="tag lav">đang dùng</span>':''}</div><div class="m">${b.desc}</div><div class="m">${need||'Không cần nguyên liệu'}</div></div>
        <div style="display:flex;flex-direction:column;gap:4px"><button class="btn sm butter" data-craft="${k}" ${canCraft(k)?'':'disabled'}>Pha</button>${have?`<button class="btn sm mint" data-use="${k}">Dùng</button>`:''}</div></div>`; }).join('')}`;
  const sh=$('#sheet'), last=sh.querySelector('.row:last-child'); sh.insertBefore(box,last);
  box.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>craft(b.dataset.craft));
  box.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>useItem(b.dataset.use));
})(openInv);

// =================== NHIỆM VỤ NGÀY ===================
const DQ_POOL={
  served:{t:n=>`Phục vụ ${n} lượt khách`, target:()=>{ const l=(S.svcLog||[]).slice(-3); const a=l.length? l.reduce((x,y)=>x+(y.served||0),0)/l.length : 8; return clamp(Math.round(a*0.9),6,60); }, val:()=>S.stats.served},
  rev:{t:n=>`Doanh thu hôm nay đạt ${fmt(n)}`, target:()=>{ const l=(S.svcLog||[]).slice(-3); const a=l.length? l.reduce((x,y)=>x+(y.gross||0),0)/l.length : 2e6; return Math.max(1.5e6, r10(a*0.9)); }, val:()=>S.stats.rev+S.stats.tips},
  reply:{t:n=>`Trả lời ${n} đánh giá của khách`, target:()=>2, val:()=>S.dq.cnt.reply||0, ok:()=>S.reviews.length>=2},
  merge:{t:n=>`Gộp ${n} lần ở Bàn pha chế`, target:()=>12, val:()=>S.dq.cnt.merge||0},
  harvest:{t:()=>'Thu 1 vật tư ở Bàn pha chế', target:()=>1, val:()=>S.dq.cnt.harvest||0},
  g128:{t:()=>'Chạm ô 128 trong Tủ spa 2048', target:()=>1, val:()=>S.dq.cnt.g128||0},
  premium:{t:n=>`Bán ${n} lượt body / Thái / đá nóng`, target:()=>4, val:()=>['body','thai','stone'].reduce((a,k)=>a+(S.stats.by[k]||0),0), ok:()=>['body','thai','stone'].some(canOffer)}
  // 10/10 Viec 16 #9: bo nhiem vu 'garden' (Thu hoach 1 luong o vuon) - tab Vuon da khoa. Code vuon giu nguyen (de-sau.md).
};
const DQ_REWARD=1, DQ_BONUS={sen:2, rare:1};   // chỉnh sau mô phỏng 30 ngày: hoa sen dư ~127 → giảm nguồn
function dqEnsure(){
  if(S.dq && S.dq.day===S.day) return;
  const keys=Object.keys(DQ_POOL).filter(k=>!DQ_POOL[k].ok||DQ_POOL[k].ok()).sort(()=>Math.random()-.5);
  const pick3=['served',...keys.filter(k=>k!=='served')].slice(0,3);   // luôn có 1 nhiệm vụ phục vụ khách
  S.dq={day:S.day, cnt:{}, bonus:false, list:pick3.map(k=>({k, n:DQ_POOL[k].target(), claimed:false}))}; save();
}
const dqDone=q=>DQ_POOL[q.k].val()>=q.n;
function dqClaim(i,after){ dqEnsure(); const q=S.dq.list[i]; if(!q||q.claimed||!dqDone(q)) return; q.claimed=true; S.mg.lotus+=DQ_REWARD; let msg=`+${DQ_REWARD} hoa sen`;
  if(!S.dq.bonus && S.dq.list.every(x=>x.claimed)){ S.dq.bonus=true; S.mg.lotus+=DQ_BONUS.sen; const pool=Object.keys(ING).filter(k=>ING[k].r===1), k=pick(pool); S.mg.inv[k]=(S.mg.inv[k]||0)+1; msg+=` · Hoàn thành cả 3: +${DQ_BONUS.sen} sen, +1 ${ING[k].name}`; }
  save(); toast(msg,'good'); if(typeof renderTop==='function') renderTop(); if(after) after(); else openDaily('quests'); }
// đếm tiến độ
doReply=(orig=>function(id,kind){ const r=S.reviews.find(x=>x.id===id); const was=r&&r.reply; orig(id,kind); if(r&&!was&&r.reply){ dqEnsure(); S.dq.cnt.reply=(S.dq.cnt.reply||0)+1; save(); } })(doReply);
mbAct=(orig=>function(from,to){ const B=S.mg.board, a=B[from], b=B[to], merge=a&&b&&a.c===b.c&&a.t===b.t&&!mbTop(a); const r=orig(from,to); if(merge){ dqEnsure(); S.dq.cnt.merge=(S.dq.cnt.merge||0)+1; save(); } return r; })(mbAct);
mbHarvest=(orig=>function(i){ const had=S.mg.board[i]; orig(i); if(had && !S.mg.board[i]){ dqEnsure(); S.dq.cnt.harvest=(S.dq.cnt.harvest||0)+1; save(); } })(mbHarvest);
g2Milestone=(orig=>function(g){ const out=orig(g); if(out.some(m=>m.v>=7)){ dqEnsure(); S.dq.cnt.g128=(S.dq.cnt.g128||0)+1; save(); } return out; })(g2Milestone);

// =================== VƯỜN THẢO MỘC (giờ thật) ===================
const GARDEN={sa:{name:'Sả', img:'m_oil3', h:4}, gung:{name:'Gừng', img:'m_soak2', h:4}, tram:{name:'Lá tràm', img:'plant', h:4}, dua:{name:'Dầu dừa', img:'m_oil1', h:4}, sim:{name:'Sim rừng', img:'plant2', h:8}};
const PLOTS=4, GARDEN_YIELD=2, FERT_COST=2;
const GARDEN_ON=false;   // 21c: vuon trong cay = Y TUONG DE SAU (Dai nhan 14/10). Tat khoi luat, giu code.
S.garden=S.garden&&S.garden.length===PLOTS? S.garden : Array.from({length:PLOTS},()=>({h:null,t:0,fert:false}));
const plotReady=p=>p.h && Date.now()>=p.t;
const hms=ms=>{ const m=Math.max(0,Math.ceil(ms/60000)); return m>=60?`${Math.floor(m/60)} giờ ${m%60} phút`:`${m} phút`; };
function plant(i,h){ if(!GARDEN_ON) return; const p=S.garden[i]; if(p.h) return; p.h=h; p.t=Date.now()+GARDEN[h].h*3600e3; p.fert=false; save(); openDaily('garden'); }
function harvestPlot(i){ if(!GARDEN_ON) return; const p=S.garden[i]; if(!plotReady(p)) return; let got=[];
  const n=Math.min(GARDEN_YIELD, ING_CAP-(S.mg.inv[p.h]||0)); if(n>0){ S.mg.inv[p.h]=(S.mg.inv[p.h]||0)+n; got.push(`+${n} ${ING[p.h].name}`); }
  if(p.h!=='sim' && Math.random()<.1){ const k=pick(['tieu','sim']); S.mg.inv[k]=(S.mg.inv[k]||0)+1; got.push(`+1 ${ING[k].name} (may mắn)`); }
  p.h=null; p.t=0; dqEnsure(); S.dq.cnt.garden=(S.dq.cnt.garden||0)+1; save(); toast(got.join(' · ')||'Kho đã đầy','good'); openDaily('garden'); }
function fertilize(i){ if(!GARDEN_ON) return; const p=S.garden[i]; if(!p.h||plotReady(p)||p.fert||S.mg.lotus<FERT_COST) return; S.mg.lotus-=FERT_COST; p.fert=true; p.t=Date.now(); save(); openDaily('garden'); }

// =================== ĐIỂM DANH (ngày thật) ===================
const STREAK=[{t:'+2 hoa sen', f:()=>{S.mg.lotus+=2;}}, {t:'+2 nguyên liệu thường', f:()=>{ for(let i=0;i<2;i++){ const k=pick(['sa','gung','tram','dua']); S.mg.inv[k]=(S.mg.inv[k]||0)+1; } }},
  {t:'+3 hoa sen', f:()=>{S.mg.lotus+=3;}}, {t:'+10 lượt Bàn pha chế', f:()=>{S.mg.energy=(S.mg.energy||0)+10;}},
  {t:'+1 nguyên liệu Hiếm', f:()=>{ const k=pick(['tieu','sim']); S.mg.inv[k]=(S.mg.inv[k]||0)+1; }}, {t:'+5 hoa sen', f:()=>{S.mg.lotus+=5;}},
  {t:'+1 Đá bazan (Quý) +3 sen', f:()=>{ S.mg.inv.bazan=(S.mg.inv.bazan||0)+1; S.mg.lotus+=3; }}];
const ymd=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
S.login=S.login||{last:'', streak:0, claimed:''};
function loginCheck(){
  const today=ymd(new Date()), y=new Date(); y.setDate(y.getDate()-1);
  if(S.login.last===today) return;
  // lỡ 1 ngày chỉ lùi 2 bậc, không mất trắng
  S.login.streak = S.login.last===ymd(y)? S.login.streak+1 : S.login.last? Math.max(1,S.login.streak-1) : 1;
  S.login.last=today; save();
}
const loginIdx=()=>(Math.max(1,S.login.streak)-1)%7;
const loginCanClaim=()=>S.login.claimed!==S.login.last;
function loginClaim(after){ if(!loginCanClaim()) return; STREAK[loginIdx()].f(); S.login.claimed=S.login.last; save(); toast(`Điểm danh ngày ${S.login.streak}: ${STREAK[loginIdx()].t}`,'good'); if(typeof renderTop==='function') renderTop(); if(typeof after==='function') after(); else openDaily('login'); }
loginCheck();

// =================== BẢNG "HẰNG NGÀY" ===================
function dailyBadge(){ if(!S.prem) return 0; dqEnsure(); return S.dq.list.filter(q=>!q.claimed&&dqDone(q)).length + (loginCanClaim()?1:0); }   // 10/10 Viec 16 #9: bo dem luong vuon (tab Vuon da khoa)
let dailyTab='quests', dailyTimer=null;
function openDaily(t){
  if(t) dailyTab=t; dqEnsure(); loginCheck(); clearInterval(dailyTimer);
  // 10/10 Viec 16 #9: khoa tab Vuon (gia luu ma). Code vuon giu nguyen trong file, cho sau nay.
  const tabs=[['quests','Nhiệm vụ'],['login','Điểm danh']];
  if(dailyTab==='garden') dailyTab='quests';
  let body='';
  if(dailyTab==='quests'){
    body=`<div class="list">${S.dq.list.map((q,i)=>{ const P=DQ_POOL[q.k], v=Math.min(P.val(),q.n), done=v>=q.n;
      return `<div class="item${q.claimed?' own':''}"><div class="grow"><div class="n">${P.t(q.n)}</div><div class="bar" style="margin-top:4px"><i style="width:${v/q.n*100}%"></i></div><div class="m">${q.k==='rev'?`${fmt(v)} / ${fmt(q.n)}`:`${v} / ${q.n}`}</div></div>
        ${q.claimed?'<span class="tag">Đã nhận</span>':`<button class="btn sm ${done?'mint':'alt'}" data-dq="${i}" ${done?'':'disabled'}>+${DQ_REWARD} sen</button>`}</div>`; }).join('')}</div>
      <p class="note">Xong cả 3 việc: thêm +${DQ_BONUS.sen} hoa sen và 1 nguyên liệu hiếm.${S.dq.bonus?' <b>Hôm nay đã nhận thưởng hoàn thành.</b>':''}</p>`;
  }
  if(dailyTab==='garden'){
    body=`<div class="trays garden">${S.garden.map((p,i)=>{ if(!p.h) return `<div class="tray plot empty"><span class="lab">Luống ${i+1}</span><div class="plant-pick">${Object.keys(GARDEN).map(h=>`<button class="btn sm alt" data-plant="${i}:${h}">${GARDEN[h].name}</button>`).join('')}</div></div>`;
      const G=GARDEN[p.h], ready=plotReady(p), left=p.t-Date.now(), pct=ready?100:clamp(100-left/(G.h*3600e3)*100,2,100);
      return `<div class="tray plot${ready?' ready':''}">${mgImg(ready?G.img:'m_oil2','art')}<span class="lab">${G.name}</span>${ready?`<button class="btn sm mint" data-harvest="${i}">Thu hoạch</button>`:`<span class="m" data-left="${i}">${hms(left)}</span><span class="pg"><i style="width:${pct}%"></i></span>${p.fert?'':`<button class="btn sm lav" data-fert="${i}" ${S.mg.lotus<FERT_COST?'disabled':''}>Bón phân · ${FERT_COST} sen</button>`}`}</div>`; }).join('')}</div>
      <p class="note">Cây lớn theo <b>giờ thật</b>, kể cả khi tắt game: Sả, Gừng, Lá tràm, Dầu dừa 4 giờ; Sim rừng 8 giờ. Mỗi luống thu ${GARDEN_YIELD} nguyên liệu, 10% được thêm 1 món Hiếm. Bón phân (${FERT_COST} sen) cho chín ngay, mỗi vụ 1 lần.</p>`;
  }
  if(dailyTab==='login'){
    const idx=loginIdx();
    body=`<div class="streak">${STREAK.map((r,i)=>`<div class="sday${i<idx||(i===idx&&!loginCanClaim())?' got':''}${i===idx?' now':''}"><b>Ngày ${i+1}</b><small>${r.t}</small></div>`).join('')}</div>
      <p class="note">Chuỗi hiện tại: <b>${S.login.streak} ngày</b> liên tiếp.</p>
      <div class="row"><button class="btn big butter" id="loginGo" ${loginCanClaim()?'':'disabled'}>${loginCanClaim()?`Nhận quà ngày ${idx+1}`:'Hôm nay đã nhận, mai quay lại nhé'}</button></div>`;
  }
  sheet(`${mgHead('i_day','Điểm danh','Ghé mỗi ngày, quà càng lớn.')}
    <div class="seg">${tabs.map(([k,l])=>`<button data-dt="${k}" aria-pressed="${dailyTab===k}">${l}</button>`).join('')}</div>
    ${body}<div class="row"><button class="btn big butter" data-x>Đóng</button></div>`, sh=>{
      sh.querySelector('[data-x]').onclick=()=>{ clearInterval(dailyTimer); closeSheet(); renderAll(); };
      sh.querySelectorAll('[data-dt]').forEach(b=>b.onclick=()=>openDaily(b.dataset.dt));
      sh.querySelectorAll('[data-dq]').forEach(b=>b.onclick=()=>dqClaim(+b.dataset.dq));
      sh.querySelectorAll('[data-plant]').forEach(b=>b.onclick=()=>{ const [i,h]=b.dataset.plant.split(':'); plant(+i,h); });
      sh.querySelectorAll('[data-harvest]').forEach(b=>b.onclick=()=>harvestPlot(+b.dataset.harvest));
      sh.querySelectorAll('[data-fert]').forEach(b=>b.onclick=()=>fertilize(+b.dataset.fert));
      const lg=sh.querySelector('#loginGo'); if(lg) lg.onclick=loginClaim;
      if(dailyTab==='garden') dailyTimer=setInterval(()=>{ if($('#sheetBg').hidden){ clearInterval(dailyTimer); return; }
        let redraw=false; S.garden.forEach((p,i)=>{ const el=sh.querySelector(`[data-left="${i}"]`); if(!el) return; if(plotReady(p)) redraw=true; else el.textContent=hms(p.t-Date.now()); });
        if(redraw) openDaily('garden'); },15000);
    });
}
// Mở game lần đầu trong ngày: nhắc điểm danh
setTimeout(function nag(){ if(!S.prem || S.stage==='story' || S.stage==='prem') return; if(!$('#sheetBg').hidden||haggling){ setTimeout(nag,3000); return; } if(loginCanClaim()){ if(typeof openGuide==='function') openGuide('day'); else openDaily('login'); } },1200);

// 15f-stars.js — v2.2: Hệ thống sao của tiệm
//  • Sao càng cao khách càng đông (và ngược lại) — thay hệ số cũ (0,6 + sao×0,1, chỉ lệch ±20%)
//  • Khách kỳ vọng theo sao và theo giá → tiệm 5★ phải giữ chất lượng, không tự đứng yên ở 5★
//  • Chủ tiệm trả lời bằng 6 thái độ; tuỳ tính khách, khách có thể sửa sao LÊN hoặc HẠ sao xuống
// Nạp sau 15e. Bọc lại: hourCurve, spawn, finishService, makeReview, endDay. Thay hẳn: doReply, reviewsHTML.
'use strict';

// ---------- 1. Sao → lượng khách & mức giá khách chịu ----------
const STAR_CURVE=[[1,.35],[2,.55],[3,.8],[3.5,.9],[4,1],[4.5,1.2],[5,1.4]];
function starMul(r){ r=clamp(r,1,5); for(let i=1;i<STAR_CURVE.length;i++){ const [a,va]=STAR_CURVE[i-1],[b,vb]=STAR_CURVE[i]; if(r<=b) return va+(vb-va)*(r-a)/(b-a); } return 1.4; }
const starPrice=r=>1+(clamp(r,1,5)-4)*0.06;          // 5★ khách chịu giá +6%, 3★ −6%, 1★ −18%
// Công thức gốc (11-tick) nhân (0,6 + sao×0,1); ở đây chia bỏ phần đó rồi nhân đường cong mới
// 7 ngày đầu khai trương: khách tò mò, sao thấp chưa làm giảm khách (mô phỏng cho thấy tiệm mới hay tụt ~3,6★ lúc chủ tự làm)
const NEW_SHOP_DAYS=7;
const starMulNow=()=>{ const m=starMul(rating()); return S.day<=NEW_SHOP_DAYS? Math.max(1,m) : m; };
hourCurve=(orig=>function(){ const r=rating(); return orig()*starMulNow()/(0.6+r*0.1); })(hourCurve);
spawn=(orig=>function(kind){ const n=guests.length; orig(kind); const g=guests[guests.length-1]; if(guests.length>n && g && g.M) g.M*=starPrice(rating()); })(spawn);

// ---------- 2. Kỳ vọng của khách (chống bão hoà 5★) ----------
const EXPECT={hype:8, priceUp:30, priceDown:15, priceCap:12};
Object.assign(RV_VI,{hype:['nghe đồn 5 sao mà thấy cũng thường','kỳ vọng cao hơn vậy'], pricey:['giá cao so với chất lượng','hơi đắt'], cheap:['giá mềm, đáng tiền']});
Object.assign(RV_EN,{hype:['expected more from a 5-star place'], pricey:['overpriced for what it is'], cheap:['great value']});
finishService=(orig=>function(g){
  const price=g.price, want=g.want; orig(g);
  if(!g.rv) return;
  const hype=Math.max(0,rating()-4)*EXPECT.hype;                       // 4,5★ −4 · 5★ −8
  const ratio=price/market(want);
  const pp=clamp(ratio>1? -(ratio-1)*EXPECT.priceUp : (1-ratio)*EXPECT.priceDown, -EXPECT.priceCap, EXPECT.priceCap);
  g.sat=clamp(g.sat-hype+pp,0,100);
  if(hype>=3) g.rv.reasons.push(['hype',-hype]);
  if(pp<=-4) g.rv.reasons.push(['pricey',pp]); else if(pp>=4) g.rv.reasons.push(['cheap',pp]);
})(finishService);

// ---------- 3. Tính khách khi viết đánh giá ----------
const TEMPER={easy:{name:'dễ tính', up:1.4, down:.6}, normal:{name:'bình thường', up:1, down:1}, picky:{name:'khó tính', up:.6, down:1.4}};
makeReview=(orig=>function(g){ const id0=S.rv.nextId; orig(g); if(S.rv.nextId>id0){ const r=S.reviews[0]; const x=Math.random(), pk=g.type==='tay'?.25:.2; r.temp=x<pk?'picky':x<pk+.3?'easy':'normal'; } })(makeReview);

// ---------- 4. Trả lời theo thái độ → khách sửa sao lên / hạ xuống ----------
const TONES={
  warm:{label:'Cảm ơn chân thành', cls:'mint', vi:'Cảm ơn anh/chị rất nhiều vì đã ghé {S} và dành lời khen! Cả tiệm vui lắm, hẹn gặp lại ạ.', en:'Thank you so much for visiting {S} and for the kind words! See you again soon.'},
  fix:{label:'Xin lỗi & hứa sửa', cls:'butter', vi:'Tiệm thành thật xin lỗi anh/chị. Tiệm đã ghi nhận và sửa ngay điều này ạ.', en:'We are truly sorry. We have noted this and are fixing it right away.'},
  voucher:{label:'Xin lỗi + phiếu giảm giá', cls:'butter', vi:'Tiệm xin lỗi và gửi anh/chị phiếu giảm giá cho lần sau, mong có dịp phục vụ tốt hơn ạ.', en:'We apologise — here is a 20% voucher for your next visit. We hope to do better.'},
  explain:{label:'Giải thích lịch sự', cls:'alt', vi:'Cảm ơn anh/chị đã góp ý. Tiệm xin giải thích thêm để anh/chị hiểu hơn ạ.', en:'Thanks for the feedback, let us kindly explain a little more.'},
  template:{label:'Trả lời qua loa', cls:'alt', vi:'Cảm ơn quý khách.', en:'Thank you.'},
  argue:{label:'Cãi lại khách', cls:'danger', vi:'Tiệm làm đúng quy trình, anh/chị khó tính quá.', en:'We did everything right, you are just too picky.'}
};
TONES.thank=TONES.warm;   // câu trả lời cũ (v1.9)
// [cơ hội sửa LÊN, cơ hội HẠ xuống] theo nhóm sao. Lên được +1★ (có khi +2★), hạ −1★ (cãi nhau có khi −2★).
const TONE_ODDS={
  high:{warm:[.25,0], fix:[.05,0], voucher:[.1,0], explain:[.05,0], template:[0,.1], argue:[0,.5]},
  mid:{warm:[.2,.05], fix:[.35,0], voucher:[.45,0], explain:[.15,.05], template:[0,.15], argue:[0,.6]},
  low:{warm:[.05,.2], fix:[.35,.05], voucher:[.5,0], explain:[.15,.1], template:[0,.25], argue:[0,.6]}
};
const FIXABLE2={nochange:()=>!!S.owned.changing, lazy:()=>!S.staff.some(s=>s.lazy), tired:()=>true, noskill:()=>true, wait:()=>S.staff.length>=4, pricey:()=>true, tea:()=>true};
const CUST_UP_VI=['Cảm ơn tiệm đã quan tâm, mình sửa lại {N}★ nha.','Tiệm dễ thương ghê, lên {N}★ luôn.','Ok, thấy tiệm có thành ý, mình chỉnh {N}★.'];
const CUST_DN_VI=['Trả lời vậy thì {N}★ là đúng rồi.','Thái độ kiểu này, mình hạ còn {N}★.','Tiệm không tôn trọng khách, {N}★.'];
const CUST_UP_EN=['Thanks for caring, updated to {N}★.','Lovely response, {N}★ now!'], CUST_DN_EN=['With that attitude, {N}★ it is.','Rude reply. Changing to {N}★.'];
function doReply(id,kind){
  const r=S.reviews.find(x=>x.id===id); if(!r||r.reply||!TONES[kind]) return;
  const band=r.stars>=4?'high':r.stars===3?'mid':'low', T=TEMPER[r.temp||'normal'], late=S.day-r.d, k=RV.timing(late);
  const fixed=r.reasons.some(x=>FIXABLE2[x]&&FIXABLE2[x]());
  let [pu,pd]=TONE_ODDS[band][kind];
  if(kind==='fix' && fixed) pu*=2;                    // lỗi đã thật sự được sửa → khách tin hơn
  pu=Math.min(.95,pu*T.up*k); pd=Math.min(.95,pd*T.down);
  const before=r.stars, x=Math.random(); let delta=0;
  if(x<pd) delta= (kind==='argue' && Math.random()<.35)? -2 : -1;
  else if(x<pd+pu) delta= ((kind==='voucher'||(kind==='fix'&&fixed)) && band==='low' && Math.random()<.3)? 2 : 1;
  r.stars=clamp(r.stars+delta,1,5); delta=r.stars-before; if(delta) r.edited=true;
  const out=[];
  if(kind==='warm'){ S.rv.devotion++; if(r.stars>=4 && Math.random()<.15*k){ S.returning++; out.push('Khách hẹn quay lại'); } }
  if(kind==='voucher' && Math.random()<.6*k){ S.returning++; S.rv.vouchers++; out.push('Khách sẽ quay lại dùng phiếu'); }
  if(kind==='argue' && (r.blogger || Math.random()<(before<=1?.35:.2))){ S.rv.badPress=S.day+3; out.push('Bị chê khắp nơi: khách ít đi vài ngày'); }
  if(delta>0) out.unshift(`Khách sửa ${before}★ → ${r.stars}★`); if(delta<0) out.unshift(`Khách hạ ${before}★ → ${r.stars}★`);
  const en=r.type==='tay', pool=delta>0?(en?CUST_UP_EN:CUST_UP_VI):delta<0?(en?CUST_DN_EN:CUST_DN_VI):null;
  r.reply={kind, d:S.day, late, text:(en?TONES[kind].en:TONES[kind].vi).replace('{S}',S.name), out:out.join(' · '), delta, cust:pool?pick(pool).replace('{N}',r.stars):''};
  toast(out.join(' · ')||'Đã trả lời, khách không đổi đánh giá.', delta<0||kind==='argue'?'warn':delta>0?'good':undefined);
  dqEnsure(); S.dq.cnt.reply=(S.dq.cnt.reply||0)+1;      // nhiệm vụ ngày (15e)
  save(); renderTop(); renderScreen();
}

// ---------- 5. Giao diện tab Đánh giá ----------
function reviewsHTML(){
  const all=S.reviews, n=all.length, un=all.filter(r=>!r.reply).length, rep=all.filter(r=>r.reply).length, r0=rating(), mul=starMulNow();
  const dist=[5,4,3,2,1].map(s=>[s,all.slice(0,RV.window).filter(r=>r.stars===s).length]), mx=Math.max(1,...dist.map(d=>d[1]));
  const ups=all.filter(r=>r.reply&&r.reply.delta>0).length, dns=all.filter(r=>r.reply&&r.reply.delta<0).length;
  const card=r=>{ const T=CTYPES[r.type], tp=TEMPER[r.temp||'normal'], ago=S.day-r.d===0?'hôm nay':`${S.day-r.d} ngày trước`;
    const opts=r.stars>=4?['warm','template','argue']:['fix','voucher','explain','warm','template','argue'];
    const btns=!r.reply? `<div class="rv-tones">${opts.map(k=>`<button class="btn sm ${TONES[k].cls}" data-rep="${r.id}" data-k="${k}">${TONES[k].label}</button>`).join('')}</div>${S.day-r.d>0?`<div class="note" style="margin-top:3px">Trả lời muộn ${S.day-r.d} ngày: cơ hội khách sửa sao còn ${Math.round(RV.timing(S.day-r.d)*100)}%</div>`:''}` : '';
    const d=r.reply&&r.reply.delta;
    const rp=r.reply? `<div class="pm me" style="margin-top:6px;max-width:100%"><b>Chủ tiệm · ${TONES[r.reply.kind]?TONES[r.reply.kind].label:'trả lời'}${r.reply.late?` (muộn ${r.reply.late} ngày)`:''}</b>${esc(r.reply.text)}</div>
      ${r.reply.cust?`<div class="pm" style="margin-top:4px;max-width:100%"><b>${esc(r.name)}</b>${esc(r.reply.cust)}</div>`:''}
      ${r.reply.out?`<span class="tag${d<0||r.reply.kind==='argue'?' warn':''}" style="margin-top:4px">${esc(r.reply.out)}</span>`:''}` : '';
    return `<div class="item rv-card${d>0?' up':d<0?' down':''}" style="align-items:flex-start">${r.pid&&IMG[r.pid]?`<img class="av avimg" src="${IMG[r.pid]}" alt="">`:''}<div class="grow">
      <div class="n">${esc(r.name)} <span class="chip ${T.chip}">${T.name}</span>${r.blogger?' <span class="tag lav">Blogger ×5</span>':''}${!r.reply&&r.temp&&r.temp!=='normal'?` <span class="tag ${r.temp==='picky'?'warn':''}">có vẻ ${tp.name}</span>`:''}</div>
      <div class="m"><span class="stars" style="font-size:var(--fz-muc)">${starStr(r.stars)}</span>${r.edited?` <span class="tag${r.stars<r.orig?' warn':''}">${r.orig}★ → ${r.stars}★</span>`:''} · ${SERVICES[r.svc].name} · ${ago}</div>
      <div style="font-weight:700;font-size:var(--fz-than);margin-top:3px">${esc(r.text)}</div>${rp}${btns}</div></div>`; };
  const pos=(clamp(r0,1,5)-1)/4*100;
  return `<div class="seg"><button data-pt="group" aria-pressed="false">Nhóm Bay${unread.group?' •':''}</button><button data-pt="inbox" aria-pressed="false">Tin khách${unread.inbox?' •':''}</button><button data-pt="reviews" aria-pressed="true">Đánh giá</button></div>
  <div class="card"><div class="row" style="justify-content:space-between;align-items:flex-end"><div><div class="big-num">${r0.toFixed(1).replace('.',',')} <span class="stars" style="font-size:var(--fz-tieude)">★</span></div><div class="note">${n} đánh giá · đã trả lời ${n?Math.round(rep/n*100):0}% · chờ trả lời ${un}</div></div>
    <div style="min-width:150px">${dist.map(([s,c])=>`<div class="srow" style="grid-template-columns:18px 1fr 22px;font-size:var(--fz-ghichu)"><span>${s}★</span><span class="sbar"><i style="width:${c/mx*100}%"></i></span><span class="sv">${c}</span></div>`).join('')}</div></div>
    <div class="star-meter"><div class="track"><i style="left:${pos}%"></i></div><div class="lbls"><span>1★ vắng khách</span><span>5★ đông khách</span></div></div>
    <div class="tiles" style="margin-top:6px"><div class="tile"><b>${mul>=1.1?'Đông':mul<.9?'Vắng':'Vừa'}</b><small>lượng khách</small></div><div class="tile"><b>${starPrice(r0)>=1.03?'Cao':starPrice(r0)<.97?'Thấp':'Vừa'}</b><small>giá khách chịu</small></div><div class="tile"><b>${ups} / ${dns}</b><small>sửa lên / hạ xuống</small></div></div>
    <p class="note" style="margin-top:6px">Sao cao thì khách đông và chịu giá cao. Trả lời đánh giá cho khéo, khách có thể sửa sao lên. ${S.rv.badPress>=S.day?'<b style="color:var(--danger)">Đang bị chê khắp nơi, khách ít đi.</b>':''}${S.rv.vouchers?` Phiếu giảm giá chờ khách dùng: <b>${S.rv.vouchers}</b>.`:''}</p></div>
  <div class="list">${n?all.slice(0,40).map(card).join(''):'<p class="note">Chưa có đánh giá nào. Khách rất hài lòng hoặc rất bực mới hay viết.</p>'}</div>`;
}
// Cuối ngày: báo hệ số khách theo sao
endDay=(orig=>function(){ orig(); const row=$('#sheet .row:last-child'); if(!row) return; const r=rating();
  row.insertAdjacentHTML('beforebegin',`<div class="note">Sao ${r.toFixed(1).replace('.',',')}★ → ngày mai khách <b>${(S.day+1<=NEW_SHOP_DAYS?Math.max(1,starMul(r)):starMul(r))>=1.1?'đông':(S.day+1<=NEW_SHOP_DAYS?Math.max(1,starMul(r)):starMul(r))<.9?'vắng':'vừa phải'}</b>.</div>`); })(endDay);

// 15g-services.js — v2.3: 4 dịch vụ mới có chỗ làm riêng: Chăm sóc da mặt, Làm nail, Xông hơi, Tắm thảo dược
// Nạp sau 15f. Bọc lại: freeStation, holdStation, freeStationOf, hasStation, postFly, pickWant, spawn, available, startDay, autoRestock, renderBoard.
'use strict';
const NEWSV={
  facial:{name:'Chăm sóc da mặt', min:60, st:'facial', mul:1.6, w:.14, learn:{cash:8e6, xp:120}, icon:'w_facial_0', pose:'d_facial'},
  nail:{name:'Làm nail', min:45, st:'nail', mul:.8, w:.14, learn:{cash:5e6, xp:60}, icon:'w_nail_0', pose:'d_nail'},
  sauna:{name:'Xông hơi', min:30, st:'sauna', mul:.7, w:.10, learn:{cash:3e6, xp:30}, icon:'w_sauna_0', pose:'i_sauna'},
  herbal:{name:'Tắm thảo dược', min:45, st:'herbal', mul:1.5, w:.10, learn:{cash:6e6, xp:90}, icon:'w_herbal_0', pose:'i_tub'}
};
const NEWST=Object.keys(NEWSV).map(k=>NEWSV[k].st);
// Đưa vào bảng dịch vụ chung. w=0 để hàm chọn dịch vụ gốc không đụng tới; nhu cầu dịch vụ mới do pickWant bọc bên dưới quyết định.
Object.entries(NEWSV).forEach(([k,v])=>{ SERVICES[k]={name:v.name, min:v.min, st:v.st, mul:v.mul, w:0, learn:v.learn}; if(!SK.includes(k)) SK.push(k); SVC_ICON[k]=v.icon; });

// ---------- vật tư mới ----------
const NEW_SUP={
  mask:{name:'Mặt nạ & serum', unit:'miếng', batch:50, price:1000000, cap:100, use:k=>k==='facial'?1:0},
  polish:{name:'Sơn móng & dụng cụ', unit:'lọ', batch:10, price:600000, cap:20, use:k=>k==='nail'?.1:0},
  herb:{name:'Thảo dược tắm & xông', unit:'gói', batch:40, price:800000, cap:120, use:k=>k==='herbal'?1:k==='sauna'?.5:0}
};
Object.entries(NEW_SUP).forEach(([k,v])=>{ SUP[k]=v; if(!SUPK.includes(k)) SUPK.push(k); if(S.stock[k]===undefined) S.stock[k]=Math.round(v.cap*.3); });
SUP_ICON.mask='w_facial_0'; SUP_ICON.polish='w_nail_0'; SUP_ICON.herb='w_herbal_0';
{ const t=SUP.towel.use; SUP.towel.use=k=>t(k)+(k==='sauna'||k==='herbal'?.5:k==='facial'?.3:0); }
// Tự nhập hàng chỉ nhập vật tư mới khi tiệm đã có dịch vụ dùng tới
autoRestock=(orig=>function(){ const hold={}; Object.keys(NEW_SUP).forEach(k=>{ const used=Object.keys(NEWSV).some(sv=>NEW_SUP[k].use(sv)>0&&S.skills[sv]); if(!used){ hold[k]=S.stock[k]; S.stock[k]=1e9; } });
  orig(); Object.entries(hold).forEach(([k,v])=>S.stock[k]=v); })(autoRestock);

// ---------- chỗ làm (ô mua được) ----------
// Giá là ước tính mặt bằng Phú Quốc, chưa đối chiếu báo giá thật.
const NEW_SLOTS=[
  {id:'facial1', st:'facial', idx:0, name:'Giường chăm sóc da 1 (+ máy xông mặt)', price:14e6, desc:'Giường chỉnh độ ngả, máy xông hơi nước và đèn soi da. Cho dịch vụ chăm sóc da mặt.'},
  {id:'facial2', st:'facial', idx:1, name:'Giường chăm sóc da 2 (+ máy xông mặt)', price:14e6, desc:'Giường thứ hai cho chăm sóc da mặt.'},
  {id:'nail1', st:'nail', idx:0, name:'Bàn nail 1 (+ ghế khách)', price:7e6, desc:'Bàn làm móng có đèn, kệ sơn và ghế khách.'},
  {id:'nail2', st:'nail', idx:1, name:'Bàn nail 2 (+ ghế khách)', price:7e6, desc:'Bàn làm móng thứ hai.'},
  {id:'sauna1', st:'sauna', idx:0, name:'Phòng xông hơi khô', price:45e6, desc:'Cabin gỗ thông, lò đá xông. Mỗi lượt 1 khách.', noSell:true},   // 11/10: ẩn khỏi Mua sắm chờ hình cabin trong nhà; ô giữ nguyên nên save cũ không vỡ
  {id:'herbal1', st:'herbal', idx:0, name:'Bồn tắm thảo dược 1', price:18e6, desc:'Bồn gỗ pơ-mu ngâm lá thuốc.'},
  {id:'herbal2', st:'herbal', idx:1, name:'Bồn tắm thảo dược 2', price:18e6, desc:'Bồn gỗ thứ hai.'}
];
const EXTRA_CAP={chodem:2, thd:3, sunset:5, resort:7};
NEW_SLOTS.forEach(o=>{ if(!SLOTS.find(s=>s.id===o.id)) SLOTS.push(Object.assign({art:null, listOnly:true, zone:'svc2', x:0, y:0, w:0, h:0}, o)); SLOT_IMG[o.id]=NEWSV[Object.keys(NEWSV).find(k=>NEWSV[k].st===o.st)].icon; });
if(!ZONES.find(z=>z[0]==='svc2')) ZONES.push(['svc2','Dịch vụ cao cấp']);
const extraCap=()=>{ const p=prem(); return p? (EXTRA_CAP[p.id]||2) : 0; };
const svc2Owned=()=>SLOTS.filter(s=>s.zone==='svc2'&&S.owned[s.id]).length;
available=(orig=>function(s){ if(s.zone!=='svc2') return orig(s); const p=prem(); if(!p) return {ok:false,why:'Chưa thuê mặt bằng'};
  if(!S.owned[s.id] && svc2Owned()>=extraCap()) return {ok:false, why:`Mặt bằng chỉ đủ ${extraCap()} chỗ dịch vụ cao cấp`}; return {ok:true}; })(available);
const ownedSt=t=>SLOTS.filter(s=>s.st===t&&S.owned[s.id]).map(s=>s.idx);

// ---------- xếp chỗ ----------
let busyNew={}; NEWST.forEach(t=>busyNew[t]={});
startDay=(orig=>function(){ busyNew={}; NEWST.forEach(t=>busyNew[t]={}); orig(); })(startDay);
freeStation=(orig=>function(k){ const t=SERVICES[k].st; if(!NEWST.includes(t)) return orig(k); const i=ownedSt(t).find(i=>!busyNew[t][i]); return i===undefined?null:{t,i}; })(freeStation);
holdStation=(orig=>function(st,v){ if(NEWST.includes(st.t)) busyNew[st.t][st.i]=v; else orig(st,v); })(holdStation);
freeStationOf=(orig=>function(st){ if(st && NEWST.includes(st.t)) delete busyNew[st.t][st.i]; else orig(st); })(freeStationOf);
hasStation=(orig=>function(k){ const t=SERVICES[k].st; if(!NEWST.includes(t)) return orig(k); return ownedSt(t).length>0; })(hasStation);
postFly=(orig=>function(g,st,auto){ if(st && NEWST.includes(st.t)) return false; return orig(g,st,auto); })(postFly);   // Nhóm Bay chưa có thợ các nghề mới
NEWST.forEach((t,n)=>{ P[t+'G']=i=>P.bedG(Math.min(3,i+n%2)); P[t+'W']=i=>P.bedW(Math.min(3,i+n%2)); });

// ---------- nhu cầu: khách chỉ hỏi dịch vụ mới khi tiệm thật sự làm được ----------
const newOffer=k=>hasStation(k) && someoneKnows(k);
pickWant=(orig=>function(){ const off=Object.keys(NEWSV).filter(newOffer); const sum=off.reduce((a,k)=>a+NEWSV[k].w,0);
  if(sum && Math.random()<sum/(1+sum)){ let r=Math.random()*sum; for(const k of off){ r-=NEWSV[k].w; if(r<=0) return k; } }
  return orig(); })(pickWant);
spawn=(orig=>function(kind){ const n=guests.length; orig(kind); const g=guests[guests.length-1];
  if(guests.length>n && g && NEWSV[g.want] && !newOffer(g.want)){ const old=g.want; g.want=pickWant(); if(NEWSV[g.want]) g.want='foot'; g.M=g.M/market(old)*market(g.want); } })(spawn);

// ---------- bảng tiệm: khu "Dịch vụ cao cấp" ----------
function svcTray(s){
  const own=!!S.owned[s.id], av=available(s), kk=Object.keys(NEWSV).find(k=>NEWSV[k].st===s.st), sv=NEWSV[kk];
  const short={facial:'Da mặt', nail:'Nail', sauna:'Xông hơi', herbal:'Bồn tắm'}[s.st]+(s.idx?' '+(s.idx+1):'');
  if(!own){ if(!av.ok && svc2Owned()>=extraCap()) return ''; return `<button class="tray locked" data-slot="${s.id}">${mgImg(sv.icon,'art')}<span class="lab">${short}</span><span class="lockt">Khoá<small>${fmt(s.price)}</small></span></button>`; }
  const g=guests.find(x=>x.station&&x.station.t===s.st&&x.station.i===s.idx&&(x.state==='service'||x.state==='toStation'));
  if(g){ const inSvc=g.state==='service'&&g.dur, left=inSvc?Math.max(1,Math.ceil(SERVICES[g.want].min*(1-g.svc/g.dur))):SERVICES[g.want].min, pct=inSvc?Math.min(100,g.svc/g.dur*100):0;
    return `<button class="tray busy" data-slot="${s.id}">${mgImg(sv.pose,'art pose')}<span class="cd">${inSvc?left+"'":'…'}</span><span class="pg"><i style="width:${pct}%"></i></span><span class="lab">${esc(workerName(g.worker))}</span></button>`; }
  const stage=typeof wearStage==='function'? wearStage(s.id) : 0, broken=stage>=4;
  return `<button class="tray${broken?' broken':''}" data-slot="${s.id}">${mgImg(`w_${s.st}_${Math.min(stage,4)}`,'art')}${typeof wearBadge==='function'?wearBadge(s.id):''}<span class="lab">${short}</span>${!S.skills[kk]&&!S.staff.some(x=>x.skills[kk])?'<span class="lockt small">Chưa học</span>':''}</button>`;
}
renderBoard=(orig=>function(){
  orig(); const B=$('#board'); if(!B||tab!=='shop'||!S.prem) return;
  const items=SLOTS.filter(s=>s.zone==='svc2').map(svcTray).filter(Boolean).join(''); if(!items) return;
  const html=`<div class="plaque">Dịch vụ cao cấp<small>${svc2Owned()}/${extraCap()} chỗ · da mặt, nail, xông hơi, tắm thảo dược</small></div><div class="trays c4 svc2">${items}</div>`;
  const anchor=[...B.querySelectorAll('.plaque')].find(p=>p.textContent.startsWith('Việc tay'));
  if(anchor) anchor.insertAdjacentHTML('beforebegin',html); else B.insertAdjacentHTML('beforeend',html);
})(renderBoard);

// 15h-wear.js — v2.3: Hao mòn thiết bị, sửa chữa, nâng cấp; biểu tượng trạng thái cho vật tư, nhân viên, chỉ số
// Nạp sau 15g. Bọc lại: finishService, startDay, endDay, trayHTML, openSlot, renderTop, renderScreen, ico.
'use strict';
// ---------- độ bền (số lượt dùng tới lúc hỏng) ----------
// Giai đoạn: 0 mới (<30%) · 1 (30–50%) · 2 (50–70%) · 3 (70–100%) · 4 hỏng (100%, không dùng được)
const WEAR_D={chair:220, room:220, facial:200, nail:250, sauna:300, herbal:200, sofa:1200, cashier:3000, tea:1500, towel:900, trolley:160, changing:1500, decor:120};
const WEAR_IMG={room:'w_body', facial:'w_facial', nail:'w_nail', sauna:'w_sauna', herbal:'w_herbal', sofa:'w_furniture', trolley:'w_stone', changing:'w_room', art:'w_decor', plant1:'w_plant', plant2:'w_plant'};
const WEAR_SAT=[0,-2,-5,-10,0];
const DECOR_IDS=()=>SLOTS.filter(s=>s.zone==='dc').map(s=>s.id);
S.wear=S.wear||{}; S.lv=S.lv||{}; S.autoFix=!!S.autoFix;
const wearKind=id=>id.startsWith('chair')?'chair':id.startsWith('room')?'room':(slot(id)&&slot(id).st)||(DECOR_IDS().includes(id)?'decor':id);
const wearMax=id=>(WEAR_D[wearKind(id)]||1000)*(1+0.25*((S.lv[id]||1)-1));
const wearPct=id=>Math.min(1,(S.wear[id]||0)/wearMax(id));
function wearStage(id){ const p=wearPct(id); return p>=1?4:p>=.7?3:p>=.5?2:p>=.3?1:0; }
const STAGE_TXT=['Mới','Hơi cũ','Cũ','Sắp hỏng','Hỏng'];
function wearBadge(id){ const st=wearStage(id); return st?`<span class="wear w${st}">${st>=4?'Hỏng':Math.round(wearPct(id)*100)+'%'}</span>`:''; }
const repairCost=id=>Math.max(100000, r10(slot(id).price*wearPct(id)*0.25)); // v3.0: bảo trì ~18% giá đồ khi mòn 70% (trước 35%)
const upgradeCost=id=>{ const l=S.lv[id]||1; return l>=3?0:r10(slot(id).price*(l===1?.6:1.2)); };
const upgradable=id=>['chair','room','facial','nail','sauna','herbal','sofa'].includes(wearKind(id));
function stationOfSlot(id){ const s=slot(id); if(!s) return null; if(s.zone==='chan') return {t:'chair',i:s.seat}; if(id.startsWith('room')) return {t:'bed',i:s.need}; if(s.st) return {t:s.st,i:s.idx}; return null; }
function slotOfStation(st){ if(!st) return null; if(st.t==='chair') return 'chair'+(st.i+1); if(st.t==='bed') return 'room'+(st.i+1); const s=SLOTS.find(x=>x.st===st.t&&x.idx===st.i); return s?s.id:null; }
function markBroken(){ SLOTS.forEach(s=>{ if(!S.owned[s.id]) return; const st=stationOfSlot(s.id); if(st && wearStage(s.id)>=4) holdStation(st,'broken'); }); }
function addWear(id,n){ if(!id||!S.owned[id]) return false; const before=wearStage(id); S.wear[id]=(S.wear[id]||0)+(n||1); const after=wearStage(id);
  if(after>before && after>=3) toast(after>=4?`${slot(id).name} đã hỏng! Vào Mua sắm › Bảo trì để sửa.`:`${slot(id).name} sắp hỏng, khách bắt đầu chê.`, 'warn');
  return after>=4 && before<4; }

// ---------- dùng là mòn ----------
finishService=(orig=>function(g){
  const st=g.station, want=g.want, sid=slotOfStation(st);
  const stage=sid?wearStage(sid):0, lv=sid?(S.lv[sid]||1):1, sofaSt=S.owned.sofa?wearStage('sofa'):0;
  orig(g);
  // hài lòng: chỗ làm mòn thì khách chê, nâng cấp thì khách thích; sofa chờ mòn cũng trừ
  const d=WEAR_SAT[stage]+(lv-1)*3+[0,-1,-3,-6,-8][sofaSt];
  if(d){ g.sat=clamp(g.sat+d,0,100); if(g.rv && stage>=2) g.rv.reasons.push(['worn',WEAR_SAT[stage]]); if(g.rv && lv>1) g.rv.reasons.push(['upgraded',(lv-1)*3]); }
  const broke=addWear(sid,1); ['sofa','cashier','tea','towel'].forEach(k=>addWear(k,1)); if(want==='stone') addWear('trolley',1); if(st&&st.t==='bed') addWear('changing',1);
  if(broke && st) holdStation(st,'broken');
})(finishService);
Object.assign(RV_VI,{worn:['ghế giường cũ kỹ, bong tróc','đồ trong tiệm xuống cấp'], upgraded:['giường mới xịn, êm lắm']});
Object.assign(RV_EN,{worn:['the equipment looks worn out'], upgraded:['super comfy new bed']});
startDay=(orig=>function(){ orig(); markBroken(); })(startDay);
endDay=(orig=>function(){
  DECOR_IDS().forEach(id=>addWear(id,1));
  let auto=0; if(S.autoFix) SLOTS.forEach(s=>{ if(S.owned[s.id] && wearStage(s.id)>=3){ const c=r10(repairCost(s.id)*1.1); if(S.cash>=c){ S.cash-=c; S.wear[s.id]=0; auto+=c; } } });
  if(auto) addLog('Quản lý tự bảo trì thiết bị',-auto);
  orig();
  const row=$('#sheet .row:last-child'), worn=SLOTS.filter(s=>S.owned[s.id]&&wearStage(s.id)>=3);
  if(row && (auto||worn.length)) row.insertAdjacentHTML('beforebegin',`<div class="note">${auto?`Tự bảo trì: −${fmt(auto)}. `:''}${worn.length?`<b style="color:var(--danger)">${worn.length} đồ sắp hỏng</b> (${worn.slice(0,3).map(s=>esc(s.name)).join(', ')}${worn.length>3?'…':''}) — vào Mua sắm › Bảo trì.`:''}</div>`);
})(endDay);

function repair(id){ const c=repairCost(id); if(S.cash<c||!(S.wear[id]>0)) return; S.cash-=c; const was=wearStage(id)>=4; S.wear[id]=0; addLog('Sửa '+slot(id).name,-c);
  if(was){ const st=stationOfSlot(id); if(st) freeStationOf(st); } save(); renderAll(); toast(`Đã sửa ${slot(id).name}.`,'good'); }
function upgrade(id){ const c=upgradeCost(id); if(!c||S.cash<c) return; S.cash-=c; S.lv[id]=(S.lv[id]||1)+1; addLog(`Nâng cấp ${slot(id).name} lên cấp ${S.lv[id]}`,-c); save(); renderAll(); toast(`${slot(id).name} lên cấp ${S.lv[id]}: khách hài lòng hơn, đồ bền hơn.`,'good'); }

// ---------- bảng tiệm: huy hiệu mòn + hình theo mức mòn ----------
trayHTML=(orig=>function(s,label){
  let h=orig(s,label); if(!S.owned[s.id]||!h||h.includes('tray busy')) return h;
  const st=wearStage(s.id), key=WEAR_IMG[s.id]||WEAR_IMG[wearKind(s.id)];
  if(key && IMG[`${key}_${st}`]){ const src=IMG[imgOf(s)]; if(src) h=h.replace(`src="${src}"`,`src="${IMG[`${key}_${st}`]}"`); }
  else if(st) h=h.replace('class="art"',`class="art worn${st}"`);
  const lv=S.lv[s.id]||1;
  h=h.replace('<span class="lab">',`${wearBadge(s.id)}${lv>1?`<span class="lvb">${'★'.repeat(lv-1)}</span>`:''}<span class="lab">`);
  if(st>=4) h=h.replace('class="tray','class="tray broken');
  return h;
})(trayHTML);

// ---------- xem ô: tình trạng + sửa + nâng cấp ----------
openSlot=(orig=>function(id){
  orig(id); if(!S.owned[id]) return;
  const st=wearStage(id), pct=Math.round(wearPct(id)*100), lv=S.lv[id]||1, rc=repairCost(id), uc=upgradeCost(id), key=WEAR_IMG[id]||WEAR_IMG[wearKind(id)];
  const box=document.createElement('div'); box.className='card';
  box.innerHTML=`<div class="sec-t">Tình trạng <span class="tag ${st>=3?'warn':''}">${STAGE_TXT[st]}</span></div>
    ${key?`<div class="wear-strip">${[0,1,2,3,4].map(n=>`<span class="${n===st?'on':''}">${mgImg(`${key}_${n}`)}<small>${STAGE_TXT[n]}</small></span>`).join('')}</div>`:''}
    <div class="bar" style="margin-top:6px"><i style="width:${pct}%;background:${st>=3?'var(--danger)':st>=2?'#F0A04B':'var(--mint)'}"></i></div>
    <p class="note"> Đồ cũ thì khách chê. Hỏng thì không dùng được.${upgradable(id)?` Cấp ${lv}/3: khách hài lòng hơn, đồ bền hơn.`:''}</p>
    <div class="row" style="justify-content:flex-start">${wearStage(id)>=1?`<button class="btn sm butter" data-fix ${S.cash<rc?'disabled':''}>${st>=4?'Sửa lại':'Bảo trì'} · ${fmt(rc)}</button>`:''}${upgradable(id)&&lv<3?`<button class="btn sm lav" data-up ${S.cash<uc?'disabled':''}>Nâng cấp lên ${lv+1} · ${fmt(uc)}</button>`:''}</div>`;
  const sh=$('#sheet'); sh.insertBefore(box, sh.querySelector('.row:last-child'));
  const f=box.querySelector('[data-fix]'); if(f) f.onclick=()=>{ repair(id); openSlot(id); };
  const u=box.querySelector('[data-up]'); if(u) u.onclick=()=>{ upgrade(id); openSlot(id); };
})(openSlot);

// ---------- biểu tượng trạng thái ----------
const supStage=k=>{ const r=S.stock[k]/SUP[k].cap; return r<=0?4:r<.25?3:r<.45?2:r<.7?1:0; };
const SUP_WIMG={towel:'w_towel', oil:'w_oil', soak:'w_foot'};
ico=(orig=>function(k){ if(typeof k==='string' && k.startsWith('sup:')){ const s=k.slice(4), w=SUP_WIMG[s]; return w? orig(`${w}_${supStage(s)}`) : orig(SUP_ICON_BASE[s]); } return orig(k); })(ico);
const SUP_ICON_BASE=Object.assign({},SUP_ICON); Object.keys(SUP_WIMG).forEach(k=>SUP_ICON[k]='sup:'+k);
const repStage=r=>r>=4.5?0:r>=4?1:r>=3.5?2:r>=2.5?3:4;
const cashStage=c=>c>=3e8?0:c>=1e8?1:c>=3e7?2:c>=0?3:4;
renderTop=(orig=>function(){
  orig();
  const put=(sel,id,src)=>{ const host=$(sel); if(!host) return; let im=document.getElementById(id); if(!im){ im=document.createElement('img'); im.id=id; im.className='hud-ico'; im.alt=''; host.prepend(im); } if(src&&im.getAttribute('src')!==src) im.src=src; };
  put('#rating','hudRep',IMG['w_rep_'+repStage(rating())]); put('#cash','hudCash',IMG['w_money_'+cashStage(S.cash)]);
  const star=$('#rating') && $('#rating').parentElement.querySelector('.stars'); if(star) star.style.display='none';
})(renderTop);
// Nhân viên: bình pin thể lực theo tinh thần · Sổ sách: bảng tình hình tiệm · Mua sắm: bảng bảo trì
const staminaStage=m=>m>=80?0:m>=60?1:m>=40?2:m>=25?3:4;
function bookCard(){
  const sats=S.sats||[], avg=sats.length?sats.reduce((a,b)=>a+b,0)/sats.length:70, satSt=avg>=85?0:avg>=72?1:avg>=60?2:avg>=45?3:4;
  const debtR=S.debt/LOAN.amount, debtSt=S.debt<=0?0:debtR<.3?1:debtR<.6?2:debtR<.9?3:4, left=30-(S.day%30||30), daySt=left>=20?0:left>=12?1:left>=6?2:left>=2?3:4;
  const served=S.stats.served, lost=S.stats.lost+S.stats.missed, custSt=served+lost===0?1:served===0?4:lost/(served+lost)<.1?0:lost/(served+lost)<.2?1:lost/(served+lost)<.35?2:3;
  const t=(img,big,small)=>`<div class="tile st-tile">${mgImg(img)}<b>${big}</b><small>${small}</small></div>`;
  return `<div class="card kh-ngang"><div class="sec-t">Tình hình tiệm</div><div class="tiles st-tiles" style="margin-top:6px">
    ${t('w_money_'+cashStage(S.cash),fmt(S.cash),'tiền mặt')}${t('w_debt_'+debtSt,S.debt>0?fmt(S.debt):'Hết nợ','dư nợ')}${t('w_rep_'+repStage(rating()),rating().toFixed(1).replace('.',',')+'★','uy tín')}
    ${t('w_sat_'+(sats.length?satSt:1),sats.length?Math.round(avg):'—','hài lòng TB')}${t('w_day_'+daySt,left+' ngày','tới kỳ trả')}${t('w_cust_'+custSt,served+' / '+lost,'xong / bỏ về')}</div></div>`;
}
function maintCard(){
  const own=SLOTS.filter(s=>S.owned[s.id]).sort((a,b)=>wearPct(b.id)-wearPct(a.id)), need=own.filter(s=>wearStage(s.id)>=1), all=need.reduce((a,s)=>a+repairCost(s.id),0);
  const rows=own.slice(0,12).map(s=>{ const st=wearStage(s.id), key=WEAR_IMG[s.id]||WEAR_IMG[wearKind(s.id)];
    return `<div class="item${st>=3?' own':''}">${key?mgImg(`${key}_${st}`,'ico'):ico(SLOT_IMG[s.id]||(s.zone==='chan'?'footchair':s.id.startsWith('room')?'bed':''))}<div class="grow"><div class="n">${esc(s.name)}${(S.lv[s.id]||1)>1?` <span class="tag lav">cấp ${S.lv[s.id]}</span>`:''}</div><div class="bar" style="margin-top:3px"><i style="width:${wearPct(s.id)*100}%;background:${st>=3?'var(--danger)':st>=2?'#F0A04B':'var(--mint)'}"></i></div><div class="m">${STAGE_TXT[st]} · ${Math.floor(S.wear[s.id]||0)}/${Math.round(wearMax(s.id))}</div></div>${wearStage(s.id)>=1?`<button class="btn sm butter" data-fixid="${s.id}" ${S.cash<repairCost(s.id)?'disabled':''}>Sửa · ${fmt(repairCost(s.id))}</button>`:''}</div>`; }).join('');
  return `<div class="card"><div class="sec-t">Bảo trì thiết bị ${need.length?`<button class="btn sm mint" data-fixall ${S.cash<all?'disabled':''}>Sửa hết · ${fmt(all)}</button>`:''}</div>
    <p class="note">Đồ dùng mòn dần theo lượt khách (trang trí mòn theo ngày). Mòn nhiều khách chê, hỏng thì không dùng được. Chi phí sửa = 50% giá mua × mức mòn. Bấm vào từng món trên bảng tiệm để nâng cấp.</p>
    <label class="switch"><input type="checkbox" id="autoFix" ${S.autoFix?'checked':''}> Quản lý tự sửa đồ mòn từ 70% vào cuối ngày (phí +10%)</label>
    <div class="list" style="margin-top:6px">${rows||'<p class="note">Chưa có thiết bị.</p>'}</div></div>`;
}
renderScreen=(orig=>function(){
  orig(); const D=$('#dyn'); if(!D) return;
  if(tab==='book') D.insertAdjacentHTML('afterbegin',bookCard());
  if(tab==='buy' && S.prem) D.insertAdjacentHTML('afterbegin',maintCard());
  if(tab==='staff') S.staff.forEach(s=>{ const b=D.querySelector(`[data-rew="${s.id}"]`), it=b&&b.closest('.item'); if(it && !it.querySelector('.stam')) it.insertAdjacentHTML('afterbegin',`<span class="stam" title="Thể lực">${mgImg('w_stamina_'+staminaStage(s.morale))}</span>`); });
})(renderScreen);
$('#dyn').addEventListener('click',e=>{ const b=e.target.closest('[data-fixid]'); if(b){ repair(b.dataset.fixid); return; }
  if(e.target.closest('[data-fixall]')){ SLOTS.forEach(s=>{ if(S.owned[s.id]&&wearStage(s.id)>=1&&S.cash>=repairCost(s.id)) repair(s.id); }); } });
$('#dyn').addEventListener('change',e=>{ if(e.target.id==='autoFix'){ S.autoFix=e.target.checked; save(); } });

// 15i-endgame.js — v2.4: Sự kiện, trả nợ trước hạn, bộ Bảo vật Bãi Trường và luật mở Resort
// Nạp sau 15h. Bọc lại: startDay, endDay, hourCurve, pickType, spawn, mgGrant, mbHarvest, g2Milestone, dqClaim, harvestPlot, renderScreen.
'use strict';
S.won=true;   // tắt thông báo "đủ điều kiện lên resort" cũ của 17 nhiệm vụ; luật resort mới ở dưới

// =================== SỰ KIỆN ===================
const EVENTS={
  peak:{name:'Mùa cao điểm du lịch', days:3, img:'i_guests', desc:'Khách đông hơn, khách Tây nhiều hơn.', traffic:1.3, tay:.15},
  rain:{name:'Mưa bão kéo dài', days:2, img:'water', desc:'Khách ít đi, chủ yếu khách địa phương.', traffic:.7, dp:.3},
  korea:{name:'Đoàn khách Hàn Quốc', days:2, img:'t_kr_f', desc:'Nhiều khách nước ngoài, chịu chi hơn.', tay:.35, price:1.1},
  festival:{name:'Lễ hội ẩm thực Phú Quốc', days:3, img:'teatable', desc:'Khách đông hơn.', traffic:1.2},
  blogger:{name:'Tuần lễ review du lịch', days:3, img:'i_star', desc:'Blogger ghé nhiều. Đánh giá của họ rất quan trọng.', blogger:8},
  inspect:{name:'Đoàn kiểm tra vệ sinh', days:1, img:'i_towel', desc:'Cuối ngày kiểm tra: đồ sắp hỏng bị phạt 3tr, tiệm sạch được thưởng 2tr.'}
};
S.event=S.event||null;
const evOn=()=>S.event && S.day>=S.event.from && S.day<=S.event.to ? EVENTS[S.event.k] : null;
startDay=(orig=>function(){
  if(S.day>=6 && (!S.event || S.day>S.event.to+2) && Math.random()<.45){ const k=pick(Object.keys(EVENTS)); S.event={k, from:S.day, to:S.day+EVENTS[k].days-1}; }
  orig();
  const e=evOn(); if(e && S.event.from===S.day) setTimeout(()=>{ if($('#sheetBg').hidden) sheet(`${mgHead(e.img,e.name,`Từ ngày ${S.event.from} tới ngày ${S.event.to}`)}<p>${e.desc}</p><div class="row"><button class="btn big butter" data-x>Chuẩn bị thôi</button></div>`, sh=>sh.querySelector('[data-x]').onclick=closeSheet); },400);
})(startDay);
hourCurve=(orig=>function(){ const e=evOn(); return orig()*(e&&e.traffic||1); })(hourCurve);
pickType=(orig=>function(){ const e=evOn(), t=orig(); if(!e) return t; if(e.tay && t!=='tay' && Math.random()<e.tay) return 'tay'; if(e.dp && t!=='dp' && Math.random()<e.dp) return 'dp'; return t; })(pickType);
spawn=(orig=>function(kind){ const n=guests.length; orig(kind); const e=evOn(), g=guests[guests.length-1]; if(e && e.price && guests.length>n && g) g.M*=e.price; })(spawn);
{ const base=RV.bloggerRate; Object.defineProperty(RV,'bloggerRate',{get:()=>base*((evOn()&&evOn().blogger)||1), configurable:true}); }
endDay=(orig=>function(){
  const e=evOn(); let note='';
  if(e && S.event.k==='inspect'){ const bad=SLOTS.filter(s=>S.owned[s.id]&&wearStage(s.id)>=3);
    if(bad.length){ S.cash-=3e6; addLog('Phạt vệ sinh: đồ xuống cấp',-3e6); note=`<div class="note" style="color:var(--danger)">Đoàn kiểm tra phạt <b>3tr</b> vì ${bad.length} thiết bị mòn nặng.</div>`; }
    else { S.cash+=2e6; addLog('Giấy khen vệ sinh',2e6); note='<div class="note" style="color:var(--mint-d)">Đoàn kiểm tra khen tiệm sạch đẹp: <b>+2tr</b>.</div>'; } }
  orig();
  const row=$('#sheet .row:last-child'); if(row && note) row.insertAdjacentHTML('beforebegin',note);
  if(row && e && S.event.to>=S.day+1) row.insertAdjacentHTML('beforebegin',`<div class="note">Sự kiện <b>${e.name}</b> còn tới ngày ${S.event.to}.</div>`);
})(endDay);
// sự kiện đang chạy hiện trên bảng tiệm
renderBoard=(orig=>function(){ orig(); const e=evOn(), B=$('#board'); if(!e||!B||tab!=='shop') return; const f=B.querySelector('.front'); if(f) f.insertAdjacentHTML('afterend',`<div class="ev-bar">${mgImg(e.img)}<b>${e.name}</b><small>tới ngày ${S.event.to} · ${e.desc}</small></div>`); })(renderBoard);

// =================== TRẢ NỢ TRƯỚC HẠN ===================
function prepay(amount){ const a=Math.min(amount,S.debt,S.cash); if(a<=0) return; S.cash-=a; S.debt-=a; addLog('Trả nợ trước hạn',-a); save(); renderAll(); toast(S.debt<=0?'Đã tất toán khoản vay!':`Đã trả trước ${fmt(a)}, còn nợ ${fmt(S.debt)}.`,'good'); }

// =================== BẢO VẬT BÃI TRƯỜNG ===================
const TREASURES={
  map:{name:'Bản đồ huyệt cổ', img:'i_body', src:'Bấm huyệt đạt hạng S', p:.06, pity:18},
  silk:{name:'Khăn lụa tơ tằm', img:'m_twl6', src:'Thu "Chồng 10 khăn" ở Bàn pha chế', p:.15, pity:8},
  agar:{name:'Lọ trầm hương', img:'m_oil6', src:'Thu "Can dầu massage" ở Bàn pha chế', p:.15, pity:8},
  pearl:{name:'Ngọc trai đen', img:'i_star', src:'Chơi Tủ spa 2048 tới mốc cao', p:.4, pity:3},
  bell:{name:'Chuông gió vỏ ốc', img:'diffuser', src:'Hoàn thành cả 3 nhiệm vụ ngày', p:.12, pity:10},
  gourd:{name:'Gáo dừa thảo dược', img:'m_soak5', src:'Quà hiếm từ nhiệm vụ và điểm danh', p:.12, pity:8}
};
S.tr=Object.assign({have:{}, pity:{}, dup:0}, S.tr||{});
function rollTreasure(k,force){
  const T=TREASURES[k]; S.tr.pity[k]=(S.tr.pity[k]||0)+1;
  if(!(force || Math.random()<T.p || S.tr.pity[k]>=T.pity)) return;
  S.tr.pity[k]=0;
  if(S.tr.have[k]){ S.tr.dup++; toast(`Lại được ${T.name} (trùng). Đủ 3 món trùng đổi được 1 bảo vật còn thiếu.`,'good'); }
  else { S.tr.have[k]=true; setTimeout(()=>{ sheet(`<div class="mg-grade gS">${mgImg(T.img)}</div><h2 style="text-align:center">Bảo vật: ${T.name}!</h2><p class="note" style="text-align:center">${Object.keys(S.tr.have).length}/6 bảo vật Bãi Trường. Xem luật mở Resort ở Sổ sách.</p><div class="row"><button class="btn big butter" data-x>Tuyệt!</button></div>`, sh=>sh.querySelector('[data-x]').onclick=()=>{ closeSheet(); renderAll(); }); },600); }
  save();
}
function tradeDup(k){ if(S.tr.dup<3||S.tr.have[k]) return; S.tr.dup-=3; S.tr.have[k]=true; save(); toast(`Đổi 3 món trùng lấy ${TREASURES[k].name}.`,'good'); renderScreen(); }
mgGrant=(orig=>function(game,score,supplies){ const r=orig(game,score,supplies); if(game==='rub' && r.grade==='S') rollTreasure('map'); return r; })(mgGrant);
mbHarvest=(orig=>function(i){ const it=S.mg.board[i]; orig(i); if(it && !S.mg.board[i] && mbTop(it)){ if(it.c==='towel') rollTreasure('silk'); if(it.c==='oil') rollTreasure('agar'); } })(mbHarvest);
g2Milestone=(orig=>function(g){ const out=orig(g); if(out.some(m=>m.v===11)) rollTreasure('pearl',true); else if(out.some(m=>m.v===10)) rollTreasure('pearl'); return out; })(g2Milestone);
dqClaim=(orig=>function(i){ const was=S.dq&&S.dq.bonus; orig(i); if(S.dq && S.dq.bonus && !was) rollTreasure('bell'); })(dqClaim);
harvestPlot=(orig=>function(i){ const h=S.garden[i]&&S.garden[i].h, ready=plotReady(S.garden[i]); orig(i); if(ready && h==='sim') rollTreasure('gourd'); })(harvestPlot);

// =================== LUẬT MỞ RESORT ===================
const RESORT_RULE={cash:1.5e9, skill:20, stars:4.5};
const RESORT_PREM={id:'resort', name:'Resort Bãi Trường', lvl:3, rent:150e6, traffic:1.6, chairs:8, rooms:4, market:450000, kwh:140, mix:[.05,.35,.6], desc:'Resort ven biển Bãi Trường, khách cao cấp, giá dịch vụ cao nhất đảo.'};
// chỉ đưa resort vào danh sách mặt bằng khi đã chuyển lên (để màn chọn mặt bằng lúc mở đầu không hiện resort)
const addResortPrem=()=>{ if(!PREMISES.find(p=>p.id==='resort')) PREMISES.push(RESORT_PREM); };
if(S.prem==='resort') addResortPrem();
const skillTotal=()=>Object.values(S.skills).reduce((a,s)=>a+(s.lv||0),0);
function resortChecks(){ return [
  {t:`Đủ 6 bảo vật Bãi Trường (${Object.keys(S.tr.have).length}/6)`, ok:Object.keys(S.tr.have).length>=6},
  {t:`Tổng cấp nghề của chủ tiệm từ ${RESORT_RULE.skill} (hiện ${skillTotal()})`, ok:skillTotal()>=RESORT_RULE.skill},
  {t:`Đã trả hết nợ ngân hàng (còn ${fmt(Math.max(0,S.debt))})`, ok:S.debt<=0},
  {t:`Tiền mặt từ ${fmt(RESORT_RULE.cash)} (hiện ${fmt(S.cash)})`, ok:S.cash>=RESORT_RULE.cash},
  {t:`Uy tín từ ${String(RESORT_RULE.stars).replace('.',',')}★ (hiện ${rating().toFixed(1).replace('.',',')}★)`, ok:rating()>=RESORT_RULE.stars}
]; }
function moveResort(){
  if(!resortChecks().every(c=>c.ok) || S.prem==='resort') return; const up=RESORT_PREM.rent*3; if(S.cash<up) return;
  S.cash-=up; addResortPrem(); S.prem='resort'; S.prices={}; SK.forEach(k=>{ if(S.skills[k]) S.prices[k]=market(k); }); addLog('Chuyển lên Resort Bãi Trường: cọc + thuê tháng đầu',-up); S.resortDay=S.day; save();
  drawScene(); ensureWorkers(); renderAll();
  if(window.WIN) WIN.show();   // 19r: màn thắng toàn màn (js/19r-thang.js)
}
function resortCard(){
  if(S.prem==='resort') return `<div class="card"><div class="sec-t">Resort Bãi Trường <span class="tag">Đã mở từ ngày ${S.resortDay||'?'}</span></div><p class="note">Mục tiêu tiếp theo: giữ Resort từ 4,8★ và doanh thu ngày 50tr.</p></div>`;
  const cs=resortChecks(), ok=cs.every(c=>c.ok), up=RESORT_PREM.rent*3;
  const tr=Object.keys(TREASURES).map(k=>{ const T=TREASURES[k], h=S.tr.have[k]; return `<div class="item${h?'':' own'}">${mgImg(T.img,'ico'+(h?'':' dim'))}<div class="grow"><div class="n">${T.name} ${h?'<span class="tag">Đã có</span>':''}</div><div class="m">${T.src}</div></div>${!h&&S.tr.dup>=3?`<button class="btn sm lav" data-trade="${k}">Đổi 3 trùng</button>`:''}</div>`; }).join('');
  return `<div class="card"><div class="sec-t">Mở Resort Bãi Trường <span class="note">${cs.filter(c=>c.ok).length}/${cs.length}</span></div>
    <div class="list" style="margin-top:6px">${cs.map(c=>`<div class="check${c.ok?' ok':''}"><i></i><span>${c.t}</span></div>`).join('')}
    <div class="check"><i></i><span class="note">5 bạn thân (mở khi có máy chủ, chưa tính)</span></div></div>
    <button class="btn big ${ok?'butter':'alt'}" id="goResort" style="margin-top:8px" ${ok&&S.cash>=up?'':'disabled'}>${ok?`Chuyển lên Resort · cọc ${fmt(up)}`:'Chưa đủ điều kiện'}</button>
    <details style="margin-top:8px"><summary class="sec-t">6 bảo vật và nơi tìm ▾</summary><div class="list" style="margin-top:6px">${tr}</div><p class="note">Món trùng: ${S.tr.dup}. Đủ 3 món trùng đổi được 1 bảo vật còn thiếu.</p></details></div>`;
}
renderScreen=(orig=>function(){ orig(); if(tab!=='book') return; const D=$('#dyn'), first=D.querySelector('.card'); if(first) first.insertAdjacentHTML('afterend',resortCard()); })(renderScreen);
$('#dyn').addEventListener('click',e=>{ const b=e.target.closest('button'); if(!b||b.disabled) return;
  if(b.id==='goResort') moveResort();
  if(b.dataset.trade) tradeDup(b.dataset.trade);
  if(b.dataset.prepay) prepay(b.dataset.prepay==='all'?S.debt:+b.dataset.prepay); });

// ---------- tip tính sau cùng: cộng đủ bấm huyệt, bùa, độ mòn rồi mới xét tip ----------
// Hàm gốc tính tip ngay sau điểm hài lòng thô; các lớp bọc sau đó (mini game, bùa, đồ mòn) đổi g.sat nhưng tip vẫn theo điểm cũ.
finishService=(orig=>function(g){
  const w=g.worker, stf=w?staffOf(w):null; orig(g);
  if(!w || g.tip===undefined) return;
  const tr=CTYPES[g.type].tip; let q=w.kind==='fly'?1.4:1; if(stf) q*=1+(stf.st.c-5)*0.06;
  let tip=0; if(g.sat>=80) tip=r10(g.price*tr[0]*q); else if(g.sat>=65 && tr[1]) tip=r10(g.price*tr[1]*q);
  if(g.type==='dp' && Math.random()<.5) tip=0;   // dân địa phương: nửa số lần không tip, như hàm gốc
  g.tip=tip;
})(finishService);

// 15j-realism.js — v2.5: kinh tế sát thực tế
// - KTV: lương cứng thấp + tua 30% giá dịch vụ + giữ 100% tip (chủ tiệm tự làm thì tip vào quỹ tiệm)
// - Thuế hộ kinh doanh: phần doanh thu vượt 500tr/năm nộp 7% (GTGT 5% + TNCN 2%)
// - Lượng khách theo vị trí và uy tín, không tăng chỉ vì mua thêm ghế (sửa trong 11-tick)
// - Đồ dùng bền hơn: ghế giường chịu ~1.000 lượt thay vì 220
// - Chuyển lên resort: nhận lại tiền cọc mặt bằng cũ
'use strict';

// ---------- độ bền đồ dùng theo lượt dùng thật ----------
// Ghế foot, giường gỗ dùng nặng ở tiệm du lịch thường phải bọc lại nệm sau vài tháng tới một năm.
Object.assign(WEAR_D,{chair:1000, room:1000, facial:900, nail:1000, sauna:1200, herbal:900, sofa:4000, cashier:10000, tea:5000, towel:3000, trolley:700, changing:5000});

// ---------- resort: nhu cầu khách theo vị trí ----------
RESORT_PREM.demand=60; RESORT_PREM.fit=0; RESORT_PREM.misc=20e6;
RESORT_PREM.name='Khu spa Resort Bãi Trường';
RESORT_PREM.desc='Nhận thầu khu spa trong một resort ven biển Bãi Trường: khách lưu trú cao cấp, giá dịch vụ cao nhất đảo.';

// ---------- chuyển đổi save cũ sang cách trả lương mới ----------
S.staff.forEach(s=>{ if(!s.pay2){ const sum=STK.reduce((a,k)=>a+(s.st[k]||0),0); s.monthly=baseSalary(sum,s.rank==='tc'); s.pay2=1; } });
S.cands.forEach(c=>{ if(!c.pay2){ const sum=STK.reduce((a,k)=>a+(c.st[k]||0),0); c.monthly=baseSalary(sum,c.rank==='tc'); c.pay2=1; } });
makeCands=(orig=>function(){ orig(); S.cands.forEach(c=>c.pay2=1); })(makeCands);
S.yr=S.yr||{start:S.day, rev:0}; S.taxPaid=S.taxPaid||0;

// ---------- ai làm khách này ----------
finishService=(orig=>function(g){
  const w=g.worker, stf=w&&w.kind==='staff'?staffOf(w):null; orig(g);
  if(stf) g.byStaff=stf.id;
})(finishService);

// ---------- thanh toán: tua cho KTV, tip KTV giữ ----------
pay=(orig=>function(g){
  if(g.problem) return orig(g);               // còn sự cố: hàm gốc mở bảng xử lý rồi gọi lại pay
  const stf=g.byStaff? S.staff.find(s=>s.id===g.byStaff) : null;
  if(!stf) return orig(g);
  const tip=g.tip||0; g.tip=0; orig(g);
  const tua=Math.round(g.price*TUA/1000)*1000;
  S.cash-=tua; S.stats.tua=(S.stats.tua||0)+tua; S.stats.costs+=tua;
  stf.tuaM=(stf.tuaM||0)+tua; stf.tipM=(stf.tipM||0)+tip; stf.tuaDay=(stf.tuaDay||0)+1;
  if(tip) stf.morale=clamp(stf.morale+1,0,100);
  if(tip) setTimeout(()=>fxText(g.x,g.y-84,`tip ${stf.name.split(' ').pop()} +${fmt(tip)}`,'tip'),250);
})(pay);

// ---------- đầu ngày: đầu tháng thì xoá số tua/tip tháng trước ----------
startDay=(orig=>function(){ if(S.day%30===1) S.staff.forEach(s=>{ s.tuaM=0; s.tipM=0; }); S.staff.forEach(s=>s.tuaDay=0); orig(); })(startDay);

// ---------- cuối ngày: thuế, tinh thần theo thu nhập ----------
endDay=(orig=>function(){
  const st=S.stats, rev=st.rev+st.tips;
  if(S.day-S.yr.start>=TAX.yearDays) S.yr={start:S.day, rev:0};
  const before=Math.max(0,S.yr.rev-TAX.free); S.yr.rev+=rev; const after=Math.max(0,S.yr.rev-TAX.free);
  const tax=Math.round((after-before)*TAX.rate/1000)*1000;
  if(tax>0){ S.cash-=tax; st.costs+=tax; st.tax=tax; S.taxPaid+=tax; }
  const laundry=st.served*LAUNDRY, misc=Math.round((prem().misc||5e6)/30/1000)*1000;
  S.cash-=laundry+misc; st.costs+=laundry+misc; st.laundry=laundry; st.misc=misc;
  // Âm tiền = chậm lương, nợ tiền hàng: nhân viên lo lắng
  if(S.cash<0) S.staff.forEach(s=>s.morale=clamp(s.morale-4,0,100));
  // KTV sống bằng tua: ít khách thì chán, đông khách vừa sức thì vui
  S.staff.forEach(s=>{ const n=s.tuaDay||0; if(n<2) s.morale=clamp(s.morale-3,0,100); else if(n>=4 && n<=s.st.e*2+4) s.morale=clamp(s.morale+1,0,100); });
  orig();
  const L=$('#sheet dl.ledger'), sum=L&&L.querySelector('dt.sum');
  if(sum){ let h='';
    if(st.laundry) h+=`<dt>Giặt khăn, đồ dùng một lần (${fmt(LAUNDRY)}/khách)</dt><dd>−${fmt(st.laundry)}</dd>`;
    if(st.misc) h+=`<dt>Chi phí khác</dt><dd>−${fmt(st.misc)}</dd>`;
    if(st.tua) h+=`<dt>Tua KTV (${Math.round(TUA*100)}% giá dịch vụ)</dt><dd>−${fmt(st.tua)}</dd>`;
    if(st.tax) h+=`<dt>Thuế (7% phần doanh thu vượt 500tr/năm)</dt><dd>−${fmt(st.tax)}</dd>`;
    if(h) sum.insertAdjacentHTML('beforebegin',h);
    const lw=[...L.querySelectorAll('dt')].find(d=>d.textContent.startsWith('Lương')); if(lw) lw.textContent='Lương cứng (lương tháng ÷ 30)';
  }
  // Hết tháng mà âm tiền: nợ tiền nhà. Chủ nhà trừ vào cọc (2 tháng); hết cọc thì lấy lại mặt bằng
  // v3.1: tiền thuê thu theo ngày; âm tiền liên tục 90 ngày (hết 2 tháng cọc và thêm 1 tháng) thì chủ nhà lấy lại mặt bằng
  S.rentLate=S.cash<0?(S.rentLate||0)+1:0;
  if(S.rentLate>=90){ bankrupt('rent'); return; }
  const low=S.staff.filter(s=>(s.tuaDay||0)<2); const note=$('#sheet .row');
  if(note && S.cash<0) note.insertAdjacentHTML('beforebegin',`<div class="note" style="color:var(--danger)"><b>Đang thiếu ${fmt(-S.cash)}.</b> Khoản thiếu chịu lãi quá hạn mỗi ngày. Nhân viên chậm lương nên tinh thần giảm mỗi ngày. ${S.rentLate>=30?`Đã thiếu tiền thuê ${S.rentLate} ngày liền, chủ nhà đang trừ vào cọc; đủ 90 ngày sẽ lấy lại mặt bằng.`:'Âm tiền là đang nợ tiền thuê, chủ nhà trừ dần vào cọc.'}</div>`);
  if(note){ const left=Math.max(0,TAX.free-S.yr.rev);
    note.insertAdjacentHTML('beforebegin',`<div class="note">Doanh thu năm nay ${fmt(S.yr.rev)} · ${left>0?`còn ${fmt(left)} nữa là phải nộp thuế`:'đã phải nộp thuế'}.</div>${low.length?`<div class="note">${low.map(s=>esc(s.name)).join(', ')} làm dưới 2 tua hôm nay, thu nhập thấp nên tinh thần giảm.</div>`:''}`); }
})(endDay);

// ---------- chuyển lên resort: nhận lại cọc mặt bằng cũ ----------
moveResort=(orig=>function(){ const old=prem(); orig(); if(S.prem==='resort' && old && old.id!=='resort'){ const dep=old.rent*2; S.cash+=dep; addLog('Nhận lại cọc mặt bằng '+old.name,dep); save(); renderAll(); } })(moveResort);

// ---------- nợ xấu: mất tiệm ----------
// 20j: màn "Làm lại" cho mọi loại phá sản/siết nợ: tranh + lời nhắn, chạm/Tiếp → ván mới (BỎ QUA truyện mở đầu), vào chọn độ khó (CIC xấu thì ép Khó)
const INTRO_KEY='spa-miu-intro';
function redoGo(){ try{ localStorage.setItem(INTRO_KEY,'1'); localStorage.removeItem(KEY); }catch(e){} window.__khongLuu=true; location.reload(); }
// 20p: MỘT màn cho mọi loại phá sản + nút "Làm lại từ đầu" sau siết nợ: nền = video lặp (PS_VIDEO=true khi có art/video/in-PS-lam-lai.mp4) hoặc tranh PS-lam-lai + Ken Burns rất chậm;
// dải dưới giữa (rộng ~60%, cao ~26%, cách đáy 3%) 1 tấm bảng nhỏ giấy kem: hỏi [Làm lại][Thoát]; Làm lại -> lời nhắn + [Bắt đầu] -> ván mới.
const PS_VIDEO=true;   // 21b: clip Grok lặp; bản nhẹ / máy yếu / reduced-motion -> ảnh tĩnh
const PS_NHE=!!window.__NHE/*BUILD_NHE*/;
const PS_DONG=()=>PS_VIDEO&&!PS_NHE&&!(window.matchMedia&&matchMedia('(prefers-reduced-motion:reduce)').matches)&&!(navigator.hardwareConcurrency&&navigator.hardwareConcurrency<4)&&!/[?&]noVideo/.test(location.search);
(()=>{ const st=document.createElement('style'); st.textContent=`#redoMan{position:fixed;inset:0;z-index:100000;background:#2a2638;overflow:hidden;font-family:Nunito,sans-serif;color:#4a3524}
#redoMan .rm-bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 40%;animation:rmKB 40s ease-in-out infinite alternate}
@keyframes rmKB{from{transform:scale(1)}to{transform:scale(1.05) translateX(-1%)}}
@media (prefers-reduced-motion:reduce){#redoMan .rm-bg{animation:none}}
#redoMan .rm-board{position:absolute;left:50%;bottom:3%;width:60%;min-width:min(92vw,300px);aspect-ratio:1100/314;min-height:132px;max-height:34%;box-sizing:border-box;padding:7% 13% 6%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;text-align:center;filter:drop-shadow(0 6px 14px rgba(74,58,44,.45));transform:translateX(-50%);animation:rmIn .5s ease-out both}
@media (max-width:600px){#redoMan .rm-board{width:94%;aspect-ratio:auto;height:205px;max-height:none;padding:46px 56px 34px;gap:6px}}
/* 21c: ngang thấp (844x390): bảng cao hơn, chữ nằm giữa khoảng trống, không bị hoa che */
@media (orientation:landscape) and (max-height:480px){#redoMan .rm-board{width:min(80%,660px);aspect-ratio:auto;height:184px;min-height:0;max-height:none;padding:46px 136px 36px;gap:8px}#redoMan .rm-t{font-size:var(--fz-than);line-height:1.3}}
/* 23g: khung hoa 9 mảnh, góc hoa giữ nguyên tỉ lệ, chỉ cạnh/giữa giãn (trước: 1 ảnh kéo 100% 100% nên hoa méo ở màn dọc) */
#redoMan .rm-board::before{content:"";position:absolute;inset:0;z-index:-1;box-sizing:border-box;border:solid transparent;border-width:50px 118px;border-image:url(img/0db3e5243c28.webp) 120 280 fill / 50px 118px stretch;pointer-events:none}
@keyframes rmIn{from{opacity:0;transform:translateX(-50%) scale(.92)}to{opacity:1;transform:translateX(-50%) scale(1)}}
#redoMan .rm-t{margin:0;font-weight:800;font-size:clamp(12px,2.2vw,18px);line-height:1.4;color:#4a2c14}
#redoMan .rm-b{display:flex;gap:10px;justify-content:center}
#redoMan .rm-n{appearance:none;border:0;cursor:pointer;min-width:112px;height:40px;padding:0 14px 0 34px;background:url(img/65d034d4fc04.webp) center/100% 100% no-repeat;color:#4a2c14;font:800 var(--fz-than) Nunito,sans-serif;-webkit-tap-highlight-color:transparent}
#redoMan .rm-n:active,#redoMan .rm-n.on{background-image:url(img/485cc3e25d6f.webp);transform:translateY(1px)}
#redoMan .rm-n.kem{background-image:url(img/676c8e74219b.webp)}
#redoMan .rm-n.kem:active,#redoMan .rm-n.kem.on{background-image:url(img/125d985f947d.webp)}`; document.head.appendChild(st); })();
function redoScreen(mode){ if(document.getElementById('redoMan')) return; const el=document.createElement('div'); el.id='redoMan';
  const bg=PS_DONG()?'<video class="rm-bg" src="art/video/in-PS-lam-lai.mp4" autoplay muted loop playsinline></video>':'<img class="rm-bg" alt="" src="img/5e29b11be2c6.webp">';
  el.innerHTML=bg+'<div class="rm-board" role="dialog"></div>'; document.body.appendChild(el);
  const bd=el.querySelector('.rm-board'), hoi=()=>{ bd.innerHTML='<p class="rm-t">Tạm biệt nhé, lại tha phương cầu thực tiếp à? Hay… có muốn làm lại không?</p><div class="rm-b"><button class="rm-n" type="button" data-restart>Làm lại</button><button class="rm-n kem" type="button" data-exit>Thoát</button></div>';
    bd.querySelector('[data-restart]').onclick=nhac;
    bd.querySelector('[data-exit]').onclick=()=>{ try{ window.close(); }catch(e){} document.body.innerHTML='<div style="display:flex;height:100vh;align-items:center;justify-content:center;background:#2a2638;color:#fbf3df;font:700 var(--fz-tieude) system-ui;text-align:center;padding:24px">Hẹn gặp lại nhé!</div>'; }; },
    nhac=()=>{ bd.style.animation='none'; void bd.offsetWidth; bd.style.animation=''; bd.innerHTML='<p class="rm-t">Rất có ý chí đấy, nhưng không vì thế mà mọi thứ sẽ trở nên dễ dàng hơn đâu nhé. Cố gắng lên!</p><div class="rm-b"><button class="rm-n" type="button" data-rd-next>Bắt đầu</button></div>';
    bd.querySelector('[data-rd-next]').onclick=redoGo; };
  hoi(); }
window.redoScreen=redoScreen;
function bankrupt(why){
  why=why||S.bankrupt||'bank';
  if(why==='Ngân hàng siết nợ'||why==='bank'){ try{ cicSave(); }catch(e){} }
  S.stage='closed'; S.bankrupt=why; save();
  try{ closeSheet&&closeSheet(); }catch(e){}
  redoScreen();
}
if(S.bankrupt) setTimeout(bankrupt,300);

// ---------- khách nhìn bảng hiệu rồi mới vào ----------
// Người muốn dịch vụ tiệm không có: phần lớn đi thẳng hoặc đổi ý làm món tiệm có; chỉ số ít vào hỏi rồi về.
const unofferedShare=()=>{ const ks=SK.filter(k=>SERVICES[k].w), tot=ks.reduce((a,k)=>a+SERVICES[k].w,0), u=ks.filter(k=>!canOffer(k)).reduce((a,k)=>a+SERVICES[k].w,0); return tot?u/tot:0; };
const REALISM={drop:.35, force:false};   // v3.4: 15w hạ drop xuống .15 (phần còn lại vào hỏi, người chơi thấy được); force = khách chắc chắn ghé
spawn=(orig=>function(kind){ if(kind==='new' && !REALISM.force && Math.random()<unofferedShare()*REALISM.drop) return; return orig(kind); })(spawn);
pickWant=(orig=>function(){ const w=orig(); if(canOffer(w)||Math.random()>=50/65) return w;
  const off=SK.filter(k=>SERVICES[k].w&&canOffer(k)); if(!off.length) return w;
  let x=Math.random()*off.reduce((a,k)=>a+SERVICES[k].w,0); for(const k of off){ x-=SERVICES[k].w; if(x<=0) return k; } return off[0]; })(pickWant);

// 15k-debt.js — v2.6: Khoản vay & trả nợ. 20e (14/10): khó hơn, nhắc 3 lần rồi siết nợ.
// Kỳ góp 10 ngày một lần (PERIOD), mỗi kỳ trả một phần TỔNG NỢ (gốc + lãi chia đều), KHÔNG được trả chỉ lãi. Trừ Quỹ trả nợ trước rồi tới tiền mặt.
// Thiếu bao nhiêu thì phần thiếu thành nợ quá hạn (tính lãi phạt 150%) và là TRỄ KỲ:
//   ngày trễ 1 = nhắc lần 1, sau 3 ngày nhắc lần 2, sau 3 ngày nữa nhắc lần 3 (cảnh báo cuối, đếm ngược), sau 3 ngày nữa chưa trả đủ → NGÂN HÀNG SIẾT NỢ (20g: thu vật phẩm giá 10%, chơi tiếp, khóa vay vĩnh viễn; không đủ nợ mới phá sản).
//   Mỗi lần nhắc = tin nhắn cán bộ ngân hàng + chip HUD (20g: không còn tạt sơn, không tự trích tiền). Đã bị nhắc thì KHÓA vay ngân hàng tới khi tất toán khoản vay.
// 20h: siết nợ = giữ ĐÚNG 1 giường + 1 ghế (rẻ nhất), thu hết còn lại (kể cả quầy) giá 10%. 20i: đủ nợ quá hạn thì chơi tiếp (ngân hàng không nhắc/siết nữa); KHÔNG đủ thì PHÁ SẢN. Luật giãn lịch của 20h đã bỏ. Đặt S.cicXau=true (lưu vĩnh viễn, vào Resort ép mức Khó, khóa ngân hàng).
// Không có "đòi nợ thuê": dịch vụ đòi nợ bị cấm kinh doanh từ 2021. Tạt sơn ở đây là hậu quả trong game.
'use strict';
const DEBT={penalty:1.5, nhacGap:3, nhacMax:3, fee:{de:.02,vua:0,kho:.03,legacy:.02}};
const GIAN_MUL=2, GIAN_PAY=.6;   // 20h: kỳ giãn dài gấp đôi, tiền mỗi kỳ = 60% mức cũ
const CIC_TXT='Nợ ngân hàng trễ thì ván sau khó hơn.';
window.CIC_TXT=CIC_TXT; window.cicWarn=()=>toast(CIC_TXT,'warn');
S.loan=Object.assign({gian:false, due:0, od:0, odDays:0, fund:0, fundPct:0, promise:0, promises:0, broken:0, ignored:0, cicUntil:0, visitDay:0, hist:[], paidOnTime:0, nhac:0, lock:false, perma:false, siet:0}, S.loan||{});
if(!S.loan.due) S.loan.due=S.stage==='story'||S.stage==='prem'? PERIOD : Math.max(PERIOD, Math.ceil(S.day/PERIOD)*PERIOD);

const perLen=()=>S.loan.gian?PERIOD*GIAN_MUL:PERIOD;   // độ dài kỳ góp hiện tại
const instRate=()=>mRate()*(S.loan.gian?GIAN_MUL:1);   // lãi mỗi kỳ (lãi năm giữ nguyên)
const nextInst=()=>{ if(S.debt<=0) return 0; const it=S.debt*instRate(); let p=periodPay()*(S.loan.gian?GIAN_PAY:1); if(S.loan.gian) p=Math.max(p,it*1.5); return Math.round(Math.min(p, S.debt+it)); };
const daysToDue=()=>S.loan.due-S.day;
const owedAll=()=>Math.max(0,S.debt)+S.loan.od;
const canPay=()=>S.loan.fund+Math.max(0,S.cash);
const loanHist=(t,a)=>{ S.loan.hist.unshift({d:S.day,t,a}); S.loan.hist=S.loan.hist.slice(0,20); };
// Lấy tiền từ Quỹ trả nợ trước, rồi tới tiền mặt dương. Trả về số tiền thực lấy được.
function payFrom(amount){ let need=Math.round(amount); const f=Math.min(S.loan.fund,need); S.loan.fund-=f; need-=f; const c=Math.min(Math.max(0,S.cash),need); S.cash-=c; need-=c; return Math.round(amount)-need; }
function clearOverdueIfDone(){ if(S.loan.od<=1000){ const was=S.loan.odDays; S.loan.od=0; S.loan.odDays=0; S.loan.nhac=0; if(was) toast('Đã trả hết nợ quá hạn. Ngân hàng ngừng nhắc, nhưng khóa vay thêm tới khi tất toán.','good'); } }
function payOverdue(amt){ amt=Math.min(amt,S.loan.od); const got=payFrom(amt); if(got<=0) return 0; S.loan.od-=got; loanHist('Trả nợ quá hạn',-got); addLog('Trả nợ quá hạn ngân hàng',-got); clearOverdueIfDone(); save(); return got; }
function payInstEarly(){ const inst=nextInst(); if(!inst||canPay()<inst) return; const it=Math.round(S.debt*instRate()); payFrom(inst); S.debt=Math.max(0,S.debt-(inst-it)); S.loan.due+=perLen(); S.loan.paidOnTime++; loanHist('Góp trước kỳ',-inst); addLog('Góp ngân hàng trước kỳ',-inst); debtDoneCheck(); save(); toast(`Đã góp trước kỳ ${fmt(inst)}. Kỳ tới: ngày ${S.loan.due}.`,'good'); }
function prepayPrincipal(a){ a=Math.min(a,S.debt); if(a<=0) return; const fee=Math.round(a*(DEBT.fee[S.diff]??.02)); if(canPay()<a+fee) return;
  payFrom(a+fee); S.debt-=a; loanHist(`Trả trước gốc (phí ${fmt(fee)})`,-(a+fee)); addLog('Trả trước gốc ngân hàng',-(a+fee)); debtDoneCheck(); save();
  toast(S.debt<=0?'Đã tất toán khoản vay!':`Đã trả trước ${fmt(a)} gốc, phí ${fmt(fee)}. Còn nợ ${fmt(S.debt)}.`,'good'); }
function debtDoneCheck(){ if(S.debt<=0 && S.loan.od<=0){ S.debt=0; if(S.loan.lock&&!S.loan.perma){ S.loan.lock=false; toast('Đã tất toán khoản vay: ngân hàng mở lại vay.','good'); } if(S.loan.fund>0){ S.cash+=S.loan.fund; addLog('Quỹ trả nợ về tiền mặt',S.loan.fund); S.loan.fund=0; } } }
// prepay cũ (15i) gọi sang hàm mới để có phí
prepay=function(a){ prepayPrincipal(a); renderAll(); };

// ---------- 20e: nhắc nợ 3 lần → siết nợ ----------
const NHAC_TXT=[null,
  n=>`Kỳ góp chưa thanh toán đủ. Số tiền quá hạn ${fmt(n)}. Đề nghị Quý khách thanh toán trong 3 ngày. (Nhắc nợ lần 1/3)`,
  n=>`Quý khách vẫn chưa thanh toán ${fmt(n)}. Chúng tôi sẽ cử người tới tiệm. Nếu còn chậm, ngân hàng thu hồi khoản vay. (Nhắc nợ lần 2/3)`,
  n=>`CẢNH BÁO CUỐI: ${fmt(n)} chưa thanh toán. Còn 3 ngày; hết hạn ngân hàng SIẾT NỢ, thu hồi toàn bộ khoản vay và tiệm. (Nhắc nợ lần 3/3)`];
function nhacNo(n){ const L=S.loan; L.nhac=n; L.lock=true;
  inboxMsg('Cán bộ ngân hàng',NHAC_TXT[n](L.od)+' '+CIC_TXT,'nv-nganhang-H1'); setTimeout(cicWarn,900);
  if(typeof sfx==='function') sfx('ring');
  return `<span style="color:var(--danger)"><b>Ngân hàng nhắc nợ lần ${n}/3.</b> Bị khóa vay ngân hàng.${n===3?' <b>3 ngày nữa chưa trả đủ là bị siết nợ: thu vật phẩm trong tiệm.</b>':''}</span>`; }
// 20h: siết nợ = giữ ĐÚNG 1 giường + 1 ghế (món rẻ nhất mỗi loại), thu hết còn lại (kể cả quầy) giá 10% giá mua, trừ vào nợ quá hạn rồi tiền mặt/quỹ.
// Dư thì trừ gốc; thiếu thì cộng vào gốc và GIÃN LỊCH. Không phá sản. Từ đây ngân hàng không nhắc/siết nữa.
const SIET_GIA=.1;
function sietNo(){ const L=S.loan; let need=Math.round(S.debt+L.od); const taken=[];   // 20j: thu TOÀN BỘ dư nợ (gốc + quá hạn), không chỉ phần quá hạn
  const keep={}; ['chair','room'].forEach(t=>{ const c=SLOTS.filter(s=>S.owned[s.id]&&s.id.startsWith(t)).sort((a,b)=>a.price-b.price)[0]; if(c) keep[c.id]=1; });
  SLOTS.filter(s=>S.owned[s.id]&&!keep[s.id]).sort((a,b)=>b.price-a.price).forEach(s=>{ const v=Math.round(s.price*SIET_GIA); delete S.owned[s.id]; if(S.wear) delete S.wear[s.id]; if(S.lv) delete S.lv[s.id]; taken.push({n:s.name,v}); });
  const itemSum=taken.reduce((a,x)=>a+x.v,0); need-=itemSum;
  let cashTaken=0; if(need>0){ cashTaken=payFrom(need); need-=cashTaken; }
  if(need>1000){ bankrupt('Ngân hàng siết nợ'); return null; }   // 20j: thu hết mà vẫn không đủ TOÀN BỘ dư nợ → PHÁ SẢN
  if(need<0) S.cash+=-need;   // thu dư thì trả lại phần dư
  if(itemSum) addLog('Ngân hàng thu vật phẩm trừ nợ',itemSum);
  S.debt=0; L.od=0; L.odDays=0; L.nhac=0; L.lock=true; L.perma=true; L.siet=(L.siet||0)+1; L.sietDay=S.day; S.cicXau=true; L.gian=false; cicSave(); debtDoneCheck();
  loanHist(`Siết nợ: thu ${taken.length} vật phẩm + ${fmt(cashTaken)} tiền`,0);
  const list=taken.map(x=>`${x.n} (${fmt(x.v)})`).join(', ')||'không có vật phẩm';
  inboxMsg('Cán bộ ngân hàng',`NGÂN HÀNG SIẾT NỢ. Đã thu: ${list}${cashTaken?`; trừ ${fmt(cashTaken)} tiền mặt/quỹ`:''}. Giữ lại 1 giường và 1 ghế. Khoản vay được TẤT TOÁN toàn bộ, ngân hàng không còn cho vay. Hồ sơ của Quý khách bị ghi CIC xấu.`,'nv-nganhang-H1');
  if(typeof sfx==='function') sfx('ring');
  setTimeout(sietPopup,500);
  try{ renderAll(); }catch(e){}
  return `<div style="color:var(--danger)"><b>NGÂN HÀNG SIẾT NỢ.</b> Đã thu vật phẩm theo giá 10% giá mua, chỉ giữ lại 1 giường và 1 ghế:<br>${taken.length?taken.map(x=>`• ${esc(x.n)}: ${fmt(x.v)}`).join('<br>'):'• (không còn vật phẩm nào để thu)'}${cashTaken?`<br>• Trừ tiền mặt/quỹ: ${fmt(cashTaken)}`:''}<br>Tiệm vẫn mở. Toàn bộ dư nợ đã được <b>tất toán</b>. Ngân hàng <b>khóa vay vĩnh viễn</b>, hồ sơ bị ghi <b>CIC xấu</b>.</div>`; }
// 20h: popup giấy giữa màn sau khi bị siết nợ
function sietPopup(){ if(document.getElementById('sietPop')) return; const el=document.createElement('div'); el.id='sietPop';
  el.style.cssText='position:fixed;inset:0;z-index:99999;display:flex;align-items:center;justify-content:center;background:rgba(40,28,20,.55);padding:20px';
  el.innerHTML=`<div style="max-width:320px;background:#fbf3de;border:2px solid #c9a96b;border-radius:6px;padding:22px 20px;text-align:center;box-shadow:0 8px 30px rgba(74,58,44,.4);transform:rotate(-1deg);font-family:Nunito,sans-serif;color:#4a3524">
    <div style="font-weight:800;font-size:var(--fz-muc);line-height:1.5">Cuộc đời vốn vẫn vậy mà bạn, cố lên nhé!</div>
    <div class="row" style="display:flex;flex-direction:column;gap:8px;margin-top:16px"><button class="btn big butter" data-sp-redo>Làm lại từ đầu</button><button class="btn alt" data-sp-go>Chơi tiếp</button></div></div>`;
  document.body.appendChild(el);
  el.querySelector('[data-sp-go]').onclick=()=>el.remove();
  el.querySelector('[data-sp-redo]').onclick=()=>{ el.remove(); redoScreen(); }; }
window.sietPopup=sietPopup;

// 20j: CIC xấu lưu ở MỤC HỒ SƠ (key riêng), sống qua "Làm lại"; chỉ ép ván chơi MỚI sau đó (mức Khó, không ngân hàng)
const CIC_KEY='spa-miu-cic';
function cicHas(){ try{ return !!localStorage.getItem(CIC_KEY); }catch(e){ return false; } }
function cicSave(){ try{ localStorage.setItem(CIC_KEY,'1'); }catch(e){} }
function cicClear(){ try{ localStorage.removeItem(CIC_KEY); }catch(e){} S.cicXau=false; S.cicRun=false; }
// 20l: qua map tiep theo ma het no (ngan hang + vay nong) -> xoa CIC; con no vay nong thi CIC mang theo
function cicNoNong(){ const C=S.credit||{}, cf=C.cf, ls=C.ls; return !!((cf&&(cf.debt>0||cf.od>0))||(ls&&((ls.bal||ls.left||0)>0))); }
function cicCheckClear(){ if(!(S.cicRun||S.cicXau||cicHas())) return false; if(S.debt>0||S.loan.od>0||cicNoNong()) return false; cicClear(); save(); setTimeout(()=>toast('CIC đã sạch - ngân hàng mở lại ở map mới.','good'),2500); return true; }
window.cicHas=cicHas; window.cicSave=cicSave; window.cicClear=cicClear; window.cicCheckClear=cicCheckClear;

// ---------- cuối ngày: trích quỹ, tính lãi phạt, trừ kỳ góp, leo thang ----------
endDay=(orig=>function(){
  const st=S.stats, gross=st.rev+st.tips; orig();
  if(S.bankrupt) return;
  const L=S.loan, notes=[];
  // 1. Tự trích quỹ trả nợ
  if(L.fundPct && owedAll()>0 && S.cash>0){ const a=Math.min(S.cash, Math.round(gross*L.fundPct/1000)*1000, Math.max(0,owedAll()-L.fund)); /* quỹ không vượt số còn nợ */ if(a>0){ S.cash-=a; L.fund+=a; notes.push(`Đã trích <b>${fmt(a)}</b> vào quỹ trả nợ (quỹ ${fmt(L.fund)}).`); } }
  // 2. Nợ quá hạn: lãi phạt, ngân hàng tự trích tiền, nhắc nợ / siết nợ
  if(L.od>0 && !L.siet){
    L.odDays++; const pen=Math.round(L.od*LOAN.yearRate*DEBT.penalty/360); L.od+=pen;
    if(L.od>0){
      if(L.odDays===1+DEBT.nhacGap) notes.push(nhacNo(2)); else if(L.odDays===1+2*DEBT.nhacGap) notes.push(nhacNo(3));
      else if(L.odDays>=1+3*DEBT.nhacGap){ const t=sietNo(); if(t===null) return; notes.push(t); }
      if(L.od>0) notes.push(`<span style="color:var(--danger)"><b>Nợ quá hạn ${fmt(L.od)}</b> · trễ ${L.odDays} ngày · nhắc ${L.nhac}/3${L.nhac>=3?` · còn ${1+3*DEBT.nhacGap-L.odDays} ngày tới siết nợ`:''} · lãi phạt hôm nay ${fmt(pen)}.</span>`);
    }
  }
  // 3. Tới kỳ góp
  if(S.debt>0 && S.day>=L.due){
    const it=Math.round(S.debt*instRate()), inst=nextInst(), got=payFrom(inst);
    S.debt=Math.max(0,S.debt-(inst-it)); L.due+=perLen();
    if(got>=inst){ L.paidOnTime++; loanHist('Góp kỳ đúng hạn',-inst); addLog('Góp ngân hàng đúng hạn',-inst); notes.push(`Đã góp kỳ này <b>${fmt(inst)}</b> (lãi ${fmt(it)}, gốc ${fmt(inst-it)}).`); }
    else { const short=inst-got; L.od+=short; const first=!L.odDays; if(first) L.odDays=1; loanHist(`Góp thiếu, quá hạn ${fmt(short)}`,-got); if(got) addLog('Góp ngân hàng (thiếu)',-got);
      notes.push(`<span style="color:var(--danger)"><b>Không đủ tiền góp!</b> Mới trả ${fmt(got)}/${fmt(inst)}, thiếu ${fmt(short)} thành nợ quá hạn, tính lãi phạt 150% từ mai.</span> Kẹt tiền thì xem Sổ sách › Vay thêm.`);
      if(first) notes.push(nhacNo(1)); }
    debtDoneCheck();
  } else if(S.debt>0){ const d=daysToDue(), inst=nextInst(), need=Math.max(0,inst-L.fund);
    if(d<=3) notes.push(`${d<=3?'<b style="color:var(--danger)">':'<b>'}Còn ${d} ngày tới kỳ góp ${fmt(inst)}.</b> Quỹ trả nợ ${fmt(L.fund)}${need>0?`, cần để dành thêm khoảng ${fmt(need/Math.max(1,d))} mỗi ngày`:', đã đủ'}.`); }
  save(); renderTop();
  const row=$('#sheet .row'); if(row && notes.length) row.insertAdjacentHTML('beforebegin',`<div class="card debt-note">${notes.map(n=>`<div class="note">${n}</div>`).join('')}</div>`);
})(endDay);

// ---------- mỗi sáng: tin nhắn nhắc kỳ, cuộc gọi đòi nợ ----------
startDay=(orig=>function(){ orig(); if(S.bankrupt) return; const L=S.loan;
  if(S.debt>0 && L.od<=0 && daysToDue()===3) inboxMsg('Ngân hàng',`Kỳ góp ${fmt(nextInst())} đến hạn ngày ${L.due} (còn 3 ngày). Quý khách vui lòng chuẩn bị đủ tiền.`);
  if(S.debt>0 && L.od<=0 && daysToDue()<=3 && daysToDue()>0) setTimeout(()=>toast(`Còn ${daysToDue()} ngày tới kỳ góp ${fmt(nextInst())}. Quỹ + tiền mặt: ${fmt(canPay())}.`,canPay()>=nextInst()?'':'warn'),600);
  if(L.od>0 && L.nhac>=3) setTimeout(()=>toast(`Nhắc nợ 3/3: còn ${Math.max(0,1+3*DEBT.nhacGap-L.odDays)} ngày để trả đủ ${fmt(L.od)}, không thì ngân hàng siết nợ, thu vật phẩm.`,'warn'),600);
})(startDay);

// ---------- HUD: đếm ngược kỳ góp ----------
renderTop=(orig=>function(){ orig(); const sm=$('#cash')&&$('#cash').nextElementSibling; if(!sm||!S.loan) return;
  if(S.loan.od>0) sm.innerHTML=`<span class="due bad">nợ NH: nhắc ${S.loan.nhac}/3</span>`;
  else if(S.debt>0 && S.stage!=='story' && S.stage!=='prem'){ const d=daysToDue(); sm.innerHTML=`tiền mặt · <span class="due${d<=3?' bad':d<=7?' warn':''}">góp ${d}n</span>`; }
  else sm.textContent='tiền mặt'; })(renderTop);

// ---------- Sổ sách: mục Khoản vay & trả nợ ----------
const cicChip=()=>(S.cicXau||cicHas())?'<span class="tag warn" title="Hồ sơ CIC xấu: ván chơi sau chỉ mở mức Khó, không có ngân hàng." style="background:#fde1da;color:#8a2a14">CIC xấu</span>':'';
window.cicChip=cicChip;
function debtCard(){
  const L=S.loan, d=DIFFS[S.diff]||DIFFS.vua, inst=nextInst(), dd=daysToDue(), fee=DEBT.fee[S.diff]??.02;
  if(S.debt<=0 && L.od<=0) return `<div class="card"><div class="sec-t">Khoản vay <span class="tag">Đã tất toán</span> ${cicChip()}</div><p class="note">Không còn nợ ngân hàng. ${L.cicUntil>S.day?`CIC còn ghi nợ nhóm 2 tới ngày ${L.cicUntil}.`:'Lịch sử tín dụng sạch.'}</p></div>`;
  const status=L.gian? `<span class="tag warn">Giãn lịch ${perLen()} ngày</span>` : L.od>0? `<span class="tag warn">Trễ ${L.odDays} ngày · nhắc ${L.nhac}/3</span>` : dd<=3? '<span class="tag warn">Sắp tới hạn</span>' : '<span class="tag">Đúng hạn</span>';
  const paidPct=Math.round((1-S.debt/LOAN.amount)*100), need=Math.max(0,inst-L.fund);
  let sched='', b=S.debt; for(let i=0;i<6&&b>0;i++){ const it=b*instRate(), p=Math.min(periodPay()*(L.gian?GIAN_PAY:1)-it,b); if(L.gian&&p<it*.5) break; sched+=`<tr><td>Ngày ${L.due+i*perLen()}</td><td>${fmt(p+it)}</td><td>${fmt(p)}</td><td>${fmt(it)}</td></tr>`; b-=p; }
  return `<div class="card debt-card"><div class="sec-t">Khoản vay & trả nợ ${status} ${cicChip()}</div>
    <dl class="ledger" style="margin-top:6px"><dt>${esc(d.kind)}</dt><dd>${fmt(LOAN.amount)} · ${pctRate()}</dd><dt>Dư nợ gốc</dt><dd>${fmt(S.debt)}</dd>
    <dt>Kỳ góp tới</dt><dd>ngày ${L.due} · còn ${dd} ngày</dd><dt>Số tiền kỳ tới</dt><dd>${fmt(inst)}</dd>
    <dt>Quỹ trả nợ</dt><dd>${fmt(L.fund)}${need>0&&dd>0?` · cần thêm ${fmt(need/Math.max(1,dd))}/ngày`:''}</dd>
    ${L.od>0?`<dt style="color:var(--danger)">Nợ quá hạn (bị phạt lãi)</dt><dd style="color:var(--danger)">${fmt(L.od)}</dd>`:''}
    <dt>Vay thêm ngân hàng</dt><dd>${L.lock?`<b style="color:var(--danger)">BỊ KHÓA${L.perma?' VĨNH VIỄN (đã bị siết nợ)':' (đã trả trễ)'}</b>`:'mở'}</dd><dt>Kỳ góp đúng hạn</dt><dd>${L.paidOnTime}</dd></dl>
    <div class="bar" style="margin:6px 0"><i style="width:${paidPct}%"></i></div><p class="note">Đã trả ${paidPct}% gốc.</p>
    <div class="row" style="justify-content:flex-start;flex-wrap:wrap;gap:6px">
      ${L.od>0?`<button class="btn sm butter" data-debt="od" ${canPay()>0?'':'disabled'}>Trả nợ quá hạn</button>`:''}
      <button class="btn sm alt" data-debt="inst" ${L.od<=0&&canPay()>=inst?'':'disabled'}>Góp trước kỳ · ${fmt(inst)}</button>
      <button class="btn sm alt" data-debt="p50" ${L.od<=0&&S.debt>=5e7&&canPay()>=5e7*(1+fee)?'':'disabled'}>Trả trước 50tr gốc</button>
      <button class="btn sm mint" data-debt="pall" ${L.od<=0&&canPay()>=S.debt*(1+fee)?'':'disabled'}>Tất toán · ${fmt(S.debt*(1+fee))}</button></div>
    <p class="note">Trả trước hạn: ${fee?'có phí '+Math.round(fee*100)+'% số gốc trả trước':'không mất phí'}.</p>
    <div class="sec-t" style="margin-top:8px">Tự trích vào quỹ trả nợ</div><div class="seg" style="margin:6px 0">${[0,.1,.2,.3].map(v=>`<button data-fund="${v}" aria-pressed="${L.fundPct===v}">${v?Math.round(v*100)+'% thu':'Tắt'}</button>`).join('')}</div>
    <p class="note">Quỹ chỉ dùng để trả nợ, tới kỳ tự trừ.</p>${L.fund>0?`<button class="btn sm alt" data-debt="wd">Rút quỹ về tiền mặt</button>`:''}
    <details style="margin-top:8px"><summary class="sec-t">Lịch góp 6 kỳ tới ▾</summary><table class="sched"><tr><th>Kỳ</th><th>Góp</th><th>Gốc</th><th>Lãi</th></tr>${sched}</table></details>
    <details style="margin-top:6px"><summary class="sec-t">Trễ kỳ thì sao? ▾</summary><div class="note">
      Mỗi ${PERIOD} ngày góp một kỳ (gốc + lãi chia đều), không được chỉ trả lãi. Thiếu phần nào là trễ kỳ, phần thiếu thành nợ quá hạn, lãi phạt 150%, ngân hàng tự trích mọi khoản có được.<br>
      Trễ: nhắc lần 1 ngay hôm đó, lần 2 sau 3 ngày, lần 3 (cảnh báo cuối) sau 3 ngày nữa. Mỗi lần nhắc có tin nhắn cán bộ ngân hàng.<br>
      Hết 3 ngày sau lần nhắc 3 mà chưa trả đủ → ngân hàng siết nợ: giữ lại 1 giường + 1 ghế, thu hết còn lại (kể cả quầy) giá 10%, trừ tiền mặt. Thu rồi mà vẫn không đủ nợ quá hạn thì <b>phá sản</b>; đủ thì chơi tiếp và ngân hàng không nhắc nữa. Hồ sơ bị ghi <b>CIC xấu</b> vĩnh viễn: qua Resort luôn ở mức Khó, không có ngân hàng.<br>
      Đã bị nhắc thì bị khóa vay ngân hàng (không vay mở chi nhánh, không vay bổ sung) tới khi tất toán khoản vay hiện tại.</div></details>
    ${L.hist.length?`<details style="margin-top:6px"><summary class="sec-t">Lịch sử trả nợ ▾</summary><dl class="ledger">${L.hist.slice(0,10).map(h=>`<dt>Ngày ${h.d} · ${esc(h.t)}</dt><dd>${fmt(h.a)}</dd>`).join('')}</dl></details>`:''}</div>`;
}
renderScreen=(orig=>function(){ orig(); if(tab!=='book') return; const D=$('#dyn'), first=D&&D.querySelector('.card'); if(first) first.insertAdjacentHTML('afterend',debtCard()); })(renderScreen);
$('#dyn').addEventListener('click',e=>{ const b=e.target.closest('button'); if(!b||b.disabled) return;
  const a=b.dataset.debt, f=b.dataset.fund;
  if(f!==undefined){ S.loan.fundPct=+f; save(); renderScreen(); return; }
  if(!a) return;
  if(a==='od') payOverdue(S.loan.od);
  if(a==='inst') payInstEarly();
  if(a==='p50') prepayPrincipal(5e7);
  if(a==='pall') prepayPrincipal(S.debt);
  if(a==='wd'){ S.cash+=S.loan.fund; addLog('Rút quỹ trả nợ',S.loan.fund); S.loan.fund=0; save(); }
  renderAll(); });

// ---------- resort: cần lịch sử tín dụng sạch ----------
resortChecks=(orig=>function(){ return orig().concat([{t:`Lịch sử tín dụng sạch 12 tháng${S.loan.cicUntil>S.day?` (CIC ghi nợ nhóm 2 tới ngày ${S.loan.cicUntil})`:''}`, ok:!(S.loan.cicUntil>S.day) && S.loan.od<=0}]); })(resortChecks);

// 15l-guests.js — v2.6: quốc tịch khách nước ngoài, kiểu khách, khách đoàn khu Sunset
// Quốc tịch chỉ quyết định lời chào, tên, hình, và văn hoá tip (Mỹ tip nhiều nhất, Nga sau Mỹ; Hàn, Ấn ít tip hơn vì không có thói quen tip).
// Tính cách khó/dễ (đòi hoàn tiền, đòi thêm, gạ dịch vụ nhạy cảm, mặc cả dai, gắt gỏng, dễ thương) rơi ngẫu nhiên cho MỌI loại khách,
// không gắn với quốc tịch nào.
'use strict';
const NAT={
  us:{name:'Mỹ', flag:'🇺🇸', tip:1.3, hi:['Hi, how are you today?','Hey! How’s your day going?'], names:['Emma','Jake','Olivia','Noah','Ashley','Tyler']},
  ru:{name:'Nga', flag:'🇷🇺', tip:1.15, hi:['Privet! Spasibo!','Hello, thank you, you are so kind!'], names:['Olga','Dmitri','Natasha','Ivan','Katya','Sergei']},
  kr:{name:'Hàn Quốc', flag:'🇰🇷', tip:.7, hi:['Annyeonghaseyo!','Tokbokki ở quê tôi ngon lắm đó!','Kamsahamnida!'], names:['Min-ji','Ji-hoon','Seo-yeon','Hyun-woo','Soo-ah','Jun-ho']},
  in:{name:'Ấn Độ', flag:'🇮🇳', tip:.8, hi:['Namaste!','Hello my friend, is the massage good here?'], names:['Arjun','Priya','Rahul','Ananya','Vikram','Kavya']},
  za:{name:'Nam Phi', flag:'🇿🇦', tip:1, hi:['Howzit!','Hello! Such a lovely island.'], names:['Thabo','Naledi','Sipho','Lerato','Johan','Zanele'], img:'af'}
};
// Tỷ lệ quốc tịch là ước tính cho game: Phú Quốc có nhiều khách Hàn, Ấn Độ tăng mạnh 2025, Nga tăng nhờ bay thuê chuyến;
// khách Mỹ và châu Phi ít hơn. Khách đi bộ ở Trần Hưng Đạo nghiêng về khách Âu Mỹ, Nga; khách đoàn nghiêng về Hàn, Ấn.
const NAT_MIX={walk:{ru:.35,us:.27,kr:.15,in:.18,za:.05}, group:{kr:.4,in:.3,ru:.2,us:.07,za:.03}};
const wpick=o=>{ let r=Math.random()*Object.values(o).reduce((a,b)=>a+b,0); for(const k in o){ r-=o[k]; if(r<=0) return k; } return Object.keys(o)[0]; };
const natPid=(nat,male)=>`t_${NAT[nat].img||nat}_${male?'m':'f'}`;
const isMale=g=>/(_m$|_m_|^c_m)/.test(g.pid||'');

// ---------- kiểu khách (mọi quốc tịch, cả khách Việt) ----------
const ARCH={
  refund:{p:.02, name:'đòi hoàn tiền'}, perk:{p:.03, name:'đòi thêm'}, solicit:{p:.025, name:'gạ dịch vụ nhạy cảm', maleSolo:true},
  haggle:{p:.10, name:'mặc cả dai'}, grumpy:{p:.05, name:'gắt gỏng'}, sweet:{p:.10, name:'dễ thương'}
};
function rollArch(g){ if(g.grp||g.kind==='ret') return null; let r=Math.random();
  for(const k in ARCH){ const a=ARCH[k]; if(a.maleSolo && !isMale(g)) continue; if(r<a.p) return k; r-=a.p; } return null; }

function dressGuest(g){
  if(g.type==='tay'){ g.nat=g.nat||wpick(NAT_MIX.walk); g.pid=natPid(g.nat, Math.random()<.5); }
  else if(!g.pid){ const pool=GUEST_POOL[g.type]||GUEST_POOL.dp; g.pid=pick(pool); }
  g.arch=rollArch(g);
  if(g.arch==='haggle') g.M*=.9;
}

// ---------- khách đoàn ----------
const GUIDES=['anh Tâm','chị Hạnh','anh Quân','chị Vy','anh Khải'];
const GUIDE_FEE=.2, GROUP_DISC=.9;
let grpSkip=0, grpN=1;
spawn=(orig=>{
  function group(){
    const size=3+Math.floor(Math.random()*4), nat=wpick(NAT_MIX.group), id=grpN++, guide=pick(GUIDES);
    const off=SK.filter(k=>SERVICES[k].w&&canOffer(k)&&SERVICES[k].st!=='sauna'); const want=off.length? (off.includes('foot')&&Math.random()<.6?'foot':pick(off)) : 'foot';
    grpSkip=size-1; let lost=0;
    // khách đoàn xuống xe lần lượt; hàng chờ đầy thì người sau theo HDV sang tiệm khác
    for(let i=0;i<size;i++) later(i*.8,()=>{ if(S.time>=OPEN_END){ lost++; S.stats.lost++; return; } const n=guests.length; orig('grp'); const g=guests.length>n?guests[guests.length-1]:null;
      if(!g){ lost++; return; } g.type='tay'; g.nat=nat; g.pid=natPid(nat,Math.random()<.5); g.grp=id; g.guide=guide; g.want=want; g.M=market(want)*1.5; g.arch=null; });
    toast(`Xe du lịch đổ ${size} khách ${NAT[nat].name} ${NAT[nat].flag} (HDV ${guide}).`);
    later(size*.8+.2,()=>{ if(lost) toast(`Hết chỗ xếp hàng, ${lost} khách trong đoàn theo HDV sang tiệm khác.`,'warn'); });
  }
  return function(kind){
    if(kind==='new'){ if(grpSkip>0){ grpSkip--; return; } const p=prem(); if(p&&p.groups&&Math.random()<p.groups) return group(); }
    const n=guests.length; orig(kind); const g=guests.length>n?guests[guests.length-1]:null; if(g && !g.grp) dressGuest(g);
  };
})(spawn);
arriveCounter=(orig=>function(g){
  if(g.kind!=='grp' || !canOffer(g.want) || !hasSupplies(g.want)) return orig(g);
  g.state='atCounter'; const price=r10(priceOf(g.want)*GROUP_DISC); bubble(g, `Đoàn ${g.guide}: giá đoàn ${fmt(price)}`);
  later(.8,()=>{ if(guests.includes(g)) deal(g,price,false); });
})(arriveCounter);

// ---------- chào hỏi theo quốc tịch, mặc cả dai ----------
openHaggle=(orig=>function(g){ orig(g); if(!haggling||haggling.g!==g) return;
  if(g.nat) haggling.chat.splice(0,0,['c',pick(NAT[g.nat].hi)]);
  if(g.arch==='haggle' && haggling.offer!==undefined) haggling.chat.push(['c', g.type==='tay'?'Can you lower the price more? I’ll think about it.':'Giá có thể giảm nữa không, tôi sẽ suy nghĩ.']);
  renderHaggle(haggling.offer===undefined); })(openHaggle);   // khách chịu giá ngay thì không hiện nút trả giá
renderHaggle=(orig=>function(done){ orig(done); if(!haggling||!haggling.g.nat) return; const c=$('#haggle .chip'); if(c) c.textContent=`Khách ${NAT[haggling.g.nat].name} ${NAT[haggling.g.nat].flag}`; })(renderHaggle);
autoHaggle=(orig=>function(g){ if(g.nat) bubble(g,pick(NAT[g.nat].hi)); orig(g); })(autoHaggle);

// ---------- sự cố theo kiểu khách: đòi thêm, gạ dịch vụ nhạy cảm (lúc chốt giá) ----------
const archSheetFree=()=>$('#sheetBg').hidden;
deal=(orig=>function(g,price,sq){
  if(!guests.includes(g) || g.archDone || !['perk','solicit'].includes(g.arch) || !archSheetFree()) return orig(g,price,sq);
  g.archDone=true; const en=g.type==='tay';
  if(g.arch==='solicit'){
    const line=en?'Do you have the A-to-Z service here?':'Ở đây có dịch vụ từ A tới Z không?';
    const stay=()=>{ if(Math.random()<.65){ g.satAdj=(g.satAdj||0)-3; orig(g,price,sq); } else { bubble(g,en?'Okay, bye.':'Thôi vậy.'); S.stats.lost++; reject(g); } };
    if(S.manager){ bubble(g,line); later(1,()=>{ toast('Quản lý ca đã nói rõ tiệm chỉ massage trị liệu.'); stay(); }); return; }
    sheet(`<h2>Khách gạ dịch vụ nhạy cảm</h2><div class="scene-s">${portrait(g)}<p>"${esc(line)}"</p></div>
      <p class="note">Tiệm massage để xảy ra mua bán dâm bị xử phạt, đình chỉ, có thể truy cứu hình sự. Nhân viên cũng cần được bảo vệ.</p>
      <div class="list"><button class="btn alt" style="text-align:left;white-space:normal" data-a="1">Dạ tiệm chỉ massage trị liệu, anh chọn dịch vụ trong bảng giá nhé</button>
      <button class="btn alt" style="text-align:left;white-space:normal" data-a="2">Từ chối thẳng và mời khách ra về</button></div>`, sh=>{
      sh.querySelector('[data-a="1"]').onclick=()=>{ closeSheet(); stay(); };
      sh.querySelector('[data-a="2"]').onclick=()=>{ closeSheet(); bubble(g,en?'Fine.':'Được rồi.'); S.stats.lost++; reject(g); S.staff.forEach(s=>s.morale=clamp(s.morale+3,0,100)); toast('Nhân viên thấy được chủ tiệm bảo vệ, tinh thần tăng.','good'); };
    }); return;
  }
  // perk
  const line=en?'Give me 15 extra minutes for free, and some tea, okay?':'Cho thêm 15 phút miễn phí với ly trà nha em?';
  if(S.manager){ g.satAdj=(g.satAdj||0)+2; orig(g,price,sq); return; }
  sheet(`<h2>Khách đòi thêm</h2><div class="scene-s">${portrait(g)}<p>"${esc(line)}"</p></div>
    <div class="list"><button class="btn alt" style="text-align:left;white-space:normal" data-a="yes">Đồng ý: làm thêm 15 phút, mời trà (tốn thời gian của KTV)</button>
    <button class="btn alt" style="text-align:left;white-space:normal" data-a="tea">Chỉ mời trà, giữ đúng thời gian</button>
    <button class="btn alt" style="text-align:left;white-space:normal" data-a="no">Từ chối nhẹ nhàng</button></div>`, sh=>{
    sh.querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>{ closeSheet(); const a=b.dataset.a;
      if(a==='yes'){ g.durMul=1.25; g.satAdj=(g.satAdj||0)+8; } if(a==='tea') g.satAdj=(g.satAdj||0)+2; if(a==='no') g.satAdj=(g.satAdj||0)-6;
      orig(g,price,sq); });
  });
})(deal);
dispatch=(orig=>function(w,g,st){ orig(w,g,st); if(g.durMul && g.dur){ g.dur*=g.durMul; g.durMul=null; } })(dispatch);

// ---------- làm xong: điểm hài lòng, gắt gỏng, dễ thương, tip theo quốc tịch ----------
finishService=(orig=>function(g){
  const w=g.worker, stf=w&&w.kind==='staff'?staffOf(w):null; orig(g);
  if(g.satAdj){ g.sat=clamp(g.sat+g.satAdj,0,100); }
  if(g.arch==='grumpy' && stf){ stf.done=(stf.done||0)+1; stf.morale=clamp(stf.morale-3,0,100); }   // mệt và nản gấp đôi
  if(g.arch==='sweet'){ if(stf) stf.morale=clamp(stf.morale+2,0,100); g.sat=clamp(g.sat+3,0,100); }
  if(g.tip){ let t=g.tip; if(g.nat) t*=NAT[g.nat].tip; if(g.arch==='sweet') t*=1.2; if(g.arch==='grumpy') t*=.5; g.tip=r10(t); }
})(finishService);

// ---------- thanh toán: đòi hoàn tiền, hoa hồng hướng dẫn viên ----------
Object.assign(RV_VI,{refundNo:['đòi hoàn tiền mà chủ tiệm không chịu','thái độ chủ tiệm khi khách phàn nàn rất tệ'], refundOk:['chủ tiệm xử lý phàn nàn đàng hoàng']});
Object.assign(RV_EN,{refundNo:['they refused my refund, terrible attitude'], refundOk:['the owner handled my complaint well']});
pay=(orig=>function(g){
  if(g.problem) return orig(g);
  if(g.arch==='refund' && !g.archDone && archSheetFree()){ g.archDone=true; return refundSheet(g,()=>pay(g)); }
  orig(g);
  if(g.grp){ const c=Math.round(g.price*GUIDE_FEE/1000)*1000; S.cash-=c; S.stats.guide=(S.stats.guide||0)+c; S.stats.costs+=c; }
})(pay);
function refundSheet(g,done){
  const en=g.type==='tay', line=en?'This was not what I expected. I want my money back!':'Không như tôi mong đợi. Trả lại tiền cho tôi!', P=g.price;
  const reason=(k,v)=>{ if(g.rv) g.rv.reasons.push([k,v]); };
  const opt={
    half:()=>{ g.price=r10(P*.5); g.sat=Math.max(g.sat,55); reason('refundOk',6); },
    full:()=>{ g.price=0; g.tip=0; g.sat=Math.max(g.sat,65); reason('refundOk',8); },
    explain:()=>{ if(Math.random()<.55){ g.sat=Math.max(g.sat,50); reason('refundOk',4); toast('Khách nghe giải thích, nhận voucher và thanh toán đủ.','good'); } else { g.sat=15; g.tip=0; reason('refundNo',-25); toast('Khách không chịu, bỏ về và doạ viết đánh giá xấu.','warn'); } },
    no:()=>{ g.sat=10; g.tip=0; reason('refundNo',-30); }
  };
  if(S.manager){ (Math.random()<.7?opt.explain:opt.half)(); toast('Quản lý ca xử lý khách đòi hoàn tiền.'); done(); return; }
  sheet(`<h2>Khách đòi hoàn tiền</h2><div class="scene-s">${portrait(g)}<p>"${esc(line)}"</p></div><p class="note">Hoá đơn ${fmt(P)}. Hài lòng thật của khách: ${Math.round(g.sat)}/100.</p>
    <div class="list"><button class="btn alt" style="text-align:left;white-space:normal" data-r="half">Xin lỗi, hoàn 50% (${fmt(r10(P*.5))})</button>
    <button class="btn alt" style="text-align:left;white-space:normal" data-r="full">Hoàn 100% cho êm chuyện</button>
    <button class="btn alt" style="text-align:left;white-space:normal" data-r="explain">Giải thích quy trình, tặng voucher 20% lần sau</button>
    <button class="btn alt" style="text-align:left;white-space:normal" data-r="no">Từ chối hoàn tiền</button></div>`, sh=>{
    sh.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>{ closeSheet(); opt[b.dataset.r](); done(); });
  });
}

// ---------- đánh giá: tên và cờ theo quốc tịch ----------
makeReview=(orig=>function(g){ const id0=S.rv.nextId; orig(g); if(S.rv.nextId>id0 && g.nat){ const r=S.reviews[0]; if(!r.blogger) r.name=`${pick(NAT[g.nat].names)} ${NAT[g.nat].flag}`; r.nat=g.nat; } })(makeReview);

// ---------- cuối ngày: dòng hoa hồng HDV ----------
endDay=(orig=>function(){ const st=S.stats; orig(); const L=$('#sheet dl.ledger'), sum=L&&L.querySelector('dt.sum');
  if(sum && st.guide) sum.insertAdjacentHTML('beforebegin',`<dt>Hoa hồng hướng dẫn viên (${Math.round(GUIDE_FEE*100)}% khách đoàn)</dt><dd>−${fmt(st.guide)}</dd>`); })(endDay);

// ---------- lưới an toàn: khách đứng quầy quá lâu mà không ai tiếp thì tự về (tránh kẹt quầy, không hết ngày được) ----------
tick=(orig=>function(dt){ orig(dt); if(S.stage!=='open'||haggling||!$('#sheetBg').hidden||(window.LZ&&LZ.held&&LZ.held())) return; // M-g b2 R3
  for(const g of guests){ if(g.state==='atCounter'){ g.cT=(g.cT||0)+dt; if(g.cT>25){ g.cT=0; bubble(g, g.type==='tay'?'Nobody here? Bye.':'Không ai tiếp, thôi về.'); S.stats.lost++; reject(g); } } } })(tick);

// ---------- hàng đợi bảng: bảng đang chờ người chơi chọn (sự cố khách, hoàn tiền, đòi thêm, gọi đòi nợ...) không bị bảng khác đè ----------
// Trước đây bảng "Bảo vật" hay thông báo mở bằng hẹn giờ có thể đè lên bảng sự cố: nút chọn biến mất, khách đứng chờ trả tiền mãi, ngày không kết thúc.
const SHEETQ=[];
const sheetBusy=()=>!$('#sheetBg').hidden && !!$('#sheet').querySelector('[data-o],[data-r],[data-a],[data-c],[data-b],[data-t],[data-w]');
let sheetFlowing=false;   // đang trong chính luồng chọn (bấm nút → đóng → mở bảng kế) thì cho qua
sheet=(orig=>function(h,b){ if(sheetBusy() && !sheetFlowing){ SHEETQ.push([h,b]); return; } return orig(h,b); })(sheet);
$('#sheet').addEventListener('click',e=>{ if(e.target.closest('button')){ sheetFlowing=true; setTimeout(()=>sheetFlowing=false,0); } },true);
new MutationObserver(()=>{ if($('#sheetBg').hidden && SHEETQ.length) setTimeout(()=>{ if($('#sheetBg').hidden && SHEETQ.length){ const [h,b]=SHEETQ.shift(); sheet(h,b); } },30); }).observe($('#sheetBg'),{attributes:true,attributeFilter:['hidden']});
// lưới an toàn: khách tới quầy trả tiền mà 25 giây chưa xong (không có bảng nào mở) thì thanh toán lại
tick=(orig=>function(dt){ orig(dt); if(S.stage!=='open'||!$('#sheetBg').hidden) return;
  for(const g of guests){ if(g.state==='toPay' && !(g.walkT>0)){ g.pT=(g.pT||0)+dt; if(g.pT>25){ g.pT=0; g.archDone=true; pay(g); } } } })(tick);

// 15m-seasons.js — v2.7: lịch 12 tháng, mùa khô / mùa mưa Phú Quốc, thời tiết, Tết, chủ nhà tăng giá
// Mùa khô tháng 11–4 (biển êm, cao điểm khách quốc tế), mùa mưa tháng 5–10 (gió mùa tây nam, biển phía tây động).
// Bão nhiều nhất tháng 7–9: tàu ngưng chạy, đường ngập. Mùa khô hồ Dương Đông cạn, chính quyền kêu gọi tiết kiệm nước.
// Hệ số khách theo tháng là ƯỚC TÍNH thiết kế (khách quốc tế cao điểm tháng 12–3; khách trong nước cao điểm hè tháng 6–8 và Tết).
'use strict';
const MONTHS={
  1:{f:1.30,d:1.05,rain:0,   name:'mùa khô · cao điểm'},
  2:{f:1.30,d:1.20,rain:0,   name:'mùa khô · Tết'},
  3:{f:1.20,d:.90, rain:0,   heat:.4, name:'mùa khô · nắng nóng'},
  4:{f:1.00,d:1.10,rain:.05, heat:.7, dry:.25, name:'mùa khô · nóng, thiếu nước'},
  5:{f:.80, d:.90, rain:.25, heat:.5, dry:.1, name:'đầu mùa mưa'},
  6:{f:.60, d:1.20,rain:.35, name:'mùa mưa · hè'},
  7:{f:.55, d:1.25,rain:.40, storm:.02, name:'mùa mưa · bão'},
  8:{f:.55, d:1.05,rain:.45, storm:.035,name:'mùa mưa · bão, ngập'},
  9:{f:.55, d:.75, rain:.45, storm:.03, name:'mùa mưa · bão, ngập'},
  10:{f:.65,d:.70, rain:.35, storm:.01, name:'cuối mùa mưa · vắng nhất'},
  11:{f:1.00,d:.80,rain:.05, name:'đầu mùa khô'},
  12:{f:1.30,d:.90,rain:0,   name:'mùa khô · cao điểm'}
};
const rainy=m=>m>=5&&m<=10;
// Tháng bắt đầu theo độ khó: Dễ vào ngay mùa khách đông, Khó mở đúng đầu mùa mưa
// v3.1: ai cũng mở ở chợ đêm (95% khách trong nước) → Dễ mở đầu hè (khách trong nước đông nhất), Vừa đầu mùa khô, Khó tháng 9 (vắng nhất)
Object.assign(DIFFS.de,{start:6}); Object.assign(DIFFS.vua,{start:11}); Object.assign(DIFFS.kho,{start:9}); Object.assign(DIFFS.legacy,{start:10});
// v3.1: lịch mùa rút gọn — 1 tháng mùa = 10 ngày game, 12 tháng = 120 ngày rồi lặp lại.
// Lương, tiền thuê, góp nợ, thuế năm, hợp đồng thuê vẫn tính theo kỳ 30 ngày / 360 ngày như cũ.
const MONTH_DAYS=10, YEAR_DAYS=MONTH_DAYS*12;
if(!S.startMonth) S.startMonth=(DIFFS[S.diff]||DIFFS.vua).start||8;
const monthOf=(d=S.day)=>((S.startMonth-1)+Math.floor((d-1)/MONTH_DAYS))%12+1;
const dayOfMonth=(d=S.day)=>((d-1)%MONTH_DAYS)+1;
const MON=()=>MONTHS[monthOf()];
// Ngập hay xảy ra ở vùng trũng Dương Đông (chợ đêm, Trần Hưng Đạo) hơn khu Sunset phía nam
const FLOOD_RISK={chodem:.35, thd:.3, sunset:.12, resort:.08};
S.wx=S.wx||{}; S.prep=Object.assign({sandbag:0, generator:false, tank:false}, S.prep||{}); S.rentMul=S.rentMul||1;
{ const p=prem(); if(p && S.rentMul>1 && !p._baseRent){ p._baseRent=p.rent; p.rent=Math.round(p._baseRent*S.rentMul/1e5)*1e5; } }

// ---------- khách theo mùa ----------
// Tỷ lệ khách: dân địa phương không đổi, khách trong nước ×d, khách nước ngoài ×f (và bão thì tàu, máy bay huỷ)
const segMul=()=>{ const M=MON(), w=S.wx, st=w.today; let f=M.f, d=M.d; if(st==='storm1'||st==='storm3') f*=.35; if(isTet()) d*=1.1; return [tetLocal()?.4:1, d, f]; };
pickType=(orig=>function(){ const w=segMul(), mx=Math.max(...w); for(let i=0;i<6;i++){ const t=orig(), k=t==='dp'?0:t==='dl'?1:2; if(Math.random()<w[k]/mx) return t; } return orig(); })(pickType);
hourCurve=(orig=>function(){ const p=prem(); if(!p) return orig(); const w=segMul(), m=p.mix; let mul=m[0]*w[0]+m[1]*w[1]+m[2]*w[2];
  const t=S.wx.today; if(t==='rain') mul*=.8; if(t==='heavy') mul*=.55; if(t==='storm1') mul*=.6; if(t==='storm3') mul*=.6; if(t==='outage'&&!S.prep.generator) mul*=.7;
  return orig()*mul; })(hourCurve);

// ---------- Tết (mùng 1–5 tháng 2 trong game) ----------
const isTet=()=>monthOf()===2 && dayOfMonth()<=3;   // v3.1: Tết mùng 1–3 (tháng mùa chỉ 10 ngày)
const tetLocal=()=>isTet() && dayOfMonth()<=2;      // mùng 1–3 dân địa phương ở nhà
spawn=(orig=>function(kind){ const n=guests.length; orig(kind); const g=guests.length>n?guests[guests.length-1]:null; if(g && isTet()) g.M*=1.2; })(spawn);  // phụ thu Tết ~20%, khách chấp nhận

// ---------- trước mỗi ngày: thời tiết hôm nay ----------
function rollWeather(day){ const m=monthOf(day), M=MONTHS[m], r=Math.random();
  if(S.wx.storm && day>=S.wx.storm && day<=S.wx.storm+2) return ['storm1','storm2','storm3'][day-S.wx.storm];
  if(M.dry && r<M.dry) return 'drought';
  if(M.rain && r<M.rain){ const h=Math.random(); return h<.3?'heavy':h<.42?'outage':'rain'; }
  if(M.heat && Math.random()<M.heat) return 'heat';
  return 'sun'; }
const WX={sun:['☀️','Nắng đẹp'], rain:['🌧️','Mưa, khách ra đường ít hơn'], heavy:['⛈️','Mưa lớn cả ngày, khách giảm gần một nửa'], outage:['🔌','Mưa giông, cúp điện nửa ngày'],
  heat:['🥵','Nắng nóng, máy lạnh chạy hết công suất'], drought:['🚱','Cắt nước luân phiên'], storm1:['🌀','Bão sắp vào: tàu cao tốc ngưng chạy, chuyến bay huỷ'], storm2:['🌀','Bão đổ bộ: phải đóng cửa'], storm3:['🌊','Sau bão: đường còn ngập, dọn dẹp']};
startDay=(orig=>function(){
  const today=S.wx.next&&S.wx.next.d===S.day? S.wx.next.k : rollWeather(S.day); S.wx.today=today; S.wx.dmg=[];
  // Ngày bão, Tết: không bốc thêm sự kiện ngẫu nhiên (đoàn kiểm tra, blogger...)
  if((/^storm/.test(today)||isTet()) && (!S.event || S.day>S.event.to+2)) S.event={k:'_none', from:S.day, to:S.day-2};
  orig(); if(S.bankrupt) return;
  const m=monthOf();
  // Tết
  if(m===1 && dayOfMonth()===6 && S.staff.length && S.tetYear!==Math.floor(S.day/YEAR_DAYS)) setTimeout(tetBonusSheet,500);
  if(isTet() && dayOfMonth()===1 && S.staff.length) setTimeout(tetHolidaySheet,500);
  if(m===2 && dayOfMonth()===4) afterTet();
  if(m===1 && dayOfMonth()>=6 || m===2 && dayOfMonth()<=5) S.supMul=1.2; else S.supMul=1;
  // Chủ nhà tăng giá khi gia hạn hợp đồng mỗi 12 tháng
  if(!S.shops && S.day>1 && (S.day-1)%360===0 && prem() && S.prem!=='resort'){ const p=prem(); p._baseRent=p._baseRent||p.rent; S.rentMul=Math.round(S.rentMul*1.1*100)/100; p.rent=Math.round(p._baseRent*S.rentMul/1e5)*1e5; inboxMsg('Chủ nhà',`Gia hạn hợp đồng năm mới: tiền thuê tăng 10%, còn ${fmt(p.rent)}/tháng. Giá mặt bằng Phú Quốc tăng hoài em ạ.`); }
  // Thiệt hại theo thời tiết
  const t=today, note=[];
  if(t==='storm2' || (t==='storm3' && Math.random()<(FLOOD_RISK[S.prem]||.2)*2) || (t==='heavy' && rainy(m) && m>=8 && Math.random()<(FLOOD_RISK[S.prem]||.2))) flood(note, t==='storm2');
  if(t==='storm3' && Math.random()<.4){ const c=Math.round(rnd(3e6,8e6)/1e5)*1e5; S.cash-=c; S.stats.costs+=c; S.wx.dmg.push(['Bảng hiệu, mái hiên hư sau bão',c]); note.push(`bảng hiệu hư, sửa ${fmt(c)}`); }
  if(t==='outage' && S.prep.generator){ const c=300000; S.cash-=c; S.stats.costs+=c; S.wx.dmg.push(['Dầu chạy máy phát',c]); }
  if(t==='drought') setTimeout(droughtSheet,450);
  if(t==='storm2'){ S.time=OPEN_END; }
  setTimeout(()=>toast(`${WX[t][0]} Tháng ${m} · ${WX[t][1]}${note.length?': '+note.join(', '):''}`, ['sun','heat'].includes(t)?'':'warn'),250);
  renderTop();
})(startDay);

function flood(note, closeDay){
  const sand=S.prep.sandbag>=S.day; S.time=Math.max(S.time, closeDay?OPEN_END:OPEN_END*.5);
  const floor=SLOTS.filter(s=>S.owned[s.id] && (s.zone==='chan'||s.id.startsWith('room')||s.zone==='svc2'||['sofa','cashier','tea','towel'].includes(s.id)));
  if(!sand) floor.forEach(s=>{ const k=s.zone==='chan'?'chair':s.id.startsWith('room')?'room':s.st||s.id; addWear(s.id, Math.round((WEAR_D[k]||1000)*.08)); });
  const lossPct=sand?.1:.4; ['soak','towel','herb','mask'].forEach(k=>{ if(S.stock[k]) S.stock[k]=Math.round(S.stock[k]*(1-lossPct)); });
  const c=Math.round((sand?rnd(.5e6,1e6):rnd(2e6,5e6))/1e5)*1e5; S.cash-=c; S.stats.costs+=c; S.wx.dmg.push([sand?'Dọn dẹp sau ngập (đã kê bao cát)':'Dọn dẹp, sấy đồ sau ngập',c]);
  note.push(sand?`nước vào ít nhờ bao cát, dọn ${fmt(c)}`:`nước tràn vào tiệm, ghế giường mòn thêm 8%, hư ${Math.round(lossPct*100)}% thuốc ngâm và khăn, dọn ${fmt(c)}`);
  S.wx.flooded=S.day;
}
function droughtSheet(){ if(!$('#sheetBg').hidden){ S.noSoak=S.day; return; }
  const cost=S.prep.tank?700000:1500000;
  sheet(`<h2>🚱 Cắt nước luân phiên</h2><p>Hồ Dương Đông xuống thấp, khu này bị cắt nước hôm nay. Ngâm chân, tắm thảo dược, giặt khăn đều cần nước.</p>${S.prep.tank?'<p class="note">Có bồn chứa dự trữ nên chỉ cần mua ít nước.</p>':''}
    <div class="list"><button class="btn butter" data-w="buy">Mua nước xe bồn · ${fmt(cost)}</button><button class="btn alt" data-w="skip">Không ngâm chân hôm nay (khách massage chân kém hài lòng)</button></div>`, sh=>{
    sh.querySelector('[data-w="buy"]').onclick=()=>{ S.cash-=cost; S.stats.costs+=cost; S.wx.dmg.push(['Mua nước xe bồn',cost]); closeSheet(); renderTop(); };
    sh.querySelector('[data-w="skip"]').onclick=()=>{ S.noSoak=S.day; closeSheet(); };
  }); }
finishService=(orig=>function(g){ orig(g); const t=S.wx.today;
  if(t==='outage' && !S.prep.generator) g.sat=clamp(g.sat-8,0,100);
  if(S.noSoak===S.day && (g.want==='foot'||g.want==='herbal')) g.sat=clamp(g.sat-10,0,100);
  if(t==='heat' && !S.owned.tea) g.sat=clamp(g.sat-3,0,100); })(finishService);
// Mùa mưa: ẩm mốc làm đồ gỗ, nệm mau xuống cấp và khăn mau hư
addWear=(orig=>function(id,n){ if(rainy(monthOf()) && n===1 && Math.random()<.3) n=2; return orig(id,n); })(addWear);
{ const tu=SUP.towel.use; SUP.towel.use=k=>tu(k)*(rainy(monthOf())?1.5:1); }
// Giá nhập vật tư dịp Tết tăng
autoRestock=(orig=>function(){ const m=S.supMul||1; if(m===1) return orig(); const P={}; SUPK.forEach(k=>{ P[k]=SUP[k].price; SUP[k].price=Math.round(P[k]*m); }); try{ orig(); } finally{ SUPK.forEach(k=>SUP[k].price=P[k]); } })(autoRestock);

// ---------- cuối ngày: tiền điện nắng nóng, thiệt hại, dự báo ngày mai ----------
endDay=(orig=>function(){ const st=S.stats, t=S.wx.today;
  if(t==='heat'){ const kwh=Math.round(((prem()&&prem().kwh)||60)*.35+3*(ownedChairs().length+ownedBeds().length)*.35), c=kwh*ELEC; S.cash-=c; st.costs+=c; S.wx.dmg.push([`Máy lạnh chạy hết công suất (+${kwh} kWh)`,c]); }
  if(S.awayStaff&&S.awayStaff.length){ const c=S.awayStaff.reduce((a,s)=>a+Math.round(s.monthly/30),0); S.cash-=c; st.costs+=c; S.wx.dmg.push(['Lương cứng nhân viên nghỉ Tết (nghỉ có lương)',c]); }
  // hẹn trước bão 2 ngày
  const M=MONTHS[monthOf(S.day+2)]; if(!(S.wx.storm && S.day<=S.wx.storm+2) && M.storm && Math.random()<M.storm*1.5){ S.wx.storm=S.day+2; inboxMsg('Trung tâm khí tượng',`Áp thấp nhiệt đới mạnh lên thành bão, dự kiến ảnh hưởng Phú Quốc từ ngày ${S.day+2}. Tàu thuyền ngưng hoạt động, đề phòng ngập úng.`); }
  const nextK=rollWeather(S.day+1); S.wx.next={d:S.day+1,k:nextK};
  orig();
  const L=$('#sheet dl.ledger'), sum=L&&L.querySelector('dt.sum');
  if(sum && S.wx.dmg && S.wx.dmg.length) sum.insertAdjacentHTML('beforebegin',S.wx.dmg.map(([n,c])=>`<dt>${esc(n)}</dt><dd>−${fmt(c)}</dd>`).join(''));
  const row=$('#sheet .row'), mm=monthOf(S.day+1);
  if(row) row.insertAdjacentHTML('beforebegin',`<div class="note">Dự báo ngày ${S.day+1} (tháng ${mm}, ${MONTHS[mm].name}): <b>${WX[nextK][0]} ${WX[nextK][1]}</b>.${S.wx.storm&&S.wx.storm>S.day?` <b style="color:var(--danger)">Bão tới ngày ${S.wx.storm}.</b>`:''}${rainy(mm)&&!(S.prep.sandbag>=S.day)&&mm>=7?' Chưa có bao cát chống ngập (Sổ sách › Mùa & thời tiết).':''}</div>`);
  S.wx.dmg=[];
})(endDay);

// ---------- Tết: thưởng, nghỉ, nghỉ việc sau Tết ----------
function tetBonusSheet(){ if(!$('#sheetBg').hidden) return setTimeout(tetBonusSheet,1500);
  const base=S.staff.reduce((a,s)=>a+s.monthly,0)+(S.cashier?CASHIER.monthly:0);
  sheet(`<h2>🧧 Thưởng Tết cho nhân viên</h2><p>Còn 5 ngày tới Tết. Luật không bắt buộc thưởng Tết, nhưng hầu như tiệm nào cũng thưởng. Không thưởng thì sau Tết nhiều người không quay lại.</p>
    <div class="list"><button class="btn butter" data-b="1">Thưởng 1 tháng lương cứng · ${fmt(base)}</button><button class="btn alt" data-b=".5">Thưởng nửa tháng · ${fmt(base/2)}</button><button class="btn alt" data-b="0">Không thưởng</button></div>`, sh=>{
    sh.querySelectorAll('[data-b]').forEach(b=>b.onclick=()=>{ const k=+b.dataset.b, c=Math.round(base*k); S.cash-=c; if(c) addLog('Thưởng Tết nhân viên',-c); S.tetBonus=k; S.tetYear=Math.floor(S.day/YEAR_DAYS);
      S.staff.forEach(s=>s.morale=clamp(s.morale+(k===1?15:k?5:-20),0,100)); closeSheet(); renderTop(); save(); });
  }); }
function tetHolidaySheet(){ if(!$('#sheetBg').hidden) return setTimeout(tetHolidaySheet,1500);
  const pay=S.staff.reduce((a,s)=>a+Math.round(s.monthly/30*3*3),0), lx=S.staff.length*200000;
  sheet(`<h2>🎆 Tết Nguyên đán: nghỉ 3 ngày</h2><p>Nhân viên được nghỉ Tết mùng 1–3 có lương. Muốn họ đi làm thì phải trả lương ngày Tết ít nhất 300% (Bộ luật Lao động) và lì xì. Mùng 1–2 dân địa phương ở nhà, khách du lịch vẫn đông, tiệm được phụ thu Tết.</p>
    <div class="list"><button class="btn butter" data-t="work">Giữ cả tiệm làm Tết · ${fmt(pay+lx)} (lương gấp 3 + lì xì)</button><button class="btn alt" data-t="home">Cho nhân viên về quê, chủ tiệm tự trực</button></div>`, sh=>{
    sh.querySelector('[data-t="work"]').onclick=()=>{ S.cash-=pay+lx; addLog('Lương làm Tết + lì xì',-(pay+lx)); S.staff.forEach(s=>s.morale=clamp(s.morale+5,0,100)); closeSheet(); renderTop(); save(); };
    sh.querySelector('[data-t="home"]').onclick=()=>{ S.awayStaff=S.staff.splice(0); ensureWorkers(); closeSheet(); renderAll(); toast('Nhân viên về quê ăn Tết tới mùng 4.'); save(); };
  }); }
function afterTet(){
  if(S.awayStaff&&S.awayStaff.length){ S.staff.push(...S.awayStaff); S.awayStaff=[]; }
  const p=S.tetBonus===1?.1:S.tetBonus?.25:.5, gone=S.staff.filter(()=>Math.random()<p);
  if(gone.length){ S.staff=S.staff.filter(s=>!gone.includes(s)); setTimeout(()=>toast(`Sau Tết ${gone.map(s=>s.name).join(', ')} không quay lại làm.`,'warn'),800); }
  S.tetBonus=null; ensureWorkers(); renderAll(); save();
}

// ---------- HUD: tháng và thời tiết ----------
renderTop=(orig=>function(){ orig(); const el=$('#sub'); if(el && S.prem && S.stage!=='story' && S.stage!=='prem'){ const w=S.wx.today&&WX[S.wx.today]; el.textContent=el.textContent.replace(/^Ngày (\d+)/,`Ngày $1 · Th${monthOf()}${w?' '+w[0]:''}`); } })(renderTop);

// ---------- Sổ sách: Mùa & thời tiết ----------
function seasonCard(){ const m=monthOf(), M=MONTHS[m], p=prem();
  const cal=[...Array(12)].map((_,i)=>{ const k=i+1, x=MONTHS[k]; const lv=p?(p.mix[0]+p.mix[1]*x.d+p.mix[2]*x.f):1; return `<div class="mcell${k===m?' now':''}${rainy(k)?' rainy':''}" title="${x.name}"><b>T${k}</b><i style="height:${Math.round(lv*40)}px"></i></div>`; }).join('');
  return `<div class="card"><div class="sec-t">Mùa & thời tiết <span class="note">tháng ${m} · ${M.name}</span></div>
    <div class="mcal">${cal}</div><p class="note">Cột cao là tháng đông khách. Xanh là mùa mưa, đồ mau hỏng.</p>
    <div class="list" style="margin-top:6px">
      <div class="item">${(window.uiIco&&uiIco('baocat','prep-ico'))||''}<div class="grow"><div class="n">Bao cát, kê cao đồ chống ngập</div><div class="m">Dùng hết mùa mưa. Ngập thì đồ ít hư hơn.</div></div>${S.prep.sandbag>=S.day?'<span class="tag">Đã chuẩn bị</span>':`<button class="btn sm butter" data-prep="sand" ${S.cash>=1.5e6?'':'disabled'}>1,5tr</button>`}</div>
      <div class="item">${(window.uiIco&&uiIco('mayphatdien','prep-ico'))||''}<div class="grow"><div class="n">Máy phát điện</div><div class="m">Cúp điện vẫn mở cửa được. Mỗi lần tốn 300k dầu.</div></div>${S.prep.generator?'<span class="tag">Đã có</span>':`<button class="btn sm butter" data-prep="gen" ${S.cash>=8e6?'':'disabled'}>8tr</button>`}</div>
      <div class="item">${(window.uiIco&&uiIco('bonnuoc','prep-ico'))||''}<div class="grow"><div class="n">Bồn nước dự trữ</div><div class="m">Ngày cắt nước đỡ tốn tiền: 700k thay vì 1,5tr.</div></div>${S.prep.tank?'<span class="tag">Đã có</span>':`<button class="btn sm butter" data-prep="tank" ${S.cash>=4e6?'':'disabled'}>4tr</button>`}</div></div>
    <p class="note">10 ngày trong game là 1 tháng. Tết mùng 1–3 tháng 2: nhớ thưởng Tết cho KTV.</p></div>`; }
renderScreen=(orig=>function(){ orig(); if(tab!=='book') return; const D=$('#dyn'), c=D&&(D.querySelector('.debt-card')||D.querySelector('.card')); if(c) c.insertAdjacentHTML('afterend',seasonCard()); })(renderScreen);
$('#dyn').addEventListener('click',e=>{ const b=e.target.closest('[data-prep]'); if(!b||b.disabled) return; const k=b.dataset.prep;
  if(k==='sand'){ S.cash-=1.5e6; let d=S.day, n=0; while(!(rainy(monthOf(d))&&!rainy(monthOf(d+MONTH_DAYS))) && n<14){ d+=MONTH_DAYS; n++; } S.prep.sandbag=d+(MONTH_DAYS-dayOfMonth(d)); addLog('Bao cát chống ngập',-1.5e6); }
  if(k==='gen'){ S.cash-=8e6; S.prep.generator=true; addLog('Mua máy phát điện',-8e6); }
  if(k==='tank'){ S.cash-=4e6; S.prep.tank=true; addLog('Bồn nước dự trữ',-4e6); }
  save(); renderAll(); });

// Sự kiện ngẫu nhiên cũ "mưa bão" và "cao điểm" nay do lịch mùa đảm nhận
delete EVENTS.rain; delete EVENTS.peak;

// Chọn độ khó xong thì đặt tháng bắt đầu
bank=(orig=>function(){ S.startMonth=(DIFFS[S.diff]||DIFFS.vua).start||8; orig(); })(bank);

// 15n-credit.js — v2.7: Vay thêm khi kẹt tiền
// 1) Ngân hàng vay bổ sung: rẻ nhất nhưng phải có lịch sử trả đúng hạn, chờ thẩm định 3 ngày, gộp vào khoản vay chính (kỳ hạn mới 36 tháng, lãi +1%).
// 2) Công ty tài chính: giải ngân ngay, lãi ~38%/năm (ước tính trong khoảng 23%/năm tới hơn 5%/tháng các công ty công bố), 12 tháng,
//    trễ hạn thì gọi người thân và ghi CIC.
// 3) Vay nóng (tín dụng đen): nhận ngay 90%, góp ngày 36 ngày ≈ 400%/năm. Lãi trên 100%/năm là tội cho vay lãi nặng (Điều 201 BLHS),
//    phần lãi trên 20%/năm vô hiệu (Điều 468 BLDS). Trễ góp thì bị làm phiền, ngồi trước tiệm, tạt sơn. Có thể trình báo công an.
'use strict';
S.credit=Object.assign({topup:null, cf:null, ls:null}, S.credit||{});
if(S.loan&&S.loan.terms) Object.assign(LOAN,S.loan.terms);
const CF={rate:.38, months:12, amounts:[20e6,50e6]};
const LS={cut:.1, days:36, total:1.2, amounts:[20e6,50e6]};
// 20h: vay nóng SAU KHI BỊ NGÂN HÀNG SIẾT NỢ: khoản nhỏ 10-20tr, lãi 3%/ngày TÍNH VÀO GỐC, cứ 3 ngày trả ~35% dư nợ. Trả đúng hạn thì giảm lãi (chip "Trả đúng hạn").
// Trễ: nhắc mỗi ngày (+0/+1/+2): 1 = tạt sơn, 2 = tạt sơn + mất sao, 3 = tạt sơn + đòi nợ ngồi trước tiệm; qua nhắc 3 thêm 1 ngày chưa trả đủ → phá sản. Đề xuất vay nóng tự đến: ngày đầu sau siết, rồi mỗi 2 ngày nếu chưa vay.
const LSD={rate:.03, minRate:.018, cut:.003, per:3, pct:.35, nhacMax:3, amounts:[10e6,20e6], cicAmounts:[10e6,20e6,30e6], pctOpen:.12};
// 20s: ván CIC xấu (S.cicRun): vay nóng đòi dồn NGAY TỪ NGÀY 1 (10/20/30tr), để người chơi luôn có đường mua bộ đồ tối thiểu. Từ chối thì mời lại mỗi 2 ngày như 20h.
const dunOn=()=>!!((S.loan&&S.loan.siet)||S.cicRun), dunAmts=()=>S.cicRun?LSD.cicAmounts:LSD.amounts;
const cfPay=c=>{ const r=CF.rate/12; return Math.round(c.amt*r/(1-Math.pow(1+r,-CF.months))); };

function topupOk(){ const L=S.loan; if(S.cicRun) return [false,'Hồ sơ CIC xấu: ván này không có ngân hàng hỗ trợ']; if(L.lock) return [false,'Bị khóa vay ngân hàng (đã trả trễ)']; if(S.credit.topup) return [false,'Đang thẩm định']; if(L.od>0) return [false,'Đang có nợ quá hạn'];
  if(L.cicUntil>S.day) return [false,'CIC còn ghi nợ nhóm 2']; if(L.paidOnTime<3) return [false,`Cần góp đúng hạn 3 kỳ (đã ${L.paidOnTime})`];
  if(S.credit.cf&&S.credit.cf.od>0) return [false,'Đang nợ quá hạn công ty tài chính']; return [true,'']; }
const topupMax=()=>Math.round(LOAN.amount*.5/1e7)*1e7;
function askTopup(a){ const [ok]=topupOk(); if(!ok) return; S.credit.topup={amt:a, day:S.day+3}; save(); toast(`Đã nộp hồ sơ vay bổ sung ${fmt(a)}. Ngân hàng thẩm định 3 ngày.`); setTimeout(cicWarn,800); renderAll(); }
function takeCF(a){ if(S.credit.cf) return; S.credit.cf={amt:a, debt:a, due:S.day+30, od:0, odDays:0, left:CF.months}; S.cash+=a; addLog('Vay công ty tài chính',a); save(); toast(`Công ty tài chính giải ngân ${fmt(a)} ngay. Góp ${fmt(cfPay(S.credit.cf))}/tháng trong 12 tháng.`,'warn'); renderAll(); }
function takeLS(a){ if(S.credit.ls) return; const dun=dunOn();
  if(dun){ S.credit.ls={amt:a, left:a, bal:a, rate:LSD.rate, dun:true, pct:(S.cicRun&&S.day<=1)?LSD.pctOpen:LSD.pct, dueDay:S.day+LSD.per, od:0, nhac:0, missed:0, streak:0, ontime:0, since:0}; S.cash+=a; addLog('Vay nóng (đòi dồn)',a); save();
    toast(`Nhận ${fmt(a)}. Lãi ${Math.round(LSD.rate*1000)/10}%/ngày tính vào gốc, cứ ${LSD.per} ngày trả khoảng ${Math.round(S.credit.ls.pct*100)}% dư nợ. Trả đúng hạn thì được giảm lãi.`,'warn'); renderAll(); return; }
  const got=Math.round(a*(1-LS.cut)), daily=Math.round(a*LS.total/LS.days/1000)*1000;
  S.credit.ls={amt:a, left:daily*LS.days, daily, missed:0, streak:0, reported:false}; S.cash+=got; addLog('Vay nóng (nhận sau khi cắt phí)',got); save();
  toast(`Nhận ${fmt(got)} (đã bị cắt ${fmt(a-got)} "phí"). Góp ${fmt(daily)} mỗi ngày trong ${LS.days} ngày.`,'warn'); renderAll(); }
const lsDue=ls=>ls.bal<=1.5e6?ls.bal:Math.round(ls.bal*(ls.pct||LSD.pct)/1000)*1000;
const OFFER_TXT=['Chị ơi, nghe nói ngân hàng vừa siết tiệm chị. Em cho vay nóng không thế chấp, có tiền ngay, khoản nhỏ 10-20tr. Vào Sổ sách › Vay thêm.','Chị còn cần tiền xoay không? Em vẫn cho vay 10-20tr, lãi 3%/ngày, cứ 3 ngày trả một ít. Trả đúng hạn em còn bớt lãi cho. (Trễ là có người tới nói chuyện.)'];

// 20s: ngày 1 (trước khai trương) của ván CIC xấu: tin nhắn + ảnh chủ nợ, chọn 10/20/30tr
const OFFER_CIC='Chị ơi, nghe nói hồ sơ chị dính CIC, ngân hàng không cho vay. Em cho vay nóng không thế chấp, 10-30tr, có tiền ngay để chị sắm đồ khai trương. Lãi 3%/ngày tính vào gốc, cứ 3 ngày trả khoảng 12% dư nợ; trả đúng hạn em bớt lãi. Trễ là có người tới nói chuyện. Vào Sổ sách › Vay thêm cũng được.';
function cicOffer(){ if(!S.cicRun||S.credit.ls||S.cicOffered) return; S.cicOffered=true; inboxMsg('Số lạ',OFFER_CIC,'nv-donno-1'); if(typeof sfx==='function') sfx('ring'); save();
  sheet(`<h2>Số lạ gọi tới</h2><div class="scene-s"><img src="img/3347b4f37586.webp" alt="" style="max-height:200px;display:block;margin:0 auto" onerror="this.remove()"><p>${OFFER_CIC}</p></div>
    <div class="row" style="flex-direction:column;gap:6px">${LSD.cicAmounts.map(a=>`<button class="btn big alt" data-ls="${a}">Vay nóng ${fmt(a)}</button>`).join('')}<button class="btn" data-ls="0">Để sau</button></div>`, sh=>{
    sh.querySelectorAll('[data-ls]').forEach(b=>b.onclick=()=>{ const a=+b.dataset.ls; closeSheet(); if(a) takeLS(a); }); }); }
window.cicOffer=cicOffer;

// ---------- mỗi sáng ----------
startDay=(orig=>function(){ orig(); if(S.bankrupt) return; const C=S.credit;
  if(C.ls&&C.ls.dun&&C.ls.bal===undefined){ const o=C.ls; Object.assign(o,{bal:o.left,rate:LSD.rate,ontime:0,since:0,od:o.od||0}); }   // save 20g cũ
  if(C.topup && S.day>=C.topup.day){ const a=C.topup.amt; C.topup=null; S.debt+=a; S.cash+=a;
    S.loan.terms={amount:Math.round(S.debt), months:36, yearRate:Math.round((LOAN.yearRate+.01)*10000)/10000}; Object.assign(LOAN,S.loan.terms);
    addLog('Giải ngân vay bổ sung',a); inboxMsg('Ngân hàng',`Khoản vay bổ sung ${fmt(a)} đã giải ngân. Dư nợ gộp ${fmt(S.debt)}, kỳ hạn mới 36 tháng, lãi ${pctRate()}, góp ${fmt(periodPay())} mỗi kỳ 10 ngày.`); }
  const dBase=S.loan.siet?S.loan.sietDay:1;
  if(dunOn() && !C.ls && S.day>dBase && (S.day-dBase)%2===1){ const k=((S.day-dBase-1)/2)%2; inboxMsg('Số lạ',OFFER_TXT[k],k?'nv-donno-2':'nv-donno-1'); if(typeof sfx==='function') sfx('ring'); }
  const ls=C.ls;
  if(ls && !ls.reported && !ls.dun){
    if(ls.streak>=2 && ls.streak<5) setTimeout(()=>toast('Hai thanh niên đeo kính đen ngồi lì trước cửa tiệm "chờ chủ". Khách thấy là đi thẳng.','warn'),700);
    if(ls.streak===5){ S.time=OPEN_END*.5; const c=5e6; S.cash-=c; S.stats.costs+=c; S.staff.forEach(s=>s.morale=clamp(s.morale-15,0,100)); setTimeout(()=>{ if(window.AUDIO) AUDIO.sfx('sfx-tat-son',.9); toast(`Đêm qua tiệm bị tạt sơn. Nửa ngày đóng cửa dọn dẹp, sơn lại ${fmt(c)}.`,'warn'); },700); }
    if(ls.streak>=7 && S.staff.length && Math.random()<.3){ const s=pick(S.staff); S.staff=S.staff.filter(x=>x!==s); ensureWorkers(); setTimeout(()=>toast(`${s.name} sợ quá, xin nghỉ việc.`,'warn'),900); }
  }
})(startDay);
hourCurve=(orig=>function(){ const ls=S.credit&&S.credit.ls; return orig()*(ls&&!ls.reported&&ls.streak>=2?.5:1)*(S.credit&&S.credit.cf&&S.credit.cf.odDays>=30?.95:1); })(hourCurve);

const LS_NHAC=[null,'Chị chậm rồi đó. Tối nay tụi em ghé tiệm chơi nhé. (Nhắc 1/3)','Em nói lần cuối trong ngày: trả ngay, đừng để khách chạy hết. (Nhắc 2/3)','Mai hết hạn. Không có tiền thì chị biết chuyện gì xảy ra rồi đấy. (Nhắc 3/3, CẢNH BÁO CUỐI)'];
function lsNhac(ls,notes){ ls.nhac++; inboxMsg('Số lạ',LS_NHAC[ls.nhac]+` Còn nợ quá hạn ${fmt(ls.od)}.`,ls.nhac%2?'nv-donno-1':'nv-donno-2'); if(typeof sfx==='function') sfx('ring');
  if(window.addDebuff){ addDebuff('tatson',S.day+1,true); if(ls.nhac===2) addDebuff('matsao',S.day+1); if(ls.nhac>=3) addDebuff('doino',S.day+1); }
  const ex=ls.nhac===1?'Tiệm bị tạt sơn, khách giảm.':ls.nhac===2?'Tạt sơn và mất sao đánh giá.':'Tạt sơn, đòi nợ ngồi chình ình trước tiệm, khách chạy mạnh.';
  notes.push(`<span style="color:var(--danger)"><b>Vay nóng nhắc ${ls.nhac}/3.</b> ${ex}${ls.nhac>=LSD.nhacMax?' <b>Ngày mai chưa trả đủ là bị xử lý.</b>':''}</span>`); }

// ---------- cuối ngày: góp công ty tài chính, góp ngày vay nóng ----------
endDay=(orig=>function(){ orig(); if(S.bankrupt) return; const C=S.credit, notes=[];
  const cf=C.cf;
  if(cf){
    if(cf.od>0){ cf.odDays++; cf.od+=Math.round(cf.od*CF.rate*1.5/360);
      if(cf.odDays===10){ S.loan.cicUntil=Math.max(S.loan.cicUntil,S.day+360); inboxMsg('Công ty tài chính',`Khoản vay quá hạn 10 ngày, đã báo cáo CIC. Số tiền quá hạn ${fmt(cf.od)}.`); }
      if(cf.odDays===20) inboxMsg('Công ty tài chính','Chúng tôi sẽ liên hệ người thân trong hồ sơ của Quý khách để nhắc nợ.');
      if(cf.odDays>=20){ S.staff.forEach(s=>s.morale=clamp(s.morale-1,0,100)); }
      if(cf.odDays>=60 && S.cash>0){ const t=Math.min(S.cash,cf.od+cf.debt); S.cash-=t; const a=Math.min(t,cf.od); cf.od-=a; cf.debt=Math.max(0,cf.debt-(t-a)); notes.push(`Công ty tài chính khởi kiện, toà cho thi hành án: bị trừ ${fmt(t)}.`); }
      notes.push(`<span style="color:var(--danger)">Nợ quá hạn công ty tài chính ${fmt(cf.od)} · ${cf.odDays} ngày.</span>`); }
    if(S.day>=cf.due){ const it=Math.round(cf.debt*CF.rate/12), p=Math.min(cfPay(cf), cf.debt+it), got=Math.min(Math.max(0,S.cash),p); S.cash-=got; cf.debt=Math.max(0,cf.debt-(p-it)); cf.due+=30; cf.left--;
      if(got<p){ cf.od+=p-got; if(!cf.odDays) cf.odDays=1; notes.push(`<span style="color:var(--danger)">Không đủ góp công ty tài chính: thiếu ${fmt(p-got)}.</span>`); } else notes.push(`Đã góp công ty tài chính ${fmt(p)}.`); }
    if(cf.debt<=1000 && cf.od<=1000){ C.cf=null; notes.push('Đã trả xong khoản vay công ty tài chính.'); }
  }
  const ls=C.ls;
  if(ls){
    if(ls.dun){
      const i0=ls.bal; ls.bal=Math.round(ls.bal*(1+ls.rate)); ls.since=(ls.since||0)+(ls.bal-i0); if(ls.od>0&&ls.od>ls.bal) ls.od=ls.bal;
      if(ls.od>0){
        if(S.cash>=ls.od){ S.cash-=ls.od; ls.bal-=ls.od; addLog('Trả vay nóng quá hạn',-ls.od); notes.push(`Đã trả vay nóng quá hạn ${fmt(ls.od)}.`); ls.od=0; ls.nhac=0; ls.since=0; ls.dueDay=S.day+LSD.per; }
        else if(ls.nhac>=LSD.nhacMax){ bankrupt('Bị xã hội đen xử lý nợ'); return; }
        else lsNhac(ls,notes);
      } else if(S.day>=ls.dueDay){
        const per=lsDue(ls);
        if(S.cash>=per){ S.cash-=per; ls.bal-=per; ls.ontime++; ls.rate=Math.max(LSD.minRate,Math.round((ls.rate-LSD.cut)*10000)/10000); ls.since=0; ls.dueDay+=LSD.per; addLog('Góp vay nóng đúng hạn',-per);
          notes.push(`Góp vay nóng đúng hạn ${fmt(per)} (còn ${fmt(ls.bal)}). Lãi giảm còn ${Math.round(ls.rate*1000)/10}%/ngày. Kỳ sau ngày ${ls.dueDay}.`); }
        else { ls.od=per; ls.nhac=0; ls.missed++; ls.rate=LSD.rate; notes.push(`<span style="color:var(--danger)"><b>Không đủ góp vay nóng ${fmt(per)}!</b> Hôm nay là nhắc đầu tiên.</span>`); lsNhac(ls,notes); }
      }
      ls.left=ls.bal; if(ls.bal<=1000){ C.ls=null; notes.push('<b>Đã trả hết vay nóng, sạch nợ!</b> Chủ nợ nói "chị sòng phẳng, cần thì cứ gọi".'); inboxMsg('Số lạ','Chị trả sòng phẳng, em quý. Lần sau cần cứ gọi em.','nv-donno-2'); }
    }
    else if(ls.reported){ /* đã trình báo: chỉ còn gốc, trả khi có tiền */ }
    else if(S.cash>=ls.daily){ S.cash-=ls.daily; ls.left-=ls.daily; ls.streak=0; notes.push(`Góp vay nóng ${fmt(ls.daily)} (còn ${fmt(ls.left)}).`); }
    else { ls.missed++; ls.streak++; ls.left+=500000; notes.push(`<span style="color:var(--danger)">Không đủ góp vay nóng hôm nay, bị "phạt" 500k. Trễ ${ls.streak} ngày liền.</span>${ls.streak===1?' Mai họ sẽ tới tiệm.':''}`); }
    if(ls.left<=0){ C.ls=null; notes.push('Đã trả xong vay nóng.'); }
  }
  save(); const row=$('#sheet .row'); if(row && notes.length) row.insertAdjacentHTML('beforebegin',`<div class="card debt-note">${notes.map(n=>`<div class="note">${n}</div>`).join('')}</div>`);
})(endDay);

function reportPolice(){ const ls=S.credit.ls; if(!ls) return; ls.reported=true; ls.streak=0;
  const principalLeft=Math.max(0,Math.round(ls.amt*(ls.left/(ls.daily*LS.days))));
  ls.left=principalLeft; S.time=Math.min(DAY,S.time+DAY*.1);
  toast('Đã trình báo công an. Nhóm cho vay bị triệu tập, ngừng làm phiền. Phần lãi vượt luật bị vô hiệu, chỉ còn nợ gốc.','good'); save(); renderAll(); }

// ---------- Sổ sách: Vay thêm ----------
function creditCard(){ const C=S.credit, [ok,why]=topupOk(), mx=topupMax();
  const cf=C.cf, ls=C.ls;
  return `<div class="card credit-card"><div class="sec-t">Vay thêm</div><p class="note">Kẹt tiền góp, lương, tiền thuê thì có 3 chỗ vay. Càng nhanh càng đắt.</p>
   <div class="list" style="margin-top:6px">
    <div class="item" style="align-items:flex-start"><div class="grow"><div class="n">🏦 Ngân hàng vay bổ sung</div><div class="m">Lãi ${String(Math.round((LOAN.yearRate+.01)*1000)/10).replace('.',',')}%/năm, gộp vào khoản vay chính. Chờ duyệt 3 ngày. Cần góp đúng hạn 3 kỳ.</div>
      ${C.topup?`<div class="m"><b>Đang thẩm định ${fmt(C.topup.amt)}, giải ngân ngày ${C.topup.day}.</b></div>`:!ok?`<div class="m" style="color:var(--danger)">${why}</div>`:''}</div>
      ${ok&&mx>0?`<div class="row" style="flex-direction:column;gap:4px"><button class="btn sm butter" data-cr="tu:${Math.round(mx/2/1e7)*1e7||1e7}">${fmt(Math.round(mx/2/1e7)*1e7||1e7)}</button><button class="btn sm butter" data-cr="tu:${mx}">${fmt(mx)}</button></div>`:''}</div>
    <div class="item" style="align-items:flex-start"><div class="grow"><div class="n">🏢 Công ty tài chính</div><div class="m">Có tiền ngay, lãi ${Math.round(CF.rate*100)}%/năm, góp 12 tháng. Trễ thì bị ghi CIC, gọi người thân, rồi kiện.</div>
      ${cf?`<div class="m"><b>Đang nợ ${fmt(cf.debt)}${cf.od?` · quá hạn ${fmt(cf.od)}`:''} · góp ${fmt(cfPay(cf))} ngày ${cf.due}</b></div>`:''}</div>
      ${cf?(cf.od>0?`<button class="btn sm butter" data-cr="cfod" ${S.cash>=cf.od?'':'disabled'}>Trả quá hạn</button>`:''):`<div class="row" style="flex-direction:column;gap:4px">${CF.amounts.map(a=>`<button class="btn sm alt" data-cr="cf:${a}">${fmt(a)}</button>`).join('')}</div>`}</div>
    <div class="item" style="align-items:flex-start"><div class="grow"><div class="n">⚠️ Vay nóng góp ngày</div><div class="m">Vay nhanh không thế chấp. Nhận 90% số vay, góp mỗi ngày trong 36 ngày. Lãi rất cao.${dunOn()?' <b style="color:var(--danger)">Khoản nhỏ 10-'+(S.cicRun?30:20)+'tr, lãi cộng mỗi ngày, trả mỗi 3 ngày. Trễ là bị tạt sơn, mất sao, đòi nợ trước tiệm, rồi mất tiệm.</b>':''}</div>
      <div class="m" style="color:var(--danger)">Lãi quá cao là phạm luật. Có thể trình báo công an.</div>
      ${ls?`<div class="m"><b>Còn phải góp ${fmt(ls.left)}${ls.dun?` · lãi ${Math.round(ls.rate*1000)/10}%/ngày · kỳ tới ngày ${ls.dueDay}: ${fmt(lsDue(ls))}${ls.ontime?` · đúng hạn ×${ls.ontime}`:''}${ls.od>0?` · QUÁ HẠN ${fmt(ls.od)}, nhắc ${ls.nhac}/3`:''}`:ls.reported?' (đã trình báo, chỉ còn gốc)':` · ${fmt(ls.daily)}/ngày · trễ ${ls.streak} ngày`}</b></div>`:''}</div>
      ${ls?`<div class="row" style="flex-direction:column;gap:4px">${ls.dun&&ls.od<=0?`<button class="btn sm mint" data-cr="lsearly" ${S.cash>=lsDue(ls)?'':'disabled'}>Góp trước kỳ · ${fmt(lsDue(ls))}</button>`:''}<button class="btn sm alt" data-cr="lspay" ${S.cash>=(ls.dun&&ls.od<=0?ls.bal-(ls.since||0):ls.left)?'':'disabled'}>Trả hết${ls.dun&&ls.od<=0&&ls.since?` · giảm ${fmt(ls.since)} lãi`:''}</button>${!ls.reported&&!ls.dun&&ls.missed?'<button class="btn sm mint" data-cr="police">Trình báo công an</button>':''}</div>`:`<div class="row" style="flex-direction:column;gap:4px">${(dunOn()?dunAmts():LS.amounts).map(a=>`<button class="btn sm alt" data-cr="ls:${a}">${fmt(a)}</button>`).join('')}</div>`}</div>
   </div></div>`; }
renderScreen=(orig=>function(){ orig(); if(tab!=='book') return; const D=$('#dyn'), c=D&&(D.querySelector('.debt-card')||D.querySelector('.card')); if(c) c.insertAdjacentHTML('afterend',creditCard()); })(renderScreen);
$('#dyn').addEventListener('click',e=>{ const b=e.target.closest('[data-cr]'); if(!b||b.disabled) return; const [k,v]=b.dataset.cr.split(':');
  if(k==='tu') askTopup(+v); if(k==='cf') takeCF(+v); if(k==='ls') takeLS(+v); if(k==='police') reportPolice();
  if(k==='cfod'){ const cf=S.credit.cf; const a=Math.min(S.cash,cf.od); S.cash-=a; cf.od-=a; if(cf.od<=1000){ cf.od=0; cf.odDays=0; } addLog('Trả quá hạn công ty tài chính',-a); save(); renderAll(); }
  if(k==='lspay'){ const ls=S.credit.ls, a=ls.dun&&ls.od<=0?ls.bal-(ls.since||0):ls.left; if(S.cash<a) return; S.cash-=a; addLog('Trả hết vay nóng',-a); S.credit.ls=null; if(ls.dun) toast(`Tất toán sớm, được miễn ${fmt(ls.since||0)} lãi kỳ này.`,'good'); save(); renderAll(); }
  if(k==='lsearly'){ const ls=S.credit.ls, a=ls&&lsDue(ls); if(!ls||!ls.dun||ls.od>0||S.cash<a) return; S.cash-=a; ls.bal-=a; ls.ontime++; ls.rate=Math.max(LSD.minRate,Math.round((ls.rate-LSD.cut)*10000)/10000); ls.since=0; ls.dueDay=S.day+LSD.per; ls.left=ls.bal; addLog('Góp vay nóng trước kỳ',-a); toast(`Góp trước kỳ ${fmt(a)}. Lãi giảm còn ${Math.round(ls.rate*1000)/10}%/ngày.`,'good'); if(ls.bal<=1000) S.credit.ls=null; save(); renderAll(); } });

// Resort: phải sạch mọi khoản nợ
resortChecks=(orig=>function(){ const C=S.credit; return orig().concat([{t:'Không còn nợ công ty tài chính hay vay nóng', ok:!C.cf&&!C.ls}]); })(resortChecks);

// 15o-fx.js — v2.8: hiệu ứng chuyển động (không cần hình mới)
// Bảng tiệm vẽ lại mỗi 0,4 giây, nên mọi hiệu ứng lặp dùng animation-delay âm theo đồng hồ chung để không bị giật về đầu.
// Tiền bay, thời tiết, pháo hoa gắn vào #phone (không nằm trong bảng) nên chạy liền mạch.
'use strict';
const FX={reduce:matchMedia('(prefers-reduced-motion: reduce)').matches};
const phase=ms=>`-${(performance.now()%ms)/1000}s`;
const fxRoot=()=>$('#phone')||document.body;

// ---------- 1. Bảng tiệm: ghế đang làm rung nhịp, hơi nước, nến, đồ hỏng bốc khói ----------
function decorateBoard(){
  const B=$('#board'); if(!B||FX.reduce) return;
  B.querySelectorAll('.tray.busy').forEach(t=>{ const id=t.dataset.slot||''; const img=t.querySelector('.art');
    if(img){ img.classList.add('fx-rub'); img.style.animationDelay=phase(900); }
    if(/^chair|^herbal|^sauna/.test(id)){ t.insertAdjacentHTML('beforeend',`<span class="fx-steam" style="--d:${phase(2400)}"><i></i><i></i><i></i></span>`); }
    if(/^room|^facial/.test(id)){ t.insertAdjacentHTML('beforeend',`<span class="fx-glow" style="--d:${phase(1800)}"></span>`); }
    if(/^nail/.test(id)){ t.insertAdjacentHTML('beforeend',`<span class="fx-spark" style="--d:${phase(1600)}"><i></i><i></i></span>`); } });
  B.querySelectorAll('.tray.broken').forEach(t=>{ t.style.setProperty('--d',phase(3000)); t.insertAdjacentHTML('beforeend',`<span class="fx-smoke" style="--d:${phase(2600)}"><i></i><i></i></span>`); });
  const sofa=B.querySelector('.tray[data-slot="sofa"] .art'); if(sofa && B.querySelector('.tray[data-slot="sofa"] .bd') && +B.querySelector('.tray[data-slot="sofa"] .bd').textContent>0){ sofa.classList.add('fx-wait'); sofa.style.animationDelay=phase(1400); }
  const sign=B.querySelector('.open.on'); if(sign) sign.style.animationDelay=phase(2000);
  const pt=B.querySelector('.counterv .pt'); if(pt && B.querySelector('.counterv .bub:not(.idle)')){ pt.classList.add('fx-talk'); pt.style.animationDelay=phase(600); }
  // vay nóng: người ngồi trước cửa, vệt sơn
  const ls=S.credit&&S.credit.ls, front=B.querySelector('.front');
  if(front && ls && !ls.reported && ls.streak>=2) front.insertAdjacentHTML('beforeend',`<div class="fx-thugs" title="Người của chủ nợ ngồi trước cửa">${window.uiIco&&UI_ICON['ic-kinhram']?uiIco('ic-kinhram')+uiIco('ic-thuoc')+uiIco('ic-kinhram'):'🕶️🚬🕶️'}</div>`);
  if(front && ls && !ls.reported && ls.streak>=5) front.insertAdjacentHTML('beforeend','<div class="fx-paint"></div>');
}
renderBoard=(orig=>function(){ orig(); if(tab==='shop') decorateBoard(); })(renderBoard);

// ---------- 2. Tiền bay: khách trả tiền, tip, chi tiền ----------
function flyMoney(fromEl, txt, kind){
  if(FX.reduce) return; const root=fxRoot(), to=$('#cash'); if(!root||!to) return;
  const R=root.getBoundingClientRect(), a=(fromEl||to).getBoundingClientRect(), b=to.getBoundingClientRect();
  const el=document.createElement('div'); el.className='fx-coin '+(kind||''); el.innerHTML=`<i>${(window.uiIco&&uiIco(kind==='minus'?'tien-ra':'xu'))||(kind==='minus'?'💸':'🪙')}</i><b>${esc(txt)}</b>`; root.appendChild(el);
  let x0=a.left+a.width/2-R.left, y0=a.top+a.height/2-R.top; const x1=b.left+b.width/2-R.left, y1=b.top+b.height/2-R.top;
  if(window.LZ&&LZ.free&&kind!=='minus'){ const p=LZ.free(x0+R.left,y0+R.top); x0=p[0]-R.left; y0=p[1]-R.top; } // M-g b3 (I.6): diem dau trong khe ban -> doi ra mep
  const frames = kind==='minus'
    ? [{transform:`translate(${x1}px,${y1}px) scale(1)`,opacity:1},{transform:`translate(${x1-20}px,${y1+50}px) scale(.9)`,opacity:0}]
    : [{transform:`translate(${x0}px,${y0}px) scale(.6)`,opacity:0},{transform:`translate(${x0}px,${y0-26}px) scale(1.1)`,opacity:1,offset:.25},{transform:`translate(${x1}px,${y1}px) scale(.5)`,opacity:.2}];
  el.animate(frames,{duration:kind==='minus'?1100:900,easing:'cubic-bezier(.4,0,.2,1)'}).onfinish=()=>{ el.remove(); if(kind!=='minus') bumpCash(); };
}
function bumpCash(){ const c=$('#cash'); if(!c||FX.reduce) return; c.classList.remove('fx-bump'); void c.offsetWidth; c.classList.add('fx-bump'); }
let coinBudget=0; setInterval(()=>coinBudget=0,1000);
pay=(orig=>function(g){ const before=S.cash, hadProblem=!!g.problem; orig(g); if(hadProblem||tab!=='shop'||!$('#sheetBg').hidden) return;
  const gain=S.cash-before; if(gain<=0 || ++coinBudget>3) return;
  const from=$('#board .tray[data-slot="cashier"]')||$('#board .counterv .pt');
  flyMoney(from,'+'+fmt(gain),'plus');
  if(g.tip && !g.byStaff) setTimeout(()=>flyMoney(from,'tip +'+fmt(g.tip),'tip'),260); })(pay);
window.onAddLog=(t,a)=>{ if(a<=-100000 && !/^Ngày \d/.test(t) && !/^Tháng/.test(t)) setTimeout(()=>flyMoney(null,fmt(a),'minus'),50); };

// ---------- 3. Thời tiết phủ màn hình ----------
let wxEl=null, wxKey='';
function updateWeather(){
  if(!wxEl){ wxEl=document.createElement('div'); wxEl.className='fx-wx'; wxEl.setAttribute('aria-hidden','true'); fxRoot().appendChild(wxEl); }
  const t=S.wx&&S.wx.today, show=tab==='shop' && S.prem && (S.stage==='open'||S.stage==='closed') && !FX.reduce;
  const tet=typeof isTet==='function' && isTet(), flood=S.wx && S.wx.flooded===S.day, paint=false;
  const key=show? [t,tet,flood].join('|') : '';
  if(key===wxKey) return; wxKey=key;
  wxEl.className='fx-wx'+(show&&t?` wx-${t}`:'')+(show&&tet?' wx-tet':'')+(show&&flood?' wx-flood':'');
  wxEl.innerHTML=!show?'':
    (['heavy','storm1','storm2'].includes(t)?'<div class="bolt"></div>':'')+

    (t==='heat'?'<div class="haze"></div><div class="sun">☀️</div>':'')+
    (t==='drought'?'<div class="cracks"></div>':'')+
    (tet?[0,1,2,3].map(i=>`<div class="fw fw${i}"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div>`).join('')+(()=>{ const L=window.HAND_ART&&HAND_ART['do-denlong-troi'], i=L?`<img src="${L.file}" alt="">`:'🏮'; return `<div class="lantern l1">${i}</div><div class="lantern l2">${i}</div>`; })():'');
}
renderTop=(orig=>function(){ orig(); updateWeather(); })(renderTop);
renderScreen=(orig=>function(){ orig(); updateWeather(); })(renderScreen);

// ---------- 4. Đòi nợ: điện thoại rung ----------
if(typeof debtCall==='function') debtCall=(orig=>function(){ orig(); const s=$('#sheet'); if(s) s.classList.add('fx-ring'); setTimeout(()=>s&&s.classList.remove('fx-ring'),1600); })(debtCall);
// sheet mới mở không mang theo hiệu ứng cũ
sheet=(orig=>function(h,b){ const s=$('#sheet'); if(s) s.classList.remove('fx-ring','fx-shine'); return orig(h,b); })(sheet);

// ---------- 5. Mini game, bảo vật, lên resort: toả sáng ----------
const shineSheet=()=>{ const s=$('#sheet'); if(!s||FX.reduce) return; const g=s.querySelector('.mg-grade.gS'); if(g && s._shone!==g){ s._shone=g; s.classList.add('fx-shine'); confetti(s); } };
function confetti(host){ const box=document.createElement('div'); box.className='fx-confetti'; box.innerHTML=[...Array(18)].map((_,i)=>`<i style="left:${5+i*5}%;animation-delay:${(i%6)*.08}s;background:${['#E9B8A6','#F9C87A','#8FD3AE','#BCD7DC','#E9B8A6'][i%5]}"></i>`).join(''); host.appendChild(box); setTimeout(()=>box.remove(),1800); }
new MutationObserver(()=>shineSheet()).observe($('#sheet'),{childList:true});

// 15p-sky.js — v2.9: lớp canvas chung cho mưa, nước ngập (sóng lặp liền mạch + bong bóng nổ), hoàng hôn, pháo hoa
// + 2 sự kiện hằng ngày có ảnh hưởng tới tiệm:
//   Hoàng hôn (mùa khô tháng 11–4, trời không mưa, 15:00–19:00): khách du lịch kéo ra biển ngắm → khách vào ít hơn,
//     một số khách đang ngồi chờ bỏ đi ngắm hoàng hôn, khoảng một nửa quay lại sau 19:30.
//   Pháo hoa (19:30 và 21:00 mỗi ngày, huỷ nếu mưa lớn/bão): khách đang làm phải dừng xem → mỗi khách tốn thêm 15 phút,
//     khách mới vào ít hơn trong lúc bắn.
'use strict';
const SKY={P:8, sunset:[15,19], fw:[19.5,21], fwMin:20, showMs:14000};
const gameHour=()=>10+S.time*GMIN/60;
const hourToT=h=>(h-10)*60/GMIN;
const goodSeason=()=>{ const m=typeof monthOf==='function'?monthOf():1; return m>=11||m<=4; };
const wetNow=()=>['rain','heavy','outage','storm1','storm2','storm3'].includes(S.wx&&S.wx.today);
const sunsetOn=()=>S.stage==='open' && goodSeason() && !wetNow() && gameHour()>=SKY.sunset[0] && gameHour()<SKY.sunset[1];
const sunsetProg=()=>{ const h=gameHour(); return clamp((h-SKY.sunset[0])/(SKY.sunset[1]-SKY.sunset[0]),0,1); };
const fwBlocked=()=>['heavy','storm1','storm2','storm3'].includes(S.wx&&S.wx.today);
// Pháo hoa là 1 màn diễn: game dừng để xem (~14 giây thật, bấm để bỏ qua), xong thì đồng hồ nhảy tới sau 20 phút.
// Trong 20 phút đó không ai làm tiếp, không khách mới vào: khách đang làm tốn thêm đúng 20 phút.
const FWS={on:false, until:0, idx:-1};
const fwIdx=()=>FWS.on?FWS.idx:-1;

hourCurve=(orig=>function(){ let m=1;
  if(sunsetOn()){ const p=prem(), tour=p?p.mix[1]+p.mix[2]:.5; m*=1-tour*(S.prem==='sunset'?.5:.35); }
  return orig()*m; })(hourCurve);
let skyState={sun:false, fwDone:{}, day:0};
function endFireworks(){ if(!FWS.on) return; FWS.on=false; S.time=Math.min(DAY,S.time+SKY.fwMin/GMIN); const b=$('#fwSkip'); if(b) b.remove();
  toast(`Pháo hoa tàn, đã ${clockStr()}. Khách và KTV làm tiếp.`); renderTop(); skyTick(); }
tick=(orig=>function(dt){
  if(FWS.on){ if(performance.now()>=FWS.until) endFireworks(); return; }           // đang xem pháo hoa: thời gian đứng
  orig(dt); if(S.stage!=='open') return;
  if(skyState.day!==S.day) skyState={sun:false, fwDone:{}, day:S.day};
  const sun=sunsetOn(), h=gameHour();
  if(sun && !skyState.sun) toast('Hoàng hôn: khách du lịch ra biển ngắm, tiệm vắng tới 19h.');
  SKY.fw.forEach((fh,i)=>{ if(h>=fh && h<fh+.5 && !skyState.fwDone[i]){ skyState.fwDone[i]=true; if(fwBlocked()){ toast('Giông sấm sét: tối nay không có pháo hoa.','warn'); return; }
    FWS.on=true; FWS.idx=i; FWS.until=performance.now()+SKY.showMs; SKY2.show0=performance.now();
    toast(`Pháo hoa ${i?'21:00':'19:30'}! Cả tiệm dừng lại xem.`);
    const bt=document.createElement('button'); bt.id='fwSkip'; bt.className='fw-skip'; bt.innerHTML=((window.uiIco&&uiIco('tua','fw-ic'))||'⏩')+' Xem xong'; bt.onclick=endFireworks; fxRoot().appendChild(bt); skyTick(); } });
  if(sun) guests.forEach(g=>{ if(g.state==='seated' && g.type!=='dp' && !g.grp && !g.sunChecked && Math.random()<dt*.012){ g.sunChecked=true;
    bubble(g, g.type==='tay'?'Sunset time! Be right back… maybe.':'Ra ngắm hoàng hôn chút nha em!'); S.stats.lost++;
    if(Math.random()<.5){ returnQueue.push({t:hourToT(19.5)+Math.random()*8, kind:'ret'}); returnQueue.sort((a,b)=>a.t-b.t); }
    reject(g); promoteStand(); } });
  skyState.sun=sun;
})(tick);

// ---------- canvas chung ----------
const SKY2={cv:null, ctx:null, raf:0, W:0, H:0, dpr:1, last:0, t:0, drops:[], bits:[], rings:[], rbub:[], sparks:[], rockets:[], nextRocket:0, gust:1, gustT:0};
function skyCanvas(){ if(SKY2.cv && SKY2.cv.isConnected) return SKY2.cv; SKY2.cv=document.createElement('canvas'); SKY2.cv.className='fx-sky'; SKY2.cv.setAttribute('aria-hidden','true'); fxRoot().appendChild(SKY2.cv); SKY2.ctx=SKY2.cv.getContext('2d'); return SKY2.cv; }
function skySize(){ const r=SKY2.cv.getBoundingClientRect(); if(Math.abs(r.width-SKY2.W)<1&&Math.abs(r.height-SKY2.H)<1) return; SKY2.dpr=Math.min(1.5,devicePixelRatio||1); SKY2.W=r.width; SKY2.H=r.height; SKY2.cv.width=Math.round(SKY2.W*SKY2.dpr); SKY2.cv.height=Math.round(SKY2.H*SKY2.dpr); SKY2.ctx.setTransform(SKY2.dpr,0,0,SKY2.dpr,0,0); }
// Canvas nền nằm DƯỚI mục Tiệm (hoàng hôn, đêm); canvas phủ trên (mưa, sét, nước, pháo hoa)
function skyBg(){ const host=$('#sceneCard'); if(!host) return null; if(SKY2.bg && SKY2.bg.isConnected) return SKY2.bg;
  SKY2.bg=document.createElement('canvas'); SKY2.bg.className='sky-bg'; SKY2.bg.setAttribute('aria-hidden','true'); host.insertBefore(SKY2.bg, host.firstChild); SKY2.bgx=SKY2.bg.getContext('2d'); return SKY2.bg; }
function bgSize(){ const r=SKY2.bg.getBoundingClientRect(); if(Math.abs(r.width-(SKY2.bW||0))<1&&Math.abs(r.height-(SKY2.bH||0))<1) return; SKY2.bW=r.width; SKY2.bH=r.height; SKY2.bg.width=Math.round(r.width*SKY2.dpr); SKY2.bg.height=Math.round(r.height*SKY2.dpr); SKY2.bgx.setTransform(SKY2.dpr,0,0,SKY2.dpr,0,0); }
function bgView(){ const card=SKY2.bg.getBoundingClientRect(), sc=$('#screen'); const vr=sc?sc.getBoundingClientRect():{top:0,bottom:innerHeight};
  SKY2.vTop=Math.max(0,vr.top-card.top); SKY2.vH=Math.max(120,Math.min(card.bottom,vr.bottom)-Math.max(card.top,vr.top)); }
function onBg(fn){ bgView(); const sv=[SKY2.ctx,SKY2.W,SKY2.H]; SKY2.ctx=SKY2.bgx; SKY2.W=SKY2.bW; SKY2.H=SKY2.bH; try{ fn(); } finally{ [SKY2.ctx,SKY2.W,SKY2.H]=sv; } }
const navH=()=>parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--nav-h'))||64;
function skyLayers(){ const show=tab==='shop' && S.prem && (S.stage==='open'||S.stage==='closed') && !FX.reduce;
  if(!show) return null; const t=S.wx&&S.wx.today, h=S.stage==='open'?gameHour():26, rainyM=typeof rainy==='function'?rainy(monthOf()):true;
  return { rain: wetNow()?t:null, bolt: ['heavy','storm1','storm2'].includes(t),
    flood: rainyM && !!(S.wx && (S.wx.flooded===S.day || t==='storm2' || t==='storm3')),     // mùa nắng không có nước ngập
    sunset: sunsetOn()?sunsetProg():-1, night: window.XEMDEM==='dem'?1:window.XEMDEM==='ngay'?0:h>=19 ? clamp((h-19)/.35,0,1) : 0, stars: !wetNow(), fw: FWS.on }; }
function skyTick(){ const L=skyLayers(), any=L;   // 17e-3: nen troi anh luon ve khi dang o muc Tiem
  if(!any){ if(SKY2.cv) SKY2.cv.style.display='none'; if(SKY2.bg) SKY2.bg.style.display='none'; const cd=$('#sceneCard'); if(cd) cd.classList.remove('sky-on'); cancelAnimationFrame(SKY2.raf); SKY2.raf=0; return; }
  skyCanvas(); SKY2.cv.style.display=''; SKY2.L=L; if(!SKY2.raf){ SKY2.last=0; SKY2.raf=requestAnimationFrame(skyFrame); } }
renderTop=(orig=>function(){ orig(); skyTick(); })(renderTop);
renderScreen=(orig=>function(){ orig(); skyTick(); })(renderScreen);

// ---------- mặt nước: mọi thành phần tuần hoàn chu kỳ P giây → lặp liền mạch, không có chỗ cắt ----------
const TAU=Math.PI*2, wv=n=>TAU*n/SKY.P;
function surf(x,t){ const W=SKY2.W, bottom=SKY2.H-navH()+4, u=x/W, lv=SKY2.lv||0;
  // nước dâng dần theo lv; sóng theo tỷ lệ bề ngang với số bước sóng nguyên → 2 mép khớp; 2 sóng ngược chiều + nghiêng qua lại
  return bottom+8-(40*lv) - lv*(5*Math.sin(wv(1)*t) - 4.2*Math.sin(TAU*3*u-wv(2)*t) - 2.6*Math.sin(TAU*5*u+wv(3)*t+1.3) - 1.2*Math.sin(TAU*9*u-wv(5)*t) - 7*Math.sin(wv(1)*t+.6)*(u-.5)); }
// bong bóng cố định theo chu kỳ (lặp đều) + bong bóng do hạt mưa rơi
const BUB_SLOTS=[...Array(7)].map((_,k)=>({u:(k+.5)/7+((k*37)%11-5)/200, ph:(k*.37)%1, r:2.2+((k*53)%5)*.6}));
function drawBubble(x,y,r,a){ const c=SKY2.ctx; c.strokeStyle=`rgba(255,255,255,${.85*a})`; c.lineWidth=1; c.beginPath(); c.arc(x,y,r,0,TAU); c.stroke(); c.fillStyle=`rgba(255,255,255,${.18*a})`; c.fill(); c.fillStyle=`rgba(255,255,255,${.9*a})`; c.beginPath(); c.arc(x-r*.35,y-r*.35,Math.max(.6,r*.25),0,TAU); c.fill(); }
function drawPop(x,y,r,k){ const c=SKY2.ctx; c.strokeStyle=`rgba(255,255,255,${.9*(1-k)})`; c.lineWidth=1; for(let i=0;i<6;i++){ const a=i*TAU/6, r1=r*(1+k*1.2), r2=r*(1.4+k*2); c.beginPath(); c.moveTo(x+Math.cos(a)*r1,y+Math.sin(a)*r1); c.lineTo(x+Math.cos(a)*r2,y+Math.sin(a)*r2); c.stroke(); } }
function drawWater(t){ const c=SKY2.ctx, W=SKY2.W, H=SKY2.H, step=4;
  const top=surf(0,t)-12, g=c.createLinearGradient(0,top,0,H); g.addColorStop(0,'rgba(160,205,232,.62)'); g.addColorStop(1,'rgba(110,160,200,.78)');
  c.fillStyle=g; c.beginPath(); c.moveTo(0,H); for(let x=0;x<=W+step;x+=step) c.lineTo(x,surf(x,t)); c.lineTo(W,H); c.closePath(); c.fill();
  const wi=waterImg('nen'); if(wi){ c.save(); c.clip(); c.globalAlpha=.4; const T=110, ox=-((t*7)%T); for(let y=top;y<H;y+=T) for(let x=ox;x<W;x+=T) c.drawImage(wi,x,y,T+1,T+1); c.restore(); }
  // lớp sóng sau mờ hơn, lệch pha → có chiều sâu
  c.strokeStyle='rgba(255,255,255,.35)'; c.lineWidth=1.2; c.beginPath(); for(let x=0;x<=W+step;x+=step){ const y=surf(x,t+SKY.P/2)+7; x?c.lineTo(x,y):c.moveTo(x,y); } c.stroke();
  c.strokeStyle='rgba(255,255,255,.9)'; c.lineWidth=2; c.beginPath(); for(let x=0;x<=W+step;x+=step){ const y=surf(x,t); x?c.lineTo(x,y):c.moveTo(x,y); } c.stroke();
  // bọt trôi qua lại (không nhảy vị trí)
  for(let k=0;k<6;k++){ const u=(k+.5)/6+.07*Math.sin(wv(1)*t+k*1.7), x=u*W, s=.7+.3*Math.sin(wv(2)*t+k); const bi=waterImg('bot'); if(bi){ c.save(); c.globalAlpha=.5+.3*s; c.drawImage(bi,x-9*s,surf(x,t)-7*s,18*s,17*s); c.restore(); } else { c.fillStyle=`rgba(255,255,255,${.35+.25*s})`; c.beginPath(); c.ellipse(x,surf(x,t)+3,7*s,1.7,0,0,TAU); c.fill(); } }
  if(window.HAT) HAT.lapNuoc(c,W,surf,t);
  // bong bóng theo chu kỳ: nổi lên, lớn dần, nổ
  const P=SKY.P; BUB_SLOTS.forEach(b=>{ const p=((t/P+b.ph)%1+1)%1, x=b.u*W+6*Math.sin(wv(1)*t+b.ph*9);
    if(p<.62){ const k=p/.62, r=b.r*(.4+.6*k); drawBubble(x,surf(x,t)-r*.6-2*k,r,Math.min(1,k*4)); }
    else if(p<.72){ const k=(p-.62)/.1; drawPop(x,surf(x,t)-b.r*.6-2,b.r,k); } });
  // bong bóng do mưa
  for(let i=SKY2.rbub.length-1;i>=0;i--){ const b=SKY2.rbub[i]; b.age+=SKY2.dt; const y=surf(b.x,t)-b.r*.6;
    if(b.age<b.life){ const k=b.age/b.life; drawBubble(b.x,y,b.r*(.5+.5*k),1); } else if(b.age<b.life+.18){ drawPop(b.x,y,b.r,(b.age-b.life)/.18); } else SKY2.rbub.splice(i,1); }
  for(let i=SKY2.rings.length-1;i>=0;i--){ const q=SKY2.rings[i]; q.r+=22*SKY2.dt; q.a-=.9*SKY2.dt; if(q.a<=0){ SKY2.rings.splice(i,1); continue; } c.strokeStyle=`rgba(255,255,255,${q.a})`; c.lineWidth=1; c.beginPath(); c.ellipse(q.x,surf(q.x,t)+1,q.r,q.r*.3,0,0,TAU); c.stroke(); } }

// ---------- mưa từng hạt ----------
function drawRain(kind,flood,t){ const c=SKY2.ctx, W=SKY2.W, dt=SKY2.dt, bottom=SKY2.H-navH()+4;
  const [rate,spd,wind]=({rain:[1.1,.9,0], heavy:[2.4,1.1,.12], outage:[1.6,1,.05], storm1:[3.2,1.25,.3], storm2:[4.2,1.35,.42], storm3:[1.4,1,.1]})[kind]||[0,0,0];
  SKY2.gustT-=dt; if(SKY2.gustT<=0){ SKY2.gust=.35+Math.random()*1.3; SKY2.gustT=.6+Math.random()*2.2; }
  let n=rate*SKY2.gust*60*dt*(W/400); while(n>0){ if(Math.random()<n) SKY2.drops.push({x:Math.random()*(W+80)-40, y:-20-Math.random()*40, l:6+Math.random()*14, v:(420+Math.random()*520)*spd, a:.3+Math.random()*.4, w:.9+Math.random()*.8}); n-=1; }
  const wx=wind*(.8+.4*Math.sin(t*.9)); c.lineCap='round';
  for(let i=SKY2.drops.length-1;i>=0;i--){ const d=SKY2.drops[i]; d.y+=d.v*dt; d.x+=d.v*wx*dt; const sy=flood?surf(d.x,t):bottom;
    if(d.y>=sy){ SKY2.drops.splice(i,1); const k=flood?2+Math.floor(Math.random()*3):Math.random()<.35?1:0;
      for(let j=0;j<k;j++) SKY2.bits.push({x:d.x,y:sy-1,vx:(Math.random()-.5)*60+wx*40,vy:-(40+Math.random()*(flood?90:50)),a:.55,r:.7+Math.random()*.9,fl:flood});
      if(flood){ if(Math.random()<.7) SKY2.rings.push({x:d.x,r:1,a:.5}); if(Math.random()<.12 && SKY2.rbub.length<14) SKY2.rbub.push({x:d.x,r:1.8+Math.random()*2.4,age:0,life:.8+Math.random()*1.6}); }
      continue; }
    c.strokeStyle=`rgba(120,160,205,${d.a})`; c.lineWidth=d.w; c.beginPath(); c.moveTo(d.x,d.y); c.lineTo(d.x-d.l*wx*.9,d.y-d.l); c.stroke(); }
  for(let i=SKY2.bits.length-1;i>=0;i--){ const b=SKY2.bits[i]; b.vy+=420*dt; b.x+=b.vx*dt; b.y+=b.vy*dt; b.a-=.9*dt; const floor=b.fl?surf(b.x,t):bottom;
    if(b.a<=0||(b.vy>0&&b.y>floor+2)){ SKY2.bits.splice(i,1); continue; } c.fillStyle=`rgba(200,225,245,${b.a})`; c.beginPath(); c.arc(b.x,b.y,b.r,0,TAU); c.fill(); } }

// ---------- hoàng hôn: nắng vàng rọi từ góc trên phải, mặt trời hạ dần đổi màu vàng → cam đỏ rồi lặn khỏi màn hình ----------
const SUN_STOPS=[[0,'#FFE66B'],[.22,'#FFD23F'],[.45,'#FFB547'],[.65,'#FF9538'],[.85,'#FF6B3D'],[1,'#F0503C']];
const lerpHex=(a,b,k)=>{ const A=parseInt(a.slice(1),16), B=parseInt(b.slice(1),16); const ch=sh=>Math.round(((A>>sh)&255)+(((B>>sh)&255)-((A>>sh)&255))*k); return '#'+((1<<24)+(ch(16)<<16)+(ch(8)<<8)+ch(0)).toString(16).slice(1); };
function sunColor(p){ for(let i=1;i<SUN_STOPS.length;i++){ const [pa,ca]=SUN_STOPS[i-1],[pb,cb]=SUN_STOPS[i]; if(p<=pb) return lerpHex(ca,cb,(p-pa)/(pb-pa)); } return SUN_STOPS[SUN_STOPS.length-1][1]; }
// Mặt trời đi theo phần mục Tiệm đang nhìn thấy trên màn hình (thẻ tiệm dài hơn màn hình), lặn đúng mép dưới lúc 19h
function sunPos(p){ const W=SKY2.W, oy=SKY2.vTop||0, VH=SKY2.vH||SKY2.H, e=p*p*(3-2*p); return [W*(.8-.1*p), oy+64+e*(VH+60-64)]; }
function cloud(x,y,s,tint,a,k){ const c=SKY2.ctx; const mi=cloudImg(k||0); if(mi){ const w=(k===1?150:k===2?110:130)*s, h=w*mi.naturalHeight/mi.naturalWidth; c.save(); c.globalAlpha=a; c.drawImage(mi,x-w*.2,y-h*.6,w,h); c.restore(); return; }
  const parts=[[0,0,13],[15,-8,16],[33,-4,14],[47,3,10],[-12,4,9],[22,6,13]];
  c.save(); c.globalAlpha=a;
  c.fillStyle='#4A4458'; parts.forEach(([dx,dy,r])=>{ c.beginPath(); c.arc(x+dx*s,y+dy*s,r*s+1.8,0,TAU); c.fill(); });   // viền ngoài liền mạch
  const g=c.createLinearGradient(0,y-24*s,0,y+18*s); g.addColorStop(0,'#FBF6EA'); g.addColorStop(.55,lerpHex('#FBF6EA',tint,.35)); g.addColorStop(1,lerpHex('#FDE3E4',tint,.55));
  c.fillStyle=g; parts.forEach(([dx,dy,r])=>{ c.beginPath(); c.arc(x+dx*s,y+dy*s,r*s,0,TAU); c.fill(); });
  c.fillStyle='rgba(255,255,255,.7)'; c.beginPath(); c.ellipse(x+10*s,y-12*s,8*s,3.5*s,-.3,0,TAU); c.fill();
  c.restore(); }
// 11/10 Viec 17e-3 (E10): nen troi bang anh (3 dai lien mep trai-phai): nang = nen-troi, chieu toi = nen-hoanghon, mua = nen-mua; troi cuon cham sang ngang
const CLIMG=[], cloudImg=k=>{ let i=CLIMG[k]; if(!i){ i=CLIMG[k]=new Image(); i.src=['img/4393e3ece119.webp','img/622efad811e5.webp','img/1795dc10e955.webp'][k]; } return i.complete&&i.naturalWidth?i:null; };
const WIMG={}, waterImg=k=>{ let i=WIMG[k]; if(!i){ i=WIMG[k]=new Image(); i.src={nen:'img/fa3a7ed0ae29.webp',bot:'img/8fd549c6548e.webp'}[k]; } return i.complete&&i.naturalWidth?i:null; };
const SKYIMG={}, skyImg=k=>{ let i=SKYIMG[k]; if(!i){ i=SKYIMG[k]=new Image(); i.src={troi:'img/c4c923f580be.webp',hoanghon:'img/afc3d6c627ba.webp',mua:'img/255a06831168.webp'}[k]; } return i.complete&&i.naturalWidth?i:null; };
function skyKey(L){ return L.rain?'mua':L.sunset>=0?'hoanghon':'troi'; }
function drawSkyImg(L,t){ const i=skyImg(skyKey(L)); if(!i) return false; const c=SKY2.ctx, W=SKY2.W, oy=SKY2.vTop||0, VH=SKY2.vH||SKY2.H;
  const h=Math.max(VH,SKY2.H*.5), w=h*i.naturalWidth/i.naturalHeight, off=(t*6)%w;   // cao theo phan Tiem nhin thay; lap ngang
  c.save(); c.globalAlpha=1-L.night*.85; for(let x=-off;x<W;x+=w) c.drawImage(i,x,oy,w+1,h); if(window.HAT&&!L.rain) HAT.may(c,W,oy,1-L.night*.85); c.restore(); return true; }
function drawSunset(p,t){ const c=SKY2.ctx, W=SKY2.W, H=SKY2.H, col=sunColor(p), [sx,sy]=sunPos(p);
  const inten=Math.min(1,p*5)*(p>.8?Math.max(0,1-(p-.8)/.2):1);
  // ánh vàng rọi xuống cả mục tiệm từ góc trên bên phải
  const oy=SKY2.vTop||0, VH=SKY2.vH||H; const glow=c.createRadialGradient(W,oy,10,W,oy,Math.max(W,VH)*1.05); glow.addColorStop(0,hexA(col,.42*inten)); glow.addColorStop(.45,hexA(col,.18*inten)); glow.addColorStop(1,hexA(col,0));
  c.fillStyle=glow; c.fillRect(0,0,W,H);
  const sky=c.createLinearGradient(0,oy,0,oy+VH*.6); sky.addColorStop(0,hexA('#C9B8F0',.18*inten)); sky.addColorStop(1,hexA('#F7A8B8',0)); c.fillStyle=sky; c.fillRect(0,0,W,H);
  if(sy>oy+VH+70) return;
  const r=28;
  // quầng sáng + tia nắng xoay chậm
  const halo=c.createRadialGradient(sx,sy,r*.8,sx,sy,r*4); halo.addColorStop(0,hexA(col,.55)); halo.addColorStop(1,hexA(col,0)); c.fillStyle=halo; c.beginPath(); c.arc(sx,sy,r*4,0,TAU); c.fill();
  c.save(); c.translate(sx,sy); c.rotate(t*.08); c.fillStyle=hexA(lerpHex(col,'#FBF6EA',.35),.35);
  for(let k=0;k<12;k++){ c.rotate(TAU/12); c.beginPath(); c.moveTo(r*1.25,-3); c.lineTo(r*2.1+4*Math.sin(t*1.5+k),0); c.lineTo(r*1.25,3); c.closePath(); c.fill(); } c.restore();
  // mặt trời: lõi sáng → rìa theo màu giờ, viền đậm kiểu sticker
  const disk=c.createRadialGradient(sx-r*.35,sy-r*.35,r*.1,sx,sy,r); disk.addColorStop(0,lerpHex(col,'#FBF6EA',.7)); disk.addColorStop(.55,lerpHex(col,'#FBF6EA',.15)); disk.addColorStop(1,col);
  c.fillStyle=disk; c.strokeStyle='#4A4458'; c.lineWidth=2.6; c.beginPath(); c.arc(sx,sy,r,0,TAU); c.fill(); c.stroke();
  c.fillStyle='rgba(255,255,255,.6)'; c.beginPath(); c.ellipse(sx-r*.38,sy-r*.42,r*.3,r*.16,-.6,0,TAU); c.fill();
  // mây: 1 đám trôi ngang trước mặt trời, 2 đám nền
  cloud(W*.1+18*Math.sin(t*.07), oy+92, .85, col, .95*Math.max(.3,inten), 0); cloud(W*.42+14*Math.sin(t*.09+1), oy+58, .7, col, .9*Math.max(.3,inten), 1);
  cloud(sx-40+30*Math.sin(t*.1+2), Math.min(sy+18,oy+VH*.62), 1, col, .95, 2);
  // chim bay về tổ
  c.strokeStyle=hexA('#4A4458',.7*inten); c.lineWidth=1.6; for(let k=0;k<3;k++){ const bx=((t*18+k*60)%(W+80))-40, by=oy+140+k*14+4*Math.sin(t*2+k); c.beginPath(); c.moveTo(bx-6,by); c.quadraticCurveTo(bx-3,by-4,bx,by); c.quadraticCurveTo(bx+3,by-4,bx+6,by); c.stroke(); } }

// ---------- đêm: trời tối dịu, sao lấp lánh sáng dần, trăng ----------
const STARS=[...Array(46)].map((_,k)=>({u:((k*97)%100)/100, v:((k*57)%70)/100, r:.6+((k*31)%10)/10, sp:.8+((k*13)%10)/6, ph:k*1.7}));
function drawNight(k,stars,t){ const c=SKY2.ctx, W=SKY2.W, H=SKY2.H, extra=FWS.on?.15:0;
  const g=c.createLinearGradient(0,0,0,H); g.addColorStop(0,`rgba(26,22,64,${(.42+extra)*k})`); g.addColorStop(.7,`rgba(44,36,90,${(.26+extra)*k})`); g.addColorStop(1,`rgba(60,44,96,${(.18+extra)*k})`);
  c.fillStyle=g; c.fillRect(0,0,W,H); if(!stars) return;
  STARS.forEach(s=>{ const a=k*(.45+.55*Math.abs(Math.sin(t*s.sp+s.ph))); c.fillStyle=`rgba(255,250,225,${a})`; c.beginPath(); c.arc(s.u*W,20+s.v*H*.8,s.r,0,TAU); c.fill();
    if(s.r>1.3){ c.strokeStyle=`rgba(255,250,225,${a*.5})`; c.lineWidth=.8; c.beginPath(); c.moveTo(s.u*W-4,20+s.v*H*.8); c.lineTo(s.u*W+4,20+s.v*H*.8); c.moveTo(s.u*W,16+s.v*H*.8); c.lineTo(s.u*W,24+s.v*H*.8); c.stroke(); } });
  // trăng lưỡi liềm góc trên trái
  const mx=46, my=(SKY2.vTop||0)+78; c.save(); c.globalAlpha=k; c.fillStyle='#FFF3C4'; c.strokeStyle='#4A4458'; c.lineWidth=2.2; c.beginPath(); c.arc(mx,my,15,0,TAU); c.fill(); c.stroke();
  c.globalCompositeOperation='destination-out'; c.beginPath(); c.arc(mx+8,my-5,13,0,TAU); c.fill(); c.restore(); }

// ---------- sét: chỉ lúc sét đánh màn hình mới tối, lóe trắng, tia sét zic zắc ----------
const BOLT={next:2, at:-9, path:null};
function drawLightning(t,dt){ const c=SKY2.ctx, W=SKY2.W, H=SKY2.H, L=SKY2.L||{}; BOLT.next-=dt;
  if(BOLT.next<=0){ BOLT.at=t; BOLT.next=(L.rain&&L.rain.startsWith('storm')?1.8:3)+Math.random()*4; const pts=[]; let x=W*(.2+Math.random()*.6), y=0; pts.push([x,y]);
    while(y<H*(.35+Math.random()*.25)){ x+=(Math.random()-.5)*34; y+=14+Math.random()*22; pts.push([x,y]); } BOLT.path=pts; }
  const e=t-BOLT.at; if(e<0||e>.75) return;
  const dark=e<.1? e/.1 : Math.max(0,1-(e-.1)/.65); c.fillStyle=`rgba(24,24,48,${.42*dark})`; c.fillRect(0,0,W,H);
  const flash=(e>.08&&e<.14)||(e>.24&&e<.3); if(!flash) return;
  c.fillStyle='rgba(255,255,255,.42)'; c.fillRect(0,0,W,H);
  c.strokeStyle='rgba(255,255,240,.95)'; c.lineWidth=2.4; c.shadowColor='#BFE3F7'; c.shadowBlur=10; c.beginPath(); BOLT.path.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y)); c.stroke(); c.shadowBlur=0; }

// ---------- pháo hoa: nhiều màu, nhiều cỡ, nhiều kiểu, nhịp bắn bất quy tắc, cuối màn bắn dồn ----------
const FW_PAL=['#FF7FA3','#FFC44D','#4FD1A0','#5FC3F5','#A98BFF','#FBF6EA','#FF9A5C','#FF5E7E','#7CE0FF','#C6F36B'];
const FW_TYPES=['peony','peony','chrys','ring','ring2','willow','palm','crackle','multi'];
function launch(W,H,big){ const x=W*(.1+Math.random()*.8), apex=H*(.08+Math.random()*.34), type=FW_TYPES[Math.floor(Math.random()*FW_TYPES.length)];
  const size=big? 1.2+Math.random()*.6 : .45+Math.random()*1.15;                                   // to nhỏ ngẫu nhiên
  const cols=[...Array(1+Math.floor(Math.random()*3))].map(()=>FW_PAL[Math.floor(Math.random()*FW_PAL.length)]);
  const vy=-Math.sqrt(2*260*Math.max(80,H-navH()-apex));
  SKY2.rockets.push({x,y:H-navH(),vx:(Math.random()-.5)*40,vy,type,cols,size,apex}); }
function fwBurst(r){ const S0=r.size, add=o=>SKY2.sparks.push(Object.assign({x:r.x,y:r.y,age:0,tr:[],w:1.6*Math.min(1.4,.7+S0*.5)},o));
  const col=i=>r.type==='multi'?FW_PAL[Math.floor(Math.random()*FW_PAL.length)]:r.cols[i%r.cols.length];
  if(r.type==='ring'||r.type==='ring2'){ const rings=r.type==='ring2'?2:1; for(let q=0;q<rings;q++){ const n=Math.round(36*S0+12), v=(120+q*60)*S0+40, tilt=Math.random()*TAU;
      for(let i=0;i<n;i++){ const a=i*TAU/n; add({vx:Math.cos(a)*v, vy:Math.sin(a)*v*(.55+.45*Math.cos(tilt)), life:1.3+Math.random()*.4, c:r.cols[q%r.cols.length], g:40, drag:.982}); } } }
  else if(r.type==='willow'){ const n=Math.round(60*S0+20); for(let i=0;i<n;i++){ const a=Math.random()*TAU, v=(60+Math.random()*90)*S0+30; add({vx:Math.cos(a)*v, vy:Math.sin(a)*v, life:2.4+Math.random()*.8, c:'#FFC44D', g:60, drag:.988, long:true, w:1.3}); } }
  else if(r.type==='palm'){ const arms=6+Math.floor(Math.random()*4); for(let i=0;i<arms;i++){ const a=i*TAU/arms+Math.random()*.2, v=(150+Math.random()*30)*S0+40; add({vx:Math.cos(a)*v, vy:Math.sin(a)*v, life:1.8, c:col(i), g:70, drag:.985, long:true, w:2.6}); } }
  else { const n=Math.round((r.type==='chrys'?90:70)*S0+20), sp=(r.type==='chrys'?150:170)*S0+40;
    for(let i=0;i<n;i++){ const a=Math.random()*TAU, v=sp*(.35+Math.random()*.7); add({vx:Math.cos(a)*v, vy:Math.sin(a)*v, life:(r.type==='chrys'?1.9:1.3)+Math.random()*.7, c:col(i), g:45, drag:.982, long:r.type==='chrys', tw:r.type==='crackle'||Math.random()<.12}); } }
  SKY2.sparks.push({flash:true,x:r.x,y:r.y,age:0,life:.28,c:r.cols[0],R:50*S0+20}); }
function drawFireworks(t){ const c=SKY2.ctx, W=SKY2.W, H=SKY2.H, dt=SKY2.dt, el=(performance.now()-(SKY2.show0||0))/1000, left=SKY.showMs/1000-el;
  if(FWS.on){ SKY2.nextRocket-=dt; if(SKY2.nextRocket<=0){ const finale=left<2.8&&left>.6; launch(W,H,finale&&Math.random()<.5);
      if(Math.random()<(finale?.8:.28)) launch(W,H); if(finale&&Math.random()<.5) launch(W,H);
      SKY2.nextRocket=finale? .08+Math.random()*.2 : Math.random()<.25? .05+Math.random()*.15 : .35+Math.random()*.9; } }   // lúc dồn dập, lúc thưa
  c.save();
  for(let i=SKY2.rockets.length-1;i>=0;i--){ const r=SKY2.rockets[i]; r.vy+=260*dt; const ox=r.x, oy=r.y; r.x+=r.vx*dt; r.y+=r.vy*dt;
    c.strokeStyle='rgba(255,236,200,.9)'; c.lineWidth=2; c.beginPath(); c.moveTo(ox,oy+7); c.lineTo(r.x,r.y); c.stroke();
    if(Math.random()<.7) SKY2.sparks.push({x:r.x,y:r.y,tr:[],vx:(Math.random()-.5)*20,vy:20+Math.random()*30,life:.4,age:0,c:'#FFE9B8',g:30,drag:.95,w:1.1});
    if(r.vy>=-15 || r.y<=r.apex){ SKY2.rockets.splice(i,1); fwBurst(r); } }
  for(let i=SKY2.sparks.length-1;i>=0;i--){ const s=SKY2.sparks[i]; s.age+=dt; if(s.age>=s.life){ SKY2.sparks.splice(i,1); continue; } const k=1-s.age/s.life;
    if(s.flash){ const g=c.createRadialGradient(s.x,s.y,0,s.x,s.y,s.R); g.addColorStop(0,hexA('#FBF6EA',.55*k)); g.addColorStop(.4,hexA(s.c,.25*k)); g.addColorStop(1,hexA(s.c,0)); c.fillStyle=g; c.beginPath(); c.arc(s.x,s.y,s.R,0,TAU); c.fill(); continue; }
    s.vx*=Math.pow(s.drag,dt*60); s.vy=s.vy*Math.pow(s.drag,dt*60)+s.g*dt; s.x+=s.vx*dt; s.y+=s.vy*dt;
    const tr=s.tr; tr.push(s.x,s.y); const maxN=(s.long?18:8)*2; if(tr.length>maxN) tr.splice(0,tr.length-maxN);
    const a=s.tw? k*(Math.random()<.5?1:.2) : k;
    for(let j=2;j<tr.length;j+=2){ const f=j/tr.length; c.strokeStyle=hexA(s.c,a*f); c.lineWidth=s.w*1.2*f; c.beginPath(); c.moveTo(tr[j-2],tr[j-1]); c.lineTo(tr[j],tr[j+1]); c.stroke(); }
    c.fillStyle=hexA(s.c,a*.28); c.beginPath(); c.arc(s.x,s.y,s.w*2.5,0,TAU); c.fill();
    c.fillStyle=hexA(s.c,a); c.beginPath(); c.arc(s.x,s.y,s.w*1.2,0,TAU); c.fill();
    if(k>.5){ c.fillStyle=hexA('#FBF6EA',a*.9); c.beginPath(); c.arc(s.x,s.y,s.w*.5,0,TAU); c.fill(); } }
  c.restore(); }
const hexA=(h,a)=>{ const n=parseInt(h.slice(1),16); return `rgba(${n>>16&255},${n>>8&255},${n&255},${Math.max(0,Math.min(1,a)).toFixed(3)})`; };

// ---------- vòng vẽ ----------
function skyFrame(now){ if(!SKY2.cv||!SKY2.cv.isConnected||SKY2.cv.style.display==='none'){ SKY2.raf=0; return; }
  const dt=Math.min(.05,(now-(SKY2.last||now))/1000); SKY2.last=now; SKY2.dt=window.FX_DT!=null?window.FX_DT:dt; SKY2.t=window.FX_CLOCK!=null?window.FX_CLOCK:SKY2.t+dt; const t=SKY2.t;
  const L0=skyLayers(); if(!L0){ SKY2.cv.style.display='none'; if(SKY2.bg) SKY2.bg.style.display='none'; const cd=$('#sceneCard'); if(cd) cd.classList.remove('sky-on'); SKY2.raf=0; return; } SKY2.L=L0;   // đọc trạng thái mỗi khung (pháo hoa chạy khi game đứng)
  skySize(); const c=SKY2.ctx, L=L0; c.clearRect(0,0,SKY2.W,SKY2.H);
  // nước dâng / rút từ từ
  SKY2.lv=(SKY2.lv||0)+((L.flood?1:0)-(SKY2.lv||0))*Math.min(1,SKY2.dt*.35);
  const bgOn=true, card=$('#sceneCard');
  if(card) card.classList.toggle('sky-on',bgOn);
  if(skyBg()){ SKY2.bg.style.display=bgOn?'':'none'; if(bgOn){ bgSize(); SKY2.bgx.clearRect(0,0,SKY2.bW,SKY2.bH); onBg(()=>{ drawSkyImg(L,t); if(L.sunset>=0) drawSunset(L.sunset,t); if(L.night>0) drawNight(L.night,L.stars,t); }); } }
  if(L.fw || SKY2.sparks.length || SKY2.rockets.length){ if(L.fw){ c.fillStyle='rgba(22,18,58,.42)'; c.fillRect(0,0,SKY2.W,SKY2.H); } drawFireworks(t); }
  if(L.rain) drawRain(L.rain,L.flood,t); else SKY2.drops=[];
  if(L.bolt) drawLightning(t,SKY2.dt);
  if(SKY2.lv>.01) drawWater(t);
  SKY2.raf=requestAnimationFrame(skyFrame); }

// 15q-progress.js — v3.0: tiến trình
// 1) Chuyển mặt bằng (chợ đêm ↔ Trần Hưng Đạo ↔ Sunset): trả cọc + tháng đầu + sửa sang nơi mới, phí chuyển đồ 5% giá đồ,
//    nhận lại cọc cũ nếu đã thuê đủ 6 tháng (chưa đủ thì mất cọc), đồ dư so với chỗ mới bán lại 40%, nghỉ 1 ngày dọn tiệm,
//    khách khu mới chưa biết tiệm (lượng khách từ 60% tăng dần lên đủ sau 20 ngày), khách hẹn quay lại mất hết.
// 2) Học nghề có thời gian (siết mức vừa): học xong 1 khoá phải 3–4 ngày sau mới học khoá khác; nâng cao cần thực hành ≥50% cấp hiện tại,
//    giá nâng cao 3tr×cấp + 40 điểm×cấp.
// 3) Bảo vật hiếm hơn (siết mức vừa): tỷ lệ giảm khoảng một nửa, số lần bảo đảm tăng gấp đôi. Chơi đều mỗi ngày ~30–40 ngày mới đủ 6.
'use strict';
// ---------- 3. bảo vật ----------
Object.assign(TREASURES.map,{p:.04,pity:30}); Object.assign(TREASURES.silk,{p:.07,pity:20}); Object.assign(TREASURES.agar,{p:.07,pity:20});
Object.assign(TREASURES.pearl,{p:.2,pity:6}); Object.assign(TREASURES.bell,{p:.06,pity:22}); Object.assign(TREASURES.gourd,{p:.06,pity:18});
TREASURES.pearl.src='Chơi Tủ spa 2048 tới mốc cao';

// ---------- 2. học nghề có thời gian ----------
const COURSE={learnDays:3, upDays:4, upCash:3e6, upXp:40, practice:.5};
S.courseUntil=S.courseUntil||0;
const upCost=sk=>({cash:COURSE.upCash*sk.lv, xp:COURSE.upXp*sk.lv});
function courseBlock(k,isUp){ if(S.courseUntil>S.day) return `Đang học · xong ngày ${S.courseUntil}`;
  if(isUp){ const sk=S.skills[k]; if((sk.exp||0)<sk.lv*60*COURSE.practice) return `Cần thực hành ${sk.exp||0}/${Math.ceil(sk.lv*60*COURSE.practice)}`; }
  return null; }
function learnSkill(k){ const sv=SERVICES[k], L=sv.learn; if(!L||S.skills[k]) return false; if(sv.needSkill&&!S.skills[sv.needSkill]) return false;
  if(courseBlock(k,false)||S.cash<L.cash||S.xp<L.xp) return false;
  S.cash-=L.cash; S.xp-=L.xp; S.skills[k]={lv:1,exp:0}; if(!S.prices[k]) S.prices[k]=market(k); S.courseUntil=S.day+COURSE.learnDays;
  addLog('Học '+sv.name,-L.cash); save(); renderAll(); toast(`Đã học ${sv.name}! Khoá tiếp theo mở sau ${COURSE.learnDays} ngày.`,'good'); return true; }
function upSkill(k){ const sk=S.skills[k]; if(!sk||sk.lv>=5) return false; const c=upCost(sk); if(courseBlock(k,true)||S.cash<c.cash||S.xp<c.xp) return false;
  S.cash-=c.cash; S.xp-=c.xp; sk.lv++; sk.exp=0; S.courseUntil=S.day+COURSE.upDays;
  addLog(`Khoá nâng cao ${SERVICES[k].name} cấp ${sk.lv}`,-c.cash); save(); renderAll(); toast(`${SERVICES[k].name} lên cấp ${sk.lv}. Khoá tiếp theo mở sau ${COURSE.upDays} ngày.`,'good'); return true; }
// sửa nút trong tab Dịch vụ theo luật mới
renderScreen=(orig=>function(){ orig(); if(tab!=='skill') return;
  $('#dyn').querySelectorAll('[data-up]').forEach(b=>{ const k=b.dataset.up, sk=S.skills[k], c=upCost(sk), why=courseBlock(k,true);
    b.innerHTML=why?`<small>${why}</small>`:`Khoá nâng cao<br>${fmt(c.cash)} + ${c.xp} điểm`; b.disabled=!!why||S.cash<c.cash||S.xp<c.xp; });
  $('#dyn').querySelectorAll('[data-learn]').forEach(b=>{ const why=courseBlock(b.dataset.learn,false); if(why){ b.innerHTML=`<small>${why}</small>`; b.disabled=true; } });
})(renderScreen);

// ---------- 4. bảo trì sát thực tế hơn ----------
// Đồ trang trí (tranh, chậu cây, tiểu cảnh) không ai dùng trực tiếp: mòn theo ngày ~2 năm mới cần sửa (trước 4 tháng).
// Giá bảo trì khi mòn 70% giảm từ ~35% xuống ~18% giá đồ (sửa trong 15h-wear). Chạy thử: tiệm 1★ trước tốn ~15tr/tháng bảo trì = bằng tiền thuê.
WEAR_D.decor=720;

// ---------- 1. chuyển mặt bằng ----------
S.leaseDay=S.leaseDay||1; S.moving=S.moving||null;
const MOVE={fee:.05, resale:.4, minLease:180, rampDays:20, rampFrom:.6};
const slotFits=(s,np)=>{ if(s.zone==='chan') return s.seat<np.chairs; if(s.id.startsWith('room')) return s.need<np.rooms; return true; };
function moveQuote(id){ const np=PREMISES.find(x=>x.id===id), op=prem(); if(!np||!op) return null;
  const owned=SLOTS.filter(s=>S.owned[s.id]); let extra=owned.filter(s=>!slotFits(s,np));
  const svc=owned.filter(s=>s.zone==='svc2'), cap=(typeof EXTRA_CAP!=='undefined'&&EXTRA_CAP[np.id])||2; if(svc.length>cap) extra=extra.concat(svc.slice(cap));
  const sale=Math.round(extra.reduce((a,s)=>a+s.price,0)*MOVE.resale/1e5)*1e5;
  const fee=Math.round(owned.filter(s=>!extra.includes(s)).reduce((a,s)=>a+s.price,0)*MOVE.fee/1e5)*1e5;
  const early=S.day-S.leaseDay<MOVE.minLease, refund=early?0:op.rent*2, up=np.rent*3+(np.fit||0);
  const total=up+fee-refund-sale;
  const fixed=np.rent+(S.debt>0?monthlyPay():0)+S.staff.reduce((a,s)=>a+s.monthly,0)+(S.cashier?CASHIER.monthly:0), reserve=fixed;
  const why=S.prem==='resort'?'Đã ở resort':S.moving?'Đang chuẩn bị dọn tiệm':(S.loan&&S.loan.od>0)?'Đang có nợ quá hạn':S.cash-total<reserve?`Cần còn lại ít nhất ${fmt(reserve)} (1 tháng chi phí cố định) sau khi chuyển`:null;
  return {np, op, extra, sale, fee, early, refund, up, total, reserve, why}; }
function doMove(id){ const q=moveQuote(id); if(!q||q.why) return;
  S.cash-=q.total; S.moving={to:id, day:S.day+1, extra:q.extra.map(s=>s.id)};
  addLog(`Chuyển sang ${q.np.name}: cọc + tháng đầu + sửa sang${q.fee?' + phí chuyển đồ':''}${q.refund?' − cọc cũ':''}${q.sale?' − bán đồ dư':''}`,-q.total);
  save(); renderAll(); toast(`Đã ký thuê ${q.np.name}. Ngày mai nghỉ 1 ngày để dọn tiệm.`,'good'); }
startDay=(orig=>function(){
  const mv=S.moving&&S.day>=S.moving.day? S.moving : null;
  if(mv){ (mv.extra||[]).forEach(id=>{ delete S.owned[id]; if(S.wear) delete S.wear[id]; if(S.lv) delete S.lv[id]; });
    S.prem=mv.to; S.leaseDay=S.day; S.rentMul=1; const np=prem(); if(np&&np._baseRent){ np.rent=np._baseRent; }
    S.prices={}; SK.forEach(k=>{ if(S.skills[k]) S.prices[k]=market(k); }); S.returning=0; S.referrals=0; S.movedDay=S.day; S.moving=null; }
  orig();
  if(mv){ S.time=OPEN_END; drawScene(); ensureWorkers(); renderAll(); setTimeout(()=>toast(`Dọn sang ${prem().name}. Hôm nay nghỉ để sắp xếp, mai mở cửa.`,'good'),400); }
})(startDay);
hourCurve=(orig=>function(){ const d=S.movedDay?S.day-S.movedDay:99; return orig()*(d<MOVE.rampDays? MOVE.rampFrom+(1-MOVE.rampFrom)*d/MOVE.rampDays : 1); })(hourCurve);
function moveCard(){ if(!S.prem||S.prem==='resort') return '';
  const others=PREMISES.filter(p=>p.id!==S.prem&&p.id!=='resort');
  const rows=others.map(p=>{ const q=moveQuote(p.id), up=p.lvl>prem().lvl;
    return `<div class="item" style="align-items:flex-start"><div class="grow"><div class="n">${up?'⬆️':'⬇️'} ${esc(p.name)} <span class="stars">${'★'.repeat(p.lvl+1)}</span></div>
      <div class="m">Thuê ${fmt(p.rent)}/tháng · tối đa ${p.demand} khách/ngày · ${p.chairs} ghế, ${p.rooms} phòng · khách nước ngoài ${Math.round(p.mix[2]*100)}%</div>
      <div class="m">Cọc + tháng đầu + sửa sang ${fmt(q.up)} · chuyển đồ ${fmt(q.fee)}${q.refund?` · nhận lại cọc cũ −${fmt(q.refund)}`:' · <b>mất cọc cũ</b> (thuê chưa đủ 6 tháng)'}${q.sale?` · bán ${q.extra.length} món dư −${fmt(q.sale)}`:''}</div>
      <div class="m"><b>Cần trả ${fmt(q.total)}</b>${q.why?` · <span style="color:var(--danger)">${q.why}</span>`:''}</div></div>
      <button class="btn sm ${up?'butter':'alt'}" data-move="${p.id}" ${q.why?'disabled':''}>Chuyển</button></div>`; }).join('');
  return `<div class="card"><div class="sec-t">Chuyển mặt bằng</div><p class="note">Đang thuê ${esc(prem().name)} từ ngày ${S.leaseDay} (${S.day-S.leaseDay} ngày). Chuyển xong nghỉ 1 ngày dọn tiệm; khách khu mới chưa biết tiệm nên 20 ngày đầu vắng hơn, khách hẹn quay lại mất hết. Đích cuối vẫn là Resort.</p><div class="list" style="margin-top:6px">${rows}</div></div>`; }
renderScreen=(orig=>function(){ orig(); if(tab!=='book') return; const D=$('#dyn'), r=D&&[...D.querySelectorAll('.card')].find(c=>/Mở Resort/.test(c.textContent)); const h=moveCard(); if(!h) return; if(r) r.insertAdjacentHTML('beforebegin',h); else D.insertAdjacentHTML('beforeend',h); })(renderScreen);
$('#dyn').addEventListener('click',e=>{ const b=e.target.closest('[data-move]'); if(!b||b.disabled) return; const id=b.dataset.move;
  if(armed!=='move'+id){ armed='move'+id; b.textContent='Bấm lần nữa để chắc'; return; } armed=null; doMove(id); });

// 15r-campaign.js — v3.1: 3 map chơi lần lượt, chuỗi tiệm, chi phí sinh hoạt, vật phẩm theo map, vật phẩm hiếm
// - Ai cũng mở ở chợ đêm Dương Đông → mở tiệm Trần Hưng Đạo → mở tiệm Sunset → resort.
// - Mở map mới KHÔNG đóng tiệm cũ: tiệm cũ thành chi nhánh do thợ tự chạy (chạy nền), doanh thu về tiền chung.
//   Chủ chỉ đứng ở 1 tiệm mỗi ngày; muốn về tiệm khác thì đổi (có hiệu lực sáng hôm sau).
//   Chi nhánh không có chủ làm kém hơn (78% công suất, có quản lý 92%), thợ có thể phạm lỗi, nghỉ việc → báo qua điện thoại.
// - Mang theo: tiền (chung), cấp nghề chủ tiệm, uy tín (chung). Map mới là tiệm trống: sắm đồ, tuyển thợ mới.
// - Tiền thuê thu theo ngày (11-tick). Tiền nhà ở + điện nước nhà chủ = 50% (tiền thuê + điện nước) của tiệm lớn nhất, trừ mỗi ngày,
//   chỉ ghi vào Nhật ký, không thông báo.
// - Mỗi map có bộ 6 vật phẩm riêng (cùng nguồn rơi: mini game) và bộ trang trí theo chủ đề.
// - 2 vật phẩm hiếm xuyên suốt: hiện ngẫu nhiên, phải hoàn thành thử thách; ở dạng bán mở khoá (lợi ích nhỏ), lên resort mới mở hết.
'use strict';
// Nhà cung cấp quen cho nợ gối đầu tiền vật tư tới 20tr; âm quá mức đó thì phải mua lẻ ngoài chợ giá cao hơn 30% (tiệm vẫn làm được, nhưng lỗ thêm)
const SUP_CREDIT=20e6;
const CAMP={order:['chodem','thd','sunset'], living:.5, eff:{none:.78, mgr:.92}, perWorker:5.5, bgDemand:1.6, maxMsgs:60};
// Điều kiện mở tiệm tiếp theo (vốn đối ứng: ngân hàng thường đòi người vay tự có một phần vốn cho dự án mới)
const GATES={
  thd:{from:'chodem', days:45, stars:4.2, skill:8,  items:4, net30:20e6, own:60e6,  paid:3, loanCap:180e6},
  sunset:{from:'thd', days:60, stars:4.4, skill:18, items:6, net30:100e6, own:150e6, paid:6, loanCap:300e6}
};
// 20e: hạn mức giảm ~40%. v3.1c: hạn mức vay mở chi nhánh theo loại vay (tín chấp được vay ít hơn hẳn thế chấp)
const LOAN_CAP={de:{thd:180e6,sunset:300e6}, vua:{thd:120e6,sunset:180e6}, kho:{thd:60e6,sunset:90e6}};
const loanCapOf=id=>((LOAN_CAP[S.diff]||LOAN_CAP.vua)[id])||GATES[id].loanCap;
Object.assign(RESORT_RULE,{cash:1e9, skill:24, stars:4.5}); // đủ cọc resort + sắm đồ giá resort; chạy thử 1,5 tỷ làm map Sunset kéo dài 175–260 ngày
const SHOP_KEYS=['owned','wear','lv','staff','cashier','manager','prices','stock','returning','referrals','leaseDay','movedDay','prep','awayStaff','autoFix','selfHaggle','svcLog','staffDoneSinceIssue','rentMul'];
const premOf=id=>id==='resort'?RESORT_PREM:PREMISES.find(p=>p.id===id);
const shopName=id=>{ const p=premOf(id); return p?p.name:id; };
PREMISES.concat([RESORT_PREM]).forEach(p=>{ p._base0=p._baseRent||p.rent; });
function freshShopData(id){ const prices={}; return {owned:{}, wear:{}, lv:{}, staff:[], cashier:null, manager:false, prices, stock:freshStock(),
  returning:0, referrals:0, leaseDay:S.day, movedDay:S.day, prep:{sandbag:0,generator:false,tank:false}, awayStaff:[], autoFix:!!S.autoFix, selfHaggle:!!S.selfHaggle,
  svcLog:[], staffDoneSinceIssue:0, rentMul:1, fresh:true}; }
function freshStock(){ const st=Object.assign({},fresh().stock); SUPK.forEach(k=>{ if(st[k]===undefined) st[k]=Math.round(SUP[k].cap*.3); }); return st; }
const clone=o=>JSON.parse(JSON.stringify(o===undefined?null:o));

// ---------- dữ liệu chuỗi tiệm + chuyển save cũ ----------
S.brMsgs=S.brMsgs||[]; S.rare=Object.assign({have:{}, quest:null, cd:{}}, S.rare||{}); S.camp=Object.assign({legacy:false}, S.camp||{});
if(!S.shops){ S.shops={};
  if(S.prem){ S.shops[S.prem]={id:S.prem, opened:S.leaseDay||1, data:null, nets:[]}; if(S.prem!=='chodem') S.camp.legacy=true; } }
// vật phẩm theo map: bộ Bãi Trường cũ (S.tr) thành bộ của Sunset
if(!S.trm){ S.trm={chodem:{have:{},pity:{},dup:0}, thd:{have:{},pity:{},dup:0}, sunset:S.tr||{have:{},pity:{},dup:0}}; }
const trSet=(id=S.prem)=>S.trm[id==='resort'?'sunset':id]||S.trm.sunset;
S.tr=trSet();
// tiền thuê từng mặt bằng theo hệ số tăng giá riêng của từng hợp đồng
function applyRents(){ Object.keys(S.shops).forEach(id=>{ const p=premOf(id), sh=S.shops[id]; if(!p) return; const mul=sh.data?(sh.data.rentMul||1):(S.rentMul||1); p.rent=Math.round(p._base0*mul/1e5)*1e5; }); }
applyRents();

// ---------- đổi tiệm đang đứng ----------
function snapShop(id){ const d={}; SHOP_KEYS.forEach(k=>d[k]=clone(S[k])); S.shops[id].data=d; }
function loadShop(id){ const d=S.shops[id].data; SHOP_KEYS.forEach(k=>{ if(d[k]!==undefined) S[k]=clone(d[k]); }); S.shops[id].data=null; S.prem=id;
  if(id==='resort') addResortPrem();
  SK.forEach(k=>{ if(S.skills[k] && !S.prices[k]) S.prices[k]=market(k); }); SUPK.forEach(k=>{ if(S.stock[k]===undefined) S.stock[k]=Math.round(SUP[k].cap*.3); });
  S.tr=trSet(); applyThemeDecor(); applyRents(); }
function doSwitch(id){ if(!S.shops[id]||id===S.prem) return false; const wasFresh=!!S.shops[id].data.fresh; snapShop(S.prem); loadShop(id); delete S.fresh; return wasFresh; }
startDay=(orig=>function(){
  const to=S.switchTo; S.switchTo=null;
  if(to && S.shops[to] && to!==S.prem){ const empty=doSwitch(to);
    if(empty){ S.stage='build'; S.time=0; S.stats=freshStats(); guests.forEach(g=>{ g.el.remove(); if(g.bub) g.bub.remove(); }); guests.length=0;
      save(); drawScene(); ensureWorkers(); renderAll();
      setTimeout(()=>toast(`Nhận chìa khoá ${shopName(to)}! Sắm đồ, tuyển KTV rồi bấm Khai trương.`,'good'),300); return; }
    setTimeout(()=>toast(`Hôm nay ${S.owner||'chủ tiệm'} đứng ở ${shopName(to)}.`,'good'),300); }
  orig(); if(rareOffer) setTimeout(rareOffer,900);
})(startDay);

// ---------- đổi tiệm NGAY, lúc nào cũng được (21n) ----------
// Đang mở cửa: dịch vụ đang làm chạy cho xong (thu tiền ngay), khách còn xếp hàng/ngồi chờ ra về, hẹn quay lại chưa tới được trả lại tiệm cũ.
// Tiệm cũ KHÔNG đóng cửa: phần còn lại của ngày (tỉ lệ theo giờ mở cửa còn lại) chạy theo chế độ chi nhánh, cuối ngày tính sổ chung.
// Tiệm mới: phần đầu ngày (tỉ lệ giờ đã qua) tính theo chế độ chi nhánh, từ lúc sang là chủ điều khiển trực tiếp.
// 22e: bỏ giới hạn "giữa ngày chỉ đổi 1 lần" và "đang trả giá không đổi được" (đang trả giá thì khách bỏ về, không phạt).
function addNet(id,net){ const sh=S.shops[id], a=sh.nets||(sh.nets=[]), l=a[a.length-1];
  if(l&&l.d===S.day) l.net+=net; else a.push({d:S.day,net}); if(a.length>40) a.splice(0,a.length-40); }
function settleOpenShop(){
  guests.slice().forEach(g=>{ if(g.state==='service'&&g.worker){ g.problem=null; try{ finishService(g); g.problem=null; pay(g); }catch(e){ console.warn('settle',e); } } });
  const left=returnQueue.splice(0); left.forEach(q=>{ if(q.kind==='ret') S.returning++; else S.referrals++; });
  guests.forEach(g=>{ g.el.remove(); if(g.bub) g.bub.remove(); }); guests.length=0;
  W=W.filter(w=>{ if(w.kind==='fly'){ w.walker.el.remove(); return false; } w.state='idle'; w.arr=false; w.walker.el.classList.remove('working','walking'); return true; });
  busyChair={}; busyBed={}; flyCalls=[]; timers.length=0; seats.fill(null); stands.fill(null); }
window.shopGoNow=function(id){ if(!S.shops[id]||id===S.prem) return false;
  const mid=S.stage==='open';
  if(S.stage!=='closed'&&S.stage!=='build'&&!mid) return false;
  if(mid && haggling) closeHaggle();   // 22e: đang trả giá mà đổi map = khách bỏ về (không mất tiền, không trừ sao); settleOpenShop dọn khách
  const from=S.prem;
  const f=mid?clamp(Math.min(S.time,OPEN_END)/OPEN_END,0,1):0;
  let early=null;
  if(mid){ settleOpenShop(); const st2=S.stats; const soFar2=(st2.rev+st2.tips+st2.comm)-st2.costs-st2.sup, sv2=st2.served;
    snapShop(from);
    const o=simBranch(from,1-f,true); S.shops[from].partialDay=S.day;
    if(o){ const tot=soFar2+o.net; addNet(from,tot);
      const po0=(S.partialOuts||[]).find(q=>q.id===from);   // 23b: đổi map nhiều lần trong ngày → gộp 1 dòng/tiệm, tổng tiền giữ nguyên
      if(po0){ po0.served+=sv2+o.served; po0.net+=tot; po0.util=o.util; po0.rentDay=o.rentDay; }
      else S.partialOuts=(S.partialOuts||[]).concat({id:from, served:sv2+o.served, net:tot, util:o.util, rentDay:o.rentDay}); }
    const tgt=S.shops[id]; if(tgt.data&&!tgt.data.fresh&&f>0) early=simBranch(id,f,false);
    }
  else snapShop(from);
  const wasFresh=!!S.shops[id].data.fresh; loadShop(id); delete S.fresh; S.switchTo=null;
  if(wasFresh){ S.stage='build'; S.time=0; S.stats=freshStats(); guests.forEach(g=>{ g.el.remove(); if(g.bub) g.bub.remove(); }); guests.length=0; }
  else if(mid){ S.stage='open'; S.stats=freshStats(); if(early){ S.stats.rev+=early.gross; S.stats.served+=early.served; S.stats.costs+=early.cost; } spawnT=3; }
  save(); drawScene(); ensureWorkers(); renderAll(); setTimeout(()=>toast(wasFresh?`Nhận chìa khoá ${shopName(id)}! Sắm đồ, tuyển KTV rồi bấm Khai trương.`:mid?`Ngài sang ${shopName(id)} giữa ngày. ${shopName(from)} vẫn chạy tiếp do KTV trông.`:`Ngài đã sang ${shopName(id)}.`,'good'),300); return true; };

// ---------- mở đầu: luôn mở ở chợ đêm ----------
premises=function(){ const p=PREMISES[0], up=upfront(p);
  sheet(`${steps(4)}<h2>${esc(p.name)}</h2><p class="note">${esc(p.desc)}</p>
    <dl class="ledger" style="font-size:var(--fz-ghichu)"><dt>Ghế massage chân</dt><dd>tối đa ${p.chairs}</dd><dt>Phòng body</dt><dd>tối đa ${p.rooms}</dd><dt>Thuê</dt><dd>${fmt(p.rent)}/tháng</dd><dt>Cọc 2 tháng</dt><dd>${fmt(p.rent*2)}</dd><dt>Sửa sang</dt><dd>${fmt(p.fit||0)}</dd><dt class="sum">Trả trước</dt><dd class="sum">${fmt(up)}</dd></dl>
    <p class="note">Hành trình: Chợ đêm → Trần Hưng Đạo → Sunset → Resort. Mở tiệm mới thì tiệm cũ vẫn chạy tiếp thành chi nhánh. Sau khi ký còn phải sắm ${TEN.batbuoc} (khoảng 27tr) mới khai trương được.</p>
    <div class="row"><button class="btn big butter" data-go>Ký hợp đồng thuê</button></div>`, sh=>{
      sh.querySelector('[data-go]').onclick=()=>{ S.prem=p.id; S.cash-=up; S.leaseDay=S.day; S.shops={chodem:{id:'chodem', opened:S.day, data:null, nets:[]}}; S.tr=trSet();
        addLog('Cọc 2 tháng, sửa sang: '+p.name,-up); S.stage='build'; save(); closeSheet(); drawScene(); ensureWorkers(); renderAll(); toast('Nhận chìa khoá! Vào tab Mua sắm để sắm ' + TEN.batbuoc + '.','good'); if(S.cicRun&&window.cicOffer) setTimeout(cicOffer,1200); };
    }); };

// ---------- đồ trong tiệm đổi theo chủ đề từng map (tên + mô tả; hình dùng chung tới khi có bộ đồ hoạ riêng) ----------
// Đặc tả hình: docs/chu-de-vat-pham-theo-map.md. Ô có số (ghế 1–8, phòng 1–4, giường da mặt, bàn nail, bồn thảo dược) dùng chung 1 mẫu.
const THEME={
  chodem:{cashier:'Quầy gỗ tạp, hộp đèn menu', sofa:'Băng ghế gỗ và ghế nhựa đỏ', tea:'Bình trà đá, ly nhựa', chair:'Ghế lười vải dù', room:'Giường body (rèm vải hoa)', trolley:'Xe đẩy inox đá nóng', changing:'Góc thay đồ rèm treo', towel:'Tủ nhựa và nồi hấp khăn',
    facial:'Giường xếp chăm sóc da (đèn kẹp)', nail:'Bàn nail xếp (đèn bàn)', sauna:'Lều xông lá', herbal:'Bồn tắm composite',
    art:'Tranh thuyền thúng, ghe câu mực', plant1:'Chậu bông giấy', plant2:'Chậu trầu bà treo', lamps:'Đèn lồng vải', lights:'Dây đèn hạt bắp', buddha:'Bàn thờ Thần Tài – Ông Địa', fish:'Hồ cá vàng mini', fountain:'Lu sành trồng sen'},
  thd:{cashier:'Quầy đá trắng, máy POS', sofa:'Sofa nỉ xám', tea:'Bàn kính, nước detox chanh sả', chair:'Ghế da ngả điện', room:'Phòng body (vách gỗ, giường điện)', trolley:'Xe gỗ sồi đá nóng', changing:'Tủ locker khoá số', towel:'Tủ hấp khăn inox',
    facial:'Giường điện chăm sóc da (máy soi da)', nail:'Bàn nail kính hút bụi', sauna:'Cabin xông gỗ thông', herbal:'Bồn gỗ pơ-mu',
    art:'Tranh phố Tây về đêm', plant1:'Cau kiểng', plant2:'Chậu lưỡi hổ', lamps:'Đèn mây tre', lights:'Hộp đèn neon song ngữ', buddha:'Tượng Phật gỗ', fish:'Bể thuỷ sinh', fountain:'Tiểu cảnh đá cuội và tre'},
  sunset:{cashier:'Quầy cong ốp gạch bông', sofa:'Sofa mây trắng gối xanh biển', tea:'Bàn gạch bông, nước dừa', chair:'Ghế mây trắng lưng cao', room:'Phòng body vòm trắng, rèm voan', trolley:'Xe mây trắng đá nóng', changing:'Tủ thay đồ gỗ sơn xanh', towel:'Tủ khăn gỗ trắng',
    facial:'Giường trắng chăm sóc da (đèn vòng)', nail:'Bàn nail ốp gạch bông', sauna:'Cabin xông kính nhìn biển', herbal:'Bồn sứ ngoài ban công',
    art:'Tranh hoàng hôn trên biển', plant1:'Chậu ô liu', plant2:'Chậu oải hương', lamps:'Đèn tường sắt rèn', lights:'Dây bóng tròn kiểu Ý', buddha:'Bình gốm lớn và san hô', fish:'Bể san hô biển', fountain:'Đài phun gạch bông'},
  resort:{cashier:'Quầy thu ngân gỗ teak, chuông đồng', sofa:'Daybed teak nệm kem', tea:'Khay gốm trà thảo mộc', chair:'Ghế da cao cấp, bồn ngâm đá', room:'Cabana mái lá', trolley:'Xe teak đá bazan', changing:'Phòng thay đồ có vòi sen', towel:'Tủ ủ khăn tinh dầu',
    facial:'Giường teak chăm sóc da (máy oxy)', nail:'Bàn nail cẩm thạch', sauna:'Phòng xông đá muối', herbal:'Bồn đá nguyên khối ngoài trời',
    art:'Tranh sơn mài', plant1:'Chuối rẻ quạt', plant2:'Dương xỉ treo', lamps:'Đèn lồng đồng', lights:'Đuốc tre', buddha:'Tượng Phật đá thiền', fish:'Hồ cá koi', fountain:'Thác đá, hồ tràn mini'}
};
const ORIG_NAME={}; SLOTS.forEach(s=>ORIG_NAME[s.id]=s.name);
// Giá đồ theo map: đồ bình dân ở chợ đêm rẻ hơn, đồ Địa Trung Hải ở Sunset và đồ resort đắt hơn
const PRICE_MUL={chodem:.7, thd:1, sunset:1.3, resort:1.6};
SLOTS.forEach(s=>{ if(s._p0===undefined) s._p0=s.price; });
const priceAt=(s,id)=>Math.round(s._p0*(PRICE_MUL[id]||1)/1e5)*1e5;
const themeKey=s=>s.zone==='chan'?'chair':s.id.startsWith('room')?'room':s.st&&s.zone==='svc2'?s.st:s.id;
function applyThemeDecor(){ const t=THEME[S.prem]; SLOTS.forEach(s=>{ s.price=priceAt(s,S.prem); const k=themeKey(s), nm=t&&t[k]; if(!nm){ s.name=ORIG_NAME[s.id]; return; }
  const num=(s.id.match(/\d+$/)||[])[0]; s.name=(['chair','room','facial','nail','herbal'].includes(k)&&num)? `${nm} ${num}` : nm; }); }
applyThemeDecor();
const themeFull=()=>SLOTS.filter(s=>s.zone==='dc').every(s=>S.owned[s.id]);

// ---------- vật phẩm theo map ----------
const MAP_ITEMS={
  chodem:{map:'Sổ tay bấm huyệt của bà lang', silk:'Khăn rằn chợ đêm', agar:'Chai dầu tràm Cửa Cạn', pearl:'Đồng xu cổ Dinh Cậu', bell:'Đèn lồng giấy đỏ', gourd:'Hũ tiêu sọ Phú Quốc'},
  thd:{map:'Bảng huyệt đạo song ngữ', silk:'Khăn bông khách sạn 5 sao', agar:'Tinh dầu sả chanh Hàm Ninh', pearl:'Thẻ hội viên vàng', bell:'Chuông xe đạp phố Tây', gourd:'Gáo dừa Dương Đông'},
  sunset:null
};
const MAP_SET_NAME={chodem:'vật phẩm Chợ đêm', thd:'vật phẩm Trần Hưng Đạo', sunset:'bảo vật Bãi Trường'};
const itemName=(k,id=S.prem)=>{ const m=MAP_ITEMS[id==='resort'?'sunset':id]; return (m&&m[k])||TREASURES[k].name; };
const itemCount=id=>Object.keys((S.trm[id]||{have:{}}).have).length;
rollTreasure=function(k,force){ if(S.prem==='resort') return; const T=TREASURES[k], set=trSet(); set.pity[k]=(set.pity[k]||0)+1;
  if(!(force || Math.random()<T.p || set.pity[k]>=T.pity)) return; set.pity[k]=0; const nm=itemName(k);
  if(set.have[k]){ set.dup++; toast(`Lại được ${nm} (trùng). Đủ 3 món trùng đổi được 1 món còn thiếu.`,'good'); }
  else { set.have[k]=true; setTimeout(()=>{ sheet(`<div class="mg-grade gS">${mgImg(T.img)}</div><h2 style="text-align:center">${nm}!</h2><p class="note" style="text-align:center">${Object.keys(set.have).length}/6 ${MAP_SET_NAME[S.prem]||'vật phẩm'}. Mỗi món giúp khách khu này biết tiệm hơn.</p><div class="row"><button class="btn big butter" data-x>Tuyệt!</button></div>`, sh=>sh.querySelector('[data-x]').onclick=()=>{ closeSheet(); renderAll(); }); },600); }
  save(); };
tradeDup=function(k){ const set=trSet(); if(set.dup<3||set.have[k]) return; set.dup-=3; set.have[k]=true; save(); toast(`Đổi 3 món trùng lấy ${itemName(k)}.`,'good'); renderScreen(); };
// lượng khách: vật phẩm map (+1%/món), đủ bộ trang trí (+5%), vật phẩm hiếm Kỳ nam
hourCurve=(orig=>function(){ let m=1+.01*Object.keys(S.tr.have).length; if(themeFull()) m*=1.05; if(S.rare.have.kynam) m*=S.prem==='resort'?1.15:1.03; return orig()*m; })(hourCurve);

// ---------- vật phẩm hiếm ----------
const RARE={
  pearlking:{name:'Ngọc trai vua An Thới', img:'i_star', cond:'Trong 10 ngày phục vụ 25 khách hài lòng từ 90 điểm', days:10, need:25,
    small:'Khách chịu giá cao hơn', big:'Ở resort: khách VIP trả cao hơn, tip nhiều hơn'},
  kynam:{name:'Kỳ nam Hòn Thơm', img:'m_oil6', cond:'Trong 14 ngày có 3 ngày doanh thu từ 1,5 lần trung bình 14 ngày trước đó', days:14, need:3,
    small:'Khách tới nhiều hơn', big:'Ở resort: khách đông hơn, khách lưu trú dùng thêm dịch vụ'}
};
function rareOffer(){ const R=S.rare; if(R.quest||S.day<30||S.stage!=='open'||S.bankrupt) return;
  const ks=Object.keys(RARE).filter(k=>!R.have[k] && (R.cd[k]||0)<=S.day); if(!ks.length || Math.random()>=.012) return;
  const k=pick(ks), X=RARE[k];
  const t=k==='pearlking'?'Một ông lão làm nghề nuôi ngọc ở An Thới ghé tiệm, kể rằng ông giữ một viên ngọc trai vua. Ông chỉ trao nó cho tiệm nào thật sự chiều khách.'
    :'Một người đi rừng Hòn Thơm mang tới mẩu kỳ nam quý. Anh chỉ để lại cho tiệm làm ăn thật sự đắt khách.';
  sheet(`<div class="mg-grade gS">${mgImg(X.img)}</div><h2 style="text-align:center">Vật phẩm hiếm: ${X.name}</h2><p class="note">${t}</p>
    <div class="check"><i></i><span><b>Thử thách:</b> ${X.cond}.</span></div>
    <p class="note">Nhận được thì vật phẩm ở dạng <b>bán mở khoá</b>: ${X.small.toLowerCase()}. Mang lên Resort mới mở hết tác dụng: ${X.big.replace('Ở resort: ','').toLowerCase()}.</p>
    <div class="row"><button class="btn alt" data-no>Để dịp khác</button><button class="btn big butter" data-yes>Nhận thử thách</button></div>`, sh=>{
      sh.querySelector('[data-no]').onclick=()=>{ R.cd[k]=S.day+20; save(); closeSheet(); };
      sh.querySelector('[data-yes]').onclick=()=>{ R.quest={k, until:S.day+X.days-1, prog:0}; save(); closeSheet(); toast(`Thử thách ${X.name}: ${X.cond}.`,'good'); renderAll(); };
    }); }
finishService=(orig=>function(g){ orig(g); const q=S.rare.quest; if(q&&q.k==='pearlking'&&g.sat>=90) q.prog++;
  if(S.rare.have.pearlking && S.prem==='resort' && g.tip) g.tip=Math.round(g.tip*1.2/1000)*1000; })(finishService);
spawn=(orig=>function(kind){ const n=guests.length; orig(kind); const g=guests.length>n?guests[guests.length-1]:null; if(!g) return;
  let m=1; if(S.rare.have.pearlking) m*=S.prem==='resort'?1.12:1.03; if(S.rare.have.kynam && S.prem==='resort') m*=1.10; g.M*=m; })(spawn);
function rareEndDay(){ const R=S.rare, q=R.quest; if(!q) return '';
  const X=RARE[q.k];
  if(q.k==='kynam'){ const L=(S.svcLog||[]).slice(-15,-1), avg=L.length>=5?L.reduce((a,x)=>a+(x.gross||0),0)/L.length:Infinity, today=(S.svcLog||[]).at(-1);
    if(today && today.gross>=avg*1.5) q.prog++; }
  if(q.prog>=X.need){ R.have[q.k]=true; R.quest=null; save();
    setTimeout(()=>sheet(`<div class="mg-grade gS">${mgImg(X.img)}</div><h2 style="text-align:center">Đã nhận ${X.name}!</h2><p class="note" style="text-align:center">Bán mở khoá: ${X.small.toLowerCase()}.<br>${X.big}.</p><div class="row"><button class="btn big butter" data-x>Cất kỹ</button></div>`, sh=>sh.querySelector('[data-x]').onclick=closeSheet),500);
    return `<div class="note">✨ Hoàn thành thử thách <b>${X.name}</b>!</div>`; }
  if(S.day>=q.until){ R.quest=null; R.cd[q.k]=S.day+40; return `<div class="note" style="color:var(--danger)">Hết hạn thử thách ${X.name} (${q.prog}/${X.need}). Vật phẩm sẽ còn quay lại dịp khác.</div>`; }
  return `<div class="note">Thử thách ${X.name}: ${q.prog}/${X.need}, còn ${q.until-S.day} ngày.</div>`; }

// ---------- chi nhánh chạy nền ----------
function brMsg(id,t,warn){ S.brMsgs.push({d:S.day, shop:id, t, warn:!!warn}); S.brMsgs=S.brMsgs.slice(-CAMP.maxMsgs); if(tab!=='phone'||phoneTab!=='branch') unread.branch=true; }
function seasonDemand(p){ const M=MONTHS[monthOf()], mix=p.mix||[.3,.3,.4]; return mix[0]+mix[1]*M.d+mix[2]*M.f; }
const WXF={rain:.8, heavy:.55, storm1:.6, storm3:.6, outage:.7};
function bgStations(d,p){ const ch=SLOTS.filter(s=>s.zone==='chan'&&d.owned[s.id]&&s.seat<p.chairs).length, bd=SLOTS.filter(s=>s.id.startsWith('room')&&d.owned[s.id]&&s.need<p.rooms).length;
  return {ch, bd, svc:SLOTS.filter(s=>s.zone==='svc2'&&d.owned[s.id]).length}; }
// frac<1: chỉ chạy phần còn lại của ngày (21n). fixed=false: không tính chi phí cố định (tiền thuê, lương, quản lý, điện nước nền) vì ngày đó tính ở chỗ khác
function simBranch(id,frac=1,fixed=true){ const sh=S.shops[id], d=sh.data, p=premOf(id); if(!d||!p) return null;
  if(d.fresh){ if(!fixed||S.day<sh.opened) return null; const r=Math.round(p.rent/30/1000)*1000; S.cash-=r; return {id, served:0, gross:0, cost:r, net:-r, util:0, rentDay:r}; } // ký rồi chưa khai trương: chỉ tốn tiền thuê
  const st=bgStations(d,p), stations=st.ch+st.bd+st.svc, workers=d.staff.length, mgr=!!d.manager;
  const out={id, served:0, gross:0, cost:0, net:0, notes:[]};
  // chi phí cố định vẫn chạy kể cả khi chưa có thợ
  const rentDay=Math.round(p.rent/30/1000)*1000;
  const wages=d.staff.reduce((a,s)=>a+Math.round(s.monthly/30),0)+(d.cashier?Math.round((CASHIER.monthly+CASHIER.step*(d.cashier.lv-1))/30):0)+(mgr?Math.round(MANAGER.monthly/30):0);
  let served=0, late=false, skim=0;
  // sự cố của thợ (không có chủ đứng tiệm)
  const pInc=.035*(mgr?.4:1)*frac;
  d.staff.forEach(s=>{ if(Math.random()>=pInc) return; const r=Math.random();
    if(r<.3){ late=true; brMsg(id,`${s.name} đi trễ 2 tiếng, bỏ lỡ khách buổi trưa.`); }
    else if(r<.55){ const c=Math.round(rnd(3,15))*1e5; out.cost+=c; brMsg(id,`${s.name} làm hỏng đồ, sửa hết ${fmt(c)}.`,true); }
    else if(r<.8){ addBranchReview(id,s); brMsg(id,`Khách phàn nàn ${s.name} làm ẩu, để lại đánh giá xấu.`,true); }
    else if(!d.cashier){ skim+=.08; brMsg(id,`Sổ thu chi lệch: nghi ${s.name} ém tiền khách trả mặt.`,true); }
    else { d.staff.forEach(x=>x.morale=clamp(x.morale-8,0,100)); brMsg(id,`${s.name} cãi nhau với đồng nghiệp, cả tiệm mất vui.`); } });
  if(workers && stations && !isTet()){
    const demand=p.demand*CAMP.bgDemand*seasonDemand(p)*(WXF[S.wx&&S.wx.today]||1)*clamp(.6+.15*(rating()-3),.4,1.05)*(1+.01*itemCount(id==='resort'?'sunset':id));
    const cap=Math.min(workers*CAMP.perWorker, stations*7);
    served=Math.round(Math.min(demand,cap)*(mgr?CAMP.eff.mgr:CAMP.eff.none)*rnd(.85,1.15)*(late?.85:1)*frac); }
  // giá trung bình theo dịch vụ thợ làm được
  const ks=SK.filter(k=>d.staff.some(s=>s.skills[k]) && (SERVICES[k].st==='chair'?st.ch:st.bd) && (!SERVICES[k].item||d.owned[SERVICES[k].item]));
  const wsum=ks.reduce((a,k)=>a+SERVICES[k].w,0)||1, avgP=ks.length? ks.reduce((a,k)=>a+(d.prices[k]||Math.round(p.market*SERVICES[k].mul/1e4)*1e4)*SERVICES[k].w,0)/wsum : 0;
  const gross=Math.round(served*avgP*(1-skim)/1000)*1000;
  const tua=Math.round(gross*TUA), sup=Math.round(gross*.07), wear=Math.round(gross*.02);
  const kwh=(fixed?p.kwh+3*(st.ch+st.bd):0)+.8*served, util=Math.round(kwh*ELEC+((fixed?.6:0)+.05*served)*WATER);
  const misc=fixed?Math.round((p.misc||5e6)/30/1000)*1000:0, laundry=served*LAUNDRY;
  // thuế hộ kinh doanh: cộng doanh thu chi nhánh vào doanh thu năm
  const before=Math.max(0,S.yr.rev-TAX.free); S.yr.rev+=gross; const tax=Math.round((Math.max(0,S.yr.rev-TAX.free)-before)*TAX.rate/1000)*1000; S.taxPaid+=tax;
  out.cost+=(fixed?rentDay+wages:0)+tua+sup+wear+util+misc+laundry+tax; out.served=served; out.gross=gross; out.net=gross-out.cost; out.util=util; out.rentDay=rentDay;
  S.cash+=out.net; d.svcLog=(d.svcLog||[]).concat({d:S.day, served, gross, bg:true}).slice(-60);
  // tinh thần thợ: ít tua thì chán; quản lý giữ người
  if(!fixed) return out;   // phần đầu ngày của tiệm sắp có chủ đứng: chưa tính tinh thần/nghỉ việc, endDay của tiệm đó lo
  const per=workers?served/workers:0, quits=[];
  d.staff.forEach(s=>{ s.morale=clamp(s.morale-1+(per>=4?1.5:per<2?-3:0)+(mgr?1:0),0,100); if((s.morale<25&&Math.random()<.5)||Math.random()<.002) quits.push(s); });
  quits.forEach(s=>{ d.staff=d.staff.filter(x=>x!==s); brMsg(id,`${s.name} nhắn: "Em xin nghỉ việc từ mai." Chi nhánh còn ${d.staff.length} KTV.`,true);
    setTimeout(()=>toast(`📱 ${shopName(id)}: ${s.name} xin nghỉ việc.`,'warn'),1200); });
  if(workers && !d.staff.length) brMsg(id,'Chi nhánh không còn KTV nào: vẫn phải trả tiền thuê mỗi ngày. Vào Sổ sách › Chuỗi tiệm để tuyển hoặc điều KTV.',true);
  brMsg(id,`Báo cáo ngày ${S.day}${frac<1?' (phần còn lại sau khi chủ đi)':''}: ${served} khách, thu ${fmt(gross)}, ${out.net>=0?'lãi':'lỗ'} ${fmt(Math.abs(out.net))}.`);
  return out; }
function addBranchReview(id,s){ const stars=Math.random()<.5?1:2;
  S.reviews.unshift({id:S.rv.nextId++, d:S.day, t:0, name:vnName(), type:'dl', stars, orig:stars, text:`Chi nhánh ${shopName(id)}: thợ làm qua loa, chủ không có mặt.`, svc:'foot', reasons:['lazy'], staffId:null, w:1, blogger:false, reply:null});
  S.reviews=S.reviews.slice(0,RV.keep); unread.reviews=true; }
const lastNets=(id,n=30)=>(S.shops[id].nets||[]).filter(x=>x.d>S.day-n).reduce((a,x)=>a+x.net,0);

// ---------- cuối ngày: chi nhánh, sinh hoạt phí, tăng giá thuê theo năm ----------
endDay=(orig=>function(){
  const st=S.stats; orig(); if(S.bankrupt) return;
  const act=S.shops[S.prem]; if(act){ addNet(S.prem,(st.rev+st.tips+st.comm)-st.costs-st.sup); }
  const outs=[]; const po=S.partialOuts||[]; S.partialOuts=[];   // 21n: tiệm chủ vừa rời giữa ngày đã tính xong ngày hôm nay (nets đã ghi)
  Object.keys(S.shops).forEach(id=>{ if(id===S.prem) return; if(S.shops[id].partialDay===S.day){ const x=po.find(q=>q.id===id); if(x) outs.push(x); return; } const o=simBranch(id); if(o){ outs.push(o); S.shops[id].nets=(S.shops[id].nets||[]).concat({d:S.day,net:o.net}).slice(-40); } });
  // tiền nhà ở + điện nước nhà chủ: 50% (tiền thuê + điện nước) của tiệm lớn nhất; chỉ ghi Nhật ký
  const big=Object.keys(S.shops).filter(id=>id!=='resort').map(premOf).sort((a,b)=>b.rent-a.rent)[0];
  if(big){ const isAct=big.id===S.prem, o=outs.find(x=>x.id===big.id);
    const util=isAct? Math.round((big.kwh+3*(ownedChairs().length+ownedBeds().length)+.8*st.served)*ELEC+(.6+.05*st.served)*WATER) : (o?o.util:Math.round(big.kwh*ELEC));
    const live=Math.round(CAMP.living*(big.rent/30+util)/1000)*1000; S.cash-=live;
    S.log.unshift({t:`Ngày ${S.day}: tiền nhà ở + điện nước nhà (chủ tiệm)`, a:-live, d:S.day}); S.log=S.log.slice(0,80); S.liveTotal=(S.liveTotal||0)+live; }
  // tăng giá thuê mỗi năm hợp đồng (+10%)
  Object.keys(S.shops).forEach(id=>{ if(id==='resort') return; const sh=S.shops[id], d=sh.data||S, lease=d.leaseDay||sh.opened; if(S.day>lease && (S.day-lease)%360===0){ d.rentMul=Math.round((d.rentMul||1)*1.1*100)/100; applyRents(); inboxMsg('Chủ nhà',`Gia hạn hợp đồng ${shopName(id)}: tiền thuê tăng, thành ${fmt(premOf(id).rent)}/tháng.`); } });
  let extra=rareEndDay();
  if(outs.length) extra+=`<div class="note">Chi nhánh: ${outs.map(o=>`${esc(shopName(o.id))} ${o.served} khách, ${o.net>=0?'+':'−'}${fmt(Math.abs(o.net))}`).join(' · ')}</div>`;
  const row=$('#sheet .row:last-child'); if(row && extra) row.insertAdjacentHTML('beforebegin',extra);
  save(); renderNav();
})(endDay);

// ---------- mở tiệm tiếp theo ----------
const nextMap=()=>CAMP.order.find(id=>!S.shops[id]);
function gateChecks(id){ const G=GATES[id]; if(!G) return []; const from=S.shops[G.from];
  return [
    {t:`${shopName(G.from)} kinh doanh đủ ${G.days} ngày — hiện ${from?Math.max(0,S.day-from.opened):0}`, ok:!!from&&S.day-from.opened>=G.days},
    {t:`Uy tín từ ${String(G.stars).replace('.',',')}★ (hiện ${rating().toFixed(1).replace('.',',')}★)`, ok:rating()>=G.stars},
    {t:`Tổng cấp nghề chủ tiệm từ ${G.skill} (hiện ${skillTotal()})`, ok:skillTotal()>=G.skill},
    {t:`Có ${G.items}/6 ${MAP_SET_NAME[G.from]} (hiện ${itemCount(G.from)})`, ok:itemCount(G.from)>=G.items},
    {t:`${shopName(G.from)} lãi từ ${fmt(G.net30)} trong 30 ngày gần nhất (hiện ${fmt(from?lastNets(G.from):0)})`, ok:!!from&&lastNets(G.from)>=G.net30},
    {t:`Vốn tự có từ ${fmt(G.own)} (hiện ${fmt(S.cash)})`, ok:S.cash>=G.own},
    {t:'Không có nợ quá hạn', ok:!(S.loan&&S.loan.od>0)}
  ]; }
function loanOk(id){ const G=GATES[id], L=S.loan; if(S.cicRun) return [false,'hồ sơ CIC xấu: ván này không có ngân hàng hỗ trợ']; if(L.lock) return [false,'ngân hàng khóa vay vì đã trả trễ (mở lại khi tất toán khoản vay hiện tại)']; if(L.od>0) return [false,'đang có nợ quá hạn']; if(L.cicUntil>S.day) return [false,'CIC còn ghi nợ nhóm 2'];
  if(S.debt>0 && L.paidOnTime<G.paid) return [false,`cần góp đúng hạn ${G.paid} kỳ (đã ${L.paidOnTime})`]; if(S.credit&&(S.credit.cf||S.credit.ls)) return [false,'đang nợ công ty tài chính/vay nóng']; return [true,'']; }
function openNext(id,loan){ const p=premOf(id), up=upfront(p); if(!gateChecks(id).every(c=>c.ok) || S.shops[id]) return;
  const fixed=p.rent+(S.debt+loan>0?0:0); if(S.cash+loan-up<fixed) { toast('Không đủ tiền: sau khi trả cọc và sửa sang phải còn ít nhất 1 tháng tiền thuê.','warn'); return; }
  if(loan>0){ const [ok]=loanOk(id); if(!ok) return; const d=DIFFS[S.diff]||DIFFS.vua; S.debt+=loan; S.cash+=loan;
    S.loan.terms={amount:Math.round(S.debt), months:d.months, yearRate:d.yearRate}; Object.assign(LOAN,S.loan.terms);
    addLog(`Vay mở chi nhánh ${p.name}`,loan); setTimeout(cicWarn,800); inboxMsg('Ngân hàng',`Giải ngân ${fmt(loan)} mở tiệm ${p.name}. Dư nợ gộp ${fmt(S.debt)}, lãi ${pctRate()}, góp ${fmt(periodPay())} mỗi kỳ 10 ngày.`); }
  S.cash-=up; addLog(`Cọc 2 tháng, sửa sang: ${p.name}`,-up);
  S.shops[id]={id, opened:S.day+1, data:freshShopData(id), nets:[]}; S.shops[id].data.leaseDay=S.day+1; S.shops[id].data.movedDay=S.day+1;
  S.switchTo=id; if(window.cicCheckClear) cicCheckClear(); save(); closeSheet(); renderAll();
  toast(`Đã ký thuê ${p.name}! Sáng mai sang sắm sửa tiệm mới. ${shopName(S.prem)} vẫn chạy tiếp do KTV trông.`,'good'); }
function openNextSheet(id){ const G=GATES[id], p=premOf(id), up=upfront(p), d=DIFFS[S.diff]||DIFFS.vua, [lok,lwhy]=loanOk(id);
  let amt=0; const cap=loanCapOf(id), opts=[0,cap/2,cap];
  const pay=a=>{ if(!(S.debt+a>0)) return 0; return periodPayFor(S.debt+a,d.yearRate,d.months,S.diff); };
  const draw=()=>sheet(`<h2>Mở tiệm ${esc(p.name)}</h2><p class="note">${esc(p.desc)}</p>
    <dl class="ledger" style="font-size:var(--fz-ghichu)"><dt>Ghế / phòng tối đa</dt><dd>${p.chairs} ghế · ${p.rooms} phòng</dd><dt>Thuê</dt><dd>${fmt(p.rent)}/tháng</dd><dt>Cọc 2 tháng + sửa sang</dt><dd>${fmt(up)}</dd><dt>Khách nước ngoài</dt><dd>${Math.round(p.mix[2]*100)}%</dd></dl>
    <div class="sec-t" style="margin-top:8px">Vay mở chi nhánh (lãi ${pctRate()}, góp mỗi kỳ 10 ngày)</div>
    ${lok?`<div class="seg">${opts.map(a=>`<button data-amt="${a}" aria-pressed="${amt===a}">${a?fmt(a):'Không vay'}</button>`).join('')}</div>
    <p class="note">Dư nợ gộp sau vay ${fmt(S.debt+amt)} · góp ${fmt(pay(amt))} mỗi kỳ 10 ngày.</p><p class="note" style="color:var(--danger)"><b>Cảnh báo CIC:</b> ${CIC_TXT}</p>`:`<p class="note">Chưa vay được: ${lwhy}.</p>`}
    <p class="note">Tiệm mới trống: phải sắm đồ, tuyển KTV. ${esc(shopName(S.prem))} vẫn mở, KTV tự chạy (kém hơn khi vắng chủ; thuê quản lý thì đỡ). Tiền nhà ở của chủ tính theo tiệm lớn nhất.</p>
    <div class="row"><button class="btn alt" data-x>Để sau</button><button class="btn big butter" data-go>Ký thuê · trả ${fmt(up)}</button></div>`, sh=>{
      sh.querySelectorAll('[data-amt]').forEach(b=>b.onclick=()=>{ amt=+b.dataset.amt; draw(); });
      sh.querySelector('[data-x]').onclick=closeSheet; sh.querySelector('[data-go]').onclick=()=>openNext(id,amt); });
  draw(); }

// ---------- resort: mở thành tiệm thứ 4, chuỗi cũ vẫn chạy ----------
const branchNet30=()=>Object.keys(S.shops).filter(id=>id!==S.prem&&id!=='resort').reduce((a,id)=>a+lastNets(id),0);
function chainOk(){ return CAMP.order.every(id=>S.shops[id] || S.camp.legacy) && branchNet30()>=0; }
resortChecks=(orig=>function(){ const cs=orig(); cs[0]={t:`Đủ 6 bảo vật Bãi Trường, tìm ở khu Sunset (${itemCount('sunset')}/6)`, ok:itemCount('sunset')>=6};
  return cs.concat([{t:`Chuỗi 3 tiệm Chợ đêm, Trần Hưng Đạo, Sunset đều đang mở; các chi nhánh vắng chủ không lỗ trong 30 ngày gần nhất (hiện ${branchNet30()>=0?'lãi':'lỗ'} ${fmt(Math.abs(branchNet30()))})`, ok:chainOk()}]); })(resortChecks);
moveResort=function(){ if(S.shops.resort || !resortChecks().every(c=>c.ok)) return; const up=upfront(RESORT_PREM); if(S.cash<up) return;
  addResortPrem(); RESORT_PREM._base0=RESORT_PREM._base0||RESORT_PREM.rent; S.cash-=up; addLog('Nhận thầu khu spa resort: cọc 2 tháng',-up);
  S.shops.resort={id:'resort', opened:S.day+1, data:freshShopData('resort'), nets:[]}; S.shops.resort.data.leaseDay=S.day+1; S.switchTo='resort'; S.resortDay=S.day+1; save(); renderAll();
  sheet(`<div class="mg-grade gS">${mgImg('w_rep_0')}</div><h2 style="text-align:center">${esc(S.name)} nhận thầu khu spa Resort Bãi Trường!</h2>
    <dl class="ledger"><dt>Số ngày kinh doanh</dt><dd>${S.day}</dd><dt>Tổng lượt khách</dt><dd>${S.totals.served}</dd><dt>Tổng doanh thu</dt><dd>${fmt(S.totals.rev)}</dd><dt>Uy tín</dt><dd>${rating().toFixed(1).replace('.',',')}★</dd><dt>Chuỗi tiệm</dt><dd>${Object.keys(S.shops).length} điểm</dd></dl>
    <p class="note">Sáng mai sang Resort sắm sửa khu spa mới. Ba tiệm cũ vẫn chạy tiếp. ${Object.keys(S.rare.have).length?'Vật phẩm hiếm đã mở hết tác dụng ở Resort.':'Vật phẩm hiếm còn thiếu vẫn có thể xuất hiện.'}</p>
    <div class="row"><button class="btn big butter" data-x>Tuyệt vời</button></div>`, sh=>sh.querySelector('[data-x]').onclick=closeSheet); };
resortCard=(orig=>function(){ if(!S.shops.sunset && S.prem!=='resort') return ''; if(S.shops.resort && S.prem!=='resort') return `<div class="card"><div class="sec-t">Resort Bãi Trường <span class="tag">đã nhận thầu</span></div><p class="note">Đổi sang làm ở Resort trong thẻ Chuỗi tiệm.</p></div>`; return orig(); })(resortCard);
moveCard=()=>'';

// ---------- thẻ Chuỗi tiệm + Hành trình (Sổ sách) ----------
const net7=id=>lastNets(id,7);
function chainCard(){ if(!S.prem) return ''; const ids=Object.keys(S.shops);
  const rows=ids.map(id=>{ const act=id===S.prem, d=act?S:S.shops[id].data, p=premOf(id); if(!d) return '';
    const st=d.staff||[], pend=S.switchTo===id, fresh=!!(S.shops[id].data&&S.shops[id].data.fresh);
    const others=ids.filter(x=>x!==S.prem);
    const staffRows=act? (others.length?st.map(s=>`<div class="m">${esc(s.name)} · tinh thần ${Math.round(s.morale)} ${others.map(o=>`<button class="btn sm alt" data-cmv="${S.prem}|${s.id}|${o}">→ ${esc(shopName(o).split(' ').slice(-2).join(' '))}</button>`).join(' ')}</div>`).join(''):'')
      : st.map(s=>`<div class="m">${esc(s.name)} · tinh thần ${Math.round(s.morale)} <button class="btn sm alt" data-cmv="${id}|${s.id}|${S.prem}">Điều về tiệm đang làm</button></div>`).join('');
    return `<div class="item" style="align-items:flex-start"><div class="grow"><div class="n">${esc(p.name)} ${act?'<span class="tag">đang làm ở đây</span>':fresh?'<span class="tag">chưa khai trương</span>':'<span class="tag">KTV tự chạy</span>'}${pend?' <span class="tag">sáng mai sang</span>':''}</div>
      <div class="m">${st.length} KTV${d.cashier?' · thu ngân':''}${d.manager?' · quản lý':''} · thuê ${fmt(p.rent)}/tháng · 7 ngày ${net7(id)>=0?'lãi':'lỗ'} ${fmt(Math.abs(net7(id)))} · 30 ngày ${fmt(lastNets(id))}</div>
      ${staffRows}
      ${act?'':`<div class="row" style="gap:6px;margin-top:4px;flex-wrap:wrap">${pend?'':`<button class="btn sm butter" data-cgo="${id}">Sang làm ở đây (sáng mai)</button>`}
        ${fresh?'':`<button class="btn sm alt" data-chire="${id}" ${S.cands.length&&st.length<p.chairs+p.rooms?'':'disabled'}>Tuyển KTV</button><button class="btn sm alt" data-cmgr="${id}">${d.manager?'Cho quản lý nghỉ':'Thuê quản lý '+fmt(MANAGER.monthly)+'/th'}</button>`}
        <button class="btn sm alt" data-cclose="${id}">Trả mặt bằng</button></div>`}</div></div>`; }).join('');
  let h=`<div class="card"><div class="sec-t">Chuỗi tiệm <span class="note">${ids.length} điểm</span></div><p class="note">Tiền dùng chung. Tiệm vắng chủ do KTV tự chạy, có việc thì báo ở Điện thoại › Chi nhánh.</p><div class="list" style="margin-top:6px">${rows}</div></div>`;
  const nx=nextMap(); if(nx&&GATES[nx]){ const cs=gateChecks(nx), ok=cs.every(c=>c.ok), set=trSet(GATES[nx].from);
    const items=Object.keys(TREASURES).map(k=>{ const hv=set.have[k]; return `<div class="item${hv?'':' own'}">${mgImg(TREASURES[k].img,'ico'+(hv?'':' dim'))}<div class="grow"><div class="n">${itemName(k,GATES[nx].from)} ${hv?'<span class="tag">Đã có</span>':''}</div><div class="m">${TREASURES[k].src}</div></div>${!hv&&set.dup>=3&&S.prem===GATES[nx].from?`<button class="btn sm lav" data-trade="${k}">Đổi 3 trùng</button>`:''}</div>`; }).join('');
    h+=`<div class="card"><div class="sec-t">Mở tiệm tiếp theo: ${esc(shopName(nx))} <span class="note">${cs.filter(c=>c.ok).length}/${cs.length}</span></div>
      <div class="list" style="margin-top:6px">${cs.map(c=>`<div class="check${c.ok?' ok':''}"><i></i><span>${c.t}</span></div>`).join('')}</div>
      <button class="btn big ${ok?'butter':'alt'}" data-cnext="${nx}" style="margin-top:8px" ${ok?'':'disabled'}>${ok?'Xem hợp đồng thuê':'Chưa đủ điều kiện'}</button>
      <details style="margin-top:8px"><summary class="sec-t">6 ${MAP_SET_NAME[GATES[nx].from]} và nơi tìm ▾</summary><div class="list" style="margin-top:6px">${items}</div><p class="note">Vật phẩm rơi theo khu đang đứng. Món trùng: ${set.dup}.</p></details></div>`; }
  const R=S.rare; h+=`<div class="card"><div class="sec-t">Vật phẩm hiếm</div><div class="list" style="margin-top:6px">${Object.entries(RARE).map(([k,X])=>`<div class="item${R.have[k]?'':' own'}">${mgImg(X.img,'ico'+(R.have[k]?'':' dim'))}<div class="grow"><div class="n">${X.name} ${R.have[k]?`<span class="tag">${S.prem==='resort'?'Đã mở hết':'Bán mở khoá'}</span>`:R.quest&&R.quest.k===k?'<span class="tag">Đang thử thách</span>':''}</div><div class="m">${R.have[k]?(S.prem==='resort'?X.big:X.small+' · lên resort: '+X.big.replace('Ở resort: ','')):R.quest&&R.quest.k===k?`${X.cond}: ${R.quest.prog}/${X.need}, còn ${R.quest.until-S.day} ngày`:'Chưa xuất hiện. Có thể tới bất kỳ lúc nào sau ngày 30.'}</div></div></div>`).join('')}</div></div>`;
  return h; }
renderScreen=(orig=>function(){ orig(); if(tab==='book'){ const D=$('#dyn'), first=D&&D.querySelector('.card'); if(first) first.insertAdjacentHTML('afterend',chainCard()); }
  if(tab==='phone'){ const D=$('#dyn');
    if(phoneTab==='branch'){ unread.branch=false; D.innerHTML=branchHTML(); renderNav(); return; }
    const seg=D.querySelector('.seg'); if(seg && Object.keys(S.shops).length>1 && !seg.querySelector('[data-pt="branch"]')) seg.insertAdjacentHTML('beforeend',`<button data-pt="branch" aria-pressed="false">Chi nhánh${unread.branch?' •':''}</button>`); } })(renderScreen);
function branchHTML(){ const seg=`<div class="seg"><button data-pt="group" aria-pressed="false">Nhóm Bay</button><button data-pt="inbox" aria-pressed="false">Tin khách</button><button data-pt="reviews" aria-pressed="false">Đánh giá</button><button data-pt="branch" aria-pressed="true">Chi nhánh</button></div>`;
  const feed=S.brMsgs.slice().reverse().map(m=>`<div class="pm${m.warn?' rep':''}"><b>${esc(shopName(m.shop))} · ngày ${m.d}</b>${esc(m.t)}</div>`).join('');
  return seg+`<div class="phone-app"><div class="pa-top"><div class="gav">CN</div><div><div class="n">Báo cáo chi nhánh</div><div class="note">KTV ở các tiệm vắng chủ nhắn về: báo cáo cuối ngày, lỗi, xin nghỉ.</div></div></div><div class="pa-feed">${feed||'<div class="pm sys">Chưa có tin nhắn.</div>'}</div></div>`; }
renderNav=(orig=>function(){ orig(); if(unread.branch){ const b=$('#nav [data-tab="phone"]'); if(b&&!b.querySelector('.dot')) b.insertAdjacentHTML('beforeend','<span class="dot"></span>'); } })(renderNav);
function moveStaff(from,sid,to){ const src=from===S.prem?S:S.shops[from].data, dst=to===S.prem?S:S.shops[to].data; if(!src||!dst) return;
  const s=src.staff.find(x=>x.id==sid); if(!s) return; const p=premOf(to); if(dst.staff.length>=p.chairs+p.rooms){ toast('Tiệm đó đã đủ người.','warn'); return; }
  src.staff=src.staff.filter(x=>x!==s); dst.staff.push(s); s.morale=clamp(s.morale-5,0,100); ensureWorkers(); save(); renderScreen(); toast(`${s.name} chuyển sang ${shopName(to)}.`,'good'); }
function closeShop(id){ if(id===S.prem||!S.shops[id]) return; const d=S.shops[id].data, p=premOf(id), lease=S.day-(d.leaseDay||S.shops[id].opened);
  const dep=lease>=180?p.rent*2:0, sale=Math.round(SLOTS.filter(s=>d.owned[s.id]).reduce((a,s)=>a+priceAt(s,id),0)*.4/1e5)*1e5;
  S.cash+=dep+sale; delete S.shops[id]; addLog(`Trả mặt bằng ${p.name}${dep?' (nhận lại cọc)':' (mất cọc, thuê chưa đủ 6 tháng)'} + bán đồ`,dep+sale);
  brMsg(id,`Đã trả mặt bằng. ${d.staff.length} KTV nghỉ việc.`,true); save(); renderAll(); toast(`Đã đóng ${p.name}: nhận ${fmt(dep+sale)}.`,'warn'); }
$('#dyn').addEventListener('click',e=>{ const b=e.target.closest('button'); if(!b||b.disabled) return; const d=b.dataset;
  if(d.cgo){ S.switchTo=d.cgo; save(); renderScreen(); toast(`Sáng mai sang ${shopName(d.cgo)}.`,'good'); }
  if(d.cnext) openNextSheet(d.cnext);
  if(d.cmv){ const [f,s,t]=d.cmv.split('|'); moveStaff(f,s,t); }
  if(d.chire){ const sh=S.shops[d.chire].data, c=S.cands.slice().sort((a,b)=>b.st.q-a.st.q)[0]; if(!sh||!c) return; S.cands=S.cands.filter(x=>x!==c);
    sh.staff.push({id:c.id,name:c.name,rank:c.rank,skills:c.skills,st:c.st,monthly:c.monthly,lvl:1,xp:0,morale:70,look:c.look,taught:{},lazy:false,fine:0,done:0,pay2:1});
    brMsg(d.chire,`${c.name} nhận việc ở chi nhánh, lương cứng ${fmt(c.monthly)}/tháng.`); save(); renderScreen(); toast(`${c.name} về làm ở ${shopName(d.chire)}.`,'good'); }
  if(d.cmgr){ const sh=S.shops[d.cmgr].data; if(!sh) return; sh.manager=!sh.manager; save(); renderScreen(); }
  if(d.cclose){ if(armed!=='close'+d.cclose){ armed='close'+d.cclose; b.textContent='Bấm lần nữa để trả mặt bằng'; return; } armed=null; closeShop(d.cclose); } });

// 15s-ui.js — v3.1c: Sổ sách gọn mắt — mỗi thẻ thu lại chỉ còn dòng tiêu đề (kèm tình trạng), bấm để mở.
// "Tình hình tiệm" luôn mở. Thẻ nào đang mở được nhớ trong lượt chơi (và trong trình duyệt nếu được).
'use strict';
const BOOK_ALWAYS=['Tình hình tiệm'];
let BOOK_OPEN=new Set();
try{ BOOK_OPEN=new Set(JSON.parse(localStorage.getItem('spa-book-open')||'[]')); }catch(e){}
const bookKey=t=>t.replace(/\s+/g,' ').replace(/[\d.,]+[a-zđ%★]*|\(.*?\)/gi,'').trim().split(' ').slice(0,4).join(' ');
function foldBook(){ const D=$('#dyn'); if(!D) return;
  [...D.children].forEach(c=>{ if(!c.classList.contains('card')||c.dataset.fold) return; const t=c.querySelector(':scope > .sec-t'); if(!t) return;
    const title=t.textContent, k=bookKey(title); if(BOOK_ALWAYS.some(x=>title.startsWith(x))) return;
    c.dataset.fold='1'; const d=document.createElement('details'); d.className='fold'; d.dataset.k=k; if(BOOK_OPEN.has(k)) d.open=true;
    const s=document.createElement('summary'); s.className='fold-s'; s.appendChild(t); d.appendChild(s);
    while(c.firstChild) d.appendChild(c.firstChild); d.insertBefore(s,d.firstChild); c.appendChild(d);
    d.addEventListener('toggle',()=>{ if(d.open) BOOK_OPEN.add(k); else BOOK_OPEN.delete(k); try{ localStorage.setItem('spa-book-open',JSON.stringify([...BOOK_OPEN])); }catch(e){} }); });
  // nút "Làm lại" cuối trang: gom vào một thẻ thu gọn
  const rs=[...D.children].find(x=>x.classList&&x.classList.contains('btn')&&x.classList.contains('danger'));
  if(rs && !rs.closest('details')){ const d=document.createElement('details'); d.className='card fold'; d.innerHTML='<summary class="fold-s"><span class="sec-t">Cài đặt ván chơi</span></summary>'; rs.replaceWith(d); d.appendChild(rs); } }
renderScreen=(orig=>function(){ orig(); if(tab==='book') foldBook(); })(renderScreen);

// 15t-sound.js — v3.2: hệ thống âm thanh tổng hợp bằng Web Audio (không cần file âm thanh)
// - Nhạc nền spa: tự sinh (pad + bass + chuông gảy, hợp âm Cmaj7 · Am7 · Fmaj7 · G6, 72 nhịp/phút, có vọng).
// - Âm nền: mưa theo cường độ, sấm khi có tia sét, sóng biển ở Sunset và resort.
// - Hiệu ứng: bấm nút, tiền vào, khách trả tiền, chuông điện thoại, tin tốt / cảnh báo, pháo hoa, 2048 (lướt, gộp, mốc), bảo vật, cuối ngày.
// - Trình duyệt chỉ cho phát tiếng sau lần chạm đầu tiên: âm thanh bật ở lần chạm đầu.
// - Cài đặt: nút loa trên thanh trên cùng (bật/tắt tất cả); chỉnh từng phần ở Sổ sách › Âm thanh.
'use strict';
S.snd=Object.assign({on:true, music:.45, sfx:.8, amb:.6}, S.snd||{});
// 19v: công tắc riêng Nhạc / Hiệu ứng (lưu localStorage, tách khỏi save ván)
const MIX={mus:true, fx:true};
try{ const m=JSON.parse(localStorage.getItem('spa-snd-mix')||'{}'); if(m.mus===false) MIX.mus=false; if(m.fx===false) MIX.fx=false; }catch(e){}
function mixSave(){ try{ localStorage.setItem('spa-snd-mix',JSON.stringify(MIX)); }catch(e){} }
const SND={ctx:null, master:null, bus:{}, noise:null, rain:null, sea:null, musicT:0, step:0, timer:null, lastBolt:-9, ready:false};
function sndInit(){ if(SND.ctx) { if(SND.ctx.state==='suspended') SND.ctx.resume(); return; }
  const AC=window.AudioContext||window.webkitAudioContext; if(!AC) return;
  const c=SND.ctx=new AC(); SND.master=c.createGain(); const cmp=c.createDynamicsCompressor(); cmp.threshold.value=-14; cmp.ratio.value=6; cmp.attack.value=.01; cmp.release.value=.25; SND.master.connect(cmp); cmp.connect(c.destination);
  ['music','sfx','amb'].forEach(k=>{ const g=c.createGain(); g.connect(SND.master); SND.bus[k]=g; });
  // vọng cho nhạc và chuông
  const dl=c.createDelay(1), fb=c.createGain(), wet=c.createGain(); dl.delayTime.value=.36; fb.gain.value=.32; wet.gain.value=.35;
  dl.connect(fb); fb.connect(dl); dl.connect(wet); wet.connect(SND.bus.music); SND.echo=dl;
  // nhiễu trắng dùng chung (mưa, sóng, sấm, lướt)
  const len=c.sampleRate*2, b=c.createBuffer(1,len,c.sampleRate), d=b.getChannelData(0); let last=0;
  for(let i=0;i<len;i++){ const w=Math.random()*2-1; last=(last+.02*w)/1.02; d[i]=w*.6+last*3; } SND.noise=b;
  SND.ready=true; sndApply(); sndAmbLoop(); sndMusicStart(); }
function sndApply(){ if(!SND.ctx) return; const t=SND.ctx.currentTime, on=S.snd.on&&!document.hidden;
  SND.master.gain.setTargetAtTime(on?1:0,t,.08); SND.bus.music.gain.setTargetAtTime(MIX.mus?S.snd.music*.7:0,t,.2);
  SND.bus.sfx.gain.setTargetAtTime(MIX.fx?S.snd.sfx:0,t,.05); SND.bus.amb.gain.setTargetAtTime(MIX.fx?S.snd.amb:0,t,.3); renderSndBtn(); }
['pointerdown','keydown'].forEach(ev=>document.addEventListener(ev,()=>{ if(S.snd.on) sndInit(); },{capture:true,passive:true}));
document.addEventListener('visibilitychange',sndApply);

// ---------- công cụ dựng tiếng ----------
function tone(f,dur,o){ o=o||{}; if(!SND.ready) return; const c=SND.ctx, t=c.currentTime+(SND.off||0)+(o.at||0), osc=c.createOscillator(), g=c.createGain();
  osc.type=o.type||'sine'; osc.frequency.setValueAtTime(f,t); if(o.to) osc.frequency.exponentialRampToValueAtTime(o.to,t+dur);
  const v=o.vol||.3, a=o.att||.005; g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(v,t+a); g.gain.exponentialRampToValueAtTime(.0005,t+dur);
  osc.connect(g); g.connect(o.bus||SND.bus.sfx); if(o.echo) g.connect(SND.echo); osc.start(t); osc.stop(t+dur+.05); }
function noiseHit(dur,o){ o=o||{}; if(!SND.ready) return; const c=SND.ctx, t=c.currentTime+(SND.off||0)+(o.at||0), s=c.createBufferSource(), f=c.createBiquadFilter(), g=c.createGain();
  s.buffer=SND.noise; s.loop=true; f.type=o.ft||'bandpass'; f.frequency.setValueAtTime(o.f||1200,t); if(o.fto) f.frequency.exponentialRampToValueAtTime(o.fto,t+dur); f.Q.value=o.q||1;
  g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(o.vol||.3,t+(o.att||.005)); g.gain.exponentialRampToValueAtTime(.0005,t+dur);
  s.connect(f); f.connect(g); g.connect(o.bus||SND.bus.sfx); s.start(t,Math.random()*1.5); s.stop(t+dur+.05); }
const NOTE=n=>440*Math.pow(2,(n-69)/12);

// ---------- hiệu ứng ----------
const SFX={
  click:()=>tone(1500,.04,{type:'square',vol:.035}),
  coin:()=>{ tone(1318,.09,{type:'triangle',vol:.16}); tone(1975,.22,{type:'triangle',vol:.14,at:.07}); },
  pay:()=>{ tone(2093,.12,{type:'triangle',vol:.12}); tone(2637,.35,{type:'sine',vol:.12,at:.08,echo:true}); noiseHit(.05,{f:5000,vol:.05}); },
  good:()=>[72,76,79,84].forEach((n,i)=>tone(NOTE(n),.4,{type:'triangle',vol:.1,at:i*.07,echo:true})),
  warn:()=>{ tone(392,.18,{type:'triangle',vol:.14}); tone(311,.3,{type:'triangle',vol:.14,at:.16}); },
  phone:()=>{ tone(1568,.12,{vol:.12}); tone(2093,.2,{vol:.12,at:.13}); },
  ring:()=>{ for(let k=0;k<2;k++) for(let i=0;i<8;i++){ tone(480,.05,{type:'square',vol:.04,at:k*1.1+i*.06}); tone(620,.05,{type:'square',vol:.04,at:k*1.1+i*.06+.03}); } },
  treasure:()=>{ [67,71,74,79,83,86].forEach((n,i)=>tone(NOTE(n),.5,{type:'triangle',vol:.1,at:i*.06,echo:true})); noiseHit(.6,{f:8000,ft:'highpass',vol:.03,at:.1}); },
  dayEnd:()=>{ [60,64,67].forEach((n,i)=>tone(NOTE(n+12),1.4,{vol:.09,at:i*.12,echo:true})); },
  swipe:()=>noiseHit(.09,{f:900,fto:2400,q:.8,vol:.07}),
  merge:v=>{ const f=NOTE(60+Math.min(v,12)*2); tone(f,.14,{type:'triangle',vol:.14}); tone(f*1.5,.12,{vol:.06,at:.03}); },
  milestone:()=>[72,76,79,84,88].forEach((n,i)=>tone(NOTE(n),.45,{type:'triangle',vol:.11,at:i*.08,echo:true})),
  thunder:()=>{ const d=.25+Math.random()*.9; noiseHit(2.8,{ft:'lowpass',f:900,fto:70,q:.4,vol:.4,att:.03,at:d,bus:SND.bus.amb}); noiseHit(1.6,{ft:'lowpass',f:300,fto:50,vol:.3,at:d+.5,bus:SND.bus.amb}); },
  boom:s=>{ const v=Math.min(.5,.18+.18*(s||1)); tone(110,.6,{to:38,vol:v}); noiseHit(.5,{ft:'lowpass',f:1600,fto:120,vol:v*.8});
    for(let i=0;i<7;i++) noiseHit(.03,{f:4000+Math.random()*3000,q:3,vol:.05,at:.25+Math.random()*.6}); },
  whistle:()=>tone(700,.7,{to:1900,vol:.035,att:.1}),
  // 19v: sửa tiệm từng bước (n = bước 1..4): gõ búa, bước cuối thêm tiếng hoàn thành
  fix:n=>{ for(let i=0;i<2+n;i++){ noiseHit(.07,{f:1800+i*180,q:2.5,vol:.12,at:i*.11}); tone(190+n*25,.09,{type:'square',vol:.05,at:i*.11}); }
    if(n>=4) [60,64,67,72].forEach((m,i)=>tone(NOTE(m+12),.5,{type:'triangle',vol:.1,at:.55+i*.09,echo:true})); },
  unlock:()=>{ tone(NOTE(79),.12,{type:'triangle',vol:.1}); tone(NOTE(86),.5,{type:'sine',vol:.1,at:.09,echo:true}); noiseHit(.25,{f:7000,ft:'highpass',vol:.03,at:.08}); },
  moc:()=>[67,72,76].forEach((n,i)=>tone(NOTE(n),.35,{type:'triangle',vol:.1,at:i*.09,echo:true})),
  win:()=>{ [60,64,67,72,76,79,84].forEach((n,i)=>tone(NOTE(n),.9,{type:'triangle',vol:.1,at:i*.13,echo:true})); [72,76,79,84].forEach(n=>tone(NOTE(n),1.8,{vol:.07,at:.95,echo:true})); noiseHit(.8,{f:8000,ft:'highpass',vol:.04,at:.9}); }
};
function sfx(k,a){ try{ if(window.AUDIO&&AUDIO.over(k)) return; if(S.snd.on&&MIX.fx&&SND.ready&&SFX[k]) SFX[k](a); }catch(e){} }

// ---------- nhạc nền tự sinh ----------
// Hợp âm (MIDI): Cmaj7, Am7, Fmaj7, G6 — mỗi hợp âm 1 ô nhịp 4/4, 72 nhịp/phút
const PROG=[[48,60,64,67,71],[45,57,60,64,67],[41,57,60,65,69],[43,55,59,62,64]], PENTA=[72,74,76,79,81,84,86,88];
function sndMusicStart(){ if(SND.timer) return; SND.musicT=SND.ctx.currentTime+.3; SND.step=0; SND.timer=setInterval(sndSchedule,200); }
function sndSchedule(){ if(window.AUDIO&&AUDIO.suppressSynth()){ SND.musicT=Math.max(SND.musicT,SND.ctx.currentTime+.1); return; }   // 21e: có nhạc file thì thôi nhạc tổng hợp
  if(!SND.ready||!S.snd.on||!MIX.mus||document.hidden||S.snd.music<=0) { SND.musicT=Math.max(SND.musicT,SND.ctx.currentTime+.1); return; }
  const c=SND.ctx, beat=60/72, eighth=beat/2;
  while(SND.musicT<c.currentTime+1){ const t=SND.musicT, st=SND.step, bar=Math.floor(st/8)%PROG.length, ch=PROG[bar], at=t-c.currentTime;
    if(st%8===0){ // pad + bass đầu ô nhịp
      ch.slice(1,4).forEach((n,i)=>tone(NOTE(n),beat*4.2,{type:'sine',vol:.035,att:1.1,at,bus:SND.bus.music}));
      tone(NOTE(ch[0]),beat*3.6,{type:'triangle',vol:.06,att:.05,at,bus:SND.bus.music}); }
    // chuông gảy: hay rơi vào nốt hợp âm, đôi khi nốt ngũ cung; nghỉ ngẫu nhiên cho thoáng
    const p=st%2===0?.55:.3; if(Math.random()<p){ const pool=Math.random()<.65? ch.slice(1).map(n=>n+12) : PENTA; const n=pool[Math.floor(Math.random()*pool.length)];
      tone(NOTE(n),1.6,{type:'triangle',vol:.045+.02*Math.random(),att:.004,at,bus:SND.bus.music,echo:true}); }
    SND.step++; SND.musicT+=eighth; } }

// ---------- âm nền: mưa, sóng biển; sấm theo tia sét ----------
function loopNoise(ft,f,q){ const c=SND.ctx, s=c.createBufferSource(), fl=c.createBiquadFilter(), g=c.createGain(); s.buffer=SND.noise; s.loop=true; fl.type=ft; fl.frequency.value=f; fl.Q.value=q||.7;
  g.gain.value=0; s.connect(fl); fl.connect(g); g.connect(SND.bus.amb); s.start(); return {g, f:fl}; }
function sndAmbLoop(){ SND.rain=loopNoise('bandpass',2600,.5); SND.sea=loopNoise('lowpass',520,.6); SND.crowd=loopNoise('bandpass',650,.9); let ph=0;
  setInterval(()=>{ if(!SND.ready) return; const c=SND.ctx, t=c.currentTime, open=S.stage==='open'||S.stage==='closed';
    const w=S.wx&&S.wx.today, rv=open?({rain:.12, heavy:.26, outage:.16, storm1:.32, storm2:.4, storm3:.16})[w]||0:0;
    SND.rain.g.gain.setTargetAtTime(rv,t,.8);
    const seaOn=open&&(S.prem==='sunset'||S.prem==='resort'); ph+=.25; const swell=.5+.5*Math.sin(ph*2*Math.PI/7);
    // 19v: Chợ đêm — sóng nhỏ, tiếng chợ xa về đêm, chim buổi sáng (theo giờ của 15p-sky)
    const cd=S.prem==='chodem'&&open, h=cd?(S.stage==='open'?gameHour():26):0, nightK=cd?Math.max(0,Math.min(1,(h-18)/1.35)):0, wet=typeof wetNow==='function'&&wetNow();
    SND.crowd.g.gain.setTargetAtTime(cd?(.012+.05*nightK)*(.75+.25*Math.sin(ph*2*Math.PI/3.1)):0,t,.8);
    SND.crowd.f.frequency.setTargetAtTime(520+260*Math.sin(ph*2*Math.PI/5.3),t,.5);
    if(cd&&S.stage==='open'&&h<16.5&&!wet&&tab==='shop'&&!document.hidden&&Math.random()<.05) sndBird();
    SND.sea.g.gain.setTargetAtTime(seaOn?.04+.09*swell:cd?.015+.035*swell:0,t,.4); SND.sea.f.frequency.setTargetAtTime(380+420*swell,t,.4);
    if(typeof BOLT!=='undefined' && BOLT.at!==SND.lastBolt && BOLT.at>0){ SND.lastBolt=BOLT.at; if(tab==='shop') sfx('thunder'); } },250); }

function sndBird(){ if(!S.snd.on||!MIX.fx) return; const f=2400+Math.random()*1400, n=2+Math.floor(Math.random()*3), bus=SND.bus.amb;
  for(let i=0;i<n;i++) tone(f*(1+.06*i),.08,{to:f*(1.22+.06*i),vol:.045,at:i*.13,bus}); }

// ---------- gắn vào game ----------
document.addEventListener('click',e=>{ if(e.target.closest('button')) sfx('click'); },true);
toast=(orig=>function(msg,kind){ orig(msg,kind); if(kind==='good') sfx('good'); else if(kind==='warn') sfx('warn'); })(toast);
pay=(orig=>function(g){ const c0=S.cash; orig(g); if(S.cash>c0) sfx('pay'); })(pay);
if(typeof flyMoney==='function') flyMoney=(orig=>function(a,b,kind){ const r=orig(a,b,kind); if(kind==='tip') sfx('coin'); return r; })(flyMoney);
inboxMsg=(orig=>function(who,t,ic){ orig(who,t,ic); sfx('phone'); })(inboxMsg);
if(typeof brMsg==='function') brMsg=(orig=>function(id,t,warn){ orig(id,t,warn); if(warn) sfx('phone'); })(brMsg);
if(typeof debtCall==='function') debtCall=(orig=>function(...a){ sfx('ring'); return orig(...a); })(debtCall);
if(typeof rollTreasure==='function') rollTreasure=(orig=>function(k,f){ const n=Object.keys(S.tr.have).length, d=S.tr.dup; orig(k,f); if(Object.keys(S.tr.have).length>n) setTimeout(()=>sfx('treasure'),600); else if(S.tr.dup>d) sfx('coin'); })(rollTreasure);
endDay=(orig=>function(){ orig(); sfx('dayEnd'); })(endDay);
if(typeof fwBurst==='function') fwBurst=(orig=>function(r){ orig(r); if(tab==='shop') sfx('boom',r&&r.size); })(fwBurst);
if(typeof g2Celebrate==='function') g2Celebrate=(orig=>function(list){ orig(list); if(list&&list.length) sfx('milestone'); })(g2Celebrate);

// ---------- nút loa + thẻ cài đặt ----------
const SND_ICON=on=>`<img src="${on?'img/56b80d5f0ee1.png':'img/2d110850057d.png'}" alt="" aria-hidden="true" draggable="false">`;
function renderSndBtn(){ let b=$('#sndBtn'); if(!b){ const h=$('header.hud'); if(!h) return; h.insertAdjacentHTML('beforeend','<button class="snd-btn" id="sndBtn" aria-label="Bật/tắt âm thanh"></button>'); b=$('#sndBtn');
    b.addEventListener('click',e=>{ e.stopPropagation(); S.snd.on=!S.snd.on; if(S.snd.on) sndInit(); sndApply(); save(); }); }
  b.innerHTML=SND_ICON(S.snd.on); b.setAttribute('aria-pressed',String(!S.snd.on)); }
renderSndBtn();
// 22b: thẻ "Âm thanh" cũ đã gộp vào thẻ "Nhạc & tiếng nền" của 21e-audio.js (công tắc Nhạc / Tiếng điều khiển MIX.mus / MIX.fx qua SND_MIX).
window.SND_MIX={MIX,apply:()=>{ try{ sndApply(); }catch(e){} }};

// 15u-2048fx.js — v3.2: hiệu ứng lướt cho Tủ spa 2048
// Mỗi lần vuốt: các ô trượt từ chỗ cũ tới chỗ mới (120ms), 2 ô cùng số trượt chồng vào nhau rồi ô kết quả nảy lên,
// ô mới chỉ hiện sau khi trượt xong. Vuốt liên tục thì lần trượt trước kết thúc ngay để không chậm tay.
// Có tiếng lướt và tiếng gộp (cao dần theo giá trị ô). Người bật "giảm chuyển động" của máy thì bỏ trượt.
'use strict';
const G2FX={ms:120, fin:null};
// kế hoạch di chuyển, tính trên lưới TRƯỚC khi gộp (cùng luật với g2Move)
function g2Plan(g,dir){ const moves=[]; G2L[dir].forEach(line=>{ const tl=line.map(i=>({i,v:g.grid[i]})).filter(t=>t.v); let pos=0;
  for(let k=0;k<tl.length;k++){ const a=tl[k], b=tl[k+1];
    if(b&&b.v===a.v){ moves.push({from:a.i,to:line[pos],v:a.v}); moves.push({from:b.i,to:line[pos],v:b.v,m:true}); k++; }
    else moves.push({from:a.i,to:line[pos],v:a.v}); pos++; } }); return moves; }
g2Move=(orig=>function(g,dir){ const plan=g2Plan(g,dir); const r=orig(g,dir); r.moves=plan;
  if(r.moved){ sfx('swipe'); if(r.merged.length){ const v=Math.max(...r.merged.map(i=>g.grid[i])); setTimeout(()=>sfx('merge',v),G2FX.ms-20); } }
  return r; })(g2Move);
g2Render=(orig=>function(fx){ if(G2FX.fin) G2FX.fin();
  const el=$('#g2Grid'), wrap=el&&el.parentNode, reduce=(typeof FX!=='undefined'&&FX.reduce)||matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(!fx||!fx.moved||!fx.moves||!el||reduce||el.children.length!==16) return orig(fx);
  const W=wrap.getBoundingClientRect(), R=[...el.children].map(c=>{ const r=c.getBoundingClientRect(); return {x:r.left-W.left,y:r.top-W.top,w:r.width,h:r.height}; });
  const ov=document.createElement('div'); ov.className='g2-ov';
  fx.moves.forEach(m=>{ const src=el.children[m.from]; if(!src||src.classList.contains('empty')) return; const c=src.cloneNode(true); c.classList.remove('pop','new'); c.classList.add('g2-fly');
    const a=R[m.from], b=R[m.to]; Object.assign(c.style,{left:a.x+'px',top:a.y+'px',width:a.w+'px',height:a.h+'px'}); c.dataset.dx=b.x-a.x; c.dataset.dy=b.y-a.y; if(m.m) c.style.zIndex=1; ov.appendChild(c); });
  orig(fx); el.classList.add('g2-hold'); wrap.appendChild(ov);
  void ov.offsetWidth; ov.querySelectorAll('.g2-fly').forEach(c=>{ c.style.transform=`translate(${c.dataset.dx}px,${c.dataset.dy}px)`; });
  let done=false; const fin=()=>{ if(done) return; done=true; ov.remove(); el.classList.remove('g2-hold'); if(G2FX.fin===fin) G2FX.fin=null; };
  G2FX.fin=fin; setTimeout(fin,G2FX.ms+30); })(g2Render);

// 15v-haggle.js — v3.3: trả giá chi tiết hơn
// 1) Nguồn khách hiện rõ: khách nước ngoài theo quốc tịch (thêm Trung Quốc, Nhật, Đài Loan), khách du lịch trong nước theo tỉnh
//    (giọng Bắc / Trung / Nam), dân địa phương theo xã đảo. Quốc tịch và quê quán chỉ đổi lời chào, cách nói, tên, văn hoá tip.
// 2) Tính cách khách khi trả giá: rơi NGẪU NHIÊN cho mọi khách, không gắn với quốc tịch hay vùng miền.
//    Hiện ngay trên bảng trả giá kèm gợi ý để chủ tiệm tham khảo: sộp, khó tính, chần chừ, sành giá, đang vội, hay mặc cả, dễ tính.
//    Mỗi tính cách đổi số lượt, mức ra giá, bước nâng giá, ngưỡng bỏ đi, và câu nói.
'use strict';
// ---------- quốc tịch mới (hình tạm dùng chung, chờ bộ đồ hoạ) ----------
