  const setSub=k=>{ if(k===idx) return; idx=k; sub.textContent=KT[k][2]; };
  const end=()=>{ if(over) return; over=true; clearTimeout(tm); clearTimeout(vt); if(v){ try{ v.pause(); }catch(e){} } el.remove(); document.removeEventListener('keydown',key); if(done) done(); };
  function key(e){ if(e.key==='Escape') end(); }
  document.addEventListener('keydown',key);
  const stills=()=>{ if(over) return; if(v){ v.remove(); v=null; } clearTimeout(vt);
    const show1=k=>{ if(over) return; if(k>=KT.length) return end(); setSub(k); const old=el.querySelector('img'); if(old) old.remove(); const im=new Image(); im.alt=''; im.draggable=false; im.src=KT[k][1]; el.insertBefore(im,sub); clearTimeout(tm); tm=setTimeout(()=>show1(k+1),KT_S*1000); };
    el.onclick=e=>{ if(e.target.closest('.kt-skip')) return; show1(idx+1); }; show1(Math.max(0,idx)); };
  el.querySelector('.kt-skip').onclick=e=>{ e.stopPropagation(); end(); };
