// 17c-danhvong.js — Việc 15c: DANH VỌNG + BẢNG DANH VỌNG (docs/meo/KE-HOACH-MEO-DANH-VONG.md mục 3.1, 3.3; GDD). Nạp TRƯỚC 16-boot.js để thẻ vào Sổ sách trước khi bookPortrait/twoCol dựng danh sách.
// DV = sao TB × 200 + điểm trang trí + Σ DV mèo + 50 × số tiệm + bonus bộ sưu tập (hiện: 10 điểm mỗi combo đã tìm ra). S.dv = số hiện tại (17b-moc MT11/MT13 đọc).
// CHƯA có hình mèo: S.meo={list:[{id,hang}]} để sẵn; mỗi con +2% lượt khách, trần +12% (DVT.meoMul), DV mèo 30/60/80 theo hạng. Chưa bán mèo nên mọi số mèo = 0 và hệ số khách = 1.
// Bảng: người chơi + 9 tiệm NPC hư cấu (tiền định, không dùng thương hiệu thật). Mùa = 7 ngày game, kết mùa ở ngày chia hết cho 7. Top 3 nhận quà trong game (không tiền thật).
// Quà mèo (hạng 1, 2) chưa có hình nên lưu thành phiếu S.dvBang.phieu, đổi khi mèo vào Mua sắm (Việc 15d). Save cũ không có S.dvBang: tạo rỗng, không thưởng lại.
'use strict';
(()=>{
const isBot=()=>window.__REQBOT!=null||window.__AUTOPLACE===true;
const SEASON=7, MEO_PTS={thuong:30,hiem:60,sukien:80}, MEO_MUL=.02, MEO_CAP=.12, COMBO_BONUS=10;
// [tên, DV ngày 1, tăng/ngày, biên độ dao động]
const NPC=[['Spa Sao Biển',1250,9,70],['Hương Tiêu Spa',1080,7,60],['Nhà Thảo Mộc Ba Sơn',960,6,55],['Tiệm Lá Dứa',880,5,50],['Gió Bấc Spa',800,4.5,45],
  ['Sen Ngọc Quán',720,4,45],['Hải Đăng Nhỏ Spa',650,3.5,40],['Mây Bãi Sao',590,3,35],['Suối Tranh Spa',520,2.5,35]];
const QUA=[
  {h:1,ten:'Quán quân mùa',sen:3,phieu:'meo_doc_quyen',mo:'Mèo độc quyền mùa + khung vàng tên tiệm'},
  {h:2,ten:'Á quân mùa',sen:2,phieu:'meo_hiem',mo:'Mèo hiếm ngẫu nhiên'},
  {h:3,ten:'Hạng ba mùa',sen:1,phieu:'deco_hiem',mo:'Đồ trang trí hiếm + 1 sen'}];
const PHIEU={meo_doc_quyen:'Phiếu mèo độc quyền',meo_hiem:'Phiếu mèo hiếm',deco_hiem:'Phiếu đồ trang trí hiếm'};

function ensure(){
  if(!S.dvBang||typeof S.dvBang!=='object') S.dvBang={mua:0,hist:[],phieu:[],khung:false};
  const B=S.dvBang; B.hist=B.hist||[]; B.phieu=B.phieu||[]; B.mua=B.mua||0;
  if(!S.meo||typeof S.meo!=='object') S.meo={list:[]}; S.meo.list=S.meo.list||[];
  if(typeof S.dv!=='number') S.dv=0;
  return B;
}
const hash=s=>{ let h=2166136261; for(let i=0;i<s.length;i++){ h^=s.charCodeAt(i); h=Math.imul(h,16777619); } return (h>>>0)/4294967295; };
// DV tiệm NPC tại ngày d: nền + tăng đều + dao động theo mùa (tiền định, mỗi mùa một nhịp riêng)
function npcDv(i,d){ const [n,b,r,a]=NPC[i], m=Math.floor((Math.max(1,d)-1)/SEASON), w=(hash(n+m)-.5)*2*a; return Math.round(b+r*(d-1)+w); }
function meoMul(){ const n=(S.meo&&S.meo.list||[]).length; return 1+Math.min(MEO_CAP,MEO_MUL*n); }
function parts(){
  const sao=(typeof rating==='function'?rating():4)*200;
  let deco=0; try{ deco=typeof decorPts==='function'?decorPts():0; }catch(e){}
  const meo=((S.meo&&S.meo.list)||[]).reduce((a,c)=>a+(MEO_PTS[c.hang]||MEO_PTS.thuong),0);
  const tiem=50*Math.max(1,Object.keys(S.shops||{}).length);
  const bst=COMBO_BONUS*Object.keys((S.combo&&S.combo.found)||{}).length;
  return [{n:'Sao đánh giá',v:Math.round(sao)},{n:'Điểm trang trí',v:deco},{n:'Mèo',v:meo},{n:'Số tiệm',v:tiem},{n:'Bộ sưu tập combo',v:bst}];
}
function calc(){ if(typeof S==='undefined'||!S.totals) return 0; ensure(); S.dv=parts().reduce((a,p)=>a+p.v,0); return S.dv; }
function board(d){ d=d||S.day||1; const me={ten:S.name||'Tiệm của bạn',dv:calc(),me:1};
  return NPC.map((x,i)=>({ten:x[0],dv:npcDv(i,d)})).concat(me).sort((a,b)=>b.dv-a.dv||(b.me?1:0)-(a.me?1:0)).map((r,i)=>Object.assign(r,{h:i+1})); }

// ---- kết mùa: chốt hạng, phát quà ----
function settle(){
  const B=ensure(), d=S.day, mua=Math.floor(d/SEASON); if(d%SEASON!==0||mua<=B.mua) return;
  B.mua=mua; const rows=board(d), me=rows.find(r=>r.me), h=me.h; B.hist.unshift({mua,h,dv:me.dv,ngay:d}); B.hist.length=Math.min(B.hist.length,8);
  const q=QUA[h-1]; if(!q) return;
  if(S.mg) S.mg.lotus=(S.mg.lotus||0)+q.sen;
  B.phieu.push({id:q.phieu,mua}); S.dh=S.dh||[]; const dh=`${q.ten} ${mua}`; if(!S.dh.includes(dh)) S.dh.push(dh);
  if(h===1) B.khung=true;
  if(typeof renderTop==='function') renderTop();
  if(!isBot()&&typeof toast==='function') toast(`Kết mùa ${mua}: hạng ${h}/10 — ${q.mo}`,'good');
}

// ---- thẻ trong Sổ sách ----
function css(){ if(document.getElementById('dvCss')) return; const s=document.createElement('style'); s.id='dvCss';
  s.textContent=`.dv-row{display:flex;align-items:center;gap:8px;min-height:36px;padding:2px 6px;border-radius:8px}.dv-row+.dv-row{border-top:1px solid var(--c-vien-mo,#eee)}
.dv-row .dv-h{width:24px;font-weight:800;text-align:center;flex:none}.dv-row .dv-t{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.dv-row .dv-p{font-weight:700;flex:none}
.dv-row.me{background:var(--c-kem-2,#f7efe2);font-weight:800}.dv-row.top .dv-h{color:#b9811a}.dv-frame{border:2px solid #d9a521;border-radius:10px;padding:0 6px}`;
  document.head.appendChild(s); }
function card(){
  const B=ensure(); css(); const d=S.day||1, rows=board(d), me=rows.find(r=>r.me), con=SEASON-((d-1)%SEASON)-1;
  const mua=Math.floor((d-1)/SEASON)+1, ps=parts().filter(p=>p.v);
  const lines=rows.map(r=>`<div class="dv-row${r.me?' me':''}${r.h<=3?' top':''}"><span class="dv-h">${r.h}</span><span class="dv-t${r.me&&B.khung?' dv-frame':''}">${esc(r.ten)}</span><span class="dv-p">${r.dv}</span></div>`).join('');
  const last=B.hist[0];
  return `<div class="card"><div class="sec-t">Danh vọng <span class="tag ${me.h<=3?'good':''}">${me.dv} điểm · hạng ${me.h}/10</span></div>
  <p class="note" style="margin-top:6px">Mùa ${mua} · ${con>0?`còn ${con} ngày kết mùa`:'kết mùa hôm nay'}. So với 9 tiệm khác trên đảo.</p>
  <div style="margin-top:6px">${lines}</div>
  <p class="note" style="margin-top:6px"><b>Quà top 3:</b> ${QUA.map(q=>`hạng ${q.h} — ${esc(q.mo)}`).join('; ')}.</p>
  ${last?`<p class="note" style="margin-top:6px">Mùa ${last.mua} trước: hạng ${last.h}/10 với ${last.dv} điểm.</p>`:''}
  ${B.phieu.length?`<p class="note" style="margin-top:6px">Phiếu quà đang giữ: ${B.phieu.map(p=>esc(PHIEU[p.id]||p.id)+' (mùa '+p.mua+')').join(', ')} — đổi khi mèo vào Mua sắm.</p>`:''}</div>`;
}
renderScreen=(orig=>function(){ orig(); try{ if(tab!=='book') return; const D=$('#dyn'); if(!D) return;
  const cs=[...D.querySelectorAll('.card')], an=cs.find(c=>/Điểm trang trí/.test(c.textContent)); if(!an) return;
  an.insertAdjacentHTML('afterend',card()); }catch(e){ console.error('[dv]',e); } })(renderScreen);

// ---- móc vào game ----
checkMissions=(orig=>function(){ try{ calc(); }catch(e){} orig(); })(checkMissions);   // S.dv mới trước khi 17b-moc xét MT13
endDay=(orig=>function(){ orig(); try{ calc(); settle(); save(); }catch(e){ console.error('[dv]',e); } })(endDay);
if(typeof hourCurve==='function') hourCurve=(orig=>function(){ return orig()*meoMul(); })(hourCurve);   // mèo +2%/con, trần +12% (hiện =1)

window.DVT={calc,parts,board,npcDv,meoMul,settle,NPC,QUA,addMeo:(id,hang)=>{ ensure(); S.meo.list.push({id,hang:hang||'thuong'}); calc(); }};
})();

// 20c-meo.js — Việc 15d (bản TĨNH, Đại nhân duyệt 14/10 13:27 "mèo tĩnh"): 12 mô-đun mèo bán trong Mua sắm (tab con "Mèo"), đặt ngoài sân Chợ đêm.
// Mỗi con: DVT.addMeo (17c) → +Danh vọng (30/60) và +2% khách (trần +12%). Chân đế 3×3, xoay lật gương 2 hướng. Mở sau mốc MT13 (Danh vọng chạm 1.000).
// Vị trí: gán tự động vào 12 ô cố định của sân (không có ô thì không bán). Luật 8 không áp cho mèo; mèo không chặn lối khách (nằm ngoài nhà, ngoài lối đi).
// Hoạt cảnh: KHÔNG làm bằng code. Chỗ cho Grok: HAND_ACT['meo-<tên>'] (khung hình hd-meo-…); có thì 15y-room.js tự vẽ sống, chưa có thì hiện ảnh tĩnh.
// Giá là ĐỀ XUẤT (mục A, chờ Đại nhân quyết): thường 8tr, hiếm 15tr. Phiếu quà top 3 (S.dvBang.phieu: meo_doc_quyen, meo_hiem) đổi lấy 1 mèo hiếm chưa có.
'use strict';
(()=>{
const CATS=[
  ['huong','Mèo làm hương','thuong'],['banhtrang','Mèo tráng bánh','thuong'],['keodua','Mèo nấu kẹo dừa','thuong'],
  ['hoa','Mèo chăm hoa','thuong'],['nonla','Mèo làm nón lá','thuong'],['che','Mèo hái chè','thuong'],
  ['gom','Mèo nặn gốm','hiem'],['dongho','Mèo in tranh Đông Hồ','hiem'],['nuocmam','Mèo ủ nước mắm','hiem'],
  ['luoi','Mèo vá lưới','hiem'],['sen','Mèo hái sen','hiem'],['muoi','Mèo cào muối','hiem']].map(([k,ten,hang])=>({id:'meo-'+k,ten,hang}));
const GIA={thuong:8e6,hiem:15e6}, HANG={thuong:'Thường',hiem:'Hiếm'};
// 12 ô 3×3 trong sân (LPLOT 44×34, nhà x10–34 y6–24, lối x16–20 y≥24): 4 ô sân trước, 4 ô bên phải, 4 ô bên trái nhà
const SLOTS=[[23,26],[27,26],[31,26],[35,26],[36,18],[40,18],[36,22],[40,22],[2,8],[2,12],[2,16],[2,20]];
// 20m: ván CIC xấu (S.cicRun, Miu biến mất) mèo mua được nhưng GIÁ x2
const giaMeo=c=>GIA[c.hang]*(S.cicRun?2:1);
const PHIEU_MEO=['meo_doc_quyen','meo_hiem'];
const isBot=()=>window.__REQBOT!=null||window.__AUTOPLACE===true;
const L=()=>{ if(!S.meo||typeof S.meo!=='object') S.meo={list:[]}; S.meo.list=S.meo.list||[]; return S.meo.list; };
const own=id=>L().find(m=>m.id===id);
const mo=()=>!!(S.moc&&S.moc.MT13);
const freeSlot=()=>{ const used=new Set(L().filter(m=>m.x!=null).map(m=>m.x+','+m.y)); return SLOTS.find(([x,y])=>!used.has(x+','+y)); };
function them(c,gia,how){
  const sl=freeSlot(); if(!sl||own(c.id)) return false;
  if(gia){ if(S.cash<gia) return false; S.cash-=gia; if(typeof addLog==='function') addLog('Mua '+c.ten,-gia); }
  DVT.addMeo(c.id,c.hang); if(window.AUDIO&&AUDIO.meo) AUDIO.meo(); const m=L()[L().length-1]; m.x=sl[0]; m.y=sl[1]; m.r=0;
  if(typeof save==='function') save(); if(typeof renderTop==='function') renderTop();
  if(!isBot()&&typeof toast==='function') toast(`${c.ten} đã về sân: +${c.hang==='hiem'?60:30} danh vọng`,'good');
  return true; }
function mua(id){ const c=CATS.find(x=>x.id===id); if(!c||!mo()) return false; return them(c,giaMeo(c)); }
function lat(id){ const m=own(id); if(!m) return; m.r=m.r?0:1; if(window.AUDIO&&AUDIO.meo) AUDIO.meo(); if(typeof save==='function') save(); }
function doiPhieu(){ const B=S.dvBang; if(!B||!B.phieu) return false; const i=B.phieu.findIndex(p=>PHIEU_MEO.includes(p.id)); if(i<0) return false;
  const c=CATS.filter(x=>x.hang==='hiem'&&!own(x.id))[0]||CATS.find(x=>!own(x.id)); if(!c||!freeSlot()) return false;
  B.phieu.splice(i,1); return them(c,0); }
function render(){ const h=window.HAND_ART||{}; const ph=((S.dvBang&&S.dvBang.phieu)||[]).filter(p=>PHIEU_MEO.includes(p.id)).length, n=L().length;
  const row=c=>{ const m=own(c.id), im=h[c.id]&&h[c.id].file, g=giaMeo(c), can=mo()&&S.cash>=g&&!!freeSlot();
    return `<div class="item${m?' own':''}">${im?`<img class="ico" src="${im}" alt="">`:''}<div class="grow"><div class="n">${esc(c.ten)} <span class="tag ${c.hang==='hiem'?'lav':''}">${HANG[c.hang]}</span></div><div class="m">+${c.hang==='hiem'?60:30} danh vọng · +2% khách</div></div>${
      m?`<button class="btn sm" data-meo-lat="${c.id}">Xoay</button><span class="tag">Đã có</span>`:!mo()?'<span class="tag grey">Chưa mở</span>':`<button class="btn butter sm" data-meo-buy="${c.id}" ${can?'':'disabled'}>${fmt(g)}</button>`}</div>`; };
  return `<div class="card" data-meo><div class="sec-t">Mèo trang trí <span class="tag">${n}/${CATS.length}</span></div>
  <p class="note">Mỗi con mèo đặt ở sân Chợ đêm (nhìn ra ngoài sân để xem), cộng danh vọng và +2% lượt khách, tối đa +12%. ${mo()?'':'Mở khi danh vọng chạm 1.000.'}${S.prem==='chodem'?'':' Sân chỉ có ở tiệm Chợ đêm.'}</p>
  ${ph?`<button class="btn mint sm" data-meo-phieu style="margin:6px 0">Đổi phiếu mèo (${ph})</button>`:''}
  <div class="list" style="margin-top:8px">${CATS.map(row).join('')}</div></div>`; }
renderScreen=(orig=>function(){ orig(); try{ if(tab!=='buy') return; const D=$('#dyn'); if(!D||D.querySelector('[data-meo]')) return; D.insertAdjacentHTML('beforeend',render()); }catch(e){ console.error('[meo]',e); } })(renderScreen);
$('#dyn').addEventListener('click',e=>{ const b=e.target.closest('[data-meo-buy],[data-meo-lat],[data-meo-phieu]'); if(!b) return;
  if(b.dataset.meoBuy) mua(b.dataset.meoBuy); else if(b.dataset.meoLat) lat(b.dataset.meoLat); else doiPhieu();
  renderScreen(); });
window.MEO={CATS,GIA,giaMeo,SLOTS,mua,lat,doiPhieu,mo,
  deco:()=>L().filter(m=>m.x!=null).map(m=>({t:m.id,x:m.x,y:m.y,r:m.r||0})),
  sig:()=>L().map(m=>m.id+m.x+','+m.y+m.r).join(';')+'|'+CATS.filter(c=>window.HAND_ACT&&HAND_ACT[c.id]).length};
})();

// 20f-intro.js — Việc 20f/20i: MÀN TRUYỆN MỞ ĐẦU bản 3, 7 cảnh (nội dung: docs/lenh/truyen-mo-dau.md, Đại nhân duyệt 14/10).
// Ảnh Xưởng vẽ: art/raw/IN*.png → art/out/IN*.webp. Thiếu ảnh nào -> khung giấy kem + chữ (không báo lỗi).
// Chạy lần đầu (trước bước chọn độ khó) hoặc nút "Xem lại truyện" trong Sổ sách. Chuyển khung bằng CC.play('map') (rèm; reduced-motion = fade).
// Xong khung 7: S.introSeen=true; nếu đang ở Chợ đêm chưa sửa thì nút "Sửa tiệm · Dọn rác" (miễn phí) nháy sáng.
(function(){ 'use strict';
const FR=[
 {t:'Sài Gòn, văn phòng CSKH online', n:'IN01-sg-tiem-dt', l:['Tiệm điện thoại tông xanh biển – trắng. Tai nghe, màn hình chat nhảy liên tục, ngoài cửa kính trời đã tối.','"Dạ em xin lỗi anh chị… dạ em xin lỗi…"']},
 {t:'Phòng trọ, khuya', n:'IN02-sg-phong-tro', l:['Con heo đất vỡ, xấp tiền nhàu, tấm ảnh biển dán tường.','"Cả tuổi trẻ làm thuê cho người ta rồi… Giờ phải thay đổi thôi. Ừm… làm thuê cho chính mình đi."']},
 {t:'Ra khơi', n:'IN1-ben-tau', l:['Chuyến phà chiều tách bến, mặt trời đỏ lặn sau mũi tàu. Cô đứng ở lan can đuôi phà, vali bên chân, gió thổi tung tóc.','"Phú Quốc… mình tới đây."']},
 {t:'Mặt bằng rẻ nhất Chợ đêm', n:'IN3-tiem-cu-nat', l:['Mạng nhện, mái rách, sàn bong.','"Vốn chỉ đủ chừng này. Vậy thì bắt đầu từ đây."']},
 {t:'Dưới gầm ghế cũ', n:'IN4-meo-miu', l:['"Meo…"','"Em ở đây trước chị rồi ha. Chị gọi em là Miu nhé."']},
 {t:'Sáng hôm sau', n:'IN7-bat-dau', l:['Xắn tay áo, cầm chổi. Miu vờn túi rác.','"Việc đầu tiên: dọn rác."']},
 {t:'Khai trương', n:'IN5-bien-spa-miu', l:['Tấm biển gỗ SPA MIU treo lên. Miu ngồi chễm chệ bên cạnh.','"Bắt đầu thôi!"']}];
// ẢNH ĐÃ CÓ (khoá = tên file art/raw/<n>.png; giá trị ghi nguyên chuỗi đường dẫn để build_dist nhúng base64). Khung chưa có ảnh -> giấy kem + chữ, không gọi mạng (tránh 404 console).
const IMG={'IN01-sg-tiem-dt':'img/e87ded235fd3.webp','IN02-sg-phong-tro':'img/ae2b58334c7c.webp','IN1-ben-tau':'img/2f845d805144.webp','IN3-tiem-cu-nat':'img/cd3fe55215a6.webp','IN4-meo-miu':'img/a0d433484f1d.webp','IN5-bien-spa-miu':'img/03c32eba1c82.webp','IN7-bat-dau':'img/7f397e520a95.webp'};
// 20p: MỞ ĐẦU = 1 video dẫn chuyện art/video/intro.mp4 (bản nhẹ: intro-nhe.mp4), ghép bằng tools/ghep_intro.py từ 7 cảnh (mỗi cảnh 6s, crossfade 0,6s -> cảnh i bắt đầu ở i*5,4s). Phụ đề theo mốc thời gian. Không phát được -> ảnh tĩnh 7 cảnh.
const NHE=!!window.__NHE/*BUILD_NHE*/;
const VID_SRC='art/video/'+(NHE?'intro-nhe':'intro')+'.mp4', SCENE_S=5.4;
let vid=null;
const reduced=()=>window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;
const css=document.createElement('style'); css.textContent=`
#introMan{position:fixed;inset:0;z-index:9000;display:flex;flex-direction:column;background:#2a2638;color:#3b2f24;font-family:system-ui,sans-serif;user-select:none;-webkit-user-select:none;touch-action:manipulation}
#introMan .in-img{flex:1 1 62%;min-height:0;position:relative;overflow:hidden;background:#efe3c8}
#introMan .in-img img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 50%;display:block;-webkit-user-drag:none}
#introMan .in-img video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block}
@keyframes introKB{from{transform:scale(1)}to{transform:scale(1.07)}}
#introMan .in-img img.kb{animation:introKB 9s ease-out forwards}
@media (prefers-reduced-motion:reduce){#introMan .in-img img.kb{animation:none}}
#introMan .in-paper{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:24px;text-align:center;background:#f3e8cf;font:800 clamp(20px,4.5vw,34px) system-ui,sans-serif;color:#7a5f3a}
#introMan .in-txt{flex:0 0 auto;min-height:34%;box-sizing:border-box;padding:14px 18px calc(16px + env(safe-area-inset-bottom));background:#fbf3df;border-top:4px solid #d9b77a;display:flex;flex-direction:column;gap:6px;justify-content:flex-start;overflow:auto}
#introMan .in-cap{font-size:var(--fz-ghichu);font-weight:800;letter-spacing:.04em;color:#a2763c;text-transform:uppercase}
#introMan .in-l{margin:0;font-size:clamp(15px,3.6vw,19px);line-height:1.5;max-width:46em}
#introMan .in-dots{display:flex;gap:6px;margin-top:auto;padding-top:6px;align-items:center}
#introMan .in-dots i{width:8px;height:8px;border-radius:50%;background:#d9c9a6}
#introMan .in-dots i.on{background:#e8a317}
#introMan .in-hint{margin-left:auto;font-size:var(--fz-ghichu);opacity:.6}
#introMan .in-skip{position:absolute;top:calc(10px + env(safe-area-inset-top));right:10px;z-index:3;min-width:44px;min-height:44px;padding:0 16px;border:0;border-radius:22px;background:rgba(30,24,40,.7);color:#FBF6EA;font:700 var(--fz-than) system-ui;cursor:pointer}
@keyframes introPulse{0%,100%{box-shadow:0 0 0 0 rgba(255,214,90,.9)}50%{box-shadow:0 0 0 12px rgba(255,214,90,0)}}
.room .cd-fix.intro-pulse{animation:introPulse 1.2s ease-in-out infinite}`;
document.head.appendChild(css);
let ov=null, idx=0, tm=0, typing=false, after=null;
const $q=s=>ov&&ov.querySelector(s);
function stopType(){ clearTimeout(tm); typing=false; }
function finishLines(){ stopType(); const f=FR[idx]; ov.querySelectorAll('.in-l').forEach((p,i)=>{ p.textContent=f.l[i]; }); }
function typeLines(){ const f=FR[idx], ps=[...ov.querySelectorAll('.in-l')]; if(reduced()){ finishLines(); return; }
  typing=true; let li=0, ci=0; const step=()=>{ if(!ov||!typing) return; const p=ps[li], s=f.l[li]; ci++; p.textContent=s.slice(0,ci);
    if(ci>=s.length){ li++; ci=0; if(li>=ps.length){ typing=false; return; } tm=setTimeout(step,380); } else tm=setTimeout(step,26); };
  step(); }
function render(){ const f=FR[idx], im=$q('.in-img');
  im.innerHTML=''; const i=new Image(); i.alt=''; i.draggable=false;
  const paper=()=>{ im.innerHTML='<div class="in-paper">'+esc(f.t)+'</div>'; };
  if(!IMG[f.n]) paper(); else { i.onerror=paper; i.src=IMG[f.n]; i.className='kb'; im.appendChild(i);
 }  setTxt(); }
function setTxt(){ const f=FR[idx]; $q('.in-txt').innerHTML='<div class="in-cap">'+esc(f.t)+'</div>'+f.l.map(()=>'<p class="in-l"></p>').join('')
    +'<div class="in-dots">'+FR.map((_,k)=>'<i class="'+(k===idx?'on':'')+'"></i>').join('')+'<span class="in-hint">'+(vid?'':idx===FR.length-1?'Chạm để bắt đầu':'Chạm để tiếp')+'</span></div>';
  typeLines(); }
function go(n){ if(n>=FR.length) return end(); stopType(); const swap=()=>{ idx=n; if(ov) render(); };
  if(window.CC&&ov) CC.play('map',{mid:swap}); else swap(); }
function tap(){ if(!ov||vid) return; if(typing){ finishLines(); return; } go(idx+1); }
function end(){ stopType(); if(!ov) return; if(vid){ try{ vid.pause(); }catch(e){} vid=null; }
  const done=()=>{ if(!ov) return; ov.remove(); ov=null; document.removeEventListener('keydown',key);
    if(!S.introSeen){ S.introSeen=true; if(typeof save==='function') save(); } const cb=after; after=null; if(cb) cb();
    try{ if(S.prem==='chodem'&&S.cd&&S.cd.step===0) pulse(); }catch(e){} };
  if(window.CC) CC.play('map',{mid:done}); else done(); }
function pulse(){ let n=0; const t=setInterval(()=>{ const b=document.getElementById('cdFix');
  if(b&&!b.hidden){ b.classList.add('intro-pulse'); b.addEventListener('click',()=>b.classList.remove('intro-pulse'),{once:true}); clearInterval(t); } else if(++n>20) clearInterval(t); },500); }
function key(e){ if(e.key==='Escape') end(); else if(e.key===' '||e.key==='Enter'||e.key==='ArrowRight'){ e.preventDefault(); tap(); } }
function intro(next){ if(ov) return; after=next||null; idx=0;
  ov=document.createElement('div'); ov.id='introMan'; ov.setAttribute('role','dialog'); ov.setAttribute('aria-label','Truyện mở đầu');
  ov.innerHTML='<button class="in-skip" type="button">Bỏ qua ›</button><div class="in-img"></div><div class="in-txt"></div>';
  document.body.appendChild(ov); document.addEventListener('keydown',key);
  ov.addEventListener('click',e=>{ if(e.target.closest('.in-skip')){ e.stopPropagation(); end(); } else tap(); });
  if(!reduced()&&!/[?&]noVideo/.test(location.search)) playVid(); else render(); }
function playVid(){ const im=$q('.in-img'); const v=document.createElement('video'); v.muted=true; v.defaultMuted=true; v.autoplay=true; v.playsInline=true; v.loop=false; v.preload='auto'; v.setAttribute('playsinline','');
  const fall=()=>{ if(vid!==v) return; vid=null; v.remove(); idx=0; render(); };   // lỗi/không phát được -> ảnh tĩnh như cũ
  v.onerror=fall; v.onended=()=>{ if(vid===v) end(); };
  v.ontimeupdate=()=>{ if(vid!==v) return; const k=Math.min(FR.length-1,Math.floor(v.currentTime/SCENE_S)); if(k!==idx){ idx=k; stopType(); setTxt(); } };
  vid=v; idx=0; im.appendChild(v); setTxt(); v.src=VID_SRC;
  const pr=v.play(); if(pr&&pr.catch) pr.catch(fall);
  clearTimeout(vt); vt=setTimeout(()=>{ if(vid===v&&v.readyState<2) fall(); },6000); }
let vt=0;
// lần đầu: chen giữa "nhập tên" và "chọn độ khó" (14-story.js gọi introRun(pickDiff)); bot/test (navigator.webdriver, trừ khi thêm ?intro) và ?noIntro bỏ qua
window.introRun=function(next){ const bot=window.__REQBOT!=null||window.__AUTOPLACE===true||window.__khongLuu;
  const q=location.search; let seen=S.introSeen; try{ if(localStorage.getItem('spa-miu-intro')) seen=true; }catch(e){}
  if(seen||bot||/[?&]noIntro/.test(q)||(navigator.webdriver&&!/[?&]intro/.test(q))) return next(); intro(next); };
window.introReplay=()=>intro(null);
// nút "Xem lại truyện" trong Sổ sách
renderScreen=(orig=>function(){ orig(); if(tab!=='book'||!S.prem) return; const D=$('#dyn'), first=D&&D.querySelector('.card'); if(!first||D.querySelector('.in-card')) return;
  first.insertAdjacentHTML('afterend','<div class="card in-card"><div class="sec-t">Truyện mở đầu</div><p class="note" style="margin:6px 0">Cô chủ tiệm đến Phú Quốc thế nào, và vì sao có Miu.</p><div class="row"><button class="btn sm alt" type="button" data-introre>Xem lại truyện</button></div></div>'); })(renderScreen);
$('#dyn').addEventListener('click',e=>{ if(e.target.closest('[data-introre]')) introReplay(); });
})();

// 20r-bamhuyet.js — Việc 20r: làm lại mini game Bấm huyệt bàn chân (docs/lenh/mg-bam-huyet.md, Đại nhân duyệt 14/10).
// Ghi đè playRub của 15c: nền dọc 3:4, 8 huyệt đúng phản xạ bàn chân, vòng cánh hoa hồng anh vàng, mặt khách 3 mức, ngủ quên → tip.
// Giữ luật cũ: cấp kỹ năng chỉnh tốc độ vòng, chấm Chuẩn/Tốt/Được/Trượt, MG_SAT, phần thưởng ở mgResult/mgGrant.
(function(){ 'use strict';
const NEN='img/28185d819cdb.webp';
const KHACH=['img/d30f20214447.webp','img/77667b70b189.webp','img/985b7e3c40e8.webp'];
// [x%, y%, tên huyệt, công dụng] — toạ độ % trên ảnh nền; luân phiên bàn trái (nửa ảnh trái) / phải
const PTS=[
 [42.5,18.5,'Đầu ngón cái','đỡ đau đầu'],        // L
 [67.5,19.5,'Dưới ngón 2-3','sáng mắt'],          // R
 [30.5,32.5,'Gò ngón chân','dễ thở, nhẹ phổi'],   // L
 [68,38.5,'Dũng Tuyền','ngủ ngon'],               // R, giữa 1/3 trên lòng bàn chân
 [40.5,41.5,'Vồm trong','êm dạ dày'],             // L
 [78,33,'Vồm ngoài','đỡ mỏi vai'],                // R
 [34,57,'Giữa gan gót','nhẹ bụng, êm ruột'],      // L
 [67.5,67.5,'Gót chân','đỡ mỏi lưng']             // R
];
// 24f: man ngang dung MG27 (2 ban chan giua, to giay ben phai). Toa do % tren anh 1672x941, doi theo ban chan moi; luat diem huyet giu nguyen
const NEN_L='img/85631cdedf8a.webp', WIDEQ=matchMedia('(orientation:landscape) and (max-height:520px)');
const PTS_L=[
 [45.8,18.1,'Đầu ngón cái','đỡ đau đầu'],          // L
 [60.4,22.8,'Dưới ngón 2-3','sáng mắt'],            // R
 [38.2,35.2,'Gò ngón chân','dễ thở, nhẹ phổi'],     // L
 [58.3,42.5,'Dũng Tuyền','ngủ ngon'],               // R
 [46.4,47.8,'Vồm trong','êm dạ dày'],               // L
 [61.4,50.2,'Vồm ngoài','đỡ mỏi vai'],              // R
 [41.9,59.5,'Giữa gan gót','nhẹ bụng, êm ruột'],    // L
 [57.4,68.0,'Gót chân','đỡ mỏi lưng']               // R
];
// 20x: hoa sứ thay hồng anh vàng. Literal đường dẫn để build_dist nhúng base64.
const HOA=['img/2adfda4a52e3.webp','img/c8b2107cb2c3.webp','img/9b819efcbb04.webp','img/eddf606ba67e.webp'], HOA_ROI='img/ce1336c4cf9f.webp';
const hoaImg=src=>`<img class="pt-svg" src="${src}" alt="" draggable="false">`;
const PETAL=hoaImg('img/58bf37a00b85.webp');
const lvlOf=a=>a>=80?3:a>=50?2:1;                  // <50 căng thẳng, 50-79 dễ chịu, >=80 ngủ quên thư giãn
const MG_TIP_STEP=0.05, MG_TIP_MAX=0.30;           // mỗi huyệt liên tiếp ở cuối ván đạt Chuẩn/Tốt +5%, trần +30%
const sleepBonus=beats=>{ let n=0; for(let i=beats.length-1;i>=0&&beats[i].score>=70;i--) n++; return {n, bonus:Math.min(MG_TIP_MAX, n*MG_TIP_STEP)}; };

playRub=function(lv, onEnd, onAbort){
  const wide=WIDEQ.matches, PT=wide?PTS_L:PTS;
  const D=0.8+0.1*clamp(lv||1,1,5), GAP=D+0.3, BEATS=PT.length;
  $('#sheet').innerHTML=`${mgHead('i_foot','Bấm huyệt bàn chân','Chạm huyệt khi vòng khép khớp chấm hồng.')}
    <div class="mg-stage mg-foot${wide?' mg-wide':''}" id="mgStage" style="background-image:url('${wide?NEN_L:NEN}')"><div class="mg-face" id="mgFace" data-lv="2"><img src="${KHACH[1]}" alt="Khách"><i class="zz">z</i><i class="zz z2">z</i></div></div><div class="mg-hud" id="mgHud">0 / ${BEATS}</div>`;
  const stage=$('#mgStage'), hud=$('#mgHud'), face=$('#mgFace'), t0=performance.now()/1000+0.6, beats=[];
  for(let i=0;i<BEATS;i++){ const [x,y,nm,use]=PT[i]; beats.push({x,y,nm,use,tp:t0+i*GAP+D, show:t0+i*GAP, el:null, score:null}); }
  let judged=0, sum=0, tagbox=null;
  // 20y: khung ngang thấp: sân khấu to bằng chiều cao khung, mặt khách đặt bên trái, nhãn huyệt + tiến độ bên phải (không để trống)
  // 24f: ngang = tranh MG27 phủ khung: mặt khách ở góc trái, tờ giấy bên phải làm bảng nhãn huyệt + tiến độ, nút đóng góc phải
  if(wide){ const sh=$('#sheet'); face.classList.add('mg-fl','mg-fw'); stage.appendChild(face); stage.appendChild(hud); hud.classList.add('mg-hw');
    tagbox=document.createElement('div'); tagbox.className='mg-tagbox mg-tw'; tagbox.textContent='Chạm đúng lúc vòng hoa khép lại'; stage.appendChild(tagbox);
    sh.insertAdjacentHTML('afterbegin','<div class="mgw-bg"></div>'); sh.insertAdjacentHTML('beforeend','<button type="button" class="mgw-x" aria-label="Đóng"></button>'); sh.querySelector('.mgw-x').onclick=()=>{ if(window.closeSheet) closeSheet(); }; }
  const setFace=()=>{ const l=judged?lvlOf(sum/judged):2; if(face.dataset.lv!==String(l)){ face.dataset.lv=l; face.querySelector('img').src=KHACH[l-1]; } };
  const tag=(x,y,t,nm,use)=>{ if(tagbox){ tagbox.innerHTML=`<b>${nm}</b>${use}`; return; } const e=document.createElement('div'); e.className='mg-lb'; e.style.left=clamp(x,24,76)+'%'; e.style.top=(y+8)+'%'; e.textContent=t; stage.appendChild(e); setTimeout(()=>e.remove(),900); };
  const judge=(b,sc,label,cls)=>{ b.score=sc; sum+=sc; judged++; floatTxt(stage,b.x,b.y-8,label,cls);
    if(sc>0) tag(b.x,b.y,`${b.nm} — ${b.use}`,b.nm,b.use);
    if(b.el){ const rg=b.el.querySelector('.ring'); rg.style.transform='scale(1)';
      if(sc>=100){ rg.innerHTML=hoaImg(HOA[0]); [1,2,3].forEach(i=>setTimeout(()=>{ const im=rg.querySelector('img'); if(im) im.src=HOA[i]; },i*110)); setTimeout(()=>b.el&&b.el.classList.add('glow'),330); }
      else if(sc>0) rg.innerHTML=hoaImg(HOA[2]); else rg.innerHTML=hoaImg(HOA_ROI);
      b.el.classList.add('done', sc>=100?'bloom':sc>0?'ok':'fall'); setTimeout(()=>b.el&&b.el.remove(),sc>=100?800:450); }
    hud.textContent=`${judged} / ${BEATS}`; setFace(); };
  const loop=()=>{
    if(mgGuard(onAbort)) return;
    const now=performance.now()/1000;
    beats.forEach(b=>{
      if(b.score!==null) return;
      if(now>=b.show && !b.el){ b.el=document.createElement('button'); b.el.className='mg-pt'; b.el.style.left=b.x+'%'; b.el.style.top=b.y+'%'; b.el.innerHTML=`<i class="ring">${PETAL}</i><i class="dotp"></i><i class="spk"></i>`; b.el.setAttribute('aria-label',b.nm);
        b.el.onpointerdown=e=>{ e.preventDefault(); if(b.score!==null) return; const err=Math.abs(performance.now()/1000-b.tp);
          if(err<=0.08) judge(b,100,'Chuẩn!','good'); else if(err<=0.18) judge(b,70,'Tốt'); else if(err<=0.3) judge(b,40,'Được'); else judge(b,0,'Trượt','bad'); };
        stage.appendChild(b.el); }
      if(b.el && b.score===null){ const k=clamp((b.tp-now)/D,0,1); b.el.querySelector('.ring').style.transform=`scale(${1+1.6*k})`; }
      if(now>b.tp+0.35) judge(b,0,'Trượt','bad');
    });
    if(judged>=BEATS){ const avg=sum/BEATS, sl=lvlOf(avg)===3?sleepBonus(beats):null;
      setTimeout(()=>onEnd(avg,sl),500); mgLive.raf=0; return; }
    mgLive.raf=requestAnimationFrame(loop);
  };
  mgLive={raf:requestAnimationFrame(loop)};
};

// onEnd(avg, {n,bonus}) từ dispatch (15c) ghi g.mgSleep; ở đây cộng tip sau cùng (bọc ngoài 15i) + lời khen vào đánh giá
RV_VI.mgSleep=['ngủ quên lúc nào không hay','bấm huyệt êm quá, ngủ quên luôn']; RV_EN.mgSleep=['fell asleep without even noticing','the massage was so soothing I dozed off'];
finishService=(orig=>function(g){
  const sl=g.mgSleep||0; g.mgSleep=0; orig(g);
  if(sl>0){ if(g.tip>0) g.tip=r10(g.tip*(1+sl)); if(g.rv) g.rv.reasons.push(['mgSleep',Math.round(sl*100)]); }
})(finishService);
})();

// 20u-minigame.js — Việc 20u: bố cục mini game (khung ngang 844x390 không cuộn). Chỉ chia lại DOM; luật chơi giữ nguyên ở 15c/15d/15e.
// Kho đồ: chia 2 cột (trái: nguyên liệu + chỉ số, phải: pha chế vật phẩm). Ở màn dọc 2 khối này là display:contents nên giữ nguyên thứ tự cũ.
(function(){ 'use strict';
openInv=(orig=>function(){
  orig(); const sh=$('#sheet'); if(!sh) return;
  const kids=[...sh.children], box=kids.find(k=>k.classList.contains('list')&&k.querySelector('.plaque')), row=kids[kids.length-1];
  if(!box) return;
  const main=document.createElement('div'), side=document.createElement('div'); main.className='mg-main mg-invl'; side.className='mg-side mg-invr';
  kids.forEach(k=>{ if(k===box) side.appendChild(k); else main.appendChild(k); });
  const pn=[...main.children].filter(c=>c.matches('p.note')); if(pn[0]) pn[0].classList.add('mg-long');
  sh.appendChild(main); sh.appendChild(side); if(row&&row.classList.contains('row')) side.appendChild(row);
  // 21m: chia 2 tab (Nguyên liệu | Pha chế), không cuộn
  { const tl=main.querySelector('.tiles'); if(tl){ sh.dataset.kt=sh.dataset.kt||'ng';
    tl.insertAdjacentHTML('afterend','<div class="seg kt-tabs" role="tablist"><button data-kt="ng">Nguyên liệu</button><button data-kt="pc">Pha chế</button></div>');
    const sync=()=>sh.querySelectorAll('.kt-tabs button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.kt===sh.dataset.kt));
    sh.querySelectorAll('.kt-tabs button').forEach(b=>b.onclick=()=>{ sh.dataset.kt=b.dataset.kt; sync(); }); sync(); } }
})(openInv);

// 20y: Bàn pha chế ở khung ngang thấp: cột phải quá dài -> "Đưa nguyên liệu từ kho" và "Công thức" gom thành 2 nút, bấm ra bảng nổi (không cuộn).
const LOW=()=>matchMedia('(orientation:landscape) and (max-height:520px)').matches;
openMerge=(orig=>function(){
  orig(); if(!LOW()) return; const sh=$('#sheet'), side=sh&&sh.querySelector('.mg-side'); if(!side) return;
  const card=side.querySelector(':scope > .card:not(details)'), det=side.querySelector(':scope > details.card'), row=side.lastElementChild;
  const pops=document.createElement('div'); pops.className='mg-pops';
  const mk=(label,node,open)=>{ const pop=document.createElement('div'); pop.className='mg-pop'; pop.hidden=true;
    const x=document.createElement('button'); x.className='btn sm alt pop-x'; x.textContent='Đóng'; x.onclick=()=>{ pop.hidden=true; }; pop.appendChild(x); pop.appendChild(node); sh.appendChild(pop);
    const b=document.createElement('button'); b.className='btn sm alt'; b.textContent=label; b.onclick=()=>{ sh.querySelectorAll('.mg-pop').forEach(p=>{ if(p!==pop) p.hidden=true; }); pop.hidden=!pop.hidden; if(open) open(node); }; pops.appendChild(b); };
  if(card) mk('Đưa nguyên liệu từ kho',card);
  if(det){ det.open=true; const sm=det.querySelector('summary'); if(sm) sm.style.display='none'; mk('Công thức',det); }
  if(pops.children.length&&row) side.insertBefore(pops,row);
})(openMerge);
})();

// 20x-minigame-art.js — Việc 20x: gắn ảnh Xưởng (MG3 nền, MG4 pha nước ngâm, MG6 icon cấp 7, MG7 điểm danh, MG8 khung kết quả). Bấm huyệt hoa sứ (MG9) ở 20r.
// Chỉ đổi phần nhìn + cách thao tác của Pha nước ngâm; luật chấm điểm/thưởng giữ nguyên ở 15c. Literal đường dẫn art/out/*.webp để build_dist nhúng base64.
(function(){ 'use strict';
// ---- MG6: icon cấp 7 (Bàn pha chế, kho, kết quả) ----
Object.assign(IMG,{m_oil7:'img/96f4280aacde.webp', m_soak7:'img/55253f060b29.webp', m_cnd7:'img/7a538b9f30df.webp', m_twl7:'img/c29e9477c946.webp'});
Object.assign(MG_ICON,{soak:'m_soak7', oil:'m_oil7', candle:'m_cnd7', towel:'m_twl7'});

// ---- MG4: Pha nước ngâm ----
const DISH={'Gừng':'img/85ff0fe0409f.webp','Sả':'img/20ce42c0904d.webp','Muối hột':'img/99236a016333.webp','Lá tràm':'img/d882eb19b1d6.webp','Quế':'img/90b004c164fb.webp'};
const BON='img/85ef12833445.webp', NK='img/ffe3f5b4eed0.webp', KHOI='img/737eef1cc952.webp', GON='img/1f2a5d4c3c53.webp';
const dishImg=h=>`<img src="${DISH[h]}" alt="" draggable="false">`;
playSoak=function(onEnd, onAbort){
  $('#sheet').innerHTML=`${mgHead('i_tub','Pha nước ngâm','Bước 1: bấm Dừng khi cột đỏ nằm trong vạch xanh 40–42°C.')}
    <div class="sk1"><div class="sk-bon"><img src="${BON}" alt="" draggable="false"><img class="khoi" id="mgSteam" src="${KHOI}" alt="" draggable="false"></div>
      <div class="sk-nk"><img src="${NK}" alt="" draggable="false"><i class="zn"></i><i class="mer" id="mgNeedle"></i></div></div>
    <div class="row sk-ctl"><b id="mgTemp" class="big-num" style="font-size:var(--fz-tieude)">—</b><button class="btn big butter" id="mgStop">Dừng</button></div>`;
  let ph=Math.random()*6, sp=2.2, temp=40, stopped=false; const t0=performance.now();
  const loop=()=>{
    if(mgGuard(onAbort)) return;
    if(stopped) return;
    const el=(performance.now()-t0)/1000; ph+=0.016*(sp+el*0.5);
    temp=40+10*Math.sin(ph); const nd=$('#mgNeedle'); if(nd) nd.style.height=((temp-30)/20*43.5)+'%';
    const st=$('#mgSteam'); if(st) st.style.opacity=clamp((temp-37)/8,0,1);
    const tt=$('#mgTemp'); if(tt) tt.textContent=temp.toFixed(1).replace('.',',')+'°C';
    mgLive.raf=requestAnimationFrame(loop);
  };
  mgLive={raf:requestAnimationFrame(loop)};
  $('#mgStop').onclick=()=>{ stopped=true; const d=Math.abs(temp-41); const tScore=d<=1?60:d<=2?40:d<=4?20:0;
    const recipe=[...HERBS].sort(()=>Math.random()-.5).slice(0,3), tTxt=temp.toFixed(1).replace('.',',');
    $('#sheet').innerHTML=`${mgHead('i_tub','Pha nước ngâm','')}<p class="note">Nhiệt độ ${tTxt}°C (+${tScore}). Bước 2: nhớ thứ tự thảo dược rồi kéo thả vào bồn đúng thứ tự.</p>
      <div class="mg-recipe" id="mgRecipe">${recipe.map((h,i)=>`<span class="sk">${dishImg(h)}${i+1}. ${h}</span>`).join(' ')}</div>
      <div class="sk2"><div class="sk-bon" id="mgBon"><img src="${BON}" alt="" draggable="false"><img class="gon" id="mgGon" src="${GON}" alt="" draggable="false"></div><div class="sk-dishes" id="mgHerbs"></div></div><p class="note" id="mgPick"></p>`;
    setTimeout(()=>{ if(mgGuard(onAbort)) return; const rc=$('#mgRecipe'); if(!rc) return; rc.innerHTML='<span class="note">Kéo thảo dược vào bồn theo thứ tự vừa thấy</span>';
      let idx=0, hScore=0, over=false; const box=$('#mgHerbs'), bon=$('#mgBon'), gon=$('#mgGon');
      box.innerHTML=[...HERBS].sort(()=>Math.random()-.5).map(h=>`<button class="td" data-h="${h}">${dishImg(h)}<small>${h}</small></button>`).join('');
      const drop=b=>{ if(over||b.disabled) return; const h=b.dataset.h, ok=h===recipe[idx];
        b.disabled=true; b.classList.add(ok?'mint':'danger'); $('#mgPick').textContent=ok?`Đúng ${idx+1}/3`:`Sai, phải là ${recipe[idx]}`;
        if(ok){ hScore+=40/3; idx++; gon.classList.remove('on'); void gon.offsetWidth; gon.classList.add('on'); }
        if(!ok||idx>=3){ over=true; setTimeout(()=>onEnd(tScore+hScore, `Nhiệt độ +${tScore}, thảo dược +${Math.round(hScore)}`),600); } };
      box.querySelectorAll('[data-h]').forEach(b=>{
        let drag=null;
        b.onpointerdown=e=>{ if(over||b.disabled) return; e.preventDefault(); drag={x:e.clientX,y:e.clientY,g:null}; try{ b.setPointerCapture(e.pointerId); }catch(_){} };
        b.onpointermove=e=>{ if(!drag) return; if(!drag.g && Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>6){ const g=b.querySelector('img').cloneNode(); g.className='td-ghost'; document.body.appendChild(g); drag.g=g; b.classList.add('lift'); }
          if(drag.g){ drag.g.style.left=e.clientX+'px'; drag.g.style.top=e.clientY+'px'; bon.classList.toggle('hot',inRect(bon,e.clientX,e.clientY)); } };
        const end=e=>{ if(!drag) return; const d=drag; drag=null; bon.classList.remove('hot'); b.classList.remove('lift');
          if(d.g){ const hit=inRect(bon,e.clientX,e.clientY); d.g.remove(); if(hit) drop(b); }
          else drop(b); };                       // chạm nhẹ = thả luôn vào bồn
        b.onpointerup=end; b.onpointercancel=e=>{ if(drag&&drag.g) drag.g.remove(); drag=null; b.classList.remove('lift'); bon.classList.remove('hot'); };
        b.onclick=e=>e.preventDefault();
      });
    },1800);
  };
};
const inRect=(el,x,y)=>{ const r=el.getBoundingClientRect(); return x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom; };

// ---- MG8: màn kết quả dùng khung hoa sứ ----
const MEDAL={S:'img/f672833cc730.webp',A:'img/a00e7b978f19.webp',B:'img/a3fcd95434b8.webp',C:'img/dc9fd072d521.webp'};
const KQ_KHUNG='img/2709caa18993.webp', KQ_LAP='img/c8b23946ff60.webp';
mgResult=function(game, score, supplies, extra, after){
  mgStop();
  const res=mgGrant(game, score, supplies), its=res.items.slice(0,6);
  sheet(`<div class="kq"><div class="kq-fr"><img class="kq-bgi" src="${KQ_KHUNG}" alt="" draggable="false"><div class="kq-rb">${MG_GAMES[game].name}</div>
      <div class="kq-pa"></div><div class="kq-gr kq-n${its.length}">${its.map(it=>`<div class="kq-o" title="${esc(it.lb)}">${mgImg(MG_ICON[it.k]||'i_star')}<b>+${it.n}</b></div>`).join('')}</div>
      ${res.grade==='S'?`<img class="kq-lap" src="${KQ_LAP}" alt="" draggable="false">`:''}</div>
    <div class="kq-r"><div class="mg-grade g${res.grade}"><img src="${MEDAL[res.grade]}" alt="" draggable="false"><b class="gl">${res.grade}</b></div>
      <h2>${extra&&extra.title!=null?extra.title:Math.round(score)+' điểm'}</h2>
      ${extra&&extra.html?`<div class="kq-tb">${extra.html}</div>`:extra?`<p class="note kq-ex">${extra}</p>`:''}
      ${its.length?'':'<p class="note kq-ex">Lượt này không có vật phẩm.</p>'}
      ${res.out.filter(t=>/đầy kho/.test(t)).map(t=>`<p class="note kq-ex">${esc(t)}</p>`).join('')}
      ${res.notes.length?`<p class="note mg-resn">${res.notes.join(' ')}</p>`:''}
      <div class="row"><button class="btn big butter" data-ok>Xong</button></div></div></div>`, sh=>{
      sh.querySelector('[data-ok]').onclick=()=>{ closeSheet(); renderAll(); if(after) after(res); };
    });
  return res;
};

// ---- MG7: Điểm danh dùng thẻ ngày ----
const DD_N=['img/f5dfe567ec31.webp','img/e128edc83219.webp','img/82feec3df2fd.webp','img/cd97a766cff9.webp','img/9929efe43b5a.webp','img/3406db06d52a.webp','img/31fb82852eca.webp'], DD_KHOA='img/880068307a3d.webp', DD_DAU='img/6cc5ed5150f2.webp', DD_HN='img/416868bad53b.webp';
function ddCards(){
  const days=document.querySelectorAll('#sheet .streak .sday'); if(!days.length) return;
  days.forEach((d,i)=>{ const got=d.classList.contains('got'), now=d.classList.contains('now'), lock=!got&&!now;
    const lab=d.querySelector('b').outerHTML, sm=d.querySelector('small').outerHTML;
    d.classList.toggle('lock',lock);
    d.innerHTML=`<span class="dd-c"><img src="${lock?DD_KHOA:(now&&!got&&i===0?DD_HN:DD_N[i])}" alt="" draggable="false">${got?`<img class="dd-dau" src="${DD_DAU}" alt="" draggable="false">`:''}</span>${lab}${sm}`; });
}
openDaily=(orig=>function(t){ orig(t); ddCards(); })(openDaily);

// ---- Gỡ Gấp khăn: dọn mọi dấu vết còn lại trên thanh Việc tay (nút đã bỏ ở 15c) ----
renderBoard=(orig=>function(){ orig(); const f=document.querySelector('#board [data-mg="fold"]'); if(f) f.remove(); })(renderBoard);
})();

// 20y-fruit.js — Việc 20y: QUẦY TRÁI CÂY DINH CẬU, bước 1 (docs/lenh/mini-game-lam-lai.md, Đại nhân duyệt 14/10 20:02 + 20:34).
// Ca bán 1 lần/tối sau giờ đóng cửa tiệm Chợ đêm, mở từ ghim "Quầy trái cây Dinh Cậu" trên Bản đồ (20b), KHÔNG nằm trong thanh Việc tay.
// Gồm: mở khoá + tin nhắn · bảng Dinh Cậu · mua hàng · ca chơi (full màn, vừa khít dọc/ngang) · khoản trừ · kết quả (khung MG8) · thưởng thế giới.
// Phần lõi (FR.eng) không đụng DOM: bot cân bằng chạy thẳng trên nó. Ảnh: art/out/fr-*.webp (tools/cat_mg_20y.py), literal để build_dist nhúng base64.
(function(){ 'use strict';
// ---------- dữ liệu ----------
const FRUITS=[
  {k:'xoai',     n:'Xoài',       c:6}, {k:'thanhlong',n:'Thanh long', c:5}, {k:'duahau',   n:'Dưa hấu', c:4}, {k:'dua',      n:'Dứa',     c:4},
  {k:'chomchom', n:'Chôm chôm',  c:5}, {k:'mangcut',  n:'Măng cụt',   c:6}, {k:'oi',       n:'Ổi',      c:4}, {k:'dudu',     n:'Đu đủ',   c:4}];   // c = giá nhập nghìn đồng / phần
const IMG_BIG={xoai:'img/c1c9b9d8627c.webp',thanhlong:'img/9c6a590879e8.webp',duahau:'img/1cfd92ec0acf.webp',dua:'img/fa0f3e5a019f.webp',chomchom:'img/a0e4c8b6b4d5.webp',mangcut:'img/fb16a0d2b9ea.webp',dudu:'img/67823c1f57e4.webp',oi:'img/613548797660.webp'};
const IMG_PC={xoai:'img/1bcaec9b8727.webp',thanhlong:'img/876ebbdbc027.webp',duahau:'img/9c584ab33706.webp',dua:'img/f143b036b706.webp',chomchom:'img/d40e4667bb3e.webp',mangcut:'img/d42be5486ddf.webp',oi:'img/0809c8f56876.webp',dudu:'img/a414f0c00390.webp'};   // 22a: miếng rời MG13 (hộp xếp từng miếng)
const IMG_KHAY='img/1406eb537e8f.webp';   // 23c: khay MG18-khay-inox (8 ô đá bảo ủp, nền trong suốt). Miếng/số lượng đặt vào đúng tâm từng ô theo CELLS
// vị trí 8 ô trong ảnh khay (% rộng/cao ảnh): [trái, trên, rộng, cao], đọc từ MG18 (hàng 1 rồi hàng 2, 4 cột)
const CELLS=[[4.5,6.8,21.7,39.4],[27.7,6.8,21.5,39.4],[50.6,6.8,21.5,39.4],[73.5,6.8,21.7,39.4],[4.5,47.4,21.7,40.6],[27.7,47.4,21.5,40.6],[50.6,47.4,21.5,40.6],[73.5,47.4,21.7,40.6]];
const PILE=[[32,68,-8],[68,66,7],[36,44,5],[66,43,-6],[50,57,0]];   // 5 miếng chất đống trong ô: [tâm x %, tâm y %, xoay°]
const IMG_HOP='img/2da7f6dfdac6.webp', IMG_HOP_DONG='img/7c54506eba03.webp', IMG_BUB='img/dd218c2a6ddc.webp', IMG_GIVE='img/f75b250014cd.webp', IMG_NO='img/a1c9e7577046.webp', IMG_CHIP='img/7e08ee74b6a6.webp', IMG_OVAL='img/95c394c949b4.webp', IMG_GO='img/e47516a92641.webp', IMG_TICH='img/b9382ae1e373.webp', IMG_NEN='img/a6c219b6fb5c.webp', IMG_NEN_DOC='img/320da80a9c45.webp', IMG_QUE='img/7edd0d15066f.webp', IMG_MUOI='img/292339290aac.webp', IMG_KQ_O='img/ff2aa53191f0.webp';
const IMG_TAY_TIEN='img/f96fbf2e4723.webp', IMG_XAP='img/362f4dbf40b2.webp', IMG_XU1='img/b00dfead0d6d.webp', IMG_XU2='img/a443dd52f8fb.webp', IMG_XU3='img/54476ac85d92.webp', IMG_SAO='img/165e97d69462.webp', IMG_MAT_BUON='img/6b2198fbc8a9.webp';
const FK=FRUITS.map(f=>f.k), FBY=Object.fromEntries(FRUITS.map(f=>[f.k,f]));
const P={fee:50000, boxFee:2000, small:35000, large:55000, bad:.15, minCash:1e6, boxMax:8, nMin:13, nMax:17, patMin:10, patMax:15, comp:20000, gap:.7, p3:.35, p2:.2, unst:.1, rain:.6, quiet:.7, quietPct:.10, starS:.05, starMax:.2, tayP:.3, tayMax:3, tayWait:.8};
const RAIN=['rain','heavy','storm1','storm3'];
const FR0={tay:0, un:false, intro:0, last:0, hist:[], bonus:0, plays:0, best:null, star:0};
const fr=()=>{ if(!S.fr) S.fr={}; for(const kk in FR0) if(S.fr[kk]===undefined) S.fr[kk]=Array.isArray(FR0[kk])?[]:FR0[kk]; return S.fr; };
const k=v=>fmt(v);
const rn=(a,b)=>a+Math.random()*(b-a), ri=(a,b)=>Math.floor(rn(a,b+1));

// ---------- lõi: một ca bán (không DOM) ----------
function genOrder(stock){
  const nT=Math.random()<P.p3?3:2, ks=[];
  while(ks.length<nT){ const cand=FK.filter(x=>!ks.includes(x)), w=cand.map(x=>stock&&stock[x]>0?1:P.unst); let r=Math.random()*w.reduce((a,b)=>a+b,0), i=0; for(;i<cand.length-1;i++){ r-=w[i]; if(r<=0) break; } ks.push(cand[i]); }
  const items={}; let tot=0; ks.forEach(x=>{ items[x]=Math.random()<P.p2?2:1; tot+=items[x]; });
  for(let i=0;tot>5;i++){ const x=ks[i%ks.length]; if(items[x]>1){ items[x]--; tot--; } }
  return {items, total:tot, price:tot<=3?P.small:P.large, paid:Math.random()<.5, pat:rn(P.patMin,P.patMax)};
}
// buy = {khóa: số phần}; opt = {rain, quiet}. Trả đối tượng ca với các thao tác tap/undo/give/reject/tick.
function newShift(buy, opt){
  opt=opt||{}; const sh={stock:{}, bad:{}, buy:Object.assign({},buy), cost:0, rev:0, comp:0, boxes:0, chuan:0, hong:0, rej:0, out:0, spd:[], box:[], q:[], over:false, why:'', t:0, gap:0, wasted:0, ev:[]};
  FK.forEach(x=>{ const n=Math.max(0,Math.min(9,buy[x]|0)); let bad=0; if(n>=2 && Math.random()<P.bad) bad=Math.max(1,Math.floor(n/3));
    sh.stock[x]=n-bad; sh.bad[x]=bad; sh.cost+=n*FBY[x].c*1000; });
  const mul=(opt.rain?P.rain:1)*(opt.quiet?P.quiet:1); sh.N=Math.max(5,Math.round(ri(P.nMin,P.nMax)*mul)); sh.left=sh.N; sh.opt=opt;
  refill(sh); sh.gap=P.gap; return sh;
}
function refill(sh){ while(sh.q.length<3 && sh.left>0){ sh.q.push(genOrder(sh.stock)); sh.left--; sh.q[sh.q.length-1].t=sh.q[sh.q.length-1].pat; } }
const left=sh=>FK.reduce((a,x)=>a+sh.stock[x],0);
function front(sh){ return sh.gap>0?null:sh.q[0]||null; }   // đang chờ khách bước vào thì chưa phục vụ được
function next(sh, why){ sh.q.shift(); sh.box=[]; sh.gap=P.gap; refill(sh);
  if(!sh.q.length) { sh.over=true; sh.why='het-khach'; }
  else if(left(sh)<=0){ sh.over=true; sh.why='het-hang'; } }
function tap(sh,x){ const c=front(sh); if(sh.over||!c||sh.stock[x]<=0||sh.box.length>=P.boxMax) return false; sh.stock[x]--; sh.box.push(x); return true; }
function undo(sh){ if(sh.over||!sh.box.length) return false; sh.stock[sh.box.pop()]++; return true; }
const boxMatch=(sh,c)=>{ const n={}; sh.box.forEach(x=>n[x]=(n[x]||0)+1); return FK.every(x=>(n[x]||0)===(c.items[x]||0)); };
function give(sh){ const c=front(sh); if(sh.over||!c||!sh.box.length) return null; const ok=boxMatch(sh,c); sh.boxes++;
  if(ok){ sh.rev+=c.price; sh.chuan++; sh.spd.push(clamp(c.t/c.pat,0,1)); }
  else { sh.hong++; sh.wasted+=sh.box.length; if(c.paid) sh.comp+=P.comp; }
  const r=ok?'chuan':'sai'; sh.ev.push(r); next(sh); return r; }
function reject(sh){ const c=front(sh); if(sh.over||!c) return false; sh.box.forEach(x=>sh.stock[x]++); sh.rej++; sh.ev.push('tuchoi'); next(sh); return true; }
function tick(sh,dt){ if(sh.over) return; sh.t+=dt;
  if(sh.gap>0){ sh.gap-=dt; return; }
  const c=sh.q[0]; if(!c) return; c.t-=dt;
  if(c.t<=0){ if(sh.box.length){ sh.boxes++; sh.wasted+=sh.box.length; } sh.out++; sh.ev.push('het'); next(sh); } }
function finish(sh){ const leftC=FK.reduce((a,x)=>a+sh.stock[x]*FBY[x].c*1000,0), badC=FK.reduce((a,x)=>a+sh.bad[x]*FBY[x].c*1000,0);
  const boxFee=sh.boxes*P.boxFee, net=sh.rev-sh.cost-P.fee-boxFee-sh.comp, avgSpd=sh.spd.length?sh.spd.reduce((a,b)=>a+b,0)/sh.spd.length:0;
  const score=clamp(80*sh.chuan/sh.N+20*avgSpd-4*sh.out-1*sh.rej,0,100);
  return {rev:sh.rev, cost:sh.cost, fee:P.fee, boxFee, comp:sh.comp, net, leftC, badC, score, grade:gradeOf(score), chuan:sh.chuan, N:sh.N, hong:sh.hong, out:sh.out, rej:sh.rej, avgSpd}; }

// ---------- trạng thái thế giới ----------
const dayGross=()=>{ const l=(S.svcLog||[]).slice(-3); return l.length? l.reduce((a,x)=>a+(x.gross||0),0)/l.length : 0; };
function quiet(){ const h=fr().hist.slice(-3); if(h.length<3) return false; const g=dayGross(); return g>0 && h.reduce((a,b)=>a+b,0)/h.length > P.quietPct*g; }   // trần im lặng: lời TB 3 ca gần nhất > 10% doanh thu spa TB 3 ngày
const rainy=()=>!!(S.wx&&RAIN.includes(S.wx.today));
function unlockCond(){ const sh=S.shops&&S.shops.chodem, F=fr();
  return [ ['Tiệm Chợ đêm mở cửa từ 30 ngày', !!sh && S.day-(sh.opened||1)>=30], ['Đạt từ 4,0★', rating()>=4], ['Góp đúng hạn kỳ vay đầu', (S.loan&&S.loan.paidOnTime||0)>=1], ['Đã phục vụ 20 khách Tây', F.tay>=20] ]; }
function frCheck(){ const F=fr(); if(F.un||!S.shops||!S.shops.chodem||S.bankrupt) return;
  if(!unlockCond().every(c=>c[1])) return; F.un=true; save();
  inboxMsg('Anna (khách Tây quen)','Hi! Tối nay mình ra Dinh Cậu ngắm hoàng hôn, mà ở đó không có chỗ mua trái cây. Bạn bán trái cây ở đó được không? Khách Tây đi nhiều lắm! 🍉 (Ghim "Quầy trái cây Dinh Cậu" đã hiện trên Bản đồ.)');
  setTimeout(()=>toast('Ghim mới trên Bản đồ: Quầy trái cây Dinh Cậu','good'),600); }
const THU=/[?&]thu=traicay(&|$)/.test(location.search);   // 23e: cong tac THU cho Dai nhan test (?thu=traicay): quay mo ngay, KHONG ghi F.un vao save, luat mo khoa that giu nguyen
const canOpen=()=>{ const F=fr(); if(!F.un&&!THU) return 'Chưa mở khoá.'; if(S.stage!=='closed'||S.bankrupt) return 'Quầy chỉ mở buổi tối, sau khi đóng cửa tiệm.'; if(F.last===S.day) return 'Tối nay bạn đã bán một ca rồi.'; if(S.cash<P.minCash) return 'Cần ít nhất '+k(P.minCash)+' tiền mặt để nhập hàng.'; return ''; };

// ---------- bảng Dinh Cậu ----------
const DINH=[
  'Dinh Cậu là ngôi miếu nhỏ nằm trên ghềnh đá ở cửa sông Dương Đông, nhìn thẳng ra biển.',
  'Miếu được xây khoảng năm 1937.',
  'Nơi đây thờ Chúa Ngọc Nương Nương cùng Cậu Tài và Cậu Quý.',
  'Ngư dân thường ghé lễ ở đây trước khi ra khơi, cầu biển êm cá đầy.',
  'Lễ hội Dinh Cậu tổ chức vào ngày 15–16 tháng 10 âm lịch hằng năm.',
  'Du khách đi bậc đá lên miếu, rồi đứng ngắm hoàng hôn trên mặt biển.'];
function frDinh(then){ sheet(`${mgHead('i_foot','Dinh Cậu','Miếu nhỏ bên cửa sông Dương Đông, Phú Quốc')}
  <ul class="fr-dinh">${DINH.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>
  <div class="row"><button class="btn big butter" data-ok>${then?'Vào quầy':'Đã hiểu'}</button></div>`, sh=>{
    sh.querySelector('[data-ok]').onclick=()=>{ fr().intro=1; save(); closeSheet(); if(then) then(); }; }); }

// ---------- vào ca ----------
function frStart(){ const why=canOpen(); if(why){ toast(why,'warn'); return; } if(window.bdClose) bdClose();
  const go=()=>mgIntro('fruit','Tối ở Dinh Cậu khách Tây rất đông. Nhập trái cây, rồi pha từng hộp đúng order: chạm ô để bỏ vào hộp, chạm hộp để bỏ ra, bấm Đóng hộp khi đủ. Hàng không bán hết sẽ hư.', frBuy, null, 'Để sau'); const ic=document.querySelector('#sheet .mg-ico img'); if(ic) ic.src=IMG_BIG.xoai;
  if(!fr().intro) frDinh(go); else go(); }

// ---------- giao diện ----------
// 22a (làm kỹ lần 2): hộp xếp từng miếng rời (MG13), khay MG14, nút MG15, tiền MG16, nền dọc MG17. Luật chơi/kinh tế giữ nguyên.
// Ngang: nền MG10 1672x941 (giữ 20z). Dọc: nền MG17 940x1672. Khay/hộp/nút đặt theo % khung nền, cỡ chữ theo --s;
// cụm khách + chip nằm lớp .fr-safe (px màn, trong vùng an toàn) để Dynamic Island không cắt.
const css=document.createElement('style'); css.textContent=`
#fr{position:fixed;inset:0;z-index:9400;overflow:hidden;background:#c79a62;color:#5a3d2a;font-family:var(--font-body);touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}
#fr button{font-family:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}
#fr .fr-img{position:absolute;background:#c79a62 no-repeat center/100% 100%}
#fr.land .fr-img{background-image:url(${IMG_NEN})} #fr.por .fr-img{background-image:url(${IMG_NEN_DOC})}
#fr.buy .fr-img::after{content:"";position:absolute;inset:0;background:rgba(255,246,228,.36)}
.fr-safe{position:absolute;left:env(safe-area-inset-left,0px);right:env(safe-area-inset-right,0px);top:env(safe-area-inset-top,0px);bottom:env(safe-area-inset-bottom,0px);pointer-events:none}.fr-safe>*{pointer-events:auto}
#fr .fr-play{position:absolute;inset:0}
/* chip trạng thái: 1 hàng sát mép trên, dưới safe-area */
.fr-hud{position:absolute;left:6px;right:6px;top:4px;height:28px;display:flex;align-items:center;gap:6px;z-index:5;font:800 max(var(--fs-min),12px)/1 var(--font-display);color:#6a3f1c}
.fr-hud .fr-sp{flex:1}
.fr-hud b,.fr-hud button{background:url(${IMG_CHIP}) center/100% 100% no-repeat;border:0;color:#6a3f1c;height:28px;padding:0 14px;white-space:nowrap;display:flex;align-items:center;font:800 max(var(--fs-min),12px)/1 var(--font-display);box-sizing:border-box;min-width:34px;justify-content:center}
#fr.land .fr-hud .fr-sp{display:none} #fr.land .fr-hud{justify-content:flex-end}
/* cụm khách (lớp an toàn): chân dung + vòng kiên nhẫn, bong bóng order, 2 khách chờ */
.fr-cus{position:absolute;left:3vw;top:36px;z-index:3;pointer-events:none}
#fr.por .fr-cus{--R:30vw;--B:62vw} #fr.land .fr-cus{--R:min(16vw,35vh);--B:min(22vw,40vh);left:10px;top:34px}
.fr-cu{position:absolute;left:0;top:0;width:var(--R);height:var(--R)}
.fr-cu.in{animation:frIn .4s ease-out}
@keyframes frIn{from{opacity:0;transform:translateX(-30px)}to{opacity:1;transform:none}}
.fr-cu .prw{position:absolute;inset:0;filter:drop-shadow(0 0 5px var(--c,#6faa4a))}
.fr-cu .pr{position:absolute;inset:0;border-radius:50%;background:conic-gradient(var(--c,#6faa4a) var(--p,360deg),rgba(70,45,20,.28) 0);-webkit-mask:radial-gradient(farthest-side,transparent calc(100% - 9px),#4A3A2C calc(100% - 8px));mask:radial-gradient(farthest-side,transparent calc(100% - 9px),#4A3A2C calc(100% - 8px))}
.fr-cu .ph{position:absolute;inset:9px;border-radius:50%;overflow:hidden;background:#8fbf7a;border:3px solid #fff8ec;box-shadow:0 2px 6px rgba(60,35,10,.35)}
.fr-cu .ph img{width:100%;height:100%;object-fit:cover;object-position:50% 12%;display:block}
.fr-cu.hot{animation:frHot .3s linear infinite alternate}
@keyframes frHot{from{transform:translate(-1.5px,0) rotate(-2deg)}to{transform:translate(1.5px,1px) rotate(2deg)}}
.fr-cu .coin{position:absolute;right:-4%;top:-4%;width:24%;z-index:2;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 35% 30%,#ffe58a,#e6a91c);border:2px solid #fff8ec;display:flex;align-items:center;justify-content:center;font:800 calc(var(--R)*.13)/1 var(--font-display);color:#8a5a00}
.fr-cu .face{position:absolute;left:14%;top:14%;z-index:3;width:72%;height:72%;object-fit:contain;animation:frFace .25s ease-out}
@keyframes frFace{from{transform:scale(.4);opacity:0}}
.fr-w{position:absolute;z-index:1;aspect-ratio:1;border-radius:50%;overflow:hidden;border:2px solid #fff8ec;background:#8fbf7a;box-shadow:0 2px 5px rgba(60,35,10,.35);opacity:.6;pointer-events:none}
.fr-w img{width:100%;height:100%;object-fit:cover;object-position:50% 12%;display:block;filter:saturate(.7) blur(.6px)}
#fr.por .fr-w{width:11vw;top:calc(var(--R) + 8px)} #fr.por .fr-w1{left:calc(var(--R)/2 - 11vw - 2px)} #fr.por .fr-w2{left:calc(var(--R)/2 + 2px)}
#fr.land .fr-w{width:6.5vw;top:calc(var(--R)*.4)} #fr.land .fr-w1{left:calc(var(--R) + var(--B) + 14px)} #fr.land .fr-w2{left:calc(var(--R) + var(--B) + 14px + 6.5vw + 6px)}
.fr-bub{position:absolute;z-index:2;left:calc(var(--R) + 8px);top:0;width:var(--B);aspect-ratio:320/223;background:url(${IMG_BUB}) center/100% 100% no-repeat;display:flex;flex-wrap:nowrap;align-items:center;justify-content:center;gap:calc(var(--B)*.025);padding:calc(var(--B)*.04) calc(var(--B)*.06) calc(var(--B)*.1) calc(var(--B)*.08);box-sizing:border-box}
.fr-bi{position:relative;flex:none;width:calc(var(--B)*.27);aspect-ratio:1;display:flex;align-items:center;justify-content:center}
.fr-bi>img.ic{width:94%;height:94%;object-fit:contain}
.fr-bi b{position:absolute;right:-3%;bottom:-3%;min-width:calc(var(--B)*.13);height:calc(var(--B)*.11);padding:0 calc(var(--B)*.02);border-radius:99px;background:#fff5dc;border:2px solid #b9803f;color:#6a3f1c;font:800 calc(var(--B)*.075)/calc(var(--B)*.1) var(--font-display);text-align:center;box-sizing:border-box}
.fr-bi .ck{position:absolute;left:-6%;top:-6%;width:44%;height:44%;object-fit:contain;z-index:2;animation:frFace .2s ease-out}
.fr-bub .tg{position:absolute;left:50%;top:84%;transform:translateX(-50%);height:calc(var(--B)*.14);padding:0 calc(var(--B)*.07);background:url(${IMG_OVAL}) center/100% 100% no-repeat;display:flex;align-items:center;font:800 calc(var(--B)*.065)/1 var(--font-display);color:#FBF6EA;text-shadow:0 1px 2px #3a6a28;white-space:nowrap}
.fr-fx{position:absolute;inset:0;pointer-events:none;z-index:7;overflow:hidden}
.fr-fb{position:absolute;font:800 clamp(22px,6vw,40px)/1 var(--font-display);color:#FBF6EA;text-shadow:0 1px 3px rgba(60,35,10,.85),0 0 2px #4A3A2C;pointer-events:none;animation:frFb 1.1s ease-out forwards;white-space:nowrap}
.fr-fb.bad{color:#F4C7B5} .fr-fb.good{color:#fff08a}
@keyframes frFb{0%{transform:translate(-50%,0) scale(.6);opacity:0}20%{transform:translate(-50%,-8px) scale(1.25);opacity:1}to{transform:translate(-50%,-44px) scale(1);opacity:0}}
.fr-fx img{position:absolute;pointer-events:none}
/* khay: ô luôn dùng ảnh MG14 cột ĐẦY; hết hàng = ô mờ + số 0 */
.fr-tray{position:absolute;z-index:2}
#fr.land .fr-tray{left:4.5%;top:40.5%;width:45.5%} #fr.por .fr-tray{left:calc(50% - var(--vis,1)*50.5%);top:36.8%;width:calc(var(--vis,1)*101%)}
.fr-tray>img.kh{display:block;width:100%;aspect-ratio:1374/851;pointer-events:none;filter:drop-shadow(0 3px 3px rgba(60,35,10,.3))}
.fr-grid{position:absolute;inset:0}
.fr-cell{position:absolute;background:none;border:0;padding:0;min-width:0;min-height:0}
.fr-cell .fi{position:absolute;inset:0;pointer-events:none;transition:transform .15s,opacity .2s}
.fr-cell .fi img{position:absolute;width:48%;transform:translate(-50%,-50%);object-fit:contain;filter:drop-shadow(0 1px 1.5px rgba(70,110,160,.4))}
.fr-cell:active .fi{transform:scale(.94)}
.fr-cell .nm{position:absolute;right:4%;bottom:5%;min-width:calc(var(--s)*54px);height:calc(var(--s)*54px);padding:0 calc(var(--s)*8px);border-radius:99px;background:#fff5dc;border:calc(var(--s)*4px) solid #b9803f;color:#6a3f1c;font:800 calc(var(--s)*32px)/calc(var(--s)*46px) var(--font-display);text-align:center;box-sizing:border-box}
.fr-cell[data-lv="0"] .fi{opacity:0} .fr-cell[data-lv="0"] .nm{background:#eee;border-color:#a8a29a;color:#8a847c}
.fr-cell.pop .fi{animation:frPop .16s}
@keyframes frPop{50%{transform:scale(1.08)}}
/* hộp: ảnh hộp rỗng cố định + từng miếng rời xếp bên trong + nắp */
.fr-boxw{position:absolute;z-index:3;aspect-ratio:900/712;background:none;border:0;padding:0}
#fr.land .fr-boxw{left:73%;top:28%;width:24%} #fr.por .fr-boxw{left:20%;top:62.5%;width:46%}
.fr-boxw>img.box,.fr-boxw>img.front,.fr-boxw>img.shut{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
#frPcs{position:absolute;inset:0;pointer-events:none}
.fr-pc{position:absolute;width:13%;object-fit:contain;pointer-events:none;filter:drop-shadow(0 1px 1px rgba(60,35,10,.35))}
.fr-boxw>img.front{clip-path:polygon(0 61%,31% 71%,43% 77%,75% 77%,100% 62%,100% 100%,0 100%);opacity:.9}
.fr-boxw>img.shut{z-index:200}
.fr-deco{position:absolute;z-index:2;pointer-events:none;object-fit:contain;filter:drop-shadow(0 2px 3px rgba(60,35,10,.3))}
#fr.land .fr-que{left:91.5%;top:39%;width:6%} #fr.por .fr-que{left:69%;top:62.5%;width:9%}
#fr.land .fr-muoi{left:89.5%;top:58%;width:6.5%} #fr.por .fr-muoi{left:68%;top:73%;width:15%}
/* nút ảnh MG15 */
.fr-btn{position:absolute;z-index:4;background:none;border:0;padding:0;display:block}
.fr-btn>img{width:100%;height:100%;object-fit:contain;display:block;pointer-events:none;filter:drop-shadow(0 3px 3px rgba(60,35,10,.35))}
.fr-btn .lb{position:absolute;left:50%;bottom:-6%;transform:translateX(-50%);background:url(${IMG_CHIP}) center/100% 100% no-repeat;color:#6a3f1c;font:800 calc(var(--s)*30px)/1 var(--font-display);padding:calc(var(--s)*12px) calc(var(--s)*26px);white-space:nowrap}
.fr-give .lb{background-image:url(${IMG_OVAL});color:#FBF6EA;text-shadow:0 1px 2px #3a6a28}
.fr-btn:active{transform:translateY(2px)} .fr-btn[disabled]{opacity:.5;filter:grayscale(.5)}
#fr.land .fr-give{left:74.5%;top:63%;width:14.5%;aspect-ratio:320/218} #fr.land .fr-no{left:90%;top:68%;width:8%;aspect-ratio:320/225}
#fr.por .fr-give{left:13%;top:84%;width:40%;aspect-ratio:320/218} #fr.por .fr-no{left:60%;top:85%;width:27%;aspect-ratio:320/225}
/* mua hàng */
.fr-buy{position:absolute;inset:0;display:flex;flex-direction:column;gap:6px;padding:8px 10px}
.fr-buy .tt{flex:0 0 auto;display:flex;align-items:center;gap:8px;background:rgba(70,45,20,.62);border-radius:12px;padding:5px 10px;color:#FBF6EA;text-shadow:0 1px 3px rgba(60,35,10,.8);font:800 var(--fz-than)/1.1 var(--font-display)}
.fr-buy .tt small{font:700 max(var(--fs-min),10px)/1.25 var(--font-body);opacity:.95;display:block}
.fr-buy .tt .fr-sp{flex:1}
.fr-buy .tt .cash{font:800 max(var(--fs-min),12px)/1 var(--font-display);white-space:nowrap;color:#FBF6EA}
.fr-top{flex:1;min-height:0} .fr-mid{flex:0 0 0}
#fr.land .fr-top{flex:1}
#fr.land .fr-mid{flex:.1}
.fr-bg{display:grid;gap:6px;grid-template-columns:repeat(4,1fr);grid-auto-rows:calc(100dvh/6.3);flex:0 0 auto}
#fr.por .fr-bg{grid-template-columns:repeat(2,1fr)}
.fr-bc{background:rgba(255,249,236,.95);border:2px solid #d9b27c;border-radius:12px;display:flex;align-items:center;gap:6px;padding:4px 6px;min-height:0;min-width:0;box-sizing:border-box;box-shadow:0 2px 5px rgba(60,35,10,.25)}
.fr-bc img{height:88%;width:34%;object-fit:contain;flex:0 0 auto}
.fr-bc .in{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;min-width:0;flex:1}
#fr.por .fr-bc{flex-direction:column;justify-content:center;gap:2px}
#fr.por .fr-bc img{height:42%;width:auto;max-width:70%} #fr.por .fr-bc .in{flex:0 0 auto;gap:2px}
.fr-bc .n{font:800 max(var(--fs-min),12px)/1.1 var(--font-display);white-space:nowrap} .fr-bc .p{font:700 max(var(--fs-min),10px)/1 var(--font-body);color:#8b6a4a;white-space:nowrap}
.fr-st{display:flex;align-items:center;gap:5px}
.fr-st button{width:28px;height:28px;border-radius:50%;border:2px solid #8b5a2b;background:#FBF6EA;color:#5a3d2a;font:800 var(--fz-muc)/1 var(--font-display);padding:0}
#fr.por .fr-st button{width:32px;height:32px}
.fr-st button:disabled{opacity:.35}
.fr-st b{min-width:16px;text-align:center;font:800 var(--fz-than)/1 var(--font-display)}
.fr-ft{display:flex;align-items:center;gap:6px;flex:0 0 auto}
.fr-ft .sum{flex:1;min-width:0;background:rgba(70,45,20,.66);color:#FBF6EA;border-radius:12px;padding:0 10px;height:40px;display:flex;align-items:center;font:700 max(var(--fs-min),10.5px)/1 var(--font-body);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fr-ft .sum b{font-family:var(--font-display);margin:0 2px}
.fr-ft .fr-nb{flex:0 0 auto;height:44px;min-width:92px;border:0;padding:0 20px;background:center/100% 100% no-repeat;font:800 var(--fz-than)/1 var(--font-display);white-space:nowrap}
.fr-ft .fr-nb.go{background-image:url(${IMG_OVAL});color:#FBF6EA;text-shadow:0 1px 2px #3a6a28} .fr-ft .fr-nb.x{background-image:url(${IMG_GO});color:#6a3f1c}
.fr-ft .fr-nb:disabled{opacity:.5;filter:grayscale(.4)}
.fr-ask{position:absolute;inset:0;z-index:20;background:rgba(40,25,10,.5);display:flex;align-items:center;justify-content:center;padding:16px}
.fr-ask>div{background:#fff8ec;border:3px solid #b98b53;border-radius:16px;padding:14px;max-width:330px;text-align:center;display:flex;flex-direction:column;gap:10px;font-size:var(--fz-ghichu);line-height:1.35}
.fr-ask .row{display:flex;gap:8px;justify-content:center}
/* bảng Dinh Cậu */
.fr-dinh{margin:0;padding:0 0 0 18px;font-size:var(--fz-ghichu);line-height:1.3;color:#5a3d2a;display:flex;flex-direction:column;gap:3px}
@media (orientation:landscape) and (max-height:520px){ .fr-dinh{display:grid;grid-template-columns:1fr 1fr;gap:3px 22px;font-size:var(--fz-ghichu)} }
/* kết quả */
.kq-tb{width:100%;font-size:var(--fz-ghichu);line-height:1.25;color:#5a3d2a}
.kq-tb div{display:flex;justify-content:space-between;gap:8px;padding:1px 2px;border-bottom:1px dotted rgba(139,90,43,.35)}
.kq-tb div.n{border:0;font:800 var(--fz-muc)/1.2 var(--font-display);padding-top:3px}
.kq-tb .g{color:#2f7d3a}.kq-tb .r{color:#C96A5A}
`; document.head.appendChild(css);

// ---- tiếng: ưu tiên module AUDIO (21e, file sfx-tien); chưa có file thì bip chuông / trầm bằng WebAudio. FR.sfxOn = công tắc ----
const SND={tien:0, tram:0}; let ac=null;
function tone(f0,f1,dur,type,vol){ try{ ac=ac||new (window.AudioContext||window.webkitAudioContext)(); if(ac.state==='suspended') ac.resume(); const t=ac.currentTime, o=ac.createOscillator(), g=ac.createGain(); o.type=type; o.frequency.setValueAtTime(f0,t); o.frequency.exponentialRampToValueAtTime(f1,t+dur);
  g.gain.setValueAtTime(vol,t); g.gain.exponentialRampToValueAtTime(.001,t+dur); o.connect(g); g.connect(ac.destination); o.start(t); o.stop(t+dur+.02); }catch(e){} }
function ping(kind){ SND[kind]++; if(!window.FR||!FR.sfxOn) return;
  if(kind==='tien'){ if(window.AUDIO&&AUDIO.over&&AUDIO.over('pay')) return; tone(1320,1320,.28,'sine',.18); setTimeout(()=>tone(1976,1976,.34,'sine',.16),110); }
  else tone(150,90,.3,'triangle',.22); }

let ui=null;   // {el, sh, buy, raf, ...}
const el=(h)=>{ const d=document.createElement('div'); d.innerHTML=h; return d.firstElementChild; };
function mount(){ frClose(); const e=el(`<div id="fr" role="dialog" aria-label="Quầy trái cây Dinh Cậu"><div class="fr-img"></div><div class="fr-safe"></div></div>`); document.body.appendChild(e); ui={el:e, img:e.querySelector('.fr-img'), safe:e.querySelector('.fr-safe'), raf:0, cl:[], busy:false, timers:[]};
  ui.onR=()=>layout(); window.addEventListener('resize',ui.onR); window.addEventListener('orientationchange',ui.onR); layout(); return ui; }
function frClose(){ if(!ui) return; cancelAnimationFrame(ui.raf); (ui.timers||[]).forEach(clearTimeout); window.removeEventListener('resize',ui.onR); window.removeEventListener('orientationchange',ui.onR); ui.el.remove(); ui=null; }
const DES={land:[1672,941], por:[940,1672]};   // cỡ khung nền thiết kế
function layout(){ if(!ui) return; const W=innerWidth, H=innerHeight, land=W/H>=1.6; ui.el.classList.toggle('land',land); ui.el.classList.toggle('por',!land); ui.land=land;
  const [dw,dh]=DES[land?'land':'por'], s=Math.max(W/dw,H/dh), w=dw*s, h=dh*s;   // cover: phủ toàn màn, thừa thì cắt đều hai bên
  ui.img.style.cssText=`left:${(W-w)/2}px;top:${(H-h)/2}px;width:${w}px;height:${h}px;--s:${s};--vis:${Math.min(1,W/w)}`; }
// ---- mua hàng ----
function frBuy(){ closeSheet(); mount(); ui.el.classList.add('buy'); const buy={}; FK.forEach(x=>buy[x]=5); ui.buy=buy;
  ui.safe.innerHTML=`<div class="fr-buy">
    <div class="tt"><div>Nhập trái cây<small>Phí chỗ ${k(P.fee)} · hộp ${k(P.boxFee)} · hộp nhỏ ${k(P.small)} / lớn ${k(P.large)}</small></div><span class="fr-sp"></span><b class="cash">Tiền mặt ${k(S.cash)}</b><button class="fr-i" data-chuy="mg-quay-trai-cay" aria-label="Chú ý: hướng dẫn màn này">!</button></div>
    <div class="fr-top"></div>
    <div class="fr-bg">${FRUITS.map(f=>`<div class="fr-bc"><img src="${IMG_BIG[f.k]}" alt="" draggable="false"><div class="in"><span class="n">${f.n}</span><span class="p">${f.c}k / phần</span><div class="fr-st"><button data-m="${f.k}" aria-label="Bớt ${f.n}">−</button><b data-n="${f.k}">0</b><button data-p="${f.k}" aria-label="Thêm ${f.n}">+</button></div></div></div>`).join('')}</div>
    <div class="fr-mid"></div>
    <div class="fr-ft"><div class="sum" id="frSum"></div><button class="fr-nb x" data-x>Để sau</button><button class="fr-nb go" data-go>Mở ca</button></div></div>`;
  const upd=()=>{ const tot=FK.reduce((a,x)=>a+buy[x],0), cost=FK.reduce((a,x)=>a+buy[x]*FBY[x].c*1000,0);
    FK.forEach(x=>{ ui.safe.querySelector(`[data-n="${x}"]`).textContent=buy[x]; ui.safe.querySelector(`[data-m="${x}"]`).disabled=buy[x]<=0; ui.safe.querySelector(`[data-p="${x}"]`).disabled=buy[x]>=9; });
    ui.safe.querySelector('#frSum').innerHTML=`${tot} phần - hàng <b>${k(cost)}</b> + phí <b>${k(P.fee)}</b> = <b>${k(cost+P.fee)}</b>${rainy()?' · mưa: khách thưa':''}`;
    ui.safe.querySelector('[data-go]').disabled=tot<=0; ui.cost=cost; };
  ui.el.addEventListener('click',e=>{ const b=e.target.closest('.fr-buy button'); if(!b) return;
    if(b.dataset.m){ buy[b.dataset.m]=Math.max(0,buy[b.dataset.m]-1); upd(); } else if(b.dataset.p){ buy[b.dataset.p]=Math.min(9,buy[b.dataset.p]+1); upd(); }
    else if('x' in b.dataset) frClose(); else if('go' in b.dataset){ if(S.cash<ui.cost+P.fee){ toast('Không đủ tiền nhập từng này.','warn'); return; } frPlay(buy); } });
  upd(); }
// ---- ca chơi ----
const portraitOf=c=>{ if(!c.pid) c.pid=pick(GUEST_POOL.tay); return IMG[c.pid]; };
function bubHtml(c){ return FK.filter(x=>c.items[x]).map(x=>`<div class="fr-bi" data-k="${x}"><img class="ic" src="${IMG_BIG[x]}" alt="${FBY[x].n}" draggable="false"><b>×${c.items[x]}</b></div>`).join('')+`<span class="tg">${c.total<=3?'Hộp nhỏ':'Hộp lớn'} ${k(c.price)}</span>`; }
// 15 chỗ miếng trong lòng hộp mở MG19 (% ảnh hộp, xếp từ dưới lên). Mỗi phần = 3-4 miếng chọn ngẫu nhiên trong vài chỗ trống thấp nhất, lệch 2-4% + xoay ±10°, miếng sau đè miếng trước.
const SLOTS=[[27,77],[40,80],[53,80],[66,78],[78,72],[24,69],[37,71],[50,71],[63,69],[75,64],[28,61],[41,62],[54,62],[66,60],[77,56]];
function frPlay(buy){ const q=quiet(), rain=rainy(); const sh=newShift(buy,{rain, quiet:q}); ui.sh=sh; ui.shown=null; ui.paidOut=0; ui.el.classList.remove('buy'); ui.timers=[]; ui.shownRev=0;
  const badN=FK.filter(x=>sh.bad[x]>0).map(x=>`Lô ${FBY[x].n.toLowerCase()} kém, huỷ ${sh.bad[x]} phần`);   // hàng hư KHÔNG bày lên quầy: đã trừ khỏi tồn ngay, chỉ báo 1 lần
  if(badN.length) setTimeout(()=>toast(badN.join(' · '),'warn'),300);
  ui.safe.innerHTML=`<div class="fr-hud"><button data-quit>Dừng ca</button><span class="fr-sp"></span><b id="frN"></b><b id="frM"></b><button class="fr-i" data-chuy="mg-quay-trai-cay" aria-label="Chú ý: hướng dẫn màn này">!</button></div><div class="fr-cus" id="frCus"></div><div class="fr-fx" id="frFx"></div>`;
  ui.pl=el(`<div class="fr-play">
    <div class="fr-tray"><img class="kh" src="${IMG_KHAY}" alt="" draggable="false"><div class="fr-grid" id="frGrid">${FRUITS.map((f,i)=>`<button class="fr-cell" data-c="${f.k}" aria-label="${f.n}" style="left:${CELLS[i][0]}%;top:${CELLS[i][1]}%;width:${CELLS[i][2]}%;height:${CELLS[i][3]}%"><span class="fi">${PILE.map(([x,y,r])=>`<img src="${IMG_PC[f.k]}" alt="" draggable="false" style="left:${x}%;top:${y}%;rotate:${r}deg">`).join('')}</span><span class="nm"></span></button>`).join('')}</div></div>
    <img class="fr-deco fr-que" src="${IMG_QUE}" alt="" draggable="false"><img class="fr-deco fr-muoi" src="${IMG_MUOI}" alt="" draggable="false">
    <button class="fr-boxw" id="frBox" aria-label="Bỏ phần cuối ra khỏi hộp"><img class="box" src="${IMG_HOP}" alt="" draggable="false"><div id="frPcs"></div><img class="front" src="${IMG_HOP}" alt="" draggable="false"><img class="shut" src="${IMG_HOP_DONG}" alt="" draggable="false" hidden></button>
    <button class="fr-btn fr-give" data-give disabled aria-label="Đóng hộp"><img src="${IMG_GIVE}" alt="" draggable="false"><span class="lb">Đóng hộp</span></button><button class="fr-btn fr-no" data-no aria-label="Từ chối"><img src="${IMG_NO}" alt="" draggable="false"><span class="lb">Từ chối</span></button></div>`);
  ui.img.appendChild(ui.pl); layout();
  const root=ui.pl, cus=ui.safe.querySelector('#frCus'), fx=ui.safe.querySelector('#frFx'), place=(cls,html)=>{ const d=document.createElement('div'); d.className=cls; d.innerHTML=html; return d; };
  const hudEl=ui.safe, later=(f,ms)=>{ const t=setTimeout(()=>{ if(ui&&ui.sh===sh) f(); },ms); ui.timers.push(t); return t; };
  const rel=r=>{ const b=ui.safe.getBoundingClientRect(); return {x:r.left+r.width/2-b.left, y:r.top+r.height/2-b.top, w:r.width, h:r.height}; };
  const fb=(t,cls)=>{ const f=document.createElement('div'); f.className='fr-fb '+(cls||''); f.textContent=t; const p=ui.cu?rel(ui.cu.getBoundingClientRect()):{x:innerWidth*.3,y:90,h:60}; f.style.left=p.x+'px'; f.style.top=(p.y-p.h*.15)+'px'; fx.appendChild(f); setTimeout(()=>f.remove(),1100); };
  const hud=()=>{ hudEl.querySelector('#frN').textContent=`Khách ${Math.min(sh.N,sh.N-sh.left-sh.q.length+1)}/${sh.N}`;
    const m=hudEl.querySelector('#frM'), from=ui.shownRev, to=sh.rev; if(from===to){ m.textContent=`Thu ${k(to)}`; return; }
    ui.shownRev=to; const t0=performance.now(); const step=n=>{ if(!ui||ui.sh!==sh) return; const f=clamp((n-t0)/500,0,1); m.textContent=`Thu ${k(Math.round(from+(to-from)*f))}`; if(f<1) requestAnimationFrame(step); }; requestAnimationFrame(step); m.animate([{transform:'scale(1.25)'},{transform:'none'}],260); };
  const cellsRefresh=()=>{ FK.forEach(x=>{ const c=root.querySelector(`[data-c="${x}"]`), n=sh.stock[x]; c.querySelector('.nm').textContent=n; c.dataset.lv=n<=0?0:1; }); };   // khay luôn "đầy": chỉ huy hiệu số đổi; hết hàng -> ô mờ + số 0
  // ----- hộp theo lớp: mỗi phần bỏ vào = nhiều miếng rời -----
  const bx=root.querySelector('#frBox'), pcs=root.querySelector('#frPcs'), shut=bx.querySelector('.shut'), opn=bx.querySelectorAll('.box,.front'), give_=root.querySelector('[data-give]');
  const perPart=()=>{ const c=sh.q[0]; return c&&c.total>3?3:4; };
  const freeSlots=()=>{ const used=new Set(); ui.cl.forEach(c=>c.slots.forEach(s=>used.add(s))); return SLOTS.map((_,i)=>i).filter(i=>!used.has(i)); };
  function addCluster(key, from){ const n=perPart(), cl={k:key, els:[], slots:[]}, br=bx.getBoundingClientRect();
    for(let i=0;i<n;i++){ let free=freeSlots(), over=false; if(!free.length){ free=SLOTS.map((_,j)=>j); over=true; }
      const s=free[Math.floor(Math.random()*Math.min(4,free.length))]; cl.slots.push(over?-1:s); const x=SLOTS[s][0]+rn(-3,3), y=SLOTS[s][1]+rn(-4,4)-(over?6:0), rot=rn(-10,10), z=++ui.z;
      const im=document.createElement('img'); im.className='fr-pc'; im.src=IMG_PC[key]; im.alt=''; im.draggable=false; im.style.cssText=`left:${x}%;top:${y}%;z-index:${z};transform:translate(-50%,-50%) rotate(${rot}deg)`; im.dataset.rot=rot; pcs.appendChild(im); cl.els.push(im);
      if(from){ const f1=from.getBoundingClientRect(), dx=f1.left+f1.width/2-(br.left+br.width*x/100), dy=f1.top+f1.height*.4-(br.top+br.height*y/100);
        im.animate([{transform:`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px)) rotate(0deg) scale(1.5)`,opacity:.9},{transform:`translate(-50%,-50%) rotate(${rot}deg) scale(1)`,opacity:1}],{duration:250,delay:i*30,easing:'ease-out',fill:'backwards'}); } }
    ui.cl.push(cl); }
  function popCluster(to){ const cl=ui.cl.pop(); if(!cl) return;
    cl.els.forEach((im,i)=>{ if(to){ const r=im.getBoundingClientRect(), t=to.getBoundingClientRect(), dx=t.left+t.width/2-(r.left+r.width/2), dy=t.top+t.height*.4-(r.top+r.height/2), rot=im.dataset.rot;
        const a=im.animate([{transform:`translate(-50%,-50%) rotate(${rot}deg)`,opacity:1},{transform:`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px)) rotate(0deg) scale(1.3)`,opacity:0}],{duration:250,delay:i*25,easing:'ease-in',fill:'forwards'}); a.onfinish=()=>im.remove(); } else im.remove(); }); }
  ui.z=0; ui.cl=[];
  const boxRefresh=()=>{ const keep=sh.box.length;   // đồng bộ cụm miếng với sh.box (đổi khách / huỷ hộp -> dọn sạch)
    while(ui.cl.length>keep) popCluster(ui.flyTo||null); ui.flyTo=null; while(ui.cl.length<keep) addCluster(sh.box[ui.cl.length], ui.flyFrom); ui.flyFrom=null;
    if(!keep){ pcs.innerHTML=''; ui.z=0; ui.cl=[]; }
    give_.disabled=!keep||!sh.q[0]||sh.gap>0; const n={}; sh.box.forEach(x=>n[x]=(n[x]||0)+1);
    cus.querySelectorAll('.fr-bi').forEach(b=>{ const c=sh.q[0], need=c?c.items[b.dataset.k]||0:0, done=need>0&&(n[b.dataset.k]||0)>=need, ck=b.querySelector('.ck'); if(done&&!ck){ const i=document.createElement('img'); i.className='ck'; i.src=IMG_TICH; i.alt='đủ'; b.appendChild(i); } else if(!done&&ck) ck.remove(); }); };
  const custRefresh=()=>{ const c=sh.q[0]; cus.innerHTML=''; ui.cu=null; ui.pr=null;
    sh.q.slice(1,3).forEach((w,i)=>{ cus.appendChild(place(`fr-w fr-w${i+1}`,`<img src="${portraitOf(w)}" alt="" draggable="false">`)); });
    if(c){ const d=place('fr-cu in',`<div class="prw"><div class="pr"></div></div><div class="ph"><img src="${portraitOf(c)}" alt="Khách" draggable="false"></div>${c.paid?'<i class="coin">đ</i>':''}`); cus.appendChild(d); ui.cu=d; ui.pr=d.querySelector('.pr');
      cus.appendChild(place('fr-bub',bubHtml(c))); }
    boxRefresh(); };
  const upd=()=>{ cellsRefresh(); boxRefresh(); hud(); };
  ui.refresh=()=>{ custRefresh(); upd(); };
  const settle=()=>{ ui.busy=false; bx.getAnimations({subtree:true}).forEach(a=>a.cancel()); shut.hidden=true; if(sh.over) return endShift(); custRefresh(); hud(); cellsRefresh(); };
  const afterEv=()=>{ const ev=sh.ev.length; if(ev!==ui.evN){ ui.evN=ev; const last=sh.ev[ev-1]; if(last==='tuchoi'||last==='het') fb(last==='tuchoi'?'Khách đi':'Hết kiên nhẫn','bad'); }
    if(sh.over) return endShift(); custRefresh(); hud(); cellsRefresh(); };
  // ----- Đóng hộp: nắp đóng 0.3s -> hộp bay sang khách 0.4s -> khách nhận: đúng = trả tiền, sai = mất mặt + huỷ hộp -----
  function doGive(){ const c=front(sh); if(ui.busy||!c) return; if(!sh.box.length){ fb('Hộp còn trống','bad'); return; }
    ui.busy=true; const ok=boxMatch(sh,c); shut.hidden=false; shut.animate([{opacity:0},{opacity:1}],{duration:300,easing:'ease-in',fill:'forwards'}); opn.forEach(i=>i.animate([{opacity:i.className==='front'?.9:1},{opacity:0}],{duration:300,easing:'ease-in',fill:'forwards'}));   // 23c: hộp mở mờ dần -> hộp đóng hiện dần
    later(()=>{ if(!ui.cu) return; const a=bx.getBoundingClientRect(), t=ui.cu.getBoundingClientRect(); bx.animate([{transform:'none',opacity:1},{transform:`translate(${t.left+t.width/2-(a.left+a.width/2)}px,${t.top+t.height/2-(a.top+a.height/2)}px) scale(.35)`,opacity:.95}],{duration:400,easing:'ease-in-out',fill:'forwards'}); },300);
    later(()=>{ const p=ui.cu?rel(ui.cu.getBoundingClientRect()):{x:innerWidth*.2,y:90,w:90,h:90}; give(sh); hud(); ui.evN=sh.ev.length;
      if(ok) payFx(p,c); else { ping('tram'); const f=document.createElement('img'); f.className='face'; f.src=IMG_MAT_BUON; if(ui.cu) ui.cu.appendChild(f); bx.animate([{opacity:.95},{opacity:0}],{duration:250,fill:'forwards'}); fb(c.paid?'−'+k(P.comp):'Sai hộp!','bad'); }
      later(settle,ok?950:800); },700); }
  function payFx(p,c){ ping('tien'); const R=p.w, add=(src,w,x,y,anim,dur,delay)=>{ const i=document.createElement('img'); i.src=src; i.alt=''; i.style.cssText=`width:${w}px;left:${x}px;top:${y}px;`; fx.appendChild(i); i.animate(anim,{duration:dur,delay:delay||0,easing:'ease-out',fill:'both'}); setTimeout(()=>i.remove(),dur+(delay||0)+50); return i; };
    add(IMG_TAY_TIEN,R*.8,p.x+R*.2,p.y+R*.1,[{transform:'translate(60px,40px) rotate(8deg)',opacity:0},{transform:'translate(0,0)',opacity:1,offset:.4},{transform:'translate(0,-6px)',opacity:1,offset:.8},{transform:'translate(20px,-20px)',opacity:0}],900);
    add(IMG_SAO,R*.5,p.x-R*.5,p.y-R*.6,[{transform:'scale(.3)',opacity:0},{transform:'scale(1.1)',opacity:1,offset:.4},{transform:'scale(.9)',opacity:0}],800,150);
    [[IMG_XAP,R*.55,-.1],[IMG_XU1,R*.3,.3],[IMG_XU2,R*.26,.55],[IMG_XU3,R*.18,.8]].forEach(([src,w,dx],i)=>add(src,w,p.x+R*dx,p.y-R*.1,[{transform:'translate(0,10px) scale(.6)',opacity:0},{transform:`translate(${dx*30}px,-${R*.5}px) scale(1)`,opacity:1,offset:.4},{transform:`translate(${dx*50}px,-${R*.9}px) scale(.9)`,opacity:0}],900,i*80));
    const f=document.createElement('div'); f.className='fr-fb good'; f.textContent='+'+k(c.price); f.style.left=p.x+'px'; f.style.top=(p.y-p.h*.3)+'px'; fx.appendChild(f); setTimeout(()=>f.remove(),1100); }
  ui.evN=0; custRefresh(); upd();
  ui.el.addEventListener('pointerdown',e=>{ const c=e.target.closest('[data-c]'), b=e.target.closest('#frBox'), g=e.target.closest('[data-give]'), n=e.target.closest('[data-no]'), qt=e.target.closest('[data-quit]'); if(!(c||b||g||n||qt)||ui.ask||ui.busy) return; e.preventDefault();
    if(c){ ui.flyFrom=c; if(tap(sh,c.dataset.c)){ c.classList.remove('pop'); void c.offsetWidth; c.classList.add('pop'); upd(); } ui.flyFrom=null; }
    else if(b){ const lastK=sh.box[sh.box.length-1]; ui.flyTo=lastK?root.querySelector(`[data-c="${lastK}"]`):null; if(undo(sh)) upd(); ui.flyTo=null; }
    else if(g){ if(g.disabled) return; doGive(); }
    else if(n){ if(front(sh)&&reject(sh)) afterEv(); }
    else if(qt){ ui.ask=true; const a=el(`<div class="fr-ask"><div><b>Dừng ca bây giờ?</b><span>Khách còn lại bỏ đi, hàng chưa bán bị hư. Tiền hàng đã nhập vẫn tính.</span><div class="row"><button class="btn alt" data-k>Tiếp tục bán</button><button class="btn big butter" data-s>Dừng ca</button></div></div></div>`); ui.el.appendChild(a);
      a.addEventListener('click',ev=>{ const bb=ev.target.closest('button'); if(!bb) return; ui.ask=false; a.remove(); if('s' in bb.dataset){ sh.over=true; sh.why='dung'; endShift(); } }); } });
  let last=performance.now();
  const hue=f=>Math.round(3+107*f);   // xanh lá (110) -> vàng cam -> đỏ (3)
  const loop=now=>{ if(!ui||ui.sh!==sh) return; const dt=Math.min(.1,(now-last)/1000); last=now;
    if(!ui.ask&&!ui.busy){ const ev=sh.ev.length, was=sh.q[0]; tick(sh,dt); if(sh.ev.length!==ev) afterEv(); else if(ui.cu&&was&&was===sh.q[0]){ if(sh.gap<=0) ui.cu.classList.remove('in'); const k2=clamp(was.t/was.pat,0,1), col=`hsl(${hue(k2)} 68% 48%)`;
      ui.pr.style.setProperty('--p',(k2*360)+'deg'); ui.pr.style.setProperty('--c',col); ui.pr.parentNode.style.setProperty('--c',col); ui.cu.classList.toggle('hot',k2<.2&&sh.gap<=0); give_.disabled=!sh.box.length||sh.gap>0; } }
    if(ui) ui.raf=requestAnimationFrame(loop); };
  ui.raf=requestAnimationFrame(loop); }
// ---- kết thúc ca + kết quả ----
function endShift(){ const sh=ui&&ui.sh; if(!sh) return; const r=finish(sh); frClose(); frSettle(r); }
function frSettle(r){ const F=fr(); F.last=S.day; F.plays++; F.hist=F.hist.concat(r.net).slice(-6); F.best=F.best===null?r.net:Math.max(F.best,r.net);
  S.cash+=r.net; addLog('Quầy trái cây Dinh Cậu',r.net); if(r.badC) addLog('Huỷ hàng (hư) – Quầy trái cây Dinh Cậu: '+k(r.badC)+' (đã tính vào lời ròng)',0);
  // thưởng thế giới: mỗi khách Chuẩn 30% thành khách Tây ghé spa hôm sau (tối đa +3); hạng S +0,05★
  let tay=0; for(let i=0;i<r.chuan;i++) if(Math.random()<P.tayP) tay++; tay=Math.min(P.tayMax,tay); F.bonus=tay;
  let star=0; if(r.grade==='S'){ const b=F.star||0; F.star=Math.min(P.starMax,Math.round((b+P.starS)*100)/100); star=Math.round((F.star-b)*100)/100; }   // cộng thẳng vào điểm sao hiển thị, tối đa +0,2★ cộng dồn
  save();
  const row=(a,v,c)=>`<div><span>${a}</span><span class="${c||''}">${v}</span></div>`;
  const html=`${row('Doanh thu ('+r.chuan+'/'+r.N+' khách Chuẩn)','+'+k(r.rev),'g')}${row('Tiền hàng nhập (phần bán được)','−'+k(r.cost-r.badC),'r')}${r.badC?row('Huỷ hàng (hư)','−'+k(r.badC),'r'):''}${row('Phí chỗ bán + hộp','−'+k(r.fee+r.boxFee),'r')}${r.comp?row('Đền khách giao sai','−'+k(r.comp),'r'):''}
    <div class="n"><span>LỢI RÒNG</span><span class="${r.net>=0?'g':'r'}">${r.net>=0?'+':'−'}${k(Math.abs(r.net))}</span></div>
    ${tay||star?`<div><span>Khách Tây ghé spa mai${star?' · sao':''}</span><span class="g">${tay?'+'+tay:''}${star?' +'+String(star).replace('.',',')+'★':''}</span></div>`:''}`;
  setTimeout(()=>mgResult('fruit',r.score,[],{title:`${r.net>=0?'Lời':'Lỗ'} ${k(Math.abs(r.net))}`, html},()=>{ renderAll(); }),60); }

// ---------- gắn vào bản đồ (20b: BD_EXT) ----------
const pinState=()=>fr().un||THU;
function bdPanelFr(){ const F=fr(), why=canOpen();
  return `<div class="n"><b>Quầy trái cây Dinh Cậu</b> <span class="tag">${why?'chưa mở ca':'mở tối nay'}</span></div><div class="m">Cửa sông Dương Đông, khách Tây ghé nhiều lúc hoàng hôn. Mỗi tối bán một ca sau khi đóng tiệm, không tốn công suất tiệm.${F.plays?` Đã bán ${F.plays} ca · ca lời nhất ${k(F.best)}.`:''}</div>
    ${why?`<div class="m">${esc(why)}</div>`:''}<div class="row" style="margin-top:6px"><button class="btn sm alt" data-fr="info">Về Dinh Cậu</button><button class="btn sm ${why?'alt':'butter'}" data-fr="go"${why?' disabled':''}>Mở quầy tối nay</button></div>`; }
window.BD_EXT=window.BD_EXT||[];
BD_EXT.push({id:'dinhcau', s:'r', label:'Quầy trái cây Dinh Cậu', w:[.435,.245], d:[.355,.205], cls:'f', ic:'🍉', show:pinState, panel:bdPanelFr,
  act:a=>{ if(a==='go') frStart(); else if(a==='info'){ if(window.bdClose) bdClose(); frDinh(null); } }});

// ---------- móc vào game ----------
rating=(orig=>function(){ return clamp(orig()+((S.fr&&S.fr.star)||0),1,5); })(rating);
finishService=(orig=>function(g){ try{ if(g&&g.type==='tay'&&S.prem==='chodem') fr().tay++; }catch(e){ console.error('[fr]',e); } orig(g); })(finishService);   // đếm khách Tây đã phục vụ (điều kiện mở khoá)
endDay=(orig=>function(){ orig(); try{ frCheck(); }catch(e){ console.error('[fr]',e); } })(endDay);
startDay=(orig=>function(){ orig(); try{ frCheck(); const F=fr(), n=F.bonus; F.bonus=0;
  for(let i=0;i<n;i++) later(rn(20,OPEN_END-60),()=>{ if(S.stage!=='open'||S.time>=OPEN_END-20) return; const pt=pickType; pickType=()=>'tay'; try{ REALISM.force=true; spawn('new'); } finally{ pickType=pt; REALISM.force=false; } });
  if(n) setTimeout(()=>toast(`Khách Tây từ Quầy trái cây Dinh Cậu ghé tiệm hôm nay: ${n}.`,'good'),900); }catch(e){ console.error('[fr]',e); } })(startDay);
MG_GAMES.fruit={name:'Quầy trái cây', bias:['sim','tieu']};

window.FR={THU, sfxOn:true, snd:SND, cur:()=>ui&&ui.sh, ui:()=>ui, P, FRUITS, eng:{newShift,tick,tap,undo,give,reject,finish,front,genOrder,left}, fr, quiet, rainy, unlockCond, frCheck, canOpen, frStart, frBuy, frPlay, frSettle, frClose, DINH, frDinh};
})();

