let vidBusy=false, W=MAP_IMG.w, H=MAP_IMG.h, o=null, inn=null, pinsEl=null, cardEl=null, listEl=null, sc=1, tx=0, ty=0, minSc=.3, maxSc=1.2, sel=null, nightT=0, vid=null, vidOK=false, vidPlayed=false, anim=0, boot=false, belled=0;
const vw=()=>o.clientWidth, vh=()=>o.clientHeight;
