// 21f-thoitiet.js — Việc 21f: NGUỒN THỜI TIẾT DUY NHẤT cho bản đồ sống động, tiệm và âm thanh.
// S.tt = { gio (giờ game), pha:'ngay'|'hoanghon'|'dem', mua:'kho'|'mua', giong:0|1, phaohoa:0|1, su_kien:[] }
// Lịch: KHÔNG tạo lịch thứ 2 — mùa theo 15m-seasons (mùa mưa = tháng 5–10 = rainy(monthOf())), năm 120 ngày.
// Hook: TT.on('doi', fn) — fn(state) chạy khi pha / mùa / giông / pháo hoa đổi. Giờ liên tục: TT.dem() (0..1 đêm), TT.hh() (0..1 hoàng hôn).
(function(){ 'use strict';
// ===== LUẬT CHƠI — số ĐỀ XUẤT (DE_XUAT), Đại nhân chỉnh sau khi bot chạy xong =====
const TT_LUAT={
  hh_khach:1.10,        // DE_XUAT hoàng hôn 17:30–18:30: khách đến Sunset / Trần Hưng Đạo +10%
  hh_tip:1.15,          // DE_XUAT hoàng hôn: tip khách Tây ×1,15
  giong_vanglai:.65,    // DE_XUAT giông: khách vãng lai −35%
  giong_tru:1.15,       // DE_XUAT giông: tiệm sát mặt đường (Chợ đêm, Trần Hưng Đạo) khách trú mưa +15%
  giong_dichvu:.20,     // DE_XUAT giông: xác suất đổi sang ngâm chân / xông hơi (≈ +20% trọng số)
  giong_haomon:1.5,     // DE_XUAT giông: đồ ngoài sân hao mòn ×1,5 trong ngày giông
  giong_xs:.25,         // xác suất ngày giông (chỉ mùa mưa)
  ph_khach:1.40,        // DE_XUAT pháo hoa 21:00–22:00: khách map Sunset +40%
  ph_met:3,             // DE_XUAT pháo hoa: mỗi nhân viên mất thêm 3 tinh thần (≈ stamina −15% thêm)
  hh:[17.5,18.5], phaohoa:[21,22], g_tu:11, g_den:17   // cửa sổ giờ game
};
window.TT_LUAT=TT_LUAT;
S.tt=Object.assign({gio:10,pha:'ngay',mua:'kho',giong:0,phaohoa:0,su_kien:[],gNgay:0,g0:0,g1:0,phNgay:0},S.tt||{});
const T=S.tt, subs=[]; let ep=null, prev='';
['gio','pha','mua','giong','phaohoa','su_kien'].forEach(k=>Object.defineProperty(T,k,{value:T[k],writable:true,enumerable:false,configurable:true}));   // số suy ra từ giờ: đọc được nhưng KHÔNG ghi vào save (save chỉ giữ gNgay, g0, g1, phNgay, phShow, tG)
const on=(ev,fn)=>{ if(ev==='doi'&&typeof fn==='function') subs.push(fn); };
const mua=d=>(typeof rainy==='function'&&typeof monthOf==='function'&&rainy(monthOf(d)))?'mua':'kho';
const sunsetOpen=()=>S.prem==='sunset'||!!(S.shops&&S.shops.sunset);
function gioNow(){ if(window.XEMDEM==='dem') return 22.5; if(window.XEMDEM==='ngay') return 12;
  if(S.stage==='open'&&typeof gameHour==='function') return gameHour(); return S.stage==='closed'?22.5:10; }
const hhK=h=>Math.max(0,Math.min(1,(h-TT_LUAT.hh[0])/(TT_LUAT.hh[1]-TT_LUAT.hh[0])));
function compute(){ const e=ep||{}, h=e.gio!=null?e.gio:gioNow();
  const hoang=h>=TT_LUAT.hh[0]&&h<TT_LUAT.hh[1], pha=hoang?'hoanghon':(h>=TT_LUAT.hh[1]||h<6)?'dem':'ngay';
  const m=e.mua||mua(S.day), open=S.stage==='open'||e.gio!=null;
  const g=e.giong!=null?e.giong:(open&&S.day===T.gNgay&&m==='mua'&&h>=T.g0&&h<T.g1?1:0);
  const blocked=['heavy','storm1','storm2','storm3'].includes(S.wx&&S.wx.today);
  const ph=e.phaohoa!=null?e.phaohoa:(open&&!g&&!blocked&&h>=TT_LUAT.phaohoa[0]&&h<TT_LUAT.phaohoa[1]&&(sunsetOpen()||S.day%60===0)?1:0);
  return {gio:h,pha,mua:m,giong:g,phaohoa:ph}; }
function nhip(){ if(!S.tt||S.tt!==T){ /* save mới nạp: S bị thay */ S.tt=Object.assign(T,S.tt||{}); }
  const c=compute(), key=c.pha+c.mua+c.giong+c.phaohoa; Object.assign(T,c);
  if(key===prev) return; const first=prev==='', o=prev; prev=key; if(first) return;
  if(c.giong&&!/1/.test(o.slice(-2,-1))) tiemGiong(); if(c.phaohoa&&o.slice(-1)!=='1') tiemPhaoHoa(c);
  subs.forEach(f=>{ try{ f(T); }catch(e){ console.warn('TT.doi',e); } }); }
setInterval(nhip,500);

// ---------- ngày mới: tính giông của hôm nay (đã báo từ hôm trước), báo trước giông ngày mai ----------
function nhipNgay(){ if(S.day===T.gNgay){ T.g0=TT_LUAT.g_tu+Math.floor(Math.random()*4); T.g1=Math.min(TT_LUAT.g_den,T.g0+1+Math.floor(Math.random()*2)); }
  else if(mua(S.day+1)==='mua'&&Math.random()<TT_LUAT.giong_xs){ T.gNgay=S.day+1; inboxMsg('Dự báo thời tiết','Mai có giông, chuẩn bị nhé: dọn đồ ngoài sân, khách vãng lai sẽ vắng.'); }
  T.su_kien=[]; if(S.day===T.gNgay) T.su_kien.push('giong'); if(S.day%60===0) T.su_kien.push('phaohoa'); }
startDay=(o=>function(){ const r=o.apply(this,arguments); try{ nhipNgay(); nhip(); }catch(e){ console.warn('TT.ngay',e); } return r; })(startDay);

// ---------- trong tiệm: tint màu + toast + nút Xem (không chuyển động nhân vật mới) ----------
const css=document.createElement('style'); css.textContent=`
#tt-tint{position:fixed;inset:0;z-index:7;pointer-events:none;opacity:0;transition:opacity 2.5s ease,background-color 2.5s ease;background:#ff9a4a}
#tt-xem{position:fixed;z-index:9400;left:50%;transform:translateX(-50%);top:calc(max(10px,env(safe-area-inset-top)) + 54px);min-height:44px;padding:0 16px;border-radius:14px;border:1.5px solid var(--c-vien);background:var(--c-matong);color:var(--c-chu);box-shadow:var(--sh-btn);font:800 13px/1 var(--font-display);cursor:pointer}
`; document.head.appendChild(css);
const tint=document.createElement('div'); tint.id='tt-tint'; document.body.appendChild(tint);
function veTint(){ const c=T, ph=c.pha==='hoanghon'; tint.style.backgroundColor=c.giong?'#5c6b80':'#ff9a4a'; tint.style.opacity=c.giong?.16:ph?.12:0; }
on('doi',veTint);
function tiemGiong(){ if(T.tG===S.day) return; T.tG=S.day; toast('Trời giông, ít khách vãng lai. Khách thích ngâm chân hơn.','info'); }
function tiemPhaoHoa(c){ if(T.phNgay===S.day) return; T.phNgay=S.day; toast('Pháo hoa Sunset bắt đầu!','good'); if(S.stage==='open') S.staff.forEach(s=>{ s.morale=clamp(s.morale-TT_LUAT.ph_met,0,100); });
  if(document.getElementById('tt-xem')) return; const b=document.createElement('button'); b.id='tt-xem'; b.type='button'; b.textContent='Xem pháo hoa'; document.body.appendChild(b);
  const bye=()=>{ b.remove(); }; b.onclick=()=>{ bye(); if(window.bdOpen) bdOpen(); }; setTimeout(bye,15000); }

// ---------- luật chơi (DE_XUAT) ----------
const prem0=()=>S.prem, TT_TK={n:0,sum:0};   // thống kê: hệ số khách trung bình do thời tiết (bot đọc để đo lệch)
hourCurve=(o=>function(){ nhip(); let m=1, st=T.pha==='hoanghon', p=prem0();   // nhip(): tính lại ngay (bot chạy đồng bộ, không chờ setInterval)
  if(st&&(p==='sunset'||p==='thd')) m*=TT_LUAT.hh_khach;
  if(T.giong) m*=TT_LUAT.giong_vanglai*((p==='chodem'||p==='thd')?TT_LUAT.giong_tru:1);
  if(T.phaohoa&&p==='sunset') m*=TT_LUAT.ph_khach;
  TT_TK.n++; TT_TK.sum+=m; return o()*m; })(hourCurve);
{ const base=CTYPES.tay.tip.slice(); on('doi',()=>{ const k=T.pha==='hoanghon'?TT_LUAT.hh_tip:1; CTYPES.tay.tip=base.map(x=>x*k); }); }
pickWant=(o=>function(){ if(T.giong&&Math.random()<TT_LUAT.giong_dichvu){ const k=['foot','herbal'].filter(x=>SERVICES[x]); if(k.length) return k[Math.floor(Math.random()*k.length)]; } return o(); })(pickWant);
if(typeof addWear==='function') addWear=(o=>function(id,n){ if(T.giong&&typeof wearKind==='function'&&id&&wearKind(id)==='decor') n=(n||1)*TT_LUAT.giong_haomon; return o(id,n); })(addWear);

window.TT={on,s:T,gio:()=>T.gio,pha:()=>T.pha,mua:()=>T.mua,giong:()=>T.giong,phaohoa:()=>T.phaohoa,hh:()=>T.pha==='hoanghon'?Math.sin(Math.PI*hhK(T.gio)):0,
  dem:()=>{ const h=T.gio; return h<6?1:Math.max(0,Math.min(1,(h-TT_LUAT.hh[0])/2)); },   // 0 ban ngày → 1 đêm, chuyển dần 17:30–19:30
  ep:o=>{ ep=o; nhip(); }, nhip, luat:TT_LUAT, tk:TT_TK};   // TT.ep({gio,mua,giong,phaohoa}) chỉ để chụp / kiểm; TT.ep(null) trả lại
nhip();
})();

// 21f-bando-fx.js — Việc 21f: LỚP ĐÈ SỐNG ĐỘNG trên bản đồ đảo 21d (ảnh nền GIỮ TĨNH; mọi hiệu ứng là canvas + sprite nhỏ).
// 1 canvas trong suốt phủ khung nhìn #wm, vẽ trong hệ toạ độ ẢNH (941x1672) theo phép biến đổi của 21d (WM.view). 1 requestAnimationFrame chung, dừng khi bản đồ đóng / tab ẩn.
