// 24a-ngang.js — Việc 24a: sửa lỗi chơi thật iPhone. Chỉ chia lại DOM/vị trí nút; luật chơi, kinh tế giữ nguyên.
//  (1) nút "Bản đồ" nằm CHUNG hàng/cột nút zoom (không nổi riêng, không đè nút nào)
//  (2) bảng Công thức / Đưa nguyên liệu (Bàn pha chế, khung ngang thấp) = bảng THAY THẾ trong cùng khung (không chồng 2 lớp)
(function(){ 'use strict';
const $=s=>document.querySelector(s);
// (1) dời #mapFab vào .rm-zoom khi có phòng; không có phòng thì trả về .phone
function dockMap(){ const fab=$('#mapFab'), z=$('#rmZfit'); if(!fab) return;
  const zoom=z&&z.parentElement; if(zoom&&zoom.classList.contains('rm-zoom')){ if(fab.parentElement!==zoom){ zoom.appendChild(fab); fab.classList.add('in-zoom'); } }
  else if(fab.classList.contains('in-zoom')){ const ph=$('.phone'); if(ph){ ph.appendChild(fab); fab.classList.remove('in-zoom'); } } }
setInterval(dockMap,400); dockMap();
// (2) bảng thay thế trong Bàn pha chế
const LOW=()=>matchMedia('(orientation:landscape) and (max-height:520px)').matches;
function wrapPop(sh){ sh.querySelectorAll('.mg-pop').forEach(pop=>{ if(pop.dataset.w) return; pop.dataset.w=1;
    const x=pop.querySelector('.pop-x'), det=pop.querySelector('details'), tit=det?'Công thức':'Đưa nguyên liệu từ kho';
    const h=document.createElement('div'); h.className='pop-h'; h.innerHTML='<b></b>'; h.firstChild.textContent=tit;
    if(x){ x.textContent='Quay lại'; h.appendChild(x); } pop.insertBefore(h,pop.firstChild);
    pop.querySelectorAll('.mg-chain small').forEach(sm=>{ const t=sm.textContent, i=t.indexOf('Thu:'); if(i>0) sm.textContent=t.slice(i); });
    new MutationObserver(()=>sh.classList.toggle('ct-open',[...sh.querySelectorAll('.mg-pop')].some(p=>!p.hidden))).observe(pop,{attributes:true,attributeFilter:['hidden']}); }); }
{ const sh=$('#sheet'); if(sh) new MutationObserver(()=>{ if(sh.classList.contains('ct-open')&&![...sh.querySelectorAll('.mg-pop')].some(p=>!p.hidden)) sh.classList.remove('ct-open'); }).observe(sh,{childList:true}); }   // #sheet dùng lại cho mọi bảng: bỏ cờ khi nội dung đổi
if(typeof openMerge==='function') openMerge=(orig=>function(){ orig.apply(this,arguments); if(!LOW()) return; const sh=$('#sheet'); if(sh) wrapPop(sh); })(openMerge);
})();

