// 16b-emoji-ico.js — M-h2 (mạch chính 07/10): thay emoji giữ chỗ trong giao diện bằng icon vẽ tay (UI_ICON đợt A/B/C).
// Cách làm: quét text node trong DOM (không đụng canvas, input, textarea, option, svg) và đổi emoji có trong bảng EMO sang <img class="ui-emo">.
// Emoji không có trong bảng thì giữ nguyên. Thêm icon mới: chỉ thêm 1 dòng vào EMO.
(()=>{
  const EMO={'💆':'danglam','🧍':'hangcho','🛋':'ngoicho','🛏':'giuong','🪑':'ghemassage','💡':'goiy','☀':'tt-nang','🌧':'tt-mua','⛈':'tt-giong',
    '🚱':'tt-catnuoc','🌀':'tt-bao','🔌':'tt-cupdien','🥵':'tt-nong','🌊':'tt-ngap','🌅':'tt-hoanghon','🎆':'phaohoa','🧧':'tet-lixi','🎉':'khaitruong',
    '⏩':'tua','⏸':'tamdung','📦':'kho','🪙':'xu','💰':'tien','💸':'tien-ra','⚠':'canhbao','ℹ':'thongtin','📱':'dienthoai','📞':'cuocgoi','🏦':'nganhang',
    '🏢':'congtytc','🚚':'chuyennha','🛠':'baytri','📖':'sotay','📋':'danhsach','👁':'mat','🏠':'tiem','🎯':'muctieu','⭐':'sao','♥':'tim',
    '😤':'tinh-khotinh','🤔':'tinh-chanchu','🧐':'tinh-sanhgia','⏱':'tinh-voi','😊':'tinh-detinh','🗣':'tinh-macca','😞':'buon','✨':'lapanh','🫖':'yc-tra',
    // 17e-1: icon dot E3/E4 + sao
    '⛔':'ic-cam','✕':'ic-sai','✘':'ic-sai','🙈':'ic-an','⬆':'ic-len','⬇':'ic-xuong','❤':'ic-tim','🎮':'ic-trochoi','🎲':'ic-xucxac','🌿':'ic-thaoduoc',
    '🎵':'yc-nhac','💪':'yc-manhtay','🥤':'yc-douong','♨':'ic-hoinong','❄':'ic-lanh','🌡':'ic-nhietke','★':'ic-sao-day','☆':'ic-sao-rong'};
  EMO['⭐']='ic-sao-nho'; EMO['♥']='ic-tim';
  const keys=Object.keys(EMO).filter(k=>window.UI_ICON&&UI_ICON[EMO[k]]);
  if(!keys.length) return;
  const esc=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  const RE=new RegExp('('+keys.map(esc).join('|')+')\\uFE0F?','g');
  const SKIP=/^(SCRIPT|STYLE|TEXTAREA|INPUT|OPTION|SELECT|CANVAS|svg|title)$/;
  function fix(node){
    const t=node.nodeValue; if(!t||!RE.test(t)) return; RE.lastIndex=0;
    const p=node.parentNode; if(!p||SKIP.test(p.nodeName)||p.closest&&p.closest('svg')) return;
    const frag=document.createDocumentFragment(); let last=0;
    t.replace(RE,(m,e,i)=>{ if(i>last) frag.appendChild(document.createTextNode(t.slice(last,i)));
      const im=document.createElement('img'); im.className='ui-emo'+(EMO[e]==='ic-an'?' ui-emo-bg':''); im.src=UI_ICON[EMO[e]]; im.alt=e; im.setAttribute('aria-hidden','true'); im.draggable=false;
      frag.appendChild(im); last=i+m.length; return m; });
    if(last<t.length) frag.appendChild(document.createTextNode(t.slice(last)));
    p.replaceChild(frag,node);
  }
  function walk(root){
    if(root.nodeType===3){ fix(root); return; }
    if(root.nodeType!==1||SKIP.test(root.nodeName)) return;
    const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT); const list=[]; let n; while((n=w.nextNode())) list.push(n); list.forEach(fix);
  }
  walk(document.body);
  new MutationObserver(ms=>{ for(const m of ms){ if(m.type==='characterData') fix(m.target); else m.addedNodes.forEach(walk); } })
    .observe(document.body,{childList:true,subtree:true,characterData:true});
  window.EMO_ICO=EMO;
})();

// 16c-lz.js — M-g buoc 1 (07/10/2026, v4.14): bo chan chong cheo.
// Dat dung 1 class che do lz-* len .phone; vi tri cac lop noi nam trong khoi CSS "M-g buoc 1" cuoi style.css.
// Dac ta: docs/lenh/bao-cao-phong-cach-game.md phan I (I.4 che do, I.5 z-index, R6 doi che do).
// Buoc 2 (v4.15): hang cho R2 cho toast, the L9/L10 bi giu -> chip cho + R3 dung dem gio (LZ.held dung o 15z-pacing, 15l-guests).
// Buoc 3 (v4.16): LZ.rects/LZ.hit cho canvas ne khe (bubFlush, floats o 15y-room), LZ.free cho fx-coin (15o-fx).
(function(){
  const MODES=['lz-tiem','lz-sheet','lz-cot2','lz-baytri','lz-tragia','lz-tuaxong','lz-modal','lz-chidiem'];
  const $id=id=>document.getElementById(id);
  const shown=e=>!!e&&!e.hidden&&e.offsetParent!==null;
  let cur='', swT=0;
  function pick(){
    const ph=$id('phone'); if(!ph||!ph.classList.contains('rmv')) return '';
    if(window.LZ&&LZ.guide) return 'lz-chidiem';            // chua co chi diem trong game: de san cho buoc sau
    const sb=$id('sheetBg');
    if(sb&&!sb.hidden) return (typeof sheetTab==='function'&&sheetTab())?'lz-sheet':'lz-modal';
    if(typeof haggling!=='undefined'&&haggling) return 'lz-tragia';
    if(ph.classList.contains('tcol')) return 'lz-cot2';
    if(ph.classList.contains('tsheet')||shown($id('rmPop'))) return 'lz-sheet';
    if(typeof RM!=='undefined'&&RM.mode==='deco') return 'lz-baytri';
    if($id('fwSkip')) return 'lz-tuaxong';
    return 'lz-tiem';
  }
  function vars(ph){
    const hud=ph.querySelector('.hud'), tr=$id('reqTray'), tip=$id('tipBox');
    const h=hud?Math.round(hud.getBoundingClientRect().height):46;
    const d=shown(tr)&&tr.children.length?Math.round(tr.getBoundingClientRect().height)+6:0;
    const t=tip&&tip.style.visibility!=='hidden'?Math.round(tip.getBoundingClientRect().height)+6:0;
    const bar=$id('rmBar'), c=shown(bar)&&!matchMedia('(orientation:portrait)').matches?Math.round(bar.getBoundingClientRect().width):60;
    const ts=$id('toasts'), k=cur==='lz-cot2'&&ts&&ts.children.length?Math.round(ts.getBoundingClientRect().height)+6:0;
    const st=ph.style;
    if(st.getPropertyValue('--lz-cot')!==c+'px') st.setProperty('--lz-cot',c+'px');
    if(st.getPropertyValue('--lz-toast')!==k+'px') st.setProperty('--lz-toast',k+'px');
    if(st.getPropertyValue('--lz-hud')!==h+'px') st.setProperty('--lz-hud',h+'px');
    if(st.getPropertyValue('--lz-day')!==d+'px') st.setProperty('--lz-day',d+'px');
    if(st.getPropertyValue('--lz-tip')!==t+'px') st.setProperty('--lz-tip',t+'px');
  }
  function eyeIntoZoom(){
    const z=document.querySelector('#room .rm-zoom'), e=$id('rmEye'); if(!z||!e||e.parentElement===z) return;
    z.prepend(e, $id('rmZout')||'', $id('rmZin')||'');      // [mat][-][+][vua khung]
    [...z.childNodes].forEach(n=>{ if(n.nodeType===3&&!n.textContent.trim()) n.remove(); });
  }
  function lzMode(){
    const ph=$id('phone'); if(!ph) return;
    eyeIntoZoom(); vars(ph);
    const m=pick(); if(m===cur) return;
    const set=()=>{ MODES.forEach(c=>ph.classList.toggle(c,c===m)); ph.classList.remove('lz-out'); cur=m; chip(); drain(); calcRects(); };
    clearTimeout(swT);
    if(!cur||!m||matchMedia('(prefers-reduced-motion:reduce)').matches){ set(); return; }
    ph.classList.add('lz-out'); swT=setTimeout(set,120);       // R6: mo ra 120ms roi doi khe
  }
  // ---- R3: the khach hoi (L9) / viec tay (L10) co dang nam trong hang cho Q khong (bang I.4) ----
  const portrait=()=>matchMedia('(orientation:portrait)').matches;
  function held(m){ m=m||cur;
    if(!m) return typeof tab!=='undefined'&&tab!=='shop';     // man doc khong ve canh (So sach, Mua sam...): the khong hien
    if(m==='lz-sheet') return portrait();                      // ngang: the doi sang K-phai, van hien
    return m==='lz-cot2'||m==='lz-baytri'||m==='lz-tragia'||m==='lz-tuaxong'||m==='lz-modal'||m==='lz-chidiem'; }
  function heldN(){ if(!held()||typeof S==='undefined'||S.stage!=='open') return 0;
    const n10=typeof REQ!=='undefined'?REQ.list.length:0;
    const n9=cur!=='lz-tragia'&&typeof guests!=='undefined'&&guests.some(g=>g.state==='atCounter')?1:0;  // tra gia: L9 chinh la bang tra gia
    return n9+n10; }
  // ---- chip cho (I.4): ngang = pill goc duoi trai K-day; doc = cham so do tren nut dock "Tiem" ----
  const noGo=m=>m==='lz-tragia'||m==='lz-tuaxong'||m==='lz-modal';
  function goTiem(){ if(noGo(cur)) return;
    if(typeof RM!=='undefined'&&RM.mode==='deco'){ const ex=(RM.api&&RM.api.exitDeco)||(typeof exitDeco==='function'&&exitDeco); if(ex) ex(); }
    const px=document.querySelector('#rmPop:not([hidden]) [data-rmclose]'); if(px) px.click();
    if(typeof tab!=='undefined'&&tab!=='shop'){ const b=document.querySelector('#nav [data-tab="shop"]'); if(b) b.click(); }
    lzMode(); }
  function chip(){ const ph=$id('phone'); if(!ph) return; let c=$id('lzWait');
    if(!c){ c=document.createElement('button'); c.id='lzWait'; c.className='lz-wait'; c.type='button'; c.hidden=true; c.addEventListener('click',goTiem); ph.appendChild(c); }
    const n=heldN(), port=portrait(), show=n>0&&!port;
    if(show){ const h=((window.uiIco&&uiIco('viectay'))||'')+'<span>'+n+' việc chờ</span>'; if(c._h!==h){ c._h=h; c.innerHTML=h; }
      c.setAttribute('aria-label',n+' việc đang chờ'+(noGo(cur)?'':', chạm để về tiệm')); c.classList.toggle('nogo',noGo(cur)); }
    if(c.hidden===show) c.hidden=!show;
    const nb=document.querySelector('#nav [data-tab="shop"]'); if(nb){ const v=n>0&&port?String(n):''; if((nb.dataset.lzn||'')!==v){ if(v) nb.dataset.lzn=v; else delete nb.dataset.lzn; } } }
  // ---- R2: hang cho chung cho toast. Khan luon hien; tua/modal/chi diem -> Q; bay tri: canh bao hien, goi y vao Q, thong tin bo ----
  const PRI={urgent:0,warn:3,tip:4,good:5,info:5}, TQ=[];
  function route(kind,m){ if(kind==='urgent') return 'show';
    if(m==='lz-tuaxong'||m==='lz-modal'||m==='lz-chidiem') return 'q';
    if(m==='lz-baytri') return kind==='warn'?'show':kind==='tip'?'q':'drop';
    return 'show'; }
  if(typeof toastShow==='function'){ const ts0=toastShow;
    toastShow=function(msg,kind){ const r=route(kind,pick()||cur);
      if(r==='q'){ TQ.push({a:[...arguments],t:Date.now()}); return; } if(r==='drop') return;
      return ts0.apply(this,arguments); }; }
  function drain(){ if(!TQ.length||typeof TOASTQ==='undefined') return; const now=Date.now();
    for(let i=TQ.length-1;i>=0;i--){ const k=TQ[i].a[1]; if((k==='info'||k==='good')&&now-TQ[i].t>4000) TQ.splice(i,1); }  // tin cu vo nghia
    const ok=TQ.filter(x=>route(x.a[1],cur)==='show'); if(!ok.length) return;
    ok.sort((x,y)=>(PRI[y.a[1]]-PRI[x.a[1]])||(x.t-y.t));  // ra sau cung = nam tren cung va khong bi R5 day: khan/canh bao ra cuoi
    ok.forEach(x=>{ TQ.splice(TQ.indexOf(x),1); TOASTQ.q.push(x.a); }); toastPump(); }   // toastPump giu nhip 600ms (R7)
  // ---- I.6: hinh chu nhat cac khe dang hien (toa do canvas) — tinh 250ms/lan, khong tinh moi khung hinh ----
  const ZSEL='.hud,.nav,.room .rm-tl,.room .rm-tr,.room .rm-bar,.room .rm-zoom,.room .rm-spd,.room .rm-counter,.room .rm-held,.req-tray,#toasts .toast,#lzWait,#rmPop,.haggle,#fwSkip';
  let ZR=[], ZP=[];
  function calcRects(){ const cv=$id('rmCv'); ZR=[]; ZP=[]; if(!cv||!cv.getClientRects().length) return; const C=cv.getBoundingClientRect(), ph=$id('phone');
    const els=[...document.querySelectorAll(ZSEL)]; if(ph&&(ph.classList.contains('tsheet')||ph.classList.contains('tcol'))){ const d=$id('dyn'); if(d) els.push(d); }
    for(const e of els){ if(!e.getClientRects().length||getComputedStyle(e).visibility==='hidden') continue; const r=e.getBoundingClientRect(); if(r.width<2||r.height<2) continue;
      ZP.push([r.left,r.top,r.right,r.bottom]); ZR.push([r.left-C.left,r.top-C.top,r.right-C.left,r.bottom-C.top]); } }
  function free(x,y){ for(const z of ZP) if(x>z[0]&&x<z[2]&&y>z[1]&&y<z[3]){            // diem dau fx-coin trong khe ban -> mep gan nhat
      const o=[[x-z[0],z[0]-6,y],[z[2]-x,z[2]+6,y],[y-z[1],x,z[1]-6],[z[3]-y,x,z[3]+6]].sort((a,b)=>a[0]-b[0])[0]; return [o[1],o[2]]; } return [x,y]; }
  setInterval(()=>{ chip(); drain(); calcRects(); },250);
  addEventListener('resize',()=>setTimeout(calcRects,50));
  { const tb=$id('toasts'); if(tb) new MutationObserver(()=>{ calcRects(); setTimeout(calcRects,220); }).observe(tb,{childList:true}); }  // toast moi: tinh lai ngay + sau hieu ung vao
  window.LZ=window.LZ||{}; LZ.mode=()=>cur; LZ.update=lzMode; LZ.held=()=>held(); LZ.heldN=heldN; LZ.tq=()=>TQ.length;
  LZ.rects=()=>ZR; LZ.calc=calcRects; LZ.free=free; LZ.hit=(l,t,r,b)=>ZR.some(z=>l<z[2]&&z[0]<r&&t<z[3]&&z[1]<b);
  if(typeof renderAll==='function'){ const r0=renderAll; renderAll=function(){ const v=r0.apply(this,arguments); lzMode(); return v; }; }
  addEventListener('resize',lzMode); addEventListener('orientationchange',lzMode);
  setInterval(lzMode,200);                                    // nhe: chi doc vai thuoc tinh, khong ve lai
  lzMode();
})();

// 16d-tidy.js — v4.17 (Đại nhân 08/10/2026): HUD gọn.
// - Bỏ "góp Nn" dưới tiền mặt (kỳ góp xem ở Sổ sách/thông báo ngân hàng).
// - Bỏ chữ "đánh giá" dưới số sao: icon sao là đủ hiểu.
// - Bỏ dòng ngày tháng dưới tên tiệm; ngày chỉ báo 1 lần bằng toast lúc đầu buổi.
(function(){
  const $id=id=>document.getElementById(id);
  const r=$id('rating'); if(r){ const c=r.closest('.chipv'); if(c) c.classList.add('hud-rate'); }
  if(typeof renderTop==='function'){ const r0=renderTop; renderTop=function(){ const v=r0.apply(this,arguments);
    const cs=$id('cash'), sm=cs&&cs.parentElement.querySelector('small'); if(sm&&sm.textContent!=='tiền mặt') sm.textContent='tiền mặt'; return v; }; }
  let lastDay=null;
  setInterval(()=>{ if(typeof S==='undefined'||!S.prem||S.stage==='story'||S.stage==='prem') return;
    const k=S.day+':'+S.stage; if(lastDay===null){ lastDay=k; return; }   // vao game giua chung: khong bao lai
    if(k===lastDay) return; const prevDay=String(lastDay).split(':')[0]; lastDay=k;
    if(String(S.day)===prevDay) return;                                  // chi bao khi sang ngay moi
    const sub=$id('sub'), t=sub?sub.textContent.split(' · ').filter(x=>!/mở cửa|ngưng nhận|^\d+h/.test(x)).slice(0,3).join(' · '):'Ngày '+S.day;
    if(typeof toast==='function') toast(t,'info'); },700);
})();

// 17a-anh-a4.js — v4.19 (mạch chính 08/10): gắn icon tấm D1 vào thẻ "Tình hình tiệm" (Sổ sách) + cỡ icon 3 món chuẩn bị thời tiết.
// Thẻ cũ dùng ảnh clay 5 nấc (w_money_N…); nay 1 icon vẽ tay/ô, con số vẫn báo tình trạng. Thứ tự ô giữ như bookCard() trong 15h-wear.js.
(()=>{
  const KEYS=['tt-tienmat','tt-duno','tt-uytin','tt-hailong','tt-kytra','tt-khach'];
  if(typeof bookCard==='function'&&window.UI_ICON&&KEYS.every(k=>UI_ICON[k])){
    const orig=bookCard; let i=0;
    bookCard=function(){ i=0; return orig.apply(this,arguments).replace(/(<div class="tile st-tile">)([\s\S]*?)(<b>)/g,(m,a,_,b)=>a+uiIco(KEYS[i++]||'sao')+b); };
  }
  const st=document.createElement('style');
  st.textContent='.item>.ui-ico.prep-ico{width:36px;height:36px;flex:none;margin-right:8px;object-fit:contain}';
  document.head.appendChild(st);
})();

// 17b-moc.js — Việc 15a: MỐC THƯỞNG (đặc tả bao-cao-phong-cach-game.md J.0–J.2, J.4, J.5). Nạp sau 17a-anh-a4.js.
// Bảng MOC + S.moc (id → ngày đạt). Kiểm trong lớp bọc checkMissions() (không thêm vòng lặp). Bốn loại báo: T1 có sẵn trong cảnh;
// T2 toast; T3 popup thưởng; T4 popup + hoa giấy. Trần 2 popup/ngày (T4 ≤1/ngày), cách nhau ≥2 phút thật; dư thì gom vào bảng Đóng cửa.
// Thưởng không phải tiền. Món chưa có chỗ trong Kho hoặc chưa có hình → danh hiệu chữ. Save cũ không có S.moc: ghi nhận lặng lẽ, không thưởng lại.
// Combo (MT06/MT09/MT14) đọc S.combo của Việc 15b; Danh vọng (MT11/MT13) đọc S.dv của Việc 15c: chưa có thì chưa đạt.
'use strict';
(()=>{
const isBot=()=>window.__REQBOT!=null||window.__AUTOPLACE===true;
const GAP=120000, CAP=2;                          // ≥2 phút thật giữa 2 popup; ≤2 popup/ngày game
const MO={sokhach:'Sổ khách (đánh giá trong Điện thoại)', combo:'tab Combo trong Kho đồ', quoctich:'dòng Khách quốc tịch trong Sổ sách', meo:'mục Mèo trong Mua sắm', ghim:'ghim Trần Hưng Đạo trên bản đồ'};
const KHO={cdmonst:'Chậu monstera'};            // món tặng được vào Kho (có loại đồ + hình thật); món khác → danh hiệu chữ
const ev=()=>S.mocEv;                              // cờ sự kiện do lớp bọc endDay ghi
const hasKho=t=>{ const L=S.room&&S.room[S.prem]; return !!L&&((L.store&&L.store[t]>0)||(L.items||[]).some(i=>i.t===t)); };
const quay=()=>!!(S.owned&&S.owned.cashier);
const ncb=()=>Object.keys((S.combo&&S.combo.found)||{}).length;
const first=()=>(S.svcLog||[]).find(e=>e.d===1);
const nv=n=>({id:'NV'+n, khi:()=>S.mission>=n, thuong:()=>({})});
const T=(id,ten,khi,bao,thuong,t2)=>({id,ten,khi,bao,thuong:thuong||(()=>({})),t2});
const MOC=[
  Object.assign(nv(1),{ten:'Khai trương tiệm',bao:'T3',thuong:()=>({}),mota:'Tiệm mở cửa! Hoàn thành mục tiêu sẽ có quà như thế này.'}),
  T('MT01','Khách đầu tiên trả tiền',()=>S.totals.served>=1,'T2',()=>({sen:1}),'Khách đầu tiên trả tiền: +1 sen'),
  T('MT02','Khách đầu tiên chấm 5 sao',()=>(S.reviews||[]).some(r=>r.stars>=5),'T2',()=>({mo:'sokhach'}),'Mở Sổ khách: xem đánh giá trong Điện thoại'),
  Object.assign(nv(2),{bao:'-'}),
  T('MT03','Đóng cửa ngày 1 có lãi',()=>!!ev().d1,'T3',()=>({dh:'Chủ đèn lồng',mota:'Món đèn lồng sân vườn chưa có trong Kho: tạm tặng danh hiệu.'})),
  Object.assign(nv(3),{bao:'-'}),
  T('MT04','Chạm kịp yêu cầu giữa buổi lần đầu',()=>((S.stats||{}).reqOk||0)>=1,'T2',()=>({sen:1}),'Đáp kịp yêu cầu khách: +1 sen'),
  T('MT05','Góc đón khách',()=>quay()&&S.day>=2&&hasKho('cdmonst'),'T3',()=>({dh:'Người đón khách',mota:'Quầy thu ngân đã có cây. Đặt thêm tranh tường cạnh quầy thử xem.'})),
  T('MT06','Phát hiện combo đầu tiên',()=>ncb()>=1,'T4',()=>({mo:'combo',sen:3})),
  Object.assign(nv(4),{bao:'-'}),
  T('MT07','Khách nước ngoài đầu tiên',()=>typeof guests!=='undefined'&&guests.some(g=>g.nat),'T2',()=>({mo:'quoctich'}),'Khách nước ngoài ghé! Mở dòng Khách quốc tịch'),
  Object.assign(nv(5),{bao:'-'}),
  T('MT08','Doanh thu gấp đôi ngày 1',()=>{ const f=first(); return !!f&&f.gross>0&&(S.svcLog||[]).some(e=>e.d>1&&e.gross>=2*f.gross); },'T3',()=>({dh:'Tiệm mới nổi'})),
  T('MT09','Ô "?" combo đầu tiên',()=>!!(S.combo&&S.combo.near),'T2',()=>({}),'Một ô "?" combo vừa sáng lên'),
  Object.assign(nv(6),{bao:'T4',ten:'Xong chương 1',mota:'Chương 1 hoàn thành: tiệm đã đứng vững.'}),
  T('MT10','Ứng viên KTV giỏi tìm tới',()=>!!ev().cand,'T2',()=>({}),'Có ứng viên KTV giỏi: xem tab Tuyển'),
  T('MT11','Kết mùa danh vọng đầu tiên',()=>S.day>=7&&!!ev().mua,'T3',()=>({sen:1}),'Kết mùa đầu tiên: +1 sen'),
  T('MT12','Khách đoàn đầu tiên',()=>typeof guests!=='undefined'&&guests.some(g=>g.grp!=null),'T2',()=>({}),'Khách đoàn đầu tiên vào tiệm!'),
  Object.assign(nv(7),{bao:'-'}),
  T('MT13','Danh vọng chạm 1.000',()=>(S.dv||0)>=1000,'T3',()=>({mo:'meo'})),
  Object.assign(nv(8),{bao:'-'}),
  T('MT14','Đủ 3 combo',()=>ncb()>=3,'T3',()=>({dh:'Tiệm khéo bày',sen:2})),
  ...[9,10,11].map(n=>Object.assign(nv(n),{bao:'-'})),
  Object.assign(nv(12),{bao:'T4',ten:'Xong chương 2',mota:'Chương 2 hoàn thành: khách quen đã biết tiệm.'}),
  T('MT18','Thử thách hiếm xuất hiện',()=>!!(S.rare&&S.rare.quest),'T3',()=>({})),
  ...[13,14,15,16].map(n=>Object.assign(nv(n),{bao:'-'})),
  Object.assign(nv(17),{bao:'T4',ten:'Xong chương 3',mota:'Chương 3 hoàn thành: tiệm đã thành danh.'}),
  T('MT19','Đủ điều kiện cổng Trần Hưng Đạo',()=>!!ev().cong,'T4',()=>({mo:'ghim'}))
];
// 20a: mốc giữa game (ngày 15–30), thưởng danh hiệu/sen, không phải tiền
MOC.push(
  T('MT20','Ba KTV cùng lúc',()=>(S.staff||[]).length>=3,'T3',()=>({dh:'Bà chủ đông thợ'})),
  T('MT21','100 khách đã phục vụ',()=>S.totals.served>=100,'T3',()=>({sen:2})),
  T('MT22','Danh vọng chạm 900',()=>(S.dv||0)>=900,'T3',()=>({dh:'Tiệm có tiếng'})),
  T('MT23','Mở tiệm thứ hai',()=>Object.keys(S.shops||{}).length>=2,'T4',()=>({dh:'Chủ chuỗi nhỏ',sen:2})),
  T('MT24','Đủ 5 combo',()=>ncb()>=5,'T3',()=>({sen:2}))
);
// kết mùa tiếp theo (ngày 14, 21, …, 42): mỗi mùa một mốc riêng, ghi S.moc['MT15-14']…
for(const d of [14,21,28,35,42]) MOC.push(T('MT15-'+d,'Kết mùa ngày '+d,()=>S.day>=d&&!!ev().mua&&ev().mua>=d,'T3',()=>({sen:1}),'Kết mùa: +1 sen'));
MOC.forEach(m=>{ if(!m.ten) m.ten=m.id.startsWith('NV')?'Nhiệm vụ '+m.id.slice(2):m.id; });

function ensure(){
  if(!S.moc){ S.moc={}; S.mocOld=S.stage!=='story'&&(S.day>1||S.mission>0||S.totals.served>0); }
  S.mocEv=S.mocEv||{}; S.mocQ=S.mocQ||[]; S.mocLog=S.mocLog||[]; S.mocDone=S.mocDone||{}; S.dh=S.dh||[]; S.mocMo=S.mocMo||{}; S.mocDay=S.mocDay||{d:0,n:0,t4:0}; S.mocReal=S.mocReal||0;
}
const byId=id=>MOC.find(m=>m.id===id);
let lastPop=0;

// ---- thưởng ----
function giveKho(t){ const L=S.room&&S.room[S.prem]; if(L&&L.store){ L.store[t]=(L.store[t]||0)+1; return true; } return false; }
function rewardTxt(m,fb){ const r=m.thuong(), a=[]; if(r.sen) a.push(`+${r.sen} sen`); if(r.xp) a.push(`+${r.xp} điểm nghề`); if(r.mon) a.push(`${KHO[r.mon]||r.mon} (vào Kho đồ)`); if(r.mo) a.push(`Mở ${MO[r.mo]}`); if(r.dh) a.push(`Danh hiệu "${r.dh}"`);
  return a.join(' · ')||(fb?(m.mota||r.mota||''):''); }
function grant(m){
  if(S.mocDone[m.id]) return; S.mocDone[m.id]=1; const r=m.thuong();
  if(r.sen&&S.mg) S.mg.lotus=(S.mg.lotus||0)+r.sen; if(r.xp) S.xp+=r.xp;
  if(r.mon){ if(!giveKho(r.mon)){ S.mocGift=(S.mocGift||[]).concat(r.mon); } }
  if(r.mo){ S.mocMo[r.mo]=1; if(r.mo==='sokhach'&&typeof unread!=='undefined') unread.reviews=true; }
  if(r.dh&&!S.dh.includes(r.dh)) S.dh.push(r.dh);
  if((r.mo||r.dh||r.mon)&&typeof sfx==='function') setTimeout(()=>sfx('unlock'),700);
  if(typeof renderTop==='function') renderTop();
}
function log(m){ S.mocLog.push({id:m.id,d:S.day,t:Math.round(S.time||0),ph:Math.round(S.mocReal)}); }
function reach(m,silent){
  S.moc[m.id]=S.day;
  if(silent){ S.mocDone[m.id]=1; return; }
  log(m);
  if(m.bao==='-'){ S.mocDone[m.id]=1; return; }                // nhiệm vụ cũ: thưởng và toast do checkMissions cũ lo
  if(m.bao==='T2'){ grant(m); toast(m.t2||m.ten,'good'); return; }
  if(isBot()){ grant(m); return; }
  S.mocQ.push(m.id);
}
function check(){
  ensure();
  if(S.mocOld){ S.mocOld=false; MOC.forEach(m=>{ if(!S.moc[m.id]){ try{ if(m.khi()) reach(m,true); }catch(e){} } }); return; }
  let ch=false;
  for(const m of MOC){ if(S.moc[m.id]) continue; let ok=false; try{ ok=m.khi(); }catch(e){} if(ok){ reach(m); ch=true; } }
  if(S.mocGift&&S.mocGift.length){ S.mocGift=S.mocGift.filter(t=>!giveKho(t)); }
  if(ch) save();
  pump();
}

// ---- popup T3/T4 ----
const reduced=()=>window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;
const fxOn=()=>!reduced()&&!(window.HC&&HC.mode&&HC.mode()==='tat');
function css(){ if(document.getElementById('mocCss')) return; const s=document.createElement('style'); s.id='mocCss';
  s.textContent=`.moc-pop{position:relative;text-align:center;overflow:hidden}.moc-pop .moc-qua img,.moc-pop .moc-qua{width:96px;height:96px;margin:0 auto 6px;font-size:72px;line-height:96px;display:block}
.moc-pop h2{margin:4px 0}.moc-pop .moc-cf{position:absolute;inset:0;pointer-events:none}.moc-pop .moc-cf i{position:absolute;top:-10px;width:7px;height:11px;border-radius:2px;animation:mocCf 1.2s ease-in forwards}
.moc-day .moc-card{display:flex;align-items:center;gap:10px;min-height:64px;padding:0 8px;margin:6px 0;border-radius:12px;background:var(--c-kem-2,#f7efe2);opacity:0;animation:mocIn .24s ease-out forwards}
.moc-day .moc-card img,.moc-day .moc-card .moc-e{width:40px;height:40px;font-size:30px;line-height:40px;flex:none;text-align:center}.moc-day .moc-card b{display:block}.moc-day .moc-card span{font-size:var(--fz-ghichu);opacity:.8}
.moc-dh{display:block;font-size:var(--fz-ghichu);font-weight:800;line-height:1.1;opacity:.85}
@media (prefers-reduced-motion:no-preference){.moc-pop{animation:mocBounce .34s cubic-bezier(.3,1.6,.5,1) both}@keyframes mocBounce{from{transform:scale(.8);opacity:0}to{transform:scale(1);opacity:1}}}
@keyframes mocCf{to{transform:translateY(360px) rotate(540deg);opacity:0}}@keyframes mocIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}`;
  document.head.appendChild(s); }
function confetti(box){ if(!fxOn()) return; const cf=document.createElement('div'); cf.className='moc-cf'; const col=['#f4b942','#E9B8A6','#6fbf9a','#8FB48A','#f2e2b8'];
  for(let i=0;i<40;i++){ const p=document.createElement('i'); p.style.left=(Math.random()*100)+'%'; p.style.background=col[i%col.length]; p.style.animationDelay=(Math.random()*.25)+'s'; cf.appendChild(p); }
  box.appendChild(cf); setTimeout(()=>cf.remove(),1600); }
const ico=()=>(window.uiIco&&uiIco('qua'))||'<span class="moc-qua">🎁</span>';
function popup(m,t4){
  css(); const sfxk=t4?'milestone':'moc';
  sheet(`<div class="moc-pop"><div class="moc-qua">${ico()}</div><h2>${esc(m.ten)}</h2><p class="note">${esc(m.mota||m.thuong().mota||'')}</p>${rewardTxt(m)?`<p class="note"><b>${esc(rewardTxt(m))}</b></p>`:''}<div class="row"><button class="btn big butter" data-moc>Nhận</button></div></div>`, sh=>{
    sh.querySelector('[data-moc]').onclick=closeSheet; if(t4) confetti(sh.querySelector('.moc-pop')); });
  if(typeof sfx==='function') sfx(sfxk);
}
function modeOk(){
  if(!$('#sheetBg').hidden) return false; if(typeof haggling!=='undefined'&&haggling) return false;
  const md=window.LZ&&LZ.mode&&LZ.mode(); return !md||md==='lz-tiem';
}
function pump(){
  if(!S.mocQ.length||isBot()||S.stage!=='open'||!modeOk()) return;
  const D=S.mocDay; if(D.d!==S.day){ D.d=S.day; D.n=0; D.t4=0; }
  if(D.n>=CAP||Date.now()-lastPop<GAP) return;
  const m=byId(S.mocQ.shift()); if(!m){ return; }
  const t4=m.bao==='T4'&&D.t4<1; D.n++; if(t4) D.t4++; lastPop=Date.now();
  grant(m); save(); popup(m,t4);
}

// ---- Đóng cửa: mục "Hôm nay mở được" ----
function closingBlock(){
  const ms=S.mocQ.map(byId).filter(Boolean); if(!ms.length) return;
  const row=document.querySelector('#sheet .row:last-child'); if(!row) return; css();
  const card=(m,i)=>`<div class="moc-card" style="animation-delay:${i*80}ms"><span class="moc-e">🎁</span><div><b>${esc(m.ten)}</b><span>${esc(rewardTxt(m,1))}</span></div></div>`;
  row.insertAdjacentHTML('beforebegin',`<div class="moc-day"><div class="sec-t">Hôm nay mở được</div>${ms.map(card).join('')}<div class="row"><button class="btn alt" data-moc-all>Nhận tất cả</button></div></div>`);
  const take=()=>{ S.mocQ.splice(0).forEach(id=>{ const m=byId(id); if(m) grant(m); }); save(); const b=document.querySelector('#sheet [data-moc-all]'); if(b){ b.disabled=true; b.textContent='Đã nhận'; } };
  const go=document.querySelector('#sheet [data-go]'), b=document.querySelector('#sheet [data-moc-all]');
  if(b) b.onclick=take; if(go) go.addEventListener('click',take,true);
  ms.forEach((m,i)=>setTimeout(()=>{ if(typeof sfx==='function') sfx('click'); },i*80));
}

// ---- móc vào game ----
checkMissions=(orig=>function(){ orig(); try{ check(); }catch(e){ console.error('[moc]',e); } })(checkMissions);
tick=(orig=>function(dt){ const run=S.stage==='open'&&!(typeof haggling!=='undefined'&&haggling)&&$('#sheetBg').hidden; orig(dt); if(run){ ensure(); S.mocReal+=(speed>0?dt/speed:dt); } })(tick);
endDay=(orig=>function(){
  orig();
  try{ ensure(); const st=S.stats; S.mocReal+=30;                       // ước tính 30 giây đóng/mở cửa
    const net=st.rev+st.tips+(st.comm||0)-st.costs-(st.sup||0);
    if(S.day===1&&net>0) S.mocEv.d1=1;
    if(S.day>=5&&!S.moc.MT10&&S.cands.length){ const c=S.cands[0]; c.rank='tc'; c.moi=1; STK.forEach(k=>{ c.st[k]=Math.min(9,c.st[k]+1); }); const sum=STK.reduce((a,k)=>a+c.st[k],0); c.monthly=baseSalary(sum,true); S.mocEv.cand=1; }
    if(S.day%7===0) S.mocEv.mua=S.day;
    if(!S.moc.MT19&&typeof gateChecks==='function'){ try{ if(gateChecks('thd').every(x=>x.ok)) S.mocEv.cong=1; }catch(e){} }
    check(); closingBlock(); save();
  }catch(e){ console.error('[moc]',e); }
})(endDay);
const rt=typeof renderTop==='function'?renderTop:null;
if(rt) renderTop=function(){ rt.apply(this,arguments); try{ const h=document.getElementById('spaName'); if(!h) return; let el=document.getElementById('mocDh');
  const dh=S.dh&&S.dh[S.dh.length-1]; if(!dh){ if(el) el.remove(); return; }
  if(!el){ el=document.createElement('small'); el.id='mocDh'; el.className='moc-dh'; h.insertAdjacentElement('afterend',el); css(); } if(el.textContent!==dh) el.textContent=dh; }catch(e){} };
window.MOCLIST=MOC; window.MOCT={check,ensure,MOC};
})();

// 17b-combo.js — Việc 15b: COMBO TRANG TRÍ (đặc tả bao-cao-phong-cach-game.md J.3 + phần D). Nạp sau 17b-moc.js, trước 15z? không: 15z gọi COMBOT lúc chạy nên nạp sau cũng được.
// 12 combo xếp theo LOẠI ĐỒ THẬT trong phòng (RMC/RMW của 15y-room.js, gồm 9+ món trang trí Chợ đêm 19g/19q), không theo tên file hình trong phần D.
// Luật đặt: mọi món sàn nằm cách món neo ≤ g ô (khoảng hở giữa hai khung chân đế); đồ tường chỉ cần có trong phòng; "mặt tiền" = cách cửa chính ≤ 4 ô.
// Luật phát hiện luôn bật từ ngày 1; chỉ ô "?" + gợi ý mở dần (J.3). Món mòn ≥ 70% → combo tạm tắt. Mỗi combo tính 1 lần mỗi tiệm (S.combo.found, không xoá).
// Hiệu lực: mỗi combo đang bật cộng COMBO_PTS điểm vào decorParts() (15z-pacing.js) → boa +0,8%/điểm, trần +20% giữ nguyên.
// S.combo = {found:{c12:ngày}, hint:{c1:ngày}, near:ngày|0, warn:{c1:ngày}, q:[id chờ popup]}. Save cũ không có S.combo: tạo rỗng.
'use strict';
(()=>{
const isBot=()=>window.__REQBOT!=null||window.__AUTOPLACE===true;
const COMBO_PTS=3;
const PLANT=['plant','plant2','cdmonst','cdcau','cdcau2','cdduongxi'];
const DECO=PLANT.concat(['cdbuihoa','cddacanh','cdloida','cdbang','cdghebang','cdke','cdvach','shelf','buddha','fish','fountain']);
// slot: {t:[loại đồ], g:số ô tối đa tới món neo, wall:1 (đồ tường), door:ô tối đa tới cửa}
const S_=(t,g)=>({t,g:g==null?3:g}), W_=t=>({t,wall:1}), D_=(t,door)=>({t,door});
const COMBOS=[
 {n:1, ten:'Góc trà chờ', slots:[S_(['sofa']), S_(['tea'],2), S_(PLANT)], nhom:'A', goi:'Khách ngồi chờ thèm một ly trà, và một chậu cây cho dịu mắt…', ten_mon:['Sofa chờ 3 chỗ','Bàn trà gừng','Một chậu cây']},
 {n:2, ten:'Chợ đêm lung linh', slots:[W_(['lights']), W_(['lamps']), D_(DECO,4)], nhom:'A', goi:'Tối đến mặt tiền hơi tối: treo đèn, thả đèn, thêm một món ngay lối vào…', ten_mon:['Dây đèn lấp lánh','Đèn thả mây','Một món trang trí gần cửa']},
 {n:6, ten:'Góc làm đẹp', slots:[S_(['nail']), S_(['shelf']), S_(['plant2','diffuser'])], nhom:'A', goi:'Chỗ làm móng thiếu chỗ để đồ và chút hương thơm…', ten_mon:['Bàn nail','Kệ tinh dầu','Chậu cây nhỏ hoặc máy xông']},
 {n:4, ten:'Phát lộc', slots:[S_(['buddha']), S_(['fish']), S_(['diffuser'])], nhom:'A', goi:'Chủ tiệm nào cũng mong phát đạt: tượng, nước và hương…', ten_mon:['Tượng Phật Di Lặc','Bể cá mini','Máy xông tinh dầu']},
 {n:12, ten:'Đón khách', slots:[S_(['counter']), W_(['art']), S_(PLANT)], nhom:'D', goi:'Quầy thu ngân còn trống trải: thêm tranh và một chậu cây gần quầy…', ten_mon:['Quầy thu ngân','Tranh tường','Một chậu cây gần quầy']},
 {n:5, ten:'Phòng body kín đáo', slots:[S_(['bed']), S_(['water']), S_(['towel'])], nhom:'B', goi:'Khách nằm cần kín đáo và khăn sạch gần tay…', ten_mon:['Giường body','Cây nước / bình phong','Tủ khăn & máy hấp khăn']},
 {n:8, ten:'Hương thư giãn', slots:[S_(['bed','chair','facial']), S_(['diffuser']), S_(['rug'])], nhom:'B', goi:'Một góc nằm thơm dịu, chân chạm lớp thảm êm…', ten_mon:['Giường hoặc ghế massage','Máy xông tinh dầu','Thảm cói']},
 {n:7, ten:'Xông thảo mộc', slots:[S_(['herbal','bontam']), S_(['trolley']), S_(['sauna','tuhapkhan'])], nhom:'B', goi:'Hơi nóng, nước thuốc và một chiếc xe đá nóng…', ten_mon:['Bồn thảo dược / bồn tắm','Xe đá nóng','Phòng xông hoặc tủ hấp khăn']},
 {n:9, ten:'Sân quê', slots:[S_(['cdghebang','cdbang']), S_(['cdloida']), S_(['cdbuihoa'])], nhom:'B', goi:'Nhớ sân nhà ở quê: ghế băng, lối đá, bụi hoa trắng…', ten_mon:['Ghế băng gỗ','Lối đá bước','Bụi hoa trắng']},
 {n:3, ten:'Ao sen', slots:[S_(['fountain']), S_(['cdbuihoa']), S_(['cddacanh'])], nhom:'C', goi:'Nước, đá và một bụi hoa trắng bên cạnh…', ten_mon:['Tiểu cảnh nước','Bụi hoa trắng','Đá cảnh và dương xỉ']},
 {n:10, ten:'Vườn thiền', slots:[S_(['cddacanh']), S_(['cdcau','cdcau2']), S_(['cdloida'])], nhom:'C', goi:'Đá, cau và lối bước tĩnh lặng…', ten_mon:['Đá cảnh và dương xỉ','Cây cau','Lối đá bước']},
 {n:11, ten:'Suối róc rách', slots:[S_(['fountain']), S_(['cddacanh']), S_(['cdduongxi'])], nhom:'C', goi:'Tiếng nước chảy giữa đá và dương xỉ…', ten_mon:['Tiểu cảnh nước','Đá cảnh và dương xỉ','Chậu dương xỉ']}
];
const ORD={A:[1,2,6,4], B:[5,8,7,9], C:[3,10,11]};
const cid=c=>'c'+c.n, byN=n=>COMBOS.find(c=>c.n===n);

function ensure(){ if(!S.combo||typeof S.combo!=='object') S.combo={}; const c=S.combo; c.found=c.found||{}; c.hint=c.hint||{}; c.warn=c.warn||{}; c.q=c.q||[]; if(c.near==null) c.near=0; return c; }
const X=()=>window.RMX||null;
const worn=it=>!!it.slot&&typeof wearPct==='function'&&wearPct(it.slot)>=.7;
function rect(it,RMC){ const c=RMC[it.t]; if(!c) return null; const sw=(it.r||0)%2; return {x:it.x,y:it.y,w:sw?c.d:c.w,d:sw?c.w:c.d}; }
const gap=(a,b)=>Math.max(0,a.x-(b.x+b.w),b.x-(a.x+a.w),a.y-(b.y+b.d),b.y-(a.y+a.d));

// Quét phòng hiện tại: trả {id:{have,ok,worn}} — have = số slot có ít nhất 1 món (bỏ qua vị trí); ok = đủ + đúng vị trí + không mòn; worn = sẽ ok nếu không tính mòn
function scan(){
  const x=X(), out={}; if(!x||!S.room) return out; const L=S.room[S.prem]; if(!L) return out;
  const fl=[], wl=[];
  (L.items||[]).forEach(it=>{ const r=rect(it,x.RMC); if(r) fl.push({it,r,t:it.t,w:worn(it)}); });
  (L.walls||[]).forEach(it=>wl.push({it,t:it.t,w:worn(it)}));
  const dm=x.RMAP[S.prem]||x.RMAP.chodem, door={x:0,y:Math.max(0,dm.doorY-1),w:1,d:3};
  for(const c of COMBOS){
    const pool=ign=>c.slots.map(s=>(s.wall?wl:fl).filter(e=>s.t.includes(e.t)&&(ign||!e.w)));
    const have=c.slots.filter((s,i)=>pool(false)[i].length).length;
    const solve=ign=>{ const P=pool(ign); if(P.some(a=>!a.length)) return false;
      const rec=(i,used,anc)=>{ if(i===c.slots.length) return true; const s=c.slots[i];
        for(const e of P[i]){ if(used.has(e.it.uid)) continue; let a=anc;
          if(!s.wall){ if(s.door!=null){ if(gap(e.r,door)>s.door) continue; }
            else if(!anc) a=e.r; else if(gap(e.r,anc)>s.g) continue; }
          used.add(e.it.uid); const ok=rec(i+1,used,a); used.delete(e.it.uid); if(ok) return true; }
        return false; };
      return rec(0,new Set(),null); };
    const ok=solve(false); out[cid(c)]={have,ok,worn:!ok&&solve(true)};
  }
  return out;
}

let ACTIVE={};                                    // id → true nếu đang bật (không lưu)
function unlocked(){
  const C=ensure(), M=S.moc||{}, d=S.day||1, set=[];
  if(M.MT05) set.push(12);
  if(M.MT09) ORD.A.slice(0,Math.floor((d-M.MT09)/2)+1).forEach(n=>set.push(n));
  if((S.mission||0)>=6&&d>=10) ORD.B.slice(0,Math.floor((d-10)/2)+1).forEach(n=>set.push(n));
  if(d>=30) ORD.C.slice(0,Math.floor((d-30)/2)+1).forEach(n=>set.push(n));
  set.forEach(n=>{ const k='c'+n; if(!C.hint[k]) C.hint[k]=d; });
}
function update(){
  if(typeof S==='undefined'||!S.room||!S.prem) return;
  const C=ensure(), R=scan(), d=S.day||1; let ch=false; ACTIVE={};
  for(const c of COMBOS){ const k=cid(c), r=R[k]; if(!r) continue;
    if(r.ok){ ACTIVE[k]=true; if(!C.found[k]){ C.found[k]=d; C.hint[k]=C.hint[k]||d; if(!isBot()) C.q.push(k); ch=true; } }
    else if(r.worn&&C.found[k]&&C.warn[k]!==d&&!isBot()){ C.warn[k]=d; toast(`${c.ten} tạm tắt — sửa đồ bị mòn`,'warn'); ch=true; }
    if(!C.near&&ORD.A.includes(c.n)&&r.have>=2){ C.near=d; ch=true; } }
  unlocked();
  if(ch){ save(); if(typeof checkMissions==='function'&&!update.busy){ update.busy=1; try{ checkMissions(); }finally{ update.busy=0; } } }
  pump();
}

// ---- popup phát hiện (chờ thoát Bày trí, không cắt ngang việc khác) ----
let lastPop=0;
function modeOk(){
  if(S.stage!=='open'||isBot()) return false; if(window.RM&&RM.mode==='deco') return false;
  if(!$('#sheetBg').hidden) return false; if(typeof haggling!=='undefined'&&haggling) return false;
  const md=window.LZ&&LZ.mode&&LZ.mode(); return !md||md==='lz-tiem';
}
function pump(){
  const C=ensure(); if(!C.q.length||!modeOk()||Date.now()-lastPop<8000) return;
  const c=byN(+C.q.shift().slice(1)); if(!c){ return; } lastPop=Date.now(); save();
  sheet(`<div class="moc-pop"><h2>Phát hiện combo!</h2><h3 style="margin:2px 0">${esc(c.ten)}</h3><p class="note">${c.ten_mon.map(esc).join(' · ')}</p><p class="note"><b>+${COMBO_PTS} điểm trang trí</b> (tăng tiền boa khách)</p><div class="row"><button class="btn big butter" data-cb>Tuyệt</button></div></div>`, sh=>{ sh.querySelector('[data-cb]').onclick=closeSheet; });
  if(typeof sfx==='function') sfx('milestone');
}

// ---- Sổ combo: thẻ trong Sổ sách ----
function card(){
  const C=ensure(), d=S.day||1; const got=COMBOS.filter(c=>C.found[cid(c)]), qs=COMBOS.filter(c=>!C.found[cid(c)]&&C.hint[cid(c)]);
  if(!got.length&&!qs.length) return '';
  const R=scan(); const rows=got.map(c=>{ const on=ACTIVE[cid(c)], w=R[cid(c)]&&R[cid(c)].worn;
    return `<p class="note" style="margin-top:6px"><b>${esc(c.ten)}</b> ${on?'<span class="tag good">✓ Đang có · +'+COMBO_PTS+' điểm</span>':w?'<span class="tag">⚠ Cần sửa đồ</span>':'<span class="tag grey">Chưa đặt</span>'}<br>${c.ten_mon.map(esc).join(' · ')}</p>`; }).join('')
   +qs.map(c=>{ const k=cid(c), r=R[k]||{}; const lack=(d-C.hint[k]>=3)?c.slots.map((s,i)=>i).filter(i=>{ const L=S.room[S.prem]; return !((c.slots[i].wall?L.walls:L.items)||[]).some(e=>c.slots[i].t.includes(e.t)); })[0]:null;
    return `<p class="note" style="margin-top:6px"><b>???</b> ${'○'.repeat(c.slots.length)}<br><i>${esc(c.goi)}</i>${lack!=null?`<br>Còn thiếu: <b>${esc(c.ten_mon[lack])}</b>`:''}</p>`; }).join('');
  return `<div class="card"><div class="sec-t">Sổ combo <span class="tag ${got.length?'good':'grey'}">${got.length}/${COMBOS.length}</span></div>${rows}</div>`;
}
renderScreen=(orig=>function(){ orig(); try{ if(tab!=='book') return; const D=$('#dyn'); if(!D) return; const h=card(); if(!h) return;
  const cs=[...D.querySelectorAll('.card')], an=cs.find(c=>/Điểm trang trí/.test(c.textContent)); if(an) an.insertAdjacentHTML('afterend',h); }catch(e){ console.error('[combo]',e); } })(renderScreen);

endDay=(orig=>function(){ orig(); try{ update(); }catch(e){ console.error('[combo]',e); } })(endDay);
setInterval(()=>{ try{ update(); }catch(e){ console.error('[combo]',e); } },900);

window.COMBOT={COMBOS,scan,update,active:()=>Object.assign({},ACTIVE),
  parts:()=>COMBOS.filter(c=>ACTIVE[cid(c)]).map(c=>({n:'Combo '+c.ten,v:COMBO_PTS}))};
})();

// 18-khung-ui.js — 17j: gắn khung 9 mảnh vẽ tay (art/out/ui-9s-*) + tấm F2-1/F2-3 vào giao diện (border-image CSS + canvas phòng Tiệm).
// Sinh bởi tools/pack_khung_ui.py từ tools/_khung_ui.tpl.js. KHÔNG sửa tay phần dữ liệu.
(()=>{
const D={"khung-bang": "img/c218c02501ea.webp", "khung-the": "img/7fb1760a990d.webp", "khung-toast": "img/93364c01d254.webp", "khung-chandung": "img/b93abf75b9a2.webp", "nut-chinh": "img/978c054bd124.webp", "nut-nguy": "img/44990c87ce39.webp", "nut-phu": "img/40253f115f69.webp", "dai-tieude": "img/540c8654f689.webp", "thanh-nen": "img/e996ad7b6abb.webp", "thanh-day": "img/4b38b8134ade.webp", "khung-pop": "img/82c654bb6700.webp", "vien-thuoc": "img/6c2016ecc060.webp", "mg-khung": "img/f95a3a6c675f.webp", "mg-o": "img/7a15dc5db3d9.webp", "bongbong": "img/c7717d0eea71.webp", "nut-tron": "img/e6636bc95cd8.webp", "hong": "img/a47fdeaec312.webp", "vong": "img/dc9e46721b1f.webp", "bao": "img/aff4f4064ce1.webp", "kinhram": "img/4147b4f1e23f.webp", "thuoc": "img/9386e86d42e7.webp", "kim": "img/937c410d5a4f.webp", "hh-S": "img/94784e5d3b29.webp", "hh-A": "img/398f37332b0d.webp", "hh-B": "img/857ecebbef10.webp"}, SL={"khung-bang": 48, "khung-the": 44, "khung-toast": 44, "khung-chandung": 46, "nut-chinh": 26, "nut-nguy": 24, "nut-phu": 40, "dai-tieude": 42, "thanh": 53, "khung-pop": 40, "vien-thuoc": 40, "mg-khung": 50, "mg-o": 44};
const root=document.documentElement.style; for(const k in D) root.setProperty('--k-'+k,'url('+D[k]+')');
window.UI_ICON=window.UI_ICON||{}; Object.assign(UI_ICON,{'ic-kinhram':D.kinhram,'ic-thuoc':D.thuoc,'ic-bao-cham':D.bao});
const B=(k,w,fill)=>`border-image:var(--k-${k}) ${SL[k]}${fill?' fill':''} / ${w} stretch;box-shadow:none`;
const st=document.createElement('style');
st.textContent=`
.card{${B('khung-the','10px')};border-radius:8px;padding:12px 14px}
.item{${B('dai-tieude','9px')};border-radius:6px}
.item-hero{${B('khung-chandung','12px')};border-radius:8px}
.prem{${B('khung-the','10px')};border-radius:8px}
.prem[aria-pressed="true"]{filter:saturate(1.25) brightness(1.04)}
.btn{${B('nut-chinh','11px')};border-radius:7px}
.btn:active{transform:translateY(2px)}
.btn.alt,.btn.butter,.btn.mint,.btn.lav{${B('nut-phu','11px')};border-radius:7px}
.btn.danger,.btn.arm{${B('nut-nguy','11px')};border-radius:7px}
.seg{border:0;border-radius:0;overflow:visible;gap:3px}
.seg button{${B('nut-phu','9px')};border-radius:6px}
.seg button+button{border-left-width:1.5px}
.sheet{border-image:var(--k-khung-bang) ${SL['khung-bang']} / 14px 14px 0 14px stretch;border-radius:14px 14px 0 0;background:#FFFBF2}
.toast{${B('khung-toast','12px')};border-radius:8px}
.room .rm-drawer{border-image:var(--k-khung-bang) ${SL['khung-bang']} / 14px stretch;border-radius:0;background:rgba(255,251,242,.96);padding-top:6px}
.room .rm-pop{${B('khung-pop','13px',1)};background:none;padding:14px 16px 16px}
.room .rm-counter{${B('khung-pop','10px',1)};background:none;padding:8px 12px}
.room .rm-pill{${B('vien-thuoc','10px',1)};background:none;padding:6px 14px 7px}
.room .rm-eye,.snd-btn{border:0;border-radius:0;box-shadow:none;background:var(--k-nut-tron) center/contain no-repeat}
.room .rm-eye[aria-pressed="true"],.snd-btn[aria-pressed="true"]{background:var(--k-nut-tron) center/contain no-repeat;filter:saturate(.45) brightness(1.08)}
.st-tile{${B('khung-the','8px')};border-radius:6px}
.nav .dot{width:14px;height:14px;border:0;border-radius:0;background:var(--k-bao) center/contain no-repeat;top:4px}
.fx-thugs .ui-ico{display:inline-block;width:22px;height:22px;vertical-align:middle}
.mg-stage{${B('mg-khung','14px')};border-radius:6px}
.mg-cell{${B('mg-o','8px')};border-radius:6px}
.mg-cell.empty{border-image:none;border:1.5px dashed #D8D3CC;border-radius:11px}
.mg-gauge{${B('mg-khung','10px',1)};border-radius:6px;background:none;overflow:visible}
.mg-gauge .zone{${B('mg-o','7px',1)};border-radius:4px;background:rgba(143,211,174,.55)}
.mg-gauge .needle{width:22px;margin-left:-11px;top:-12px;bottom:-6px;border-radius:0;background:var(--k-kim) center/contain no-repeat}
.mg-grade.gS:not(:has(img)),.mg-grade.gA:not(:has(img)),.mg-grade.gB:not(:has(img)){border:0;border-radius:0;box-shadow:none;color:transparent;background-position:center;background-size:contain;background-repeat:no-repeat}
.star-meter .track{height:16px;border:0;border-image:var(--k-thanh-nen) 16 fill / 6px stretch;background:none;border-radius:0}
.dp-bar{height:16px;border:0;border-image:var(--k-thanh-nen) 16 fill / 6px stretch;background:none;border-radius:0;overflow:hidden}
.dp-bar i{background:var(--k-thanh-day) 0 0/100% 100% no-repeat;border-radius:3px}
.mg-grade.gS:not(:has(img)){background-image:var(--k-hh-S)} .mg-grade.gA:not(:has(img)){background-image:var(--k-hh-A)} .mg-grade.gB:not(:has(img)){background-image:var(--k-hh-B)}
`;
document.head.appendChild(st);

// ---- canvas phòng Tiệm (#1 bong bóng, #2 chấm than, #3 vòng tiến độ) ----
let ctx=null; const IM={}; const img=k=>{ let i=IM[k]; if(!i){ const u=D[k]||UI_ICON[k]; if(!u) return null; i=IM[k]=new Image(); i.src=u; } return i.complete&&i.naturalWidth?i:null; };
const ICO={'🫖':'ic-thaoduoc','🌿':'ic-thaoduoc','❄':'ic-lanh','🎵':'yc-nhac','🥤':'yc-douong','🌡':'ic-nhietke','💪':'yc-manhtay','✨':'fx-lap-lanh','😞':'ic-sai'};
const TAN='#FBF0D8', NAU='#6B4A33', CH='#4A3426';
function nine(c,im,sl,x,y,w,h,k,sh){ const W=im.naturalWidth,H=sh||im.naturalHeight; sl=Math.min(sl,W/2-1,H/2-1); k=Math.min(k,w/2,h/2);
  const xs=[0,sl,W-sl,W], xd=[x,x+k,x+w-k,x+w], ys=[0,sl,H-sl,H], yd=[y,y+k,y+h-k,y+h];
  for(let r=0;r<3;r++) for(let q=0;q<3;q++) c.drawImage(im,xs[q],ys[r],xs[q+1]-xs[q],ys[r+1]-ys[r],xd[q],yd[r],xd[q+1]-xd[q],yd[r+1]-yd[r]); }
function bub(bx,by,w,h,s,tx,up){ const bi=img('bongbong'); if(!bi) return false;
  ctx.save(); ctx.beginPath();   // đuôi bằng code (tấm vẽ tay có đuôi cố định góc trái nên chỉ lấy thân)
  if(up){ ctx.moveTo(tx-5,by+1); ctx.lineTo(tx,by-6); ctx.lineTo(tx+5,by+1); } else { ctx.moveTo(tx-5,by+h-1); ctx.lineTo(tx,by+h+6); ctx.lineTo(tx+5,by+h-1); }
  ctx.fillStyle=TAN; ctx.fill(); ctx.lineWidth=1.6; ctx.strokeStyle=NAU; ctx.lineJoin='round'; ctx.stroke();
  nine(ctx,bi,44,bx,by,w,h,9,Math.round(bi.naturalHeight*.8));
  ctx.font='800 11px "Nunito",sans-serif'; ctx.textBaseline='alphabetic'; ctx.fillStyle=CH; ctx.textAlign='left';
  const seg=[]; let tw=0; for(const ch of Array.from(s.replace(/️/g,''))){ const ik=ICO[ch], ii=ik&&img(ik); const a=ii?{i:ii,w:13}:{t:ch,w:ctx.measureText(ch).width}; seg.push(a); tw+=a.w; }
  let x=bx+w/2-tw/2; for(const a of seg){ if(a.i) ctx.drawImage(a.i,x,by+h/2-6.5,13,13); else ctx.fillText(a.t,x,by+14); x+=a.w; }
  ctx.restore(); return true; }
window.KHUNG={ bub(c,p){ ctx=c; return bub(p.bx,p.by,p.w,p.h,p.s,Math.max(p.bx+9,Math.min(p.bx+p.w-9,p.tx)),p.up); },   // 12/10 17u: ctx/bubbleBox nam trong IIFE cua 15y-room nen khong 'vá' tu ngoai duoc; 15y-room truyen ctx vao day
  // chấm than máy hỏng + vòng tiến độ: trả false khi hình chưa nạp để 15y-room vẽ lại như cũ
  hong(cx,cy,c){ ctx=c; const i=img('hong'); if(!i) return false; ctx.drawImage(i,cx-12,cy-12,24,24); return true; },
  vong(cx,cy,f,c){ ctx=c; const i=img('vong'); if(!i) return false; ctx.drawImage(i,cx-12,cy-12,24,24);
    ctx.beginPath(); ctx.arc(cx,cy,8.2,-Math.PI/2,-Math.PI/2+Math.PI*2*f); ctx.lineWidth=3.2; ctx.lineCap='round'; ctx.strokeStyle='#F2B84B'; ctx.stroke(); ctx.lineCap='butt'; return true; }
};
})();

