// F2-4: tranh đồ hao mòn thay ảnh w_* ở mức 3 (cũ) và 4 (hỏng)
const W={body:'body',facial:'facial',nail:'nail',sauna:'sauna',herbal:'herbal',furniture:'furniture',towel:'towel',oil:'oil',foot:'foot'};
for(const k in W){for(const st of [0,1,2]) IMG[`w_${k}_${st}`]=P('ic-moi-'+W[k]);for(const st of [3,4]) IMG[`w_${k}_${st}`]=P('ic-hao-'+W[k]);}
// ngân hàng (SC_BANK dùng ở 14-story + 15k-debt)
SC_BANK=`<img src="${P('fx-minh-nganhang')}" alt="" style="width:74px;height:74px;object-fit:contain;flex:none">`;
