  set.insertAdjacentHTML('beforeend',`<div><label class="l" for="hcSel">Hoạt cảnh</label> <select id="hcSel">${Object.keys(MODES).map(k=>`<option value="${k}"${k===mode?' selected':''}>${MODES[k]}</option>`).join('')}</select></div>`);
