// Đồng hồ FPS ẩn — chỉ chạy khi URL có ?fps=1. Không đụng biến toàn cục nào khác.
(function () {
  if (new URLSearchParams(location.search).get('fps') !== '1') return;

  var box = document.createElement('div');
  box.style.cssText = 'position:fixed;top:4px;right:4px;z-index:10000;pointer-events:none;' +
    'background:rgba(20,16,28,.72);color:#7CFC9B;font:700 max(var(--fs-min),11px)/1.35 ui-monospace,Menlo,Consolas,monospace;' +
    'padding:4px 7px;border-radius:6px;text-align:right;white-space:pre;letter-spacing:.2px';
  document.body.appendChild(box);

  var WIN = 10000;                 // cửa sổ 10 giây
  var frames = [];                 // {t, dt}
  var last = performance.now();
  var lastPaint = last;
  var framesTotal = 0, framesGood = 0; // đếm từ đầu để tính % ≥30fps

  function tick(now) {
    var dt = now - last; last = now;
    if (dt > 0) { frames.push({ t: now, dt: dt }); framesTotal++; if (1000 / dt >= 30) framesGood++; }
    while (frames.length && now - frames[0].t > WIN) frames.shift();
    requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);

  function pct1low() {
    if (frames.length < 2) return 0;
    var dts = frames.map(function (f) { return f.dt; }).sort(function (a, b) { return b - a; });
    var n = Math.max(1, Math.ceil(dts.length * 0.01));
    var sum = 0; for (var i = 0; i < n; i++) sum += dts[i];
    return 1000 / (sum / n);
  }

  function draw() {
    var now = performance.now();
    if (now - lastPaint >= 500) {
      var inst = frames.length ? 1000 / (frames.reduce(function (a, f) { return a + f.dt; }, 0) / frames.length) : 0;
      lastPaint = now;
      var good = framesTotal ? (framesGood / framesTotal * 100) : 0;
      box.textContent = 'FPS ' + inst.toFixed(0) +
        '\n1% low ' + pct1low().toFixed(0) +
        '\n≥30fps ' + good.toFixed(0) + '%';
    }
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
})();
// 24b-gom.js — Việc 24b: gom chức năng + màn mini game NGANG dựng trên ảnh vẽ tay của Xưởng (MG20..MG24). Luật chơi/kinh tế giữ nguyên.
//  (1) Sổ tay là chỗ DUY NHẤT cho Điểm danh + Nhiệm vụ hằng ngày (15x); Việc tay chỉ còn 4 mini game; Kho đồ chỉ ở cột nút phụ (+ nút Kho trong Bàn pha chế cho kho nguyên liệu)
//  (2) màn ngang: "sân khấu" 16:9 phủ khung (kiểu cover), mọi vật đặt theo % toạ độ đo từ ảnh (css/24b-toado.css do tools/cat_24b.py sinh)
//  (3) Bàn pha chế, Tủ spa 2048, Pha nước ngâm, bảng chọn Việc tay, Công thức, Mua sắm (kệ) đều là cảnh ảnh nền, không còn bảng kem phẳng.
