// ---- #sheet dùng lại cho mọi bảng: mở bảng mới thì bỏ cờ cảnh cũ ----
sheet=(o=>function(){ const sh=$('#sheet'); if(sh){ delete sh.dataset.scene; sh.classList.remove('rc-open'); } const r=o.apply(this,arguments); if(sh) sh.scrollTop=0; return r; })(sheet);   // bảng mới luôn bắt đầu từ đầu (tự focus nút đầu không kéo cuộn lệch)
const scene=(sh,name)=>{ sh.dataset.scene=name; sh.classList.remove('rc-open'); };
const xBtn=(label,attr)=>`<button class="sc-x" ${attr||'data-scx'} aria-label="${label||'Đóng'}"></button>`;

// ---- nhấn giữ icon = hiện tên (tên không nằm sẵn trên màn) ----
function holdTips(root){ let t=null, tip=null;
  const hide=()=>{ clearTimeout(t); if(tip){ tip.remove(); tip=null; } };
  root.addEventListener('pointerdown',e=>{ const el=e.target.closest('[data-tip]'); if(!el) return; hide();
    t=setTimeout(()=>{ tip=document.createElement('div'); tip.className='sc-tip'; tip.textContent=el.dataset.tip; const r=el.getBoundingClientRect(), p=root.getBoundingClientRect();
      tip.style.left=Math.round(r.left+r.width/2-p.left)+'px'; tip.style.top=Math.round(r.top-p.top-4)+'px'; root.appendChild(tip); },320); });
  ['pointerup','pointercancel','pointerleave'].forEach(ev=>root.addEventListener(ev,hide)); }

// ---- 1. dấu chấm báo việc hằng ngày trên nút ? (Sổ tay) ----
const ndot=()=>typeof dailyBadge==='function'&&S.prem?dailyBadge():0;
function syncGuideDot(){ const b=$('#guideBtn'); if(!b) return; const n=ndot(); b.classList.toggle('has-bd',n>0); if(n>0) b.dataset.n=n; else delete b.dataset.n; }
