{ const room=$('#room'); if(room) room.addEventListener('click',e=>{ const b=e.target.closest('[data-rmmg]'); if(!b||!LAND()) return; e.stopPropagation(); e.preventDefault(); openViecTay(); },true); }

// ---- 3. Bàn pha chế ----
const rwText=c=>c.qty>=1000?'+'+(c.qty/1000)+'L':'+'+c.qty;
const ARROW='<svg class="ar" viewBox="0 0 28 16" aria-hidden="true"><path d="M2 9c5-3 11-4 20-1" fill="none" stroke="#8a5a2b" stroke-width="2.4" stroke-linecap="round"/><path d="M17 2l7 6-8 5" fill="none" stroke="#8a5a2b" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>';
