  const btns=document.createElement('div'); btns.className='pp-btns'; btns.innerHTML='<button class="btn sm alt" data-rc>Công thức</button>'+(inv?'<button class="btn sm alt" data-invup>Đưa lên bàn</button>':'')+'<button class="btn sm alt" data-kho>Kho</button>'; paper.appendChild(btns);
  st.appendChild(paper);
  const invBox=document.createElement('div'); invBox.className='rc-board inv-board'; invBox.hidden=true;
  if(inv){ invBox.innerHTML=`<div class="rc-in"><p class="inv-t">Đưa nguyên liệu lên bàn</p></div>${xBtn('Quay lại','data-rcx')}`; invBox.querySelector('.rc-in').appendChild(inv.querySelector('.row')||inv); }
  const recipe=document.createElement('div'); recipe.innerHTML=recipeBoard(); const rb=recipe.firstChild; rb.hidden=true;
  sh.innerHTML=''; sh.appendChild(st); sh.appendChild(rb); sh.appendChild(invBox); sh.insertAdjacentHTML('beforeend',xBtn());
  scene(sh,'pc'); holdTips(sh);
  const back=()=>{ rb.hidden=true; invBox.hidden=true; sh.classList.remove('rc-open'); };
  sh.querySelector(':scope > .sc-x[data-scx]').onclick=()=>{ closeSheet(); renderAll(); };
  sh.querySelectorAll('[data-rcx]').forEach(b=>b.onclick=back);
  paper.querySelector('[data-rc]').onclick=()=>{ rb.hidden=false; invBox.hidden=true; sh.classList.add('rc-open'); };
  const iu=paper.querySelector('[data-invup]'); if(iu) iu.onclick=()=>{ invBox.hidden=false; rb.hidden=true; sh.classList.add('rc-open'); };
  paper.querySelector('[data-kho]').onclick=()=>openInv();
