// 24e: nut chu gan mau theo noi dung (xanh/cam/kem), nut -/+, nut xoay, hop xac nhan the go. Luat choi giu nguyen.
(()=>{
const XANH=/^(xác nhận|đồng ý|mua|nhập|đặt(?! lại)|nhận|thuê|ký|tất toán|trả|nâng|xây|bắt đầu|tuyệt|chốt|ok|vào|chơi tiếp|tiếp tục|lưu|làm|mở tiệm|thưởng)/i;
const CAM=/^(huỷ|hủy|từ chối|bán|sa thải|đuổi|bỏ|xoá|xóa|chơi lại|phạt|đóng cửa|giải tán)/i;
const SEL='.btn,.sp-main,.sp-sub2,.in-skip,.kt-skip,.mg-gen,.rm-fb:not(.v9):not(.rm-tg):not([data-rmrot]),#wm .wm-lbn';
function tone(b){ const t=(b.textContent||'').trim().replace(/\s+/g,' ');
  if(/^[−\-–＋+]$/.test(t)) return t==='+'||t==='＋'?'cong':'tru';
  if(b.classList.contains('danger')||b.classList.contains('arm')||CAM.test(t)) return 'cam';
  if(XANH.test(t)) return 'xanh'; return 'kem'; }
function paint(root){ (root||document).querySelectorAll(SEL).forEach(b=>{ if(b.closest('.nav,.g-tabs,.seg')) return; const k=tone(b);
    if(k==='tru'||k==='cong'){ b.classList.add(k==='cong'?'u3-cong':'u3-tru'); b.classList.remove('u3-b'); b.removeAttribute('data-u3'); if(!b.getAttribute('aria-label')) b.setAttribute('aria-label',k==='cong'?'Tăng':'Giảm'); return; }
    if(!b.classList.contains('btn')) b.classList.add('u3b'); if(b.dataset.u3!==k) b.dataset.u3=k; });
  (root||document).querySelectorAll('[data-rmrot]').forEach(b=>{ b.classList.add('u3-xoay'); if(!b.getAttribute('aria-label')) b.setAttribute('aria-label',b.textContent.replace(/^[^\p{L}]+/u,'').trim()||'Xoay'); });
  (root||document).querySelectorAll('.room .rm-fb.v9').forEach(b=>{ if(!b.getAttribute('aria-label')){ const l=b.querySelector('.lb'); if(l) b.setAttribute('aria-label',l.textContent.trim()); } if(!b.title) b.title=b.getAttribute('aria-label')||''; }); }
let q=0; new MutationObserver(()=>{ if(q) return; q=1; requestAnimationFrame(()=>{ q=0; paint(); }); }).observe(document.body,{childList:true,subtree:true,characterData:true});
paint();
// hop xac nhan: uiConfirm('Noi dung?','Xac nhan','Huy',()=>...)
window.uiConfirm=function(msg,okTxt,noTxt,onOk){ const old=document.getElementById('u3cf'); if(old) old.remove();
  const e=document.createElement('div'); e.id='u3cf'; e.setAttribute('role','alertdialog'); e.setAttribute('aria-modal','true');
  e.innerHTML='<div class="u3cf-c"><div class="u3cf-t"></div><div class="u3cf-b"><button type="button" class="no"></button><button type="button" class="ok"></button></div></div>';
  e.querySelector('.u3cf-t').textContent=msg; e.querySelector('.no').textContent=noTxt||'Huỷ'; e.querySelector('.ok').textContent=okTxt||'Xác nhận';
  const close=()=>e.remove(); e.addEventListener('click',ev=>{ if(ev.target===e||ev.target.closest('.no')){ close(); } else if(ev.target.closest('.ok')){ close(); try{ onOk&&onOk(); }catch(x){ console.error(x); } } });
  (document.getElementById('phone')||document.body).appendChild(e); };
})();

// 24f: man Dich vu / Nhan su / Dien thoai ve tay (MG25, MG26, UI3 dien thoai). Luat choi giu nguyen: moi nut bam chuyen sang nut that
// trong the an (data-px = bo chon nut goc), nen moi xu ly cu (hoc, nang, thue, thuong, gia...) khong doi.
// Man ngang thap: #dyn thanh canh phu khung (nhu ke hang 24b). Man doc / man rong: danh sach xep doc tren nen mo.
(function(){ 'use strict';
const LOW=()=>matchMedia('(orientation:landscape) and (max-height:600px)').matches;
const E=v=>esc(String(v==null?'':v));
const PG={}, PW=1672, PH=941;
const pc=(x,y,w,h)=>`left:${(x/PW*100).toFixed(3)}%;top:${(y/PH*100).toFixed(3)}%;width:${(w/PW*100).toFixed(3)}%;height:${(h/PH*100).toFixed(3)}%`;
// ---- hinh hoc MG25 (Dich vu): 6 hang, hang i cao 72 tu y=RY[i]; o tron x432-528, giay x538-1122, the go x1143-1272
const RY=[214,312,410,511,612,713];
// ---- hinh hoc MG26 (Nhan su): 5 polaroid. o = khung ngoai, w = cua so anh, l = nhan ten, s = tam sao
const POL=[
 {o:[335,330,520,540],w:[352,346,503,498],l:[368,555,507,615],s:[513,497],r:-2.5},
 {o:[548,335,735,538],w:[562,350,718,498],l:[580,555,717,613],s:[722,495],r:-2},
 {o:[762,335,948,538],w:[777,348,933,495],l:[797,555,935,612],s:[932,495],r:-.5},
 {o:[977,335,1162,538],w:[992,348,1146,495],l:[1010,553,1146,612],s:[1143,497],r:.5},
 {o:[1202,330,1388,538],w:[1217,346,1370,495],l:[1222,555,1360,612],s:[1375,497],r:-1}
];
const px=sel=>E(sel);
const ok=(sel)=>{ const o=$('#dyn').querySelector(sel); return o&&!o.disabled; };
// ---------------- du lieu ----------------
function dvRows(sub){
  if(sub==='gia') return SK.map(k=>{ const sv=SERVICES[k], off=canOffer(k);
    return {ic:ico(SVC_ICON[k]), name:sv.name, meta:`${sv.min}'`, tag:fmt(priceOf(k)), dim:!off, lock:!off,
      m:`[data-p="${k}"][data-d="-10000"]`, p:`[data-p="${k}"][data-d="10000"]`,
      pop:{ic:ico(SVC_ICON[k]), title:sv.name, lines:[`${sv.min} phút · giá bạn đặt ${fmt(priceOf(k))}`,`Thị trường khoảng ${fmt(market(k))}. Đặt cao thì khách trả giá gắt và dễ bỏ đi.`,off?'Đang phục vụ được.':'Chưa phục vụ được: cần học nghề hoặc thêm chỗ.']}}; });
  if(sub==='hoc') return SK.map(k=>{ const sv=SERVICES[k], sk=S.skills[k], need=sv.needSkill&&!S.skills[sv.needSkill], L=sv.learn;
    if(sk){ const up={cash:2e6*sk.lv,xp:30*sk.lv}, mx=sk.lv>=5, sel=`[data-up="${k}"]`;
      return {ic:ico(SVC_ICON[k]), name:sv.name, meta:mx?'tối đa':`cấp ${sk.lv}/5`, tag:mx?'Tối đa':fmt(up.cash), dim:mx,
        pop:{ic:ico(SVC_ICON[k]), title:`${sv.name} · cấp ${sk.lv}/5`, bar:mx?100:(sk.exp||0)/(sk.lv*60)*100,
          lines:[mx?'Đã học hết khoá nâng cao.':`Kinh nghiệm thực hành ${sk.exp||0}/${sk.lv*60}.`,`${sv.min} phút · ${sv.st==='chair'?'ghế massage':'phòng body'}`],
          a:mx?null:{t:`Nâng cao · ${fmt(up.cash)} + ${up.xp}đ`,px:sel,dis:!ok(sel)}}}; }
    const sel=`[data-learn="${k}"]`;
    return {ic:ico(SVC_ICON[k]), name:sv.name, meta:need?'cần học trước':'chưa học', tag:need?'Khoá':fmt(L.cash), dim:true, lock:need,
      pop:{ic:ico(SVC_ICON[k]), title:sv.name,
        lines:[`${sv.min} phút · ${sv.st==='chair'?'ghế massage':'phòng body'}${sv.item?' + xe đá nóng':''}`,need?`Cần học ${SERVICES[sv.needSkill].name} trước.`:`Học tốn ${fmt(L.cash)} + ${L.xp} điểm nghề.`],
        a:need?null:{t:`Học · ${fmt(L.cash)} + ${L.xp}đ`,px:sel,dis:!ok(sel)}}}; });
  // chu tiem
  return [{ic:avatarMini(OWNER_LOOK()), name:S.owner||'Chủ tiệm', meta:`Điểm nghề ${S.xp}`, tag:S.xp, av:1},
    {ic:ico('i_towel')||'', name:'Sự cố xử lý êm', meta:'đã giải quyết', tag:S.solved||0},
    {ic:'<img class="ico" src="img/5c1442516bed.webp" alt="">', name:'Xử lý êm chuyện khách', meta:'điểm nghề', tag:'+10'},
    {ic:'<img class="ico" src="img/15864e08d50d.webp" alt="">', name:'Tự tay làm khách', meta:'điểm nghề', tag:'+5'}]; }
const skillOf=o=>`<div class="skills">${skillChips(o)}</div>`;
const star=o=>o.lvl||o.lv||'';
function nsItems(sub){
  const out=[], arm=(k)=>k;
  if(sub==='tuyen'){ S.cands.forEach(c=>{ const sel=`[data-hire="${c.id}"]`;
    out.push({av:avatarMini(staffLook(c)), name:c.name, star:Math.round(STK.reduce((a,k)=>a+c.st[k],0)/STK.length), kind:'tuyển',
      pop:{av:avatarMini(staffLook(c)), title:c.name, tags:[c.rank==='tc'?'KTV chính':'Học việc',c.moi?'Mới':''], body:skillOf(c)+statBars(c.st), lines:[`Lương cứng ${fmt(c.monthly)}/tháng + tua ${Math.round(TUA*100)}% + tip`],
        a:{t:'Thuê',px:sel,dis:!ok(sel)}}}); }); return out; }
  { const c=S.cashier, hr=`#hireC`;
    out.push({av:avatarMini(CASHIER_LOOK), name:'Ngọc Hân', star:c?c.lv:'', kind:'thu ngân', dim:!c,
      pop:c?{av:avatarMini(CASHIER_LOOK), title:`Ngọc Hân · cấp ${c.lv}/5`, tags:['Thu ngân'], lines:[`${fmt(CASHIER.monthly+CASHIER.step*(c.lv-1))}/tháng`,`Chốt ${Math.round((0.8+0.04*c.lv)*100)}% giá · giữ khách ${Math.round((0.4+0.12*c.lv)*100)}%`], sw:{t:'Chủ tiệm tự trả giá',on:!!S.selfHaggle,px:'#selfH'},
        a:c.lv<5?{t:`Nâng · ${fmt(CASHIER.up[c.lv])}`,px:'#upC',dis:!ok('#upC')}:null, b:{t:'Cho nghỉ',px:'#fireC',tone:'cam',conf:`Cho thu ngân Ngọc Hân nghỉ việc?`,arm:'fireC'}}
        :{av:avatarMini(CASHIER_LOOK), title:'Ngọc Hân', tags:['Thu ngân'], lines:[`Cấp 1 · ${fmt(CASHIER.monthly)}/tháng`,'Đứng quầy, tự trả giá và chốt với khách.'], a:{t:'Thuê',px:hr,dis:!ok(hr)}}}); }
  { const m=S.manager;
    out.push({av:avatarMini(MANAGER_LOOK), name:'Anh Bảo', star:m?'★':'', kind:'quản lý ca', dim:!m,
      pop:m?{av:avatarMini(MANAGER_LOOK), title:'Anh Bảo', tags:['Quản lý ca'], lines:[`${fmt(MANAGER.monthly)}/tháng`,'Tự xử lý sự cố khách trong ca.'], b:{t:'Cho nghỉ',px:'#fireM',tone:'cam',conf:'Cho quản lý ca Anh Bảo nghỉ việc?',arm:'fireM'}}
        :{av:avatarMini(MANAGER_LOOK), title:'Anh Bảo', tags:['Quản lý ca'], lines:[`${fmt(MANAGER.monthly)}/tháng`,'Tự xử lý sự cố khách trong ca.'], a:{t:'Thuê',px:'#hireM',dis:!ok('#hireM')}}}); }
  S.staff.forEach(s=>{ const w=W_find(s), busy=w&&w.state!=='idle', fs=`[data-fire="${s.id}"]`;
    out.push({av:avatarMini(staffLook(s)), name:s.name, star:s.lvl, kind:s.rank==='tc'?'KTV chính':'Học việc',
      pop:{av:avatarMini(staffLook(s)), title:s.name, tags:[s.rank==='tc'?'KTV chính':'Học việc',`cấp ${s.lvl}`,s.lazy?'Lơ là':'',busy?'Đang làm':''], body:skillOf(s)+statBars(s.st),
        lines:[`Lương ${fmt(s.monthly)}/tháng + tua ${Math.round(TUA*100)}%`,`Tinh thần ${Math.round(s.morale)} · ${s.xp||0}/${s.lvl*60} KN`], bar:s.morale,
        side:[{t:'Phạt 100k',px:`[data-pun="${s.id}"]`},{t:'Dạy nghề',px:`[data-tea="${s.id}"]`}],
        a:{t:'Thưởng 300k',px:`[data-rew="${s.id}"]`,dis:!ok(`[data-rew="${s.id}"]`)}, b:{t:'Cho nghỉ',px:fs,tone:'cam',conf:`Cho ${s.name} nghỉ việc?`,arm:'fire'+s.id,dis:!!busy}}}); });
  return out; }
const W_find=s=>W.find(x=>x.kind==='staff'&&x.id===s.id);
// ---------------- ve ----------------
function popHTML(p){
  const tg=(p.tags||[]).filter(Boolean).map(t=>`<span class="u4-tg">${E(t)}</span>`).join('');
  const bt=(c,k)=>{ if(!c) return ''; const t=c.tone||(k==='a'?'xanh':'kem'); return `<button type="button" class="u4-pb ${k} ${t}" data-px="${px(c.px)}" ${c.conf?`data-conf="${E(c.conf)}" data-arm="${E(c.arm||'')}"`:''} ${c.dis?'disabled':''}>${E(c.t)}</button>`; };
  const side=(p.side||[]).map(c=>`<button type="button" class="btn sm" data-px="${px(c.px)}">${E(c.t)}</button>`).join('');
  return `<div class="u4-pop" role="dialog" aria-modal="true"><div class="u4-card"><div class="u4-ptx${side?' has-side':''}">
    <div class="u4-pmain"><div class="u4-pt">${p.av?`<span class="u4-pav">${p.av}</span>`:p.ic?`<span class="u4-pic">${p.ic}</span>`:''}<b>${E(p.title)}</b>${tg}</div>
    ${p.body||''}${(p.lines||[]).map(l=>`<div class="u4-pl">${E(l)}</div>`).join('')}${p.bar!=null?`<div class="bar u4-pbar"><i style="width:${Math.round(p.bar)}%"></i></div>`:''}
    ${p.sw?`<label class="u4-sw"><input type="checkbox" data-px="${px(p.sw.px)}" ${p.sw.on?'checked':''}> ${E(p.sw.t)}</label>`:''}</div>
    ${side?`<div class="u4-pside">${side}</div>`:''}</div>
    ${bt(p.a,'a')}${bt(p.b||{t:'Đóng',px:'',tone:'kem'},'b')}</div></div>`; }
function openPop(D,p){ const old=D.querySelector('.u4-pop'); if(old) old.remove(); D.insertAdjacentHTML('beforeend',popHTML(p)); const pop=D.querySelector('.u4-pop'); const f=pop.querySelector('.u4-pb.a:not([disabled])')||pop.querySelector('.u4-pb.b'); if(f) f.focus({preventScroll:true}); }
function clean(D){ D.querySelectorAll('.u4-stg,.u4-ui,.u4-bg,.u4-flow,.u4-pop').forEach(x=>x.remove()); D.classList.remove('u4-on','u4-dv','u4-ns','u4-p','u4-pon'); delete D.dataset.u4; }
const star5=n=>n===''||n==null?'':`<i class="u4-star">${E(n)}</i>`;
function build(D,kind,sub){
  const scene=$('#phone').classList.contains('tsheet')&&LOW(), isDV=kind==='skill';
  const items=isDV?dvRows(sub):nsItems(sub); if(!items.length&&!isDV) { if(sub==='tuyen'){/* van ve khung de bam Dang tin */} }
  const N=isDV?6:5, key=kind+'-'+sub; const pages=scene?Math.max(1,Math.ceil(items.length/N)):1;
  PG[key]=Math.min(PG[key]||0,pages-1); const pgi=PG[key], list=scene?items.slice(pgi*N,pgi*N+N):items;
  D.classList.add(isDV?'u4-dv':'u4-ns',scene?'u4-on':'u4-p'); D.dataset.u4=kind;
  let body='';
  if(scene&&isDV) body=list.map((r,i)=>rowDV(r,i,pgi*N+i)).join('');
  else if(scene) body=list.map((r,i)=>polNS(r,i,pgi*N+i)).join('');
  else body=isDV?list.map((r,i)=>rowFlow(r,i)).join(''):list.map((r,i)=>polFlow(r,i)).join('');
  const reroll=(!isDV&&sub==='tuyen')?`<button type="button" class="btn sm u4-rr" data-px="#reroll" ${ok('#reroll')?'':'disabled'}>Đăng tin tuyển · 500k</button>`:'';
  const pager=pages>1?`<div class="u4-pgr"><button type="button" class="u4-pgb" data-pg="-1" aria-label="Trang trước"></button><small>${pgi+1}/${pages}</small><button type="button" class="u4-pgb nx" data-pg="1" aria-label="Trang sau"></button></div>`:'';
  const empty=(!isDV&&!items.length)?'<p class="u4-empty">Hết ứng viên, sáng mai có người mới.</p>':'';
  if(scene){ D.insertAdjacentHTML('beforeend',`<div class="u4-bg"></div><div class="u4-stg">${body}</div><div class="u4-ui">${reroll}${pager}</div>`); }
  else D.insertAdjacentHTML('beforeend',`<div class="u4-bg"></div><div class="u4-flow${isDV?' dv':' ns'}">${empty}${body}</div>${reroll||pager?`<div class="u4-ui">${reroll}${pager}</div>`:''}`);
  D._u4={items,key,pages,N};
}
const lk=r=>r.lock?'<img class="lk" src="img/8cd83cb5ea4d.webp" alt="chưa mở">':'';
const nm=(r,gi)=>r.pop?`<button type="button" class="nm" data-open="${gi}">${lk(r)}<b>${E(r.name)}</b><small>${E(r.meta)}</small></button>`:`<span class="nm">${lk(r)}<b>${E(r.name)}</b><small>${E(r.meta)}</small></span>`;
function rowDV(r,i,gi){
  const y=RY[i]-12, h=96;
  const bt=r.m?`<button type="button" class="u4-m" data-px="${px(r.m)}" aria-label="Giảm giá ${E(r.name)}"></button><button type="button" class="u4-pl2" data-px="${px(r.p)}" aria-label="Tăng giá ${E(r.name)}"></button>`:'';
  return `<div class="u4-row${r.dim?' dim':''}${r.lock?' lock':''}" style="${pc(432,y,840,h)}"><span class="u4-c">${r.av?`<span class="u4-av">${r.ic}</span>`:r.ic}</span><span class="u4-pp">${nm(r,gi)}${bt}</span><span class="u4-tgp">${E(r.tag)}</span></div>`; }
function rowFlow(r,i){
  const bt=r.m?`<button type="button" class="u4-m" data-px="${px(r.m)}" aria-label="Giảm giá ${E(r.name)}"></button><button type="button" class="u4-pl2" data-px="${px(r.p)}" aria-label="Tăng giá ${E(r.name)}"></button>`:'';
  return `<div class="u4-row${r.dim?' dim':''}${r.lock?' lock':''}"><span class="u4-c">${r.av?`<span class="u4-av">${r.ic}</span>`:r.ic}</span><span class="u4-pp">${nm(r,i)}${bt}</span><span class="u4-tgp">${E(r.tag)}</span></div>`; }
function polNS(r,i,gi){
  const P=POL[i], [x0,y0,x1,_]=P.o, y1=P.l[3], bw=x1-x0, bh=y1-y0;
  const rel=(x,y,w,h)=>`left:${((x-x0)/bw*100).toFixed(2)}%;top:${((y-y0)/bh*100).toFixed(2)}%;width:${(w/bw*100).toFixed(2)}%;height:${(h/bh*100).toFixed(2)}%`;
  const [a,b,c,d]=P.w, [la,lb,lc,ld]=P.l;
  return `<button type="button" class="u4-pol${r.dim?' dim':''}" data-open="${gi}" style="${pc(x0,y0,bw,bh)}" aria-label="${E(r.name)}"><span class="ph" style="${rel(a,b,c-a,d-b)};transform:rotate(${P.r}deg)">${r.av}</span>
    <span class="lb" style="${rel(la,lb,lc-la,ld-lb)}"><b>${E(r.name)}</b></span>${r.star!==''&&r.star!=null?`<i class="u4-star" style="left:${((P.s[0]-x0)/bw*100).toFixed(2)}%;top:${((P.s[1]-y0)/bh*100).toFixed(2)}%">${E(r.star)}</i>`:''}</button>`; }
function polFlow(r,i){ return `<button type="button" class="u4-pc${r.dim?' dim':''}" data-open="${i}" aria-label="${E(r.name)}"><span class="ph">${r.av}</span><span class="lb"><b>${E(r.name)}</b><small>${E(r.kind||'')}</small></span>${r.star!==''&&r.star!=null?`<i class="u4-star">${E(r.star)}</i>`:''}</button>`; }
// ---------------- dien thoai ----------------
function wrapPhone(D){
  const host=D.querySelector(':scope > .col-r')||D; if(host.querySelector(':scope > .u4-ph')) return;
  const kids=[...host.children].filter(c=>!c.matches('.seg,.subt,.tsh-head,.u4-ph')); if(!kids.length) return;
  const fr=document.createElement('div'); fr.className='u4-ph'; const scr=document.createElement('div'); scr.className='u4-scr'; fr.appendChild(scr);
  kids.forEach(k=>scr.appendChild(k)); host.appendChild(fr); D.classList.add('u4-pon');
  const f=scr.querySelector('#feed'); if(f) f.scrollTop=f.scrollHeight; }
// ---------------- chay sau moi lan ve man ----------------
function apply(){
  const D=$('#dyn'), ph=$('#phone'); if(!D||!ph) return; clean(D); ph.classList.toggle('u4-phone',tab==='phone');
  if(tab==='phone'){ wrapPhone(D); return; }
  if(tab!=='skill'&&tab!=='staff') return;
  const sub=(D.dataset.sub||'').split('-')[1]; if(!sub||sub==='td') return;
  build(D,tab,sub); }
renderScreen=(orig=>function(){ orig.apply(this,arguments); try{ apply(); }catch(e){ console.error('24f',e); } })(renderScreen);
// ---------------- su kien ----------------
$('#dyn').addEventListener('click',e=>{
  const D=$('#dyn'), t=e.target;
  const pg=t.closest('[data-pg]'); if(pg&&D._u4){ const u=D._u4; PG[u.key]=(PG[u.key]+ +pg.dataset.pg+u.pages)%u.pages; renderScreen(); return; }
  const op=t.closest('[data-open]'); if(op&&D._u4){ const it=D._u4.items[+op.dataset.open]; if(it&&it.pop) openPop(D,it.pop); return; }
  const pop=t.closest('.u4-pop'); if(pop&&!t.closest('.u4-card')){ pop.remove(); return; }
  const pb=t.closest('.u4-pb,[data-px]'); if(!pb) return;
  if(pb.matches('input')) return;   // o tick: xu ly o su kien change
  e.stopPropagation(); if(pb.disabled) return;
  const sel=pb.dataset.px, close=()=>{ const p=D.querySelector('.u4-pop'); if(p) p.remove(); };
  if(!sel){ close(); return; }
  const o=D.querySelector(sel); if(!o||o.disabled){ close(); return; }
  if(pb.dataset.conf){ const arm=pb.dataset.arm; close(); const go=()=>{ armed=arm; o.click(); };
    if(window.uiConfirm) uiConfirm(pb.dataset.conf,'Cho nghỉ','Giữ lại',go); else go(); return; }
  close(); o.click(); },true);
$('#dyn').addEventListener('change',e=>{ const t=e.target; if(!t.matches||!t.matches('.u4-sw input')) return; e.stopPropagation(); const o=$('#dyn').querySelector(t.dataset.px); if(o) o.click(); },true);
})();

// 24i: the do hiem / so dem nhan data-u4 theo noi dung (anh ve tay UI4 trong css/24i-ui4.css). Luat choi giu nguyen.
(()=>{
const RAR=[[/^thường$/i,'thuong'],[/^hiếm$/i,'hiem'],[/^quý$/i,'quy'],[/^huyền thoại$/i,'huyen'],[/^\d+\s*\/\s*\d+$/,'dem']];
function paint(root){ (root||document).querySelectorAll('.tag').forEach(t=>{ const x=(t.textContent||'').trim(); let k=''; for(const [re,v] of RAR) if(re.test(x)){ k=v; break; }
    if(k){ if(t.dataset.u4!==k) t.dataset.u4=k; } else if(t.dataset.u4) delete t.dataset.u4; }); }
let q=0; new MutationObserver(()=>{ if(q) return; q=1; requestAnimationFrame(()=>{ q=0; paint(); }); }).observe(document.body,{childList:true,subtree:true,characterData:true});
paint();
})();

// 24k: chuan hoa chi tiet. Luat choi giu nguyen.
(()=>{ 'use strict';
// cham chip "Can mua" / bong mo -> mo thang Mua sam, cuon toi dung mon va nhay khung 1.6s
function goNeed(id){ if(typeof closeSheet==='function') closeSheet(); const nav=document.querySelector('#nav [data-tab="buy"]'); if(typeof subSel!=='undefined') subSel.buy='do'; if(nav) nav.click();
  let n=0; const t=setInterval(()=>{ const b=document.querySelector(`#dyn [data-buy="${id}"]`), it=b?b.closest('.item'):[...document.querySelectorAll('#dyn .item')].find(x=>x.textContent.includes(TEN.slot(id)));
    if(it||++n>12){ clearInterval(t); if(it){ it.scrollIntoView({block:'center'}); it.classList.add('k-flash'); setTimeout(()=>it.classList.remove('k-flash'),1700); } } },120); }
window.goNeed=goNeed;
document.addEventListener('click',e=>{ const b=e.target.closest&&e.target.closest('[data-need]'); if(!b) return; e.preventDefault(); e.stopPropagation(); goNeed(b.dataset.need); },true);
})();

